INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('plantcad/genecad/tacc', 'community', 'plantcad', 'genecad', 'plantcad/genecad', 'tacc', 25, 1, 44, '2026-02-26T19:42:32Z', '2026-03-06T06:40:19.082Z', 'd1fe8b007d04314e61de84767cd992ba86378adfb249fe38d0cb0cd40ca97d74', '{"id":"plantcad/genecad/tacc","name":"tacc","description":{"en":"The tacc skill facilitates genome annotation pre-publication results on the Vista supercomputer at TACC. It benefits developers and researchers by streamlining the annotation process.","zh":"TACC是Texas Advanced Computing Center的Genome注释预发布结果技能，支持Vista超级计算机的队列名称、模块版本和文件系统布局","ja":"TACCはテキサス州立大学のスーパーコンピューターセンターのGenomeアノテーションの事前公開結果のスキルで、Vistaスーパーコンピューターのキュー名、モジュールバージョン、ファイルシステムレイアウトをサポート","ko":"TACC는 텍사스 어드밴스드 컴퓨팅 센터의 Genome 주석 전 공개 결과 스킬로, Vista 슈퍼 컴퓨터의 큐 이름, 모듈 버전, 파일 시스템 레이아웃을 지원","es":"TACC es un cluster de supercomputación que permite la configuración de agentes de inteligencia artificial para la anotación del genoma","fr":"TACC est un cluster de supercalculateur qui permet la configuration d''outils d''intelligence artificielle pour l''annotation du génome","de":"TACC ist ein Supercomputer-Cluster, der die Konfiguration von KI-Agents für die Genomannotation ermöglicht","pt":"O TACC é uma habilidade que fornece resultados de anotação de genoma pré-publicação para desenvolvedores. Configure o TACC com nossa guia","ru":"TACC - это навык, который предоставляет результаты аннотации генома до публикации для разработчиков. Настройте TACC с нашей помощью","ar":"TACC هو مهارة توفر نتائج تركيبة الجينوم قبل النشر للمطورين. قم بتكوين TACC مع دليلنا"},"seo":{"title":{"en":"tacc: Genome Annotation Setup Guide | AI Agent Skill","zh":"TACC Setup Guide: Genome Annotation Pre-Publication Results","ja":"TACC AIエージェントの設定方法: ゲノムアノテーションの事前公開結果","ko":"TACC 설정 가이드: 유전체 주석 전 공개 결과","es":"Guía de configuración de TACC para agentes de inteligenci...","fr":"Guide de configuration TACC pour les outils d''intelligenc...","de":"TACC-Konfigurationsleitfaden für KI-Agents","pt":"Guia de Configuração TACC para Desenvolvedores","ru":"Настройка TACC для разработчиков: ИИ Агенты","ar":"دليل تكوين TACC لمنصة Vista"},"description":{"en":"Unlock the power of genome annotation with tacc. Learn how to set up and utilize the Vista supercomputer for pre-publication results. Get started now!","zh":"了解如何配置TACC环境并运行Genome注释任务，包括SSH访问验证和Vista超级计算机的设置","ja":"TACC環境の設定方法とGenomeアノテーションタスクの実行方法を紹介します。SSHアクセスの検証とVistaスーパーコンピュータの設定を含みます","ko":"TACC 환경 설정 및 Genome 주석 태스크 실행 방법을 알아보세요. SSH 접근 검증 및 Vista 슈퍼 컴퓨터 설정 포함","es":"Aprende a configurar TACC para agentes de inteligencia artificial con nuestra guía paso a paso","fr":"Découvrez comment configurer TACC pour les outils d''intelligence artificielle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie TACC für KI-Agents konfigurieren, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o TACC para desenvolvedores com nossa guia passo a passo, incluindo verificação de acesso SSH e configuração de ambiente","ru":"Настройте TACC для разработчиков с нашей пошаговой инструкцией, включая проверку доступа SSH и настройку среды","ar":"تعلم كيفية تكوين TACC لمنصة Vista بخطوات بسيطة، تشمل التحقق من الوصول إلى SSH وتكوين البيئة"},"definition":{"en":"tacc is a skill for genome annotation pre-publication results, specifically designed for the Vista supercomputer at the Texas Advanced Computing Center.","zh":"TACC是用于Genome注释预发布结果的技能，依赖于Vista超级计算机的环境","ja":"TACCはGenomeアノテーションの事前公開結果のスキルで、Vistaスーパーコンピューターの環境に依存","ko":"TACC는 Genome 주석 전 공개 결과를 위한 스킬로, Vista 슈퍼 컴퓨터의 환경에 의존","es":"TACC es un cluster de supercomputación que ofrece capacidades de procesamiento de alto rendimiento para la anotación del genoma","fr":"TACC est un cluster de supercalculateur qui offre des capacités de traitement haute performance pour l''annotation du génome","de":"TACC ist ein Supercomputer-Cluster, der Hochleistungs-Verarbeitungsfähigkeiten für die Genomannotation bietet","pt":"TACC é um cluster de supercomputador que fornece recursos de computação de alto desempenho para desenvolvedores","ru":"TACC - это суперкомпьютерный кластер, который предоставляет ресурсы высокопроизводительных вычислений для разработчиков","ar":"TACC هو مجموعة خادمات عالية الأداء توفر موارد الحوسبة للْمطوّرين"},"features":{"en":["Verifies SSH access using the command `ssh tacc \"echo ''SSH OK''\"`","Guides users through first-time setup on the Vista supercomputer","Utilizes queue names, module versions, and filesystem layout specific to Vista","Supports genome annotation pre-publication results","Ensures user environment is ready for TACC operations"],"zh":["支持Vista超级计算机的队列名称和模块版本","提供SSH访问验证和配置","支持Genome注释预发布结果的任务执行","依赖于Vista超级计算机的文件系统布局","提供第一时间设置和运行Genome注释任务的指导"],"ja":["Vistaスーパーコンピューターのキュー名とモジュールバージョンをサポート","SSHアクセスの検証と設定を提供","Genomeアノテーションの事前公開結果のタスクの実行をサポート","Vistaスーパーコンピューターのファイルシステムレイアウトに依存","最初の設定とGenomeアノテーションタスクの実行のガイドを提供"],"ko":["Vista 슈퍼 컴퓨터의 큐 이름과 모듈 버전을 지원","SSH 접근 검증과 설정을 제공","Genome 주석 전 공개 결과의 태스크 실행을 지원","Vista 슈퍼 컴퓨터의 파일 시스템 레이아웃에 의존","초기 설정과 Genome 주석 태스크 실행의 가이드를 제공"],"es":["Acceso SSH seguro","Verificación del entorno del usuario","Configuración de módulos y versiones específicas","Diseño de sistema de archivos personalizado","Compatibilidad con la supercomputadora Vista"],"fr":["Accès SSH sécurisé","Vérification de l''environnement de l''utilisateur","Configuration de modules et de versions spécifiques","Conception de système de fichiers personnalisée","Compatibilité avec la supercalculatrice Vista"],"de":["Sichere SSH-Zugriffe","Überprüfung der Benutzerumgebung","Konfiguration von Modulen und spezifischen Versionen","Benutzerdefiniertes Dateisystemdesign","Kompatibilität mit dem Supercomputer Vista"],"pt":["Acesso SSH seguro","Configuração de ambiente personalizada","Integração com o cluster Vista","Suporte a resultados de anotação de genoma pré-publicação","Verificação de acesso e configuração automática"],"ru":["Безопасный доступ SSH","Настройка среды под заказ","Интеграция с кластером Vista","Поддержка результатов аннотации генома до публикации","Автоматическая проверка доступа и настройка"],"ar":["دخول SSH آمن","إعداد بيئة مخصص","التكامل مع منصة Vista","دعم نتائج تركيبة الجينوم قبل النشر","التحقق التلقائي من الوصول وتكوين البيئة"]},"keywords":{"en":["how to use tacc","tacc setup guide","genome annotation with tacc","tacc vs other annotation tools","tacc install on Vista supercomputer","what is tacc","tacc alternative for genome annotation","tacc tutorial for developers","tacc for pre-publication results"],"zh":["TACC","Genome注释","预发布结果","Vista超级计算机","SSH访问验证","模块版本","文件系统布局","队列名称","Genome注释任务"],"ja":["TACC","Genomeアノテーション","事前公開結果","Vistaスーパーコンピューター","SSHアクセスの検証","モジュールバージョン","ファイルシステムレイアウト","キュー名","Genomeアノテーションタスク"],"ko":["TACC","Genome 주석","전 공개 결과","Vista 슈퍼 컴퓨터","SSH 접근 검증","모듈 버전","파일 시스템 레이아웃","큐 이름","Genome 주석 태스크"],"es":["TACC","agentes de inteligencia artificial","anotación del genoma","configuración de TACC","supercomputación","acceso SSH","entorno del usuario","módulos y versiones","sistema de archivos"],"fr":["TACC","outils d''intelligence artificielle","annotation du génome","configuration de TACC","supercalculateur","accès SSH","environnement de l''utilisateur","modules et versions","système de fichiers"],"de":["TACC","KI-Agents","Genomannotation","TACC-Konfiguration","Supercomputer","SSH-Zugriff","Benutzerumgebung","Module und Versionen","Dateisystem"],"pt":["tacc","configuração tacc","desenvolvedores","genoma","anotação de genoma","supercomputador","cluster vista","acesso ssh","configuração de ambiente"],"ru":["tacc","настройка tacc","разработчики","геном","аннотация генома","суперкомпьютер","кластер vista","доступ ssh","настройка среды"],"ar":["tacc","تكوين tacc","مطورين","جينوم","تركيبة الجينوم","خادمات عالية الأداء","منصة vista","دخول ssh","تكوين بيئة"]}},"owner":"plantcad","repo":"genecad","repoPath":"plantcad/genecad","stars":25,"forks":1,"updatedAt":"2026-02-26T19:42:32Z","topics":[],"category":"community","skillMd":{"name":"tacc","description":"Manages experiment execution on the TACC Vista HPC cluster. Use when the user says run on TACC, run the pipeline, allocate a GPU node, check SLURM queue, sync code to TACC, download results from TACC, cancel that job, or when any task requires GPU/CPU compute that cannot run locally. Do NOT use for local-only tasks like editing code, running tests, or plotting.","bodyPreview":"# TACC HPC Cluster (Vista)\n\nThis skill targets the **Vista** supercomputer within TACC (Texas Advanced Computing Center). Queue names, module versions, and filesystem layout are Vista-specific and may differ on other TACC systems.\n\n## First-Time Setup\n\nBefore any TACC operations, verify the user''s environment is ready. Run these checks and guide the user through fixing any failures:\n\n### Step 1: Verify SSH access\n```bash\nssh tacc \"echo ''SSH OK''\"\n```\nIf this fails, the user needs to configure `ta","body":"# TACC HPC Cluster (Vista)\n\nThis skill targets the **Vista** supercomputer within TACC (Texas Advanced Computing Center). Queue names, module versions, and filesystem layout are Vista-specific and may differ on other TACC systems.\n\n## First-Time Setup\n\nBefore any TACC operations, verify the user''s environment is ready. Run these checks and guide the user through fixing any failures:\n\n### Step 1: Verify SSH access\n```bash\nssh tacc \"echo ''SSH OK''\"\n```\nIf this fails, the user needs to configure `tacc` as an SSH host in `~/.ssh/config`.\n\n### Step 2: Install command wrapper\n```bash\nssh tacc \"test -x \\$HOME/local/bin/genecad/cmd && echo ''cmd OK'' || echo ''MISSING''\"\n```\nIf missing, install it from the local skill scripts:\n```bash\nssh tacc \"mkdir -p ~/local/bin/genecad\"\nrsync -Pz .claude/skills/tacc/scripts/cmd tacc:~/local/bin/genecad/cmd\nssh tacc \"chmod +x ~/local/bin/genecad/cmd\"\n```\nThe `cmd` script sources `.bashrc`, sets `PYTHONPATH`, cds to the repo, and exports `RANK`/`WORLD_SIZE` from SLURM variables, then execs the given command. It is the single entry point for running commands on compute nodes.\n\n### Step 3: Verify Python environment\n```bash\nssh tacc \"bash -l -c ''which python && python --version''\"\n```\nExpected: Python 3.11+ from a venv at `$WORK/envs/ml-rel/bin/activate`, sourced by `.bashrc`. Do NOT use conda, mamba, or micromamba — they are not installed on Vista.\n\n### Step 4: Verify repository exists on TACC\n```bash\nssh tacc \"bash -l -c ''cd \\$WORK/repos/genecad && git status --short''\"\n```\nIf the repo doesn''t exist, clone it: `ssh tacc \"bash -l -c ''git clone <REPO_URL> \\$WORK/repos/genecad''\"`.\n\n## Filesystem Model\n\n- **`$WORK`** — Small, persistent filesystem. All code and repositories live here. Treat stored data as **read-only** unless explicitly instructed otherwise.\n- **`$SCRATCH`** — Effectively unlimited capacity but subject to automatic garbage collection (data expires if not accessed frequently enough). **`$SCRATCH/tmp` is the default output location for ALL experiment results** unless instructed otherwise. Any other directories under `$SCRATCH` should be treated as read-only data sources, not output destinations.\n\n## Login Node vs Compute Node\n\nThe `tacc` SSH alias connects to a **login node**. Use it freely for:\n- File exploration (`ls`, `find`, `du`)\n- Environment checks (`which python`, `env`)\n- Data inspection and analysis (Python + pandas, matplotlib, parsing results, generating tables/plots)\n- Running analysis scripts that don''t need GPUs or heavy compute\n- Git operations (`git status`, `git pull`)\n- Job management (`squeue`, `scancel`, `idev`)\n\n**Compute nodes cost SU credits.** Only allocate a compute node when:\n- The task requires a GPU (model inference, predictions)\n- The task requires significant CPU or memory (large-scale post-processing)\n\nDo NOT allocate a compute node just to run `ls`, check paths, inspect files, or run quick scripts. Use `ssh tacc \"bash -l -c ''COMMAND''\"` for that.\n\n## Experiment Workflow\n\nA typical experiment follows this sequence. Each step depends on the prior step completing successfully.\n\n### Step 1: Sync code to TACC\n```bash\nbash .claude/skills/tacc/scripts/sync          # rsync (default, fast, no commit needed)\nbash .claude/skills/tacc/scripts/sync --git    # git push + pull (requires clean commit)\n```\n**rsync (default):** Directly pushes local files without requiring a git commit. Use for in-progress work.\n**git (`--git`):** Use only when changes are committed and you want the remote to match a specific branch/commit.\n\n### Step 2: Check for existing compute nodes\n```bash\nssh tacc \"squeue -u \\$USER -o ''%.18i %.9P %.30j %.2t %.10M %.6D %.20R''\"\n```\nReuse a running node if one exists — each session has a minimum 15-minute charge.\n\n### Step 3: Allocate a compute node\n\n**Queues:**\n\n| Queue | Type | Time Limit | Use Case |\n|-------|------|------------|----------|\n| `gg` | CPU-only | — | CPU-only jobs (post-processing, evaluation) |\n| `gh-dev` | GPU dev | 2 hours | Try first for GPU work |\n| `gh` | GPU prod | — | Fallback if `gh-dev` has no nodes |\n\nDo not allocate a CPU-only node (`gg`) for GPU work. The prediction step requires a GPU.\n\n**Single-node (default):** Use `idev` to allocate an interactive node:\n```bash\nidev -p gh-dev -N 1 -n 1 -t 2:00:00\n```\nThen find the allocated node:\n```bash\nssh tacc \"squeue -u \\$USER -h -t R -o ''%N''\"\n```\n\n**Multi-node:** Use `srun` directly — no `idev` needed (see Step 4).\n\n### Step 4: Run the experiment\n\nWrite all output to `$SCRATCH/tmp` unless instructed otherwise.\n\n#### Single-node execution\n\nAfter allocating a node with `idev` (Step 3), find the node name and run commands via `cmd`. Since `cmd` cds to the repo automatically, commands can use repo-relative paths directly:\n```bash\nNODE=$(ssh tacc \"squeue -u \\$USER -h -t R -o ''%N''\" | head -1)\nssh tacc \"ssh $NODE ~/local/bin/genecad/cmd python scripts/predict.py ...\"\n```\nFor long-running single-node jobs, prefer `sbatch` over `idev` to survive SSH disconnects.\n\n#### Multi-node execution with `srun`\n\nUse `srun` to launch the same command across multiple nodes simultaneously. The `cmd` wrapper sets `RANK=$PMIX_RANK` and `WORLD_SIZE=$SLURM_NNODES`, so each node knows its rank and the total node count.\n\n```bash\nssh tacc \"bash -l -c ''\\\n  srun -p gh-dev -N 8 -n 8 --tasks-per-node 1 -t 2:00:00 \\\n    --output \\$SCRATCH/tmp/logs/<name>.log \\\n    --error  \\$SCRATCH/tmp/logs/<name>.log \\\n    ~/local/bin/genecad/cmd python scripts/predict.py create_predictions \\\n      --input ... --output-dir ...''\" 2>&1 &\n```\n\n**Important notes for multi-node `srun`:**\n- Always use `--tasks-per-node 1` — each node runs one instance of the command.\n- Environment variables set *before* the `srun` call propagate to all nodes.\n- All nodes write to the same `--output`/`--error` log file (interleaved). Use `[rank=N]` prefixes in log messages to distinguish nodes.\n- `srun` blocks until all nodes finish. Run it in background (`&`) and monitor via `tail` on the log file.\n\n#### Monitoring progress\n```bash\nssh tacc \"tail -20 \\$SCRATCH/tmp/logs/<name>.log\"\n```\n\n### Step 5: Download results\n```bash\nrsync -Pz tacc:/remote/results/path local/results/path\n```\nAlways use `rsync` instead of `scp`.\n\n### Step 6: Cancel the job\n```bash\nssh tacc \"scancel <jobid>\"\n```\n**Always cancel jobs when done.** Idle jobs consume SU credits.\n\n## Environment\n\n- Python env: standard venv at `$WORK/envs/ml-rel/bin/activate`, sourced automatically by `.bashrc`\n- Do NOT use conda, mamba, or micromamba — they are not installed\n- Modules loaded by `.bashrc`: `gcc/13.2.0`, `cuda/12.4`, `python3/3.11.8`\n- `.bashrc` must be sourced for all remote commands — `cmd` handles this automatically\n\n## Troubleshooting\n\n### \"No running compute node found\"\nCause: No `idev` session is active, or the job expired.\nFix: Allocate a new node per Step 3 of the Experiment Workflow.\n\n### Node allocated on wrong queue (e.g., `gg` for GPU work)\nCause: `gg` is CPU-only. GPU predictions will fail or silently use CPU (extremely slow).\nFix: Cancel the job (`scancel <jobid>`) and allocate on `gh-dev` or `gh`.\n\n### File transfer fails with `scp`\nFix: Use `rsync -Pz` instead of `scp`.\n\n### Python environment not found / `conda` not found\nCause: `.bashrc` was not sourced, or agent tried to use conda.\nFix: Ensure all compute node commands go through `cmd`. Never use conda/mamba/micromamba.\n\n### Pre-commit `pyrefly` hook fails locally\nCause: `pyrefly` is not installed in the local dev environment.\nFix: `uv pip install pyrefly`\n\n### SSH timeout during long-running command\nCause: Command was run in foreground and SSH connection dropped.\nFix: Always background long-running commands and redirect to a log file. Check progress by tailing the remote log.\n\n### Hallucinated or incorrect numbers in result summaries\nCause: Model generated numbers from memory instead of reading source data.\nFix: ALWAYS read raw result files (`.stats`, `.tsv`) before quoting any numbers. Never guess or recall numbers from earlier in the conversation.\n"},"lastSynced":"2026-03-06T06:40:19.082Z","agentAnalysis":{"suitability":{"en":"Perfect for HPC-focused AI Agents requiring streamlined genome annotation on the Vista supercomputer at TACC.","zh":"非常适合需要在 TACC 的 Vista 超级计算机上进行流线化基因注释的 HPC 专注的 AI 代理。","ja":"TACC の Vista スーパーコンピュータでストリーミング化されたゲノム注釈が必要な HPC 専用の AI エージェントに最適です。","ko":"TACC의 Vista 슈퍼컴퓨터에서 스트림라인화된 유전체 주석이 필요한 HPC 전용 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA enfocados en HPC que requieren una anotación del genoma optimizada en la supercomputadora Vista en TACC.","fr":"Parfait pour les agents d''IA axés sur le HPC nécessitant une annotation de génome rationalisée sur le supercalculateur Vista au TACC.","de":"Perfekt für HPC-fokussierte KI-Agents, die eine optimierte Genomannotation auf dem Vista-Supercomputer bei TACC benötigen.","pt":"Perfeito para agentes de IA focados em HPC que exigem anotação de genoma simplificada no supercomputador Vista na TACC.","ru":"Идеально подходит для агентов ИИ, ориентированных на HPC, требующих упрощенной аннотации генома на суперкомпьютере Vista в TACC.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي المُركزة على الحوسبة الفائقة التي تتطلب تبسيط تعليمات الجينوم على جهاز Vista الفائق في TACC."},"recommendation":{"en":"Empowers agents to facilitate genome annotation pre-publication results using SSH access, queue management, and filesystem navigation on the Vista HPC cluster, streamlining the annotation process for developers and researchers.","zh":"赋予代理人使用 SSH 访问、队列管理和文件系统导航在 Vista HPC 集群上促进基因注释的预发表结果，简化开发人员和研究人员的注释流程。","ja":"SSH アクセス、キュー管理、ファイルシステムナビゲーションを使用して Vista HPC クラスターでゲノム注釈の事前公開結果を促進することで、エージェントが開発者と研究者にとっての注釈プロセスを効率化できるようにします。","ko":"SSH 접근, 큐 관리 및 파일시스템 탐색을 사용하여 Vista HPC 클러스터에서 유전체 주석의 사전 발행 결과를促進하여 개발자와 연구자에게 주석 프로세스를 간소화 할 수 있습니다.","es":"Habilita a los agentes a facilitar los resultados de anotación del genoma previos a la publicación utilizando el acceso SSH, la administración de colas y la navegación del sistema de archivos en el clúster HPC Vista, racionalizando el proceso de anotación para desarrolladores e investigadores.","fr":"Permet aux agents de faciliter les résultats d''annotation de génome prépublication en utilisant l''accès SSH, la gestion des files d''attente et la navigation du système de fichiers sur le cluster HPC Vista, rationalisant le processus d''annotation pour les développeurs et les chercheurs.","de":"Ermöglicht es Agenten, die Ergebnisse der Genomannotation vor der Veröffentlichung mithilfe des SSH-Zugriffs, der Warteschlangenverwaltung und der Dateisystemnavigation im Vista-HPC-Cluster zu erleichtern, wodurch der Annotierungsprozess für Entwickler und Forscher rationalisiert wird.","pt":"Habilita agentes a facilitar resultados de anotação de genoma pré-publicação usando acesso SSH, gerenciamento de fila e navegação de sistema de arquivos no cluster HPC Vista, simplificando o processo de anotação para desenvolvedores e pesquisadores.","ru":"Наделяет агентов возможностью облегчить результаты аннотации генома до публикации, используя доступ SSH, управление очередью и навигацию по файловой системе в кластере HPC Vista, оптимизируя процесс аннотации для разработчиков и исследователей.","ar":"تمكّن الوكيل من تسهيل نتائج تعليمات الجينوم قبل النشر باستخدام الوصول إلى SSH وإدارة الطوابير والتنقل في نظام الملفات على مجموعة Vista للكومبيوتر الفائق، مبسطًا عملية التعلم للباحثين والمطورين."},"useCases":{"en":["Verifying SSH access for secure connections","Streamlining genome annotation workflows on Vista","Managing queue names and module versions for optimized performance"],"zh":["验证 SSH 访问以确保安全连接","在 Vista 上简化基因注释工作流","管理队列名称和模块版本以优化性能"],"ja":["セキュアな接続を確保するために SSH アクセスを検証する","Vista 上でゲノム注釈ワークフローを効率化する","パフォーマンスを最適化するためにキュー名とモジュールバージョンを管理する"],"ko":["보안 연결을 보장하기 위한 SSH 접근 검증","Vista에서 유전체 주석 워크플로우를 최적화","성능을 최적화하기 위한 큐 이름 및 모듈 버전 관리"],"es":["Verificar el acceso SSH para conexiones seguras","Optimizar los flujos de trabajo de anotación del genoma en Vista","Administrar nombres de cola y versiones de módulos para un rendimiento optimizado"],"fr":["Vérifier l''accès SSH pour des connexions sécurisées","Rationaliser les flux de travail d''annotation de génome sur Vista","Gérer les noms de file d''attente et les versions de modules pour des performances optimisées"],"de":["Überprüfen des SSH-Zugriffs für sichere Verbindungen","Optimieren der Genomannotations-Workflows auf Vista","Verwalten von Warteschlangennamen und Modulversionen für optimierte Leistung"],"pt":["Verificar acesso SSH para conexões seguras","Otizar fluxos de trabalho de anotação de genoma no Vista","Gerenciar nomes de fila e versões de módulos para desempenho otimizado"],"ru":["Проверка доступа SSH для безопасных подключений","Оптимизация рабочих процессов аннотации генома на Vista","Управление именами очередей и версиями модулей для оптимизированной производительности"],"ar":["التحقق من الوصول إلى SSH للاتصالات الآمنة","تسهيل تدفقات عمل تعليمات الجينوم على Vista","إدارة أسماء الطوابير وإصدارات الوحدات لتحقيق أداء متكامل"]},"limitations":{"en":["Requires SSH access to TACC","Vista-specific configuration needed","Filesystem layout may differ on other TACC systems"],"zh":["需要 TACC 的 SSH 访问","需要 Vista 特定的配置","文件系统布局可能在其他 TACC 系统上有所不同"],"ja":["TACC への SSH アクセスが必要","Vista 専用の構成が必要","ファイルシステムレイアウトは他の TACC システムでは異なる場合があります"],"ko":["TACC에 대한 SSH 접근 필요","Vista 전용 구성 필요","파일시스템 레이아웃은 다른 TACC 시스템에서는 다를 수 있음"],"es":["Requiere acceso SSH a TACC","Se requiere configuración específica de Vista","La disposición del sistema de archivos puede diferir en otros sistemas TACC"],"fr":["Nécessite un accès SSH à TACC","Une configuration spécifique à Vista est requise","La disposition du système de fichiers peut différer sur d''autres systèmes TACC"],"de":["Benötigt SSH-Zugriff auf TACC","Vista-spezifische Konfiguration erforderlich","Die Dateisystemanordnung kann sich auf anderen TACC-Systemen unterscheiden"],"pt":["Exige acesso SSH à TACC","Configuração específica do Vista necessária","Layout do sistema de arquivos pode ser diferente em outros sistemas TACC"],"ru":["Требует доступа SSH к TACC","Требуется специфическая конфигурация Vista","Макет файловой системы может отличаться на других системах TACC"],"ar":["يتطلب الوصول إلى SSH إلى TACC","تتطلب إعدادات محددة لجهاز Vista","يمكن أن تختلف تخطيط نظام الملفات على أنظمة TACC الأخرى"]},"version":4},"contentHash":"d1fe8b007d04314e61de84767cd992ba86378adfb249fe38d0cb0cd40ca97d74","qualityScore":44}');
