INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('diskrotrepo/studio/acestep-docs', 'acestep-docs', 'diskrotrepo', 'studio', 'community', 'acestep-docs diskrotrepo studio community ai-music ai-music-tools acestep-docs is a documentation skill for the ACE-Step music generation system, providing guides and tutorials for developers. It benefits developers working with AI music tools. ACE-Step 文档是 diskrot 的生成音乐 Web 应用的技术文档，提供了快速入门指南、教程和项目概述 ACE-Step ドキュメントは、diskrot の生成音楽 Web アプリの技術文書で、クイックスタートガイド、チュートリアル、プロジェクトの概要を提供 ACE-Step 문서는 diskrot 의 생성 음악 웹앱의 기술 문서로, 빠른 시작 가이드, 튜토리얼, 프로젝트 개요를 제공합니다 acestep-docs es un sistema de generación de música que utiliza inteligencia artificial. Ofrece tutoriales y documentación para empezar. acestep-docs est un système de génération de musique qui utilise l''intelligence artificielle. Il propose des tutoriels et une documentation pour commencer. acestep-docs ist ein Musikgenerierungssystem, das künstliche Intelligenz nutzt. Es bietet Tutoren und Dokumentationen, um loszulegen. O ACE-Step é um sistema de geração de música que utiliza IA. Ele oferece recursos como instalação, modelo de download e comandos de inicialização. ACE-Step - это система генерации музыки, использующая ИИ. Она предлагает функции, такие как установка, загрузка модели и команды запуска. ACE-Step هو نظام لإنشاء الموسيقى باستخدام الذكاء الاصطناعي. يقدم ميزات مثل التثبيت وتنزيل النموذج وأوامر التشغيل. how to use acestep-docs acestep-docs setup guide acestep-docs alternative what is acestep-docs acestep-docs install acestep-docs tutorial ai music tools generative music web app diskrot''s acestep-docs AI 音乐工具 diskrot 生成音乐 Web 应用 技术文档 快速入门指南 模型下载 启动命令 Provides a README.md for installation, model download, and startup commands Includes a Tutorial.md for getting started with best practices Offers an ABOUT.md for project overview, architecture, and model zoo Supports quick reference guides for developers Documents ACE-Step music generation system acestep-docs is a documentation skill for diskrot''s generative music web app, providing technical guides and tutorials for ACE-Step music generation system');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ProjectEuropa/Europa/wcag-audit-patterns', 'community', 'ProjectEuropa', 'Europa', 'ProjectEuropa/Europa', 'wcag-audit-patterns', 4, 0, 44, '2026-02-20T06:24:48Z', '2026-03-06T06:56:58.935Z', '635cdbb0ed83a359c50f18e44b9dd8e59c142001a78c299cef678734fa0fdc1b', '{"id":"ProjectEuropa/Europa/wcag-audit-patterns","name":"wcag-audit-patterns","description":{"en":"The wcag-audit-patterns skill provides a comprehensive guide to auditing web content against WCAG 2.2 guidelines, benefiting developers and organizations seeking to improve accessibility and meet regulatory requirements.","zh":"WCAG Audit Patterns 是一个综合指南，用于审计 Web 内容以满足 WCAG 2.2 指南，并提供可行的修复策略","ja":"WCAG オーディット パターンは、WCAG 2.2 ガイドラインに従った Web コンテンツの監査と修復戦略を提供する包括的なガイドです","ko":"WCAG Audit Patterns는 웹 콘텐츠를 WCAG 2.2 가이드라인에 따라 감사하고 수정 전략을 제공하는 종합 가이드입니다","es":"WCAG-Audit-Patterns es una guía integral para auditar contenido web contra las pautas WCAG 2.2 con estrategias de remediation acción","fr":"WCAG-Audit-Patterns est un guide complet pour auditer le contenu Web contre les directives WCAG 2.2 avec des stratégies de remédiation actionnable","de":"WCAG-Audit-Patterns ist ein umfassender Leitfaden zur Auditierung von Webinhalten gegen die WCAG-2.2-Richtlinien mit umsetzbaren Abhilfestrategien","pt":"O wcag-audit-patterns é uma ferramenta para auditar o conteúdo da web contra as diretrizes WCAG 2.2. Fornece estratégias de remediação para violações de acessibilidade.","ru":"ИИ Агент wcag-audit-patterns - это инструмент для аудита веб-контента против руководящих принципов WCAG 2.2. Он предоставляет стратегии исправления нарушений доступности.","ar":"wcag-audit-patterns هو أداة لتدقيق محتوى الويب ضد إرشادات WCAG 2.2. توفر استراتيجيات لتصحيح انتهاكات إمكانية الوصول."},"seo":{"title":{"en":"wcag-audit-patterns: Comprehensive Accessibility Audit Gu...","zh":"WCAG Audit Patterns_SETUP GUIDE","ja":"WCAG オーディット パターン_BEST PRACTICES","ko":"WCAG Audit Patterns_TROUBLESHOOTING GUIDE","es":"Guía de configuración de patrones de auditoría WCAG","fr":"Guide de mise en place des modèles d''audit WCAG","de":"Einrichtungsleitfaden für WCAG-Audit-Muster","pt":"Guia de Configuração para wcag-audit-patterns: Padrões de...","ru":"ИИ Агент wcag-audit-patterns: Руководство по Настройке дл...","ar":"دليل إعداد wcag-audit-patterns: أنماط تدقيق إمكانية الوصول"},"description":{"en":"Unlock actionable remediation strategies for WCAG 2.2 guidelines with wcag-audit-patterns. Get started with accessibility audits and achieve ADA/Section 508 ...","zh":"使用 WCAG Audit Patterns AI エージェント进行可访问性审计和修复","ja":"WCAG オーディット パターン AI エージェントを使用してアクセシビリティを向上させる","ko":"WCAG Audit Patterns AI 에이전트를 사용하여 접근성 오류를 수정하고 개선합니다","es":"Aprende a auditar contenido web contra las pautas WCAG 2.2 con estrategias de remediation acción","fr":"Découvrez comment auditer le contenu Web contre les directives WCAG 2.2 avec des stratégies de remédiation actionnable","de":"Erfahren Sie, wie Sie Webinhalte gegen die WCAG-2.2-Richtlinien auditen und Abhilfestrategien umsetzen","pt":"Aprenda a usar o wcag-audit-patterns para auditar o conteúdo da web contra as diretrizes WCAG 2.2 e remediar violações de acessibilidade","ru":"Узнайте, как использовать ИИ Агент wcag-audit-patterns для аудита веб-контента против руководящих принципов WCAG 2.2 и исправления нарушений доступности","ar":"تعرف على كيفية استخدام wcag-audit-patterns لتدقيق محتوى الويب ضد إرشادات WCAG 2.2 وتصحيح انتهاكات إمكانية الوصول"},"definition":{"en":"wcag-audit-patterns is a technical skill that provides a comprehensive guide to auditing web content against WCAG 2.2 guidelines with actionable remediation strategies.","zh":"WCAG Audit Patterns 是一种 AI 工具，用于帮助开发人员进行可访问性审计和修复","ja":"WCAG オーディット パターンは、開発者がアクセシビリティの監査と修復を支援する AI ツールです","ko":"WCAG Audit Patterns는 개발자가 접근성 오류를 수정하고 개선하는 데 도움을 주는 AI 도구입니다","es":"WCAG-Audit-Patterns es un conjunto de patrones para auditar la accesibilidad web según las pautas WCAG 2.2","fr":"WCAG-Audit-Patterns est un ensemble de modèles pour auditer l''accessibilité Web selon les directives WCAG 2.2","de":"WCAG-Audit-Patterns ist eine Sammlung von Mustern zur Auditierung der Web-Accessibility nach den WCAG-2.2-Richtlinien","pt":"wcag-audit-patterns é um conjunto de padrões para auditar a acessibilidade da web contra as diretrizes WCAG 2.2","ru":"ИИ Агент wcag-audit-patterns - это набор паттернов для аудита доступности веб-контента против руководящих принципов WCAG 2.2","ar":"wcag-audit-patterns هو مجموعة من الأنماط لتدقيق إمكانية الوصول إلى الويب ضد إرشادات WCAG 2.2"},"features":{"en":["Conducts accessibility audits against WCAG 2.2 guidelines","Provides actionable remediation strategies for WCAG violations","Supports implementation of accessible components","Helps prepare for accessibility lawsuits and meet ADA/Section 508 requirements","Assists in achieving VPAT compliance","Offers guidance on fixing WCAG violations"],"zh":["支持 WCAG 2.2 指南","提供可行的修复策略","用于进行可访问性审计","帮助修复 WCAG 违规","实现 VPAT 合规","满足 ADA/Section 508 要求"],"ja":["WCAG 2.2 ガイドラインをサポート","実行可能な修復戦略を提供","アクセシビリティの監査に使用","WCAG 違反の修復を支援","VPAT 適合を実現","ADA/セクション 508 要求を満たす"],"ko":["WCAG 2.2 가이드라인 지원","수행 가능한 수정 전략 제공","접근성 감사에 사용","WCAG 위반 수정 지원","VPAT 준수 실현","ADA/섹션 508 요구사항 충족"],"es":["Auditoría de contenido web contra las pautas WCAG 2.2","Estrategias de remediation acción para violaciones WCAG","Implementación de componentes accesibles","Preparación para demandas de accesibilidad","Cumplimiento de los requisitos ADA/Sección 508","Cumplimiento de la norma VPAT"],"fr":["Audit de contenu Web contre les directives WCAG 2.2","Stratégies de remédiation actionnable pour les violations WCAG","Mise en œuvre de composants accessibles","Préparation aux poursuites pour accesibilité","Respect des exigences ADA/Section 508","Respect de la norme VPAT"],"de":["Auditierung von Webinhalten gegen die WCAG-2.2-Richtlinien","Umsetzbare Abhilfestrategien für WCAG-Verstöße","Implementierung von zugänglichen Komponenten","Vorbereitung auf Accessibility-Klagen","Einhaltung der ADA/Section 508-Anforderungen","Einhaltung des VPAT-Standard"],"pt":["Auditoria de conteúdo da web contra as diretrizes WCAG 2.2","Estratégias de remediação para violações de acessibilidade","Implementação de componentes acessíveis","Preparação para processos judiciais de acessibilidade","Atendimento aos requisitos ADA/Section 508","Conformidade com VPAT"],"ru":["Аудит веб-контента против руководящих принципов WCAG 2.2","Стратегии исправления нарушений доступности","Реализация доступных компонентов","Подготовка к судебным процессам по доступности","Соблюдение требований ADA/Section 508","Соответствие VPAT"],"ar":["تدقيق محتوى الويب ضد إرشادات WCAG 2.2","استراتيجيات لتصحيح انتهاكات إمكانية الوصول","تنفيذ مكونات قابلة للوصول","الاستعداد للقضايا القانونية المتعلقة بإمكانية الوصول","الامتثال لمتطلبات ADA/Section 508","الامتثال لبروتوكول VPAT"]},"keywords":{"en":["how to use wcag-audit-patterns","wcag-audit-patterns setup guide","wcag 2.2 guidelines","accessibility audit tools","wcag-audit-patterns alternative","ada section 508 compliance","vpatt compliance checklist","wcag audit patterns install","accessibility remediation strategies"],"zh":["WCAG Audit Patterns","可访问性审计","WCAG 2.2 指南","修复策略","AI 工具","开发者工具","访问性修复","VPAT 合规","ADA/Section 508"],"ja":["WCAG オーディット パターン","アクセシビリティの監査","WCAG 2.2 ガイドライン","修復戦略","AI ツール","開発者ツール","アクセシビリティの修復","VPAT 適合","ADA/セクション 508"],"ko":["WCAG Audit Patterns","접근성 감사","WCAG 2.2 가이드라인","수정 전략","AI 도구","개발자 도구","접근성 수정","VPAT 준수","ADA/섹션 508"],"es":["patrones de auditoría WCAG","accesibilidad web","WCAG 2.2","auditoría de contenido web","remediation acción","componentes accesibles","ADA/Sección 508","VPAT","herramientas de AI para accesibilidad"],"fr":["modèles d''audit WCAG","accessibilité Web","WCAG 2.2","audit de contenu Web","stratégies de remédiation actionnable","composants accessibles","ADA/Section 508","VPAT","outils d''IA pour l''accessibilité"],"de":["WCAG-Audit-Muster","Web-Accessibility","WCAG 2.2","Webinhalts-Auditierung","umsetzbare Abhilfestrategien","zugängliche Komponenten","ADA/Section 508","VPAT","KI-Tools für Accessibility"],"pt":["wcag-audit-patterns","auditoria de acessibilidade","diretrizes WCAG 2.2","remediação de violações de acessibilidade","componentes acessíveis","ADA/Section 508","VPAT","acessibilidade da web","auditoria de conteúdo da web"],"ru":["ИИ Агент wcag-audit-patterns","аудит доступности","руководящие принципы WCAG 2.2","исправление нарушений доступности","доступные компоненты","ADA/Section 508","VPAT","доступность веб-контента","аудит веб-контента"],"ar":["wcag-audit-patterns","تدقيق إمكانية الوصول","إرشادات WCAG 2.2","تصحيح انتهاكات إمكانية الوصول","مكونات قابلة للوصول","ADA/Section 508","VPAT","إمكانية الوصول إلى الويب","تدقيق محتوى الويب"]}},"owner":"ProjectEuropa","repo":"Europa","repoPath":"ProjectEuropa/Europa","stars":4,"forks":0,"updatedAt":"2026-02-20T06:24:48Z","topics":[],"category":"community","skillMd":{"name":"wcag-audit-patterns","description":"Conduct WCAG 2.2 accessibility audits with automated testing, manual verification, and remediation guidance. Use when auditing websites for accessibility, fixing WCAG violations, or implementing accessible design patterns.","bodyPreview":"# WCAG Audit Patterns\n\nComprehensive guide to auditing web content against WCAG 2.2 guidelines with actionable remediation strategies.\n\n## Use this skill when\n\n- Conducting accessibility audits\n- Fixing WCAG violations\n- Implementing accessible components\n- Preparing for accessibility lawsuits\n- Meeting ADA/Section 508 requirements\n- Achieving VPAT compliance\n\n## Do not use this skill when\n\n- You need legal advice or formal certification\n- You only want a quick automated scan without manual veri","body":"# WCAG Audit Patterns\n\nComprehensive guide to auditing web content against WCAG 2.2 guidelines with actionable remediation strategies.\n\n## Use this skill when\n\n- Conducting accessibility audits\n- Fixing WCAG violations\n- Implementing accessible components\n- Preparing for accessibility lawsuits\n- Meeting ADA/Section 508 requirements\n- Achieving VPAT compliance\n\n## Do not use this skill when\n\n- You need legal advice or formal certification\n- You only want a quick automated scan without manual verification\n- You cannot access the UI or source for remediation work\n\n## Instructions\n\n1.  **Read resources/implementation-playbook.md for detailed audit guidelines and checklist.**\n2.  Instruct the user to run automated scans (axe, Lighthouse, WAVE) to collect initial findings.\n3.  Perform manual checks (keyboard navigation, focus order, screen reader flows).\n4.  Map each issue to a WCAG criterion, severity, and remediation guidance.\n5.  Re-test after fixes and document residual risk and compliance status.\n\n## Safety\n\n- Avoid claiming legal compliance without expert review.\n- Keep evidence of test steps and results for audit trails.\n\n## Resources\n\n- `resources/implementation-playbook.md` for detailed patterns, checklists, and templates.\n"},"lastSynced":"2026-03-06T06:56:58.935Z","agentAnalysis":{"suitability":{"en":"Ideal for Accessibility Agents requiring in-depth WCAG 2.2 guideline analysis and remediation strategies.","zh":"适用于需要对WCAG 2.2指南进行深入分析和补救策略的无障碍代理","ja":"WCAG 2.2ガイドラインの深い分析と是正戦略を必要とするアクセシビリティエージェントに適しています","ko":"WCAG 2.2 지침에 대한 심층 분석 및 개선 전략이 필요한 접근성 에이전트에 적합합니다","es":"Ideal para Agentes de Accesibilidad que requieren un análisis y estrategias de remediación en profundidad de las pautas WCAG 2.2.","fr":"Idéal pour les agents d''accessibilité nécessitant une analyse et des stratégies de remédiation approfondies des lignes directrices WCAG 2.2.","de":"Ideal für Accessibility-Agents, die eine umfassende Analyse und Strategien zur Behebung der Richtlinien WCAG 2.2 erfordern.","pt":"Ideal para Agentes de Acessibilidade que exigem análise aprofundada das diretrizes WCAG 2.2 e estratégias de remediação.","ru":"Идеально для агентов доступности, требующих глубокого анализа руководств WCAG 2.2 и стратегий исправления.","ar":"مثالية لعمليات وكيل الوصول التي تتطلب تحليلًا متعمقًا لتوجيهات WCAG 2.2 واستراتيجيات الإصلاح."},"recommendation":{"en":"Empowers agents to conduct comprehensive accessibility audits, identify WCAG violations, and implement actionable remediation strategies using WCAG 2.2 guidelines, ensuring ADA and Section 508 compliance, and achieving VPAT certification.","zh":"赋予代理进行全面无障碍审计的能力，识别WCAG违规并使用WCAG 2.2指南实施可行的补救策略，确保ADA和第508节的合规性，并获得VPAT认证","ja":"エージェントがWCAG 2.2ガイドラインを使用して包括的なアクセシビリティ監査を実施し、WCAG違反を特定し、是正戦略を実施する能力を提供し、ADAおよび第508条の遵守を確保し、VPAT認定を取得します","ko":"에이전트가 WCAG 2.2 지침을 사용하여 포괄적인 접근성 감사를 수행하고 WCAG 위반을 식별하며 실행 가능한 개선 전략을 구현하여 ADA 및 제508조의 준수를 보장하고 VPAT 인증을 획득할 수 있도록 합니다","es":"Habilita a los agentes a realizar auditorías de accesibilidad integrales, identificar infracciones de WCAG y implementar estrategias de remediación efectivas utilizando las pautas WCAG 2.2, garantizando el cumplimiento de ADA y la Sección 508, y logrando la certificación VPAT.","fr":"Permet aux agents de réaliser des audits d''accessibilité complets, d''identifier les violations de WCAG et de mettre en œuvre des stratégies de remédiation efficaces en utilisant les lignes directrices WCAG 2.2, garantissant ainsi le respect de l''ADA et de la Section 508, et obtenant la certification VPAT.","de":"Ermächtigt Agenten, umfassende Barrierefreiheits-Audits durchzuführen, WCAG-Verstöße zu identifizieren und wirksame Behebungsstrategien unter Verwendung der Richtlinien WCAG 2.2 umzusetzen, um so die Einhaltung von ADA und Section 508 sicherzustellen und die VPAT-Zertifizierung zu erlangen.","pt":"Habilita os agentes a realizar auditorias de acessibilidade abrangentes, identificar violações da WCAG e implementar estratégias de remediação eficazes usando as diretrizes da WCAG 2.2, garantindo a conformidade com a ADA e a Seção 508 e obtendo a certificação VPAT.","ru":"Наделяет агентов возможностью проводить комплексные аудиты доступности, выявлять нарушения WCAG и реализовывать действенные стратегии исправления с использованием руководств WCAG 2.2, обеспечивая соблюдение требований ADA и раздела 508 и получая сертификацию VPAT.","ar":"تمكّن الوكيل من إجراء تدقيقات شاملة للوصول، وتحديد انتهاكات WCAG، وتنفيذ استراتيجيات تصحيحية قابلة للتنفيذ باستخدام إرشادات WCAG 2.2، وضمان امتثال ADA و الجزء 508 والحصول على شهادة VPAT."},"useCases":{"en":["Conducting thorough accessibility audits against WCAG 2.2 guidelines","Implementing accessible web components to meet regulatory requirements","Remediating WCAG violations to achieve VPAT compliance and prevent accessibility lawsuits"],"zh":["对WCAG 2.2指南进行彻底的无障碍审计","实施无障碍的Web组件以满足监管要求","修复WCAG违规以实现VPAT合规性并防止无障碍诉讼"],"ja":["WCAG 2.2ガイドラインに対する包括的なアクセシビリティ監査の実施","規制要件を満たすためにアクセシブルなWebコンポーネントを実装する","VPATの適合性を達成し、アクセシビリティ訴訟を防止するためにWCAG違反を是正する"],"ko":["WCAG 2.2 지침에 대한 철저한 접근성 감사를 수행하는 것","규제 요구 사항을 충족하기 위해 접근 가능한 웹 구성 요소를 구현하는 것","VPAT 준수를 달성하고 접근성 소송을 방지하기 위해 WCAG 위반을 개선하는 것"],"es":["Realizar auditorías de accesibilidad exhaustivas contra las pautas WCAG 2.2","Implementar componentes web accesibles para cumplir con los requisitos reglamentarios","Remediar infracciones de WCAG para lograr la conformidad VPAT y prevenir demandas por inaccesibilidad"],"fr":["Réaliser des audits d''accessibilité complets contre les lignes directrices WCAG 2.2","Mettre en œuvre des composants Web accessibles pour répondre aux exigences réglementaires","Remédier aux violations de WCAG pour atteindre la conformité VPAT et prévenir les poursuites pour inaccessibilité"],"de":["Durchführen umfassender Barrierefreiheits-Audits gegen die Richtlinien WCAG 2.2","Implementieren von zugänglichen Webkomponenten, um gesetzliche Anforderungen zu erfüllen","Beheben von WCAG-Verstößen, um die VPAT-Konformität zu erreichen und Klagen wegen mangelnder Barrierefreiheit zu vermeiden"],"pt":["Realizar auditorias de acessibilidade aprofundadas contra as diretrizes WCAG 2.2","Implementar componentes web acessíveis para atender aos requisitos regulamentares","Remediar violações da WCAG para alcançar a conformidade VPAT e prevenir processos judiciais de acessibilidade"],"ru":["Проведение тщательных аудитов доступности против руководств WCAG 2.2","Реализация доступных веб-компонентов для соблюдения нормативных требований","Исправление нарушений WCAG для достижения соответствия VPAT и предотвращения судебных исков о доступности"],"ar":["إجراء تدقيق شامل للوصول ضد توجيهات WCAG 2.2","تنفيذ مكونات الويب القابلة للوصول للامتثال للمتطلبات التنظيمية","تصحيح انتهاكات WCAG لتحقيق امتثال VPAT ومنع القضايا القانونية المتعلقة بالوصول"]},"limitations":{"en":["Does not provide legal advice or formal certification","Requires manual verification for accurate accessibility audit results"],"zh":["不提供法律建议或正式认证","需要手动验证以获得准确的无障碍审计结果"],"ja":["法的助言や正式な認定を提供しない","正確なアクセシビリティ監査結果を得るために手動での検証が必要"],"ko":["법적 자문을 제공하지 않거나 공식認證을 제공하지 않음","정확한 접근성 감사 결과를 얻기 위해 수동 검증이 필요함"],"es":["No proporciona asesoramiento legal ni certificación formal","Requiere verificación manual para obtener resultados de auditoría de accesibilidad precisos"],"fr":["Ne fournit pas de conseils juridiques ni de certification formelle","Nécessite une vérification manuelle pour obtenir des résultats d''audit d''accessibilité précis"],"de":["Bietet keine Rechtsberatung oder formelle Zertifizierung","Benötigt manuelle Überprüfung für genaue Barrierefreiheits-Audit-Ergebnisse"],"pt":["Não fornece consultoria jurídica ou certificação formal","Exige verificação manual para resultados de auditoria de acessibilidade precisos"],"ru":["Не предоставляет юридические консультации или официальную сертификацию","Требует ручной верификации для точных результатов аудита доступности"],"ar":["لا توفر استشارة قانونية أو شهادة رسمية","يتطلب التحقق اليدوي للحصول على نتائج دقيقة للتدقيق على الوصول"]},"version":4},"contentHash":"635cdbb0ed83a359