INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ProjectEuropa/Europa/wcag-audit-patterns', 'wcag-audit-patterns', 'ProjectEuropa', 'Europa', 'community', 'wcag-audit-patterns ProjectEuropa Europa community The wcag-audit-patterns skill provides a comprehensive guide to auditing web content against WCAG 2.2 guidelines, benefiting developers and organizations seeking to improve accessibility and meet regulatory requirements. WCAG Audit Patterns 是一个综合指南，用于审计 Web 内容以满足 WCAG 2.2 指南，并提供可行的修复策略 WCAG オーディット パターンは、WCAG 2.2 ガイドラインに従った Web コンテンツの監査と修復戦略を提供する包括的なガイドです WCAG Audit Patterns는 웹 콘텐츠를 WCAG 2.2 가이드라인에 따라 감사하고 수정 전략을 제공하는 종합 가이드입니다 WCAG-Audit-Patterns es una guía integral para auditar contenido web contra las pautas WCAG 2.2 con estrategias de remediation acción WCAG-Audit-Patterns est un guide complet pour auditer le contenu Web contre les directives WCAG 2.2 avec des stratégies de remédiation actionnable WCAG-Audit-Patterns ist ein umfassender Leitfaden zur Auditierung von Webinhalten gegen die WCAG-2.2-Richtlinien mit umsetzbaren Abhilfestrategien O wcag-audit-patterns é uma ferramenta para auditar o conteúdo da web contra as diretrizes WCAG 2.2. Fornece estratégias de remediação para violações de acessibilidade. ИИ Агент wcag-audit-patterns - это инструмент для аудита веб-контента против руководящих принципов WCAG 2.2. Он предоставляет стратегии исправления нарушений доступности. wcag-audit-patterns هو أداة لتدقيق محتوى الويب ضد إرشادات WCAG 2.2. توفر استراتيجيات لتصحيح انتهاكات إمكانية الوصول. how to use wcag-audit-patterns wcag-audit-patterns setup guide wcag 2.2 guidelines accessibility audit tools wcag-audit-patterns alternative ada section 508 compliance vpatt compliance checklist wcag audit patterns install accessibility remediation strategies WCAG Audit Patterns 可访问性审计 WCAG 2.2 指南 修复策略 AI 工具 开发者工具 访问性修复 VPAT 合规 ADA/Section 508 Conducts accessibility audits against WCAG 2.2 guidelines Provides actionable remediation strategies for WCAG violations Supports implementation of accessible components Helps prepare for accessibility lawsuits and meet ADA/Section 508 requirements Assists in achieving VPAT compliance Offers guidance on fixing WCAG violations wcag-audit-patterns is a technical skill that provides a comprehensive guide to auditing web content against WCAG 2.2 guidelines with actionable remediation strategies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ll7/robot_sf_ll7/gh-issue-sequencer', 'community', 'll7', 'robot_sf_ll7', 'll7/robot_sf_ll7', 'gh-issue-sequencer', 4, 2, 44, '2026-02-25T13:40:29Z', '2026-03-06T06:57:52.358Z', '3682499cc4644889c591d6c92a38708d0556d9043b7292742fb08e6412c51ab4', '{"id":"ll7/robot_sf_ll7/gh-issue-sequencer","name":"gh-issue-sequencer","description":{"en":"The gh-issue-sequencer skill helps developers maintain a sequential backlog, ensuring the next work item is always obvious. It achieves a goal state with one issue in progress and a small, explicit queue.","zh":"GH Issue Sequencer是一个用于创建和维护顺序的高信号待办事项列表的AI工具，通过CLI命令如gh project view实现项目板上下文加载","ja":"GH Issue Sequencerは、順序付けられたハイシグナルバックログを作成し維持するためのAIエージェントです。CLIコマンドのgh project viewを使用してプロジェクトボードコンテキストをロードします","ko":"GH Issue Sequencer는 순차적인 높은 신호 백로그를 생성하고 유지하기 위한 AI 에이전트입니다. CLI 명령어인 gh project view를 사용하여 프로젝트 보드 컨텍스트를 로드합니다","es":"El gh-issue-sequencer es una herramienta de gestión de problemas que ayuda a mantener un backlog secuencial y de alta señal. Utiliza comandos como `gh project view` para cargar el contexto de la pizarra del proyecto.","fr":"Le gh-issue-sequencer est un outil de gestion de problèmes qui aide à maintenir un backlog séquentiel et à haute signal. Il utilise des commandes comme `gh project view` pour charger le contexte de la plateforme de projet.","de":"Der gh-issue-sequencer ist ein Tool zur Problemmgmt, das hilft, ein sequenzielles und hochsignifikantes Backlog zu maintaining. Es verwendet Befehle wie `gh project view`, um den Kontext der Projekttafel zu laden.","pt":"O gh-issue-sequencer é uma ferramenta que ajuda a criar e manter uma lista de tarefas sequencial e de alta prioridade","ru":"ИИ Агент gh-issue-sequencer помогает создавать и поддерживать последовательную и приоритетную очередь задач","ar":"أداة غه-إيشو-سيكوينسر تساعد على إنشاء قائمة مهام متسلسلة وذات أولوية عالية"},"seo":{"title":{"en":"gh-issue-sequencer: Sequential Backlog Management for AI ...","zh":"GH Issue Sequencer Setup Guide - AI工具","ja":"GH Issue Sequencer ベストプラクティス - AIエージェント","ko":"GH Issue Sequencer 구축 가이드 - AI 에이전트","es":"Guía de configuración de gh-issue-sequencer para agentes ...","fr":"Guide de mise en place de gh-issue-sequencer pour les out...","de":"Einrichtungsleitfaden für gh-issue-sequencer als KI-Tool","pt":"Guia de Configuração do gh-issue-sequencer para Ferrament...","ru":"Настройка ИИ Агента gh-issue-sequencer для Оптимизации Ра...","ar":"دليل إعداد أداة غه-إيشو-سيكوينسر لتحسين إدارة المشاريع"},"description":{"en":"Discover how gh-issue-sequencer streamlines your workflow by creating a high-signal backlog. Learn how to install and setup this skill for optimal results.","zh":"使用GH Issue Sequencer创建和维护顺序的高信号待办事项列表，提高工作效率。了解更多关于AI工具的信息","ja":"GH Issue Sequencerを使用して順序付けられたハイシグナルバックログを作成し、ワークフローの効率を向上させる。AIエージェントの詳細","ko":"GH Issue Sequencer를 사용하여 순차적인 높은 신호 백로그를 생성하고 유지하여 작업 효율성을 높입니다. AI 에이전트에 대해 자세히 알아보기","es":"Aprende a configurar gh-issue-sequencer para una gestión eficiente de problemas en GitHub con nuestra guía paso a paso","fr":"Découvrez comment configurer gh-issue-sequencer pour une gestion efficace des problèmes sur GitHub avec notre guide étape par étape","de":"Erfahren Sie, wie Sie gh-issue-sequencer für eine effiziente Problemmgmt auf GitHub einrichten können, mit unserem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o gh-issue-sequencer para criar uma lista de tarefas sequencial e de alta prioridade, melhorando a produtividade do seu time de desenvol...","ru":"Узнайте, как настроить ИИ Агент gh-issue-sequencer для создания последовательной и приоритетной очереди задач, повышая эффективность вашей команды разработки","ar":"تعرف على كيفية إعداد أداة غه-إيشو-سيكوينسر لإنشاء قائمة مهام متسلسلة وذات أولوية عالية، وتحسين إنتاجية فريق التطوير"},"definition":{"en":"gh-issue-sequencer is a skill that creates and maintains a sequential, high-signal backlog for AI agents, using commands like `gh project view` to load project board context.","zh":"GH Issue Sequencer是一种AI工具，用于创建和维护顺序的高信号待办事项列表","ja":"GH Issue Sequencerは、順序付けられたハイシグナルバックログを作成し維持するためのAIエージェント","ko":"GH Issue Sequencer는 순차적인 높은 신호 백로그를 생성하고 유지하기 위한 AI 에이전트","es":"El gh-issue-sequencer es una herramienta de gestión de problemas que utiliza comandos CLI para gestionar el estado de los problemas en GitHub","fr":"Le gh-issue-sequencer est un outil de gestion de problèmes qui utilise des commandes CLI pour gérer l''état des problèmes sur GitHub","de":"Der gh-issue-sequencer ist ein Tool zur Problemmgmt, das Befehle der Kommandozeile verwendet, um den Status von Problemen auf GitHub zu verwalten","pt":"O gh-issue-sequencer é uma ferramenta de desenvolvimento que cria e mantém uma lista de tarefas sequencial","ru":"ИИ Агент gh-issue-sequencer - это инструмент разработки, создающий и поддерживающий последовательную очередь задач","ar":"أداة غه-إيشو-سيكوينسر هي أداة تطوير tạo وتنظيم قائمة مهام متسلسلة"},"features":{"en":["Loads project board context using `gh project view 5 --owner ll7 --format json`","Maintains a goal state with exactly one issue `In progress`","Creates a small, explicit queue with issues labeled as `Ready`","Tracks remaining actionable issues with `Todo` or `Tracked` labels","Blocks decision-heavy issues from silently mixing into ready work"],"zh":["加载项目板上下文","创建和维护顺序的高信号待办事项列表","使用CLI命令如gh project view","支持多种工作流状态，如In progress、Ready、Todo和Tracked","支持阻塞和决策密集型问题的标记"],"ja":["プロジェクトボードコンテキストのロード","順序付けられたハイシグナルバックログの作成と維持","CLIコマンドのgh project viewを使用","In progress、Ready、Todo、Trackedなどの複数のワークフローステータスのサポート","ブロックと意思決定密集型問題のラベル付けのサポート"],"ko":["프로젝트 보드 컨텍스트 로드","순차적인 높은 신호 백로그 생성과 유지","CLI 명령어인 gh project view 사용","In progress, Ready, Todo, Tracked 등의 여러 가지 작업 흐름 상태 지원","블록 및 의사 결정 집중형 문제의 라벨링 지원"],"es":["Carga el contexto de la pizarra del proyecto con `gh project view`","Mantiene un backlog secuencial y de alta señal","Utiliza comandos CLI para gestionar el estado de los problemas","Permite etiquetar problemas bloqueados o que requieren decisión","Mantiene una cola explícita de problemas listos para ser trabajados"],"fr":["Charge le contexte de la plateforme de projet avec `gh project view`","Maintient un backlog séquentiel et à haute signal","Utilise des commandes CLI pour gérer l''état des problèmes","Permet d''étiqueter les problèmes bloqués ou qui nécessitent une décision","Maintient une file d''attente explicite de problèmes prêts à être traités"],"de":["Lädt den Kontext der Projekttafel mit `gh project view`","Mantiene ein sequenzielles und hochsignifikantes Backlog","Verwendet Befehle der Kommandozeile, um den Status von Problemen zu verwalten","Ermöglicht das Kennzeichnen von blockierten oder entscheidungsträchtigen Problemen","Mantiene eine explizite Warteschlange von Problemen, die bereit sind, bearbeitet zu werden"],"pt":["Criação de lista de tarefas sequencial","Priorização de tarefas com base em estado de progresso","Integração com o GitHub para visualização de projetos","Suporte a etiquetas para issues bloqueados ou que requerem decisão","Capacidade de manter uma fila explícita de tarefas prontas"],"ru":["Создание последовательной очереди задач","Приоритизация задач на основе состояния прогресса","Интеграция с GitHub для просмотра проектов","Поддержка меток для блокированных или требующих решения задач","Возможность поддерживать явную очередь готовых задач"],"ar":["إنشاء قائمة مهام متسلسلة","تحديد أولوية المهام بناءً على حالة التقدم","التكامل مع غيت هاب لتصور المشاريع","دعم العلامات للمهام المحظورة أو التي تتطلب قرارًا","القدرة على الحفاظ على قائمة مهام جاهزة صريحة"]},"keywords":{"en":["how to use gh-issue-sequencer","gh-issue-sequencer setup guide","gh-issue-sequencer alternative","gh-issue-sequencer vs trello","gh-issue-sequencer install","what is gh-issue-sequencer","gh-issue-sequencer for AI agents","sequential backlog management","high-signal backlog creation"],"zh":["GH Issue Sequencer","AI工具","CLI命令","项目板上下文","顺序的高信号待办事项列表","工作流状态","阻塞和决策密集型问题"],"ja":["GH Issue Sequencer","AIエージェント","CLIコマンド","プロジェクトボードコンテキスト","順序付けられたハイシグナルバックログ","ワークフローステータス","ブロックと意思決定密集型問題"],"ko":["GH Issue Sequencer","AI 에이전트","CLI 명령어","프로젝트 보드 컨텍스트","순차적인 높은 신호 백로그","작업 흐름 상태","블록 및 의사 결정 집중형 문제"],"es":["gh-issue-sequencer","agentes de IA","herramientas de gestión de problemas","GitHub","CLI","gestión de backlog","etiquetado de problemas","cola de problemas"],"fr":["gh-issue-sequencer","outils d''IA","gestion de problèmes","GitHub","CLI","gestion de backlog","étiquetage de problèmes","file d''attente de problèmes"],"de":["gh-issue-sequencer","KI-Tools","Problemmgmt","GitHub","CLI","Backlog-Verwaltung","Kennzeichnen von Problemen","Warteschlange von Problemen"],"pt":["gh-issue-sequencer","ferramentas de desenvolvimento","gestão de projetos","github","priorização de tarefas","listas de tarefas sequenciais","desenvolvimento de software","produtividade do time de desenvolvimento"],"ru":["ИИ Агент gh-issue-sequencer","инструменты разработки","управление проектами","github","приоритизация задач","последовательные очереди задач","разработка программного обеспечения","эффективность команды разработки"],"ar":["أداة غه-إيشو-سيكوينسر","أدوات التطوير","إدارة المشاريع","غيت هاب","تحديد أولوية المهام","قوائم مهام متسلسلة","تطوير البرمجيات","إنتاجية فريق التطوير"]}},"owner":"ll7","repo":"robot_sf_ll7","repoPath":"ll7/robot_sf_ll7","stars":4,"forks":2,"updatedAt":"2026-02-25T13:40:29Z","topics":[],"category":"community","skillMd":{"name":"gh-issue-sequencer","description":"Maintain a clear next-work queue in GitHub by normalizing issue metadata, project status/priority fields, and producing a deterministic execution order.","bodyPreview":"# GH Issue Sequencer\n\n## Overview\n\nUse this skill to create and maintain a sequential, high-signal backlog so the next work item is\nalways obvious.\n\n## Goal State\n\n- Exactly one issue is `In progress`.\n- A small, explicit queue (for example top 3) is `Ready`.\n- Remaining actionable issues are `Todo` or `Tracked`.\n- Blocked/decision-heavy issues are labeled and not silently mixed into ready work.\n\n## Workflow\n\n1. Load project board context\n   - `gh project view 5 --owner ll7 --format json`\n   - `","body":"# GH Issue Sequencer\n\n## Overview\n\nUse this skill to create and maintain a sequential, high-signal backlog so the next work item is\nalways obvious.\n\n## Goal State\n\n- Exactly one issue is `In progress`.\n- A small, explicit queue (for example top 3) is `Ready`.\n- Remaining actionable issues are `Todo` or `Tracked`.\n- Blocked/decision-heavy issues are labeled and not silently mixed into ready work.\n\n## Workflow\n\n1. Load project board context\n   - `gh project view 5 --owner ll7 --format json`\n   - `gh project field-list 5 --owner ll7 --format json`\n   - `gh project item-list 5 --owner ll7 --limit 200 --format json`\n\n2. Normalize metadata for open issues\n   - Ensure issue has meaningful labels (`bug`, `enhancement`, domain labels like `validation`, `training`, `global planner`, `performance`).\n   - Ensure milestone is set when roadmap context exists (for example `benchmark` milestone).\n   - Ensure project `Priority` is set (`Very High`..`Very Low`) for actionable items.\n   - Move stale completed items to `Done`.\n\n3. Classify issues into lanes\n   - `In progress`: actively being implemented now.\n   - `Ready`: clear scope + acceptance criteria + no missing decisions.\n   - `Todo`: valid but not yet ready to start.\n   - `Tracked`: dependent, blocked, or exploratory.\n\n4. Build deterministic order\n   - Rank by:\n     1. `Status` lane (`Ready` first)\n     2. `Priority` (`Very High` to `Very Low`)\n     3. impact label preference (`bug` before `enhancement`, then others)\n     4. age (older issue number first)\n   - Select and mark:\n     - next one as `In progress` (if none already active)\n     - next 2-3 as `Ready`\n     - demote rest to `Todo` / `Tracked` as needed.\n\n5. Publish the sequence\n   - Add/update a project-level summary comment (or issue comment on the selected next issue):\n     - `Now`: `#<issue>`\n     - `Next`: `#<issue>, #<issue>`\n     - `Blocked/Decision`: `#<issue>`\n   - Use `scripts/dev/gh_comment.sh` for multiline formatting.\n\n6. Keep sequence healthy\n   - Remove `Ready` from issues missing acceptance criteria.\n   - Add `decision-required` label for unresolved decisions and move to `Tracked`.\n   - Split oversized issues into follow-ups and link them.\n\n## Practical Commands\n\n- Add issue to project:\n  - `gh project item-add 5 --owner ll7 --url https://github.com/ll7/robot_sf_ll7/issues/<n>`\n- Edit labels/milestone:\n  - `gh issue edit <n> --add-label \"<label1>,<label2>\" --milestone \"<milestone>\"`\n- Update project single-select fields:\n  - `gh project item-edit --id <item_id> --project-id <project_id> --field-id <field_id> --single-select-option-id <option_id>`\n\n## Output Requirements\n\n- Explicitly list:\n  - current `In progress` issue\n  - ordered `Ready` queue\n  - `Tracked` items requiring decisions\n  - any metadata fixes applied (labels, milestone, priority, status)\n"},"lastSynced":"2026-03-06T06:57:52.358Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Integration Agents needing streamlined issue management and sequential backlog maintenance.","zh":"适合需要简化问题管理和顺序积压维护的 GitHub 集成代理。","ja":"GitHub 統合エージェントがストリームライン化された問題管理とシーケンシャルなバックログの維持を必要とする場合に適しています。","ko":"문제 관리와 순차적 백로그 유지 보수를 간소화해야 하는 GitHub 통합 에이전트에 적합합니다.","es":"Ideal para agentes de integración de GitHub que necesitan una gestión de incidencias simplificada y un mantenimiento de backlog secuencial.","fr":"Idéal pour les agents d''intégration GitHub nécessitant une gestion de problèmes simplifiée et une maintenance de backlog séquentielle.","de":"Ideal für GitHub-Integration-Agents, die eine strukturierte Fehlerverwaltung und eine sequenzielle Backlog-Wartung benötigen.","pt":"Ideal para Agentes de Integração do GitHub que necessitam de gerenciamento de problemas simplificado e manutenção de backlog sequencial.","ru":"Идеально подходит для агентов интеграции GitHub, которым необходим упрощенное управление проблемами и последовательное обслуживание бэклога.","ar":"مثالي لعميل تطبيق تكامل GitHub الذي يحتاج إلى إدارة مشاكل مبسطة و صيانة باكلوغ متسلسلة."},"recommendation":{"en":"Empowers agents to maintain a high-signal backlog with features like issue sequencing, project board context loading, and JSON formatting, ensuring the next work item is always obvious through protocols like `gh project view` and data formats like JSON.","zh":"赋予代理维护高信号积压的能力，具有问题排序、项目板上下文加载和 JSON 格式化等功能，通过协议如 `gh project view` 和数据格式如 JSON，确保下一个工作项始终显而易见。","ja":"エージェントが高信号のバックログを維持できるようにすることで、問題のシーケンシング、プロジェクトボードのコンテキストロード、JSON形式などの機能を提供し、`gh project view`などのプロトコルやJSONなどのデータ形式を使用して、次の作業項目が常に明らかであることを保証します。","ko":"에이전트가 높은 신호 백로그를 유지할 수 있도록하여 문제 시퀀싱, 프로젝트 보드 컨텍스트 로딩, JSON 형식화 등의 기능을 제공하고 `gh project view` 등의 프로토콜 및 JSON 등의 데이터 형식을 통해 다음 작업 항목이 항상 명확하게 보장합니다.","es":"Permite a los agentes mantener un backlog de alta señal con características como la secuenciación de incidencias, la carga de contexto de la pizarra del proyecto y el formato JSON, asegurando que el siguiente elemento de trabajo sea siempre obvio a través de protocolos como `gh project view` y formatos de datos como JSON.","fr":"Permet aux agents de maintenir un backlog à haute signal avec des fonctionnalités comme la séquenciation des problèmes, le chargement du contexte de la planche de projet et le formatage JSON, en garantissant que le prochain élément de travail soit toujours évident via des protocoles comme `gh project view` et des formats de données comme JSON.","de":"Ermöglicht es den Agenten, ein Backlog mit hoher Signalstärke zu halten, mit Funktionen wie der Sequenzierung von Fehlern, dem Laden des Projektboard-Kontexts und der JSON-Formatierung, und stellt sicher, dass das nächste Arbeitselement immer durch Protokolle wie `gh project view` und Datenformate wie JSON offensichtlich ist.","pt":"Permite que os agentes mantenham um bêklog de alta capacidade de sinal com recursos como sequenciamento de problemas, carregamento de contexto de quadro de projeto e formatação JSON, garantindo que o próximo item de trabalho seja sempre óbvio por meio de protocolos como `gh project view` e formatos de dados como JSON.","ru":"Позволяет агентам поддерживать бэклог с высокой способностью сигнала с функциями, такими как последовательное управление проблемами, загрузка контекста доски проекта и форматирование JSON, гарантируя, что следующий элемент работы всегда очевиден через протоколы, такие как `gh project view` и форматы данных, такие как JSON.","ar":"تمكن الوكيل من الحفاظ على باكلوغ ذو إشارة عالية باستخدام ميزات مثل تسلسل المشاكل و تحميل سياق لوحة المشروع وتنسيق JSON ، مما يضمن أن يكون العنصر التالي للعمل واضحًا دائمًا من خلال بروتوكولات مثل `gh project view` ونماذج بيانات مثل JSON."},"useCases":{"en":["Automating issue prioritization with a small, explicit queue","Generating a sequential backlog with exactly one issue `In progress`","Maintaining a clear distinction between `Ready`, `Todo`, `Tracked`, and blocked issues"],"zh":["使用小型、显式队列自动化问题优先级","生成具有确切一个问题 `In progress` 的顺序积压","保持 `Ready`、`Todo`、`Tracked` 和阻塞问题之间的明确区别"],"ja":["小規模で明示的なキューを使用して問題の優先順位を自動化する","進行中の問題が正確に1つあるシーケンシャルなバックログを生成する","準備済み、Todo、トラッキング、ブロックされている問題などの区別を明確に維持する"],"ko":["작은 규모의 명시적인 큐를 사용하여 문제 우선순위를 자동화합니다.","진행 중인 문제가 정확히 하나 있는 순차적 백로그를 생성합니다.","준비, Todo, 추적, 차단된 문제 등과 같은 구분을 명확하게 유지합니다."],"es":["Automatización de la priorización de incidencias con una cola pequeña y explícita","Generación de un backlog secuencial con exactamente una incidencia `En progreso`","Mantenimiento de una distinción clara entre incidencias `Listas`, `Por hacer`, `Seguidas` y bloqueadas"],"fr":["Automatisation de la priorisation des problèmes avec une file d''attente petite et explicite","Génération d''un backlog séquentiel avec exactement un problème `En cours`","Maintenance d''une distinction claire entre les problèmes `Prêts`, `À faire`, `Suivis` et bloqués"],"de":["Automatisierung der Priorisierung von Fehlern mit einer kleinen, expliziten Warteschlange","Erzeugung eines sequenziellen Backlogs mit genau einem Fehler `In Bearbeitung`","Beibehaltung einer klaren Unterscheidung zwischen Fehlern `Bereit`, `Zu tun`, `Verfolgt` und blockierten Fehlern"],"pt":["Automatizar a priorização de problemas com uma fila pequena e explícita","Gerar um backlog sequencial com exatamente um problema `Em andamento`","Manter uma distinção clara entre problemas `Pronto`, `Todo`, `Rastreado` e bloqueados"],"ru":["Автоматизировать приоритизацию проблем с помощью небольшой и явной очереди","Генерировать последовательный бэклог с ровно одним проблемой `В процессе`","Поддерживать четкое различие между проблемами `Готово`, `Todo`, `Отслеживаемые` и заблокированные"],"ar":["توفير تلقائي لترتيب أولوية المشاكل باستخدام قائمة صغيرة و صريحة","توليد باكلوغ متسلسل مع مشكلة واحدة فقط `قيد التقدم`","الحفاظ على تمييز واضح بين المشاكل `جاهزة` و `قائمة` و `متابعة` و مشاكل محظورة"]},"limitations":{"en":["Requires GitHub project board access","Limited to GitHub issues and projects","Dependent on `gh` command-line tool for project view and issue management"],"zh":["需要 GitHub 项目板访问权限","仅限 GitHub 问题和项目","依赖于 `gh` 命令行工具进行项目视图和问题管理"],"ja":["GitHub プロジェクトボードへのアクセスが必要","GitHub の問題とプロジェクトのみに限定","`gh` コマンドラインツールに依存してプロジェクトビューと問題管理を行う"],"ko":["GitHub 프로젝트 보드 액세스 권한이 필요합니다.","GitHub 문제 및 프로젝트에만 제한됩니다.","`gh` 명령줄 도구에 의존하여 프로젝트 보기를 표시하고 문제를 관리합니다."],"es":["Requiere acceso a la pizarra del proyecto de GitHub","Limitado a problemas y proyectos de GitHub","Dependiente de la herramienta de línea de comandos `gh` para la vista del proyecto y la gestión de incidencias"],"fr":["Nécessite un accès à la planche de projet GitHub","Limité aux problèmes et projets GitHub","Dépendant de l''outil de ligne de commande `gh` pour la vue de projet et la gestion de problèmes"],"de":["Erfordert Zugriff auf die GitHub-Projektboard","Begrenzt auf GitHub-Probleme und -projekte","Abhängig von der Kommandozeilen-Tool `gh` für die Projektansicht und die Fehlerverwaltung"],"pt":["Exige acesso à placa de projetos do GitHub","Limitado a problemas e projetos do GitHub","Dependente da ferramenta de linha de comando `gh` para visualização de projeto e gerenciamento de problemas"],"ru":["Требует доступа к доске проектов GitHub","Ограничен проблемами и проектами GitHub","Зависит от инструмента командной строки `gh` для просмотра проекта и управления проблемами"],"ar":["يتطلب الوصول إلى لوحة مشروع GitHub","محدود بمشاكل ومشاريع GitHub","يعتمد على أداة سطر الأوامر `gh` لعرض المشروع وإدارة المشاكل"]},"version":4},"contentHash":"3682499cc4644889c591d6c92a38708d0556d9043b7292742fb08e6412c51ab4","qualityScore":44}');
