INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ll7/robot_sf_ll7/gh-issue-sequencer', 'gh-issue-sequencer', 'll7', 'robot_sf_ll7', 'community', 'gh-issue-sequencer ll7 robot_sf_ll7 community The gh-issue-sequencer skill helps developers maintain a sequential backlog, ensuring the next work item is always obvious. It achieves a goal state with one issue in progress and a small, explicit queue. GH Issue Sequencer是一个用于创建和维护顺序的高信号待办事项列表的AI工具，通过CLI命令如gh project view实现项目板上下文加载 GH Issue Sequencerは、順序付けられたハイシグナルバックログを作成し維持するためのAIエージェントです。CLIコマンドのgh project viewを使用してプロジェクトボードコンテキストをロードします GH Issue Sequencer는 순차적인 높은 신호 백로그를 생성하고 유지하기 위한 AI 에이전트입니다. CLI 명령어인 gh project view를 사용하여 프로젝트 보드 컨텍스트를 로드합니다 El gh-issue-sequencer es una herramienta de gestión de problemas que ayuda a mantener un backlog secuencial y de alta señal. Utiliza comandos como `gh project view` para cargar el contexto de la pizarra del proyecto. Le gh-issue-sequencer est un outil de gestion de problèmes qui aide à maintenir un backlog séquentiel et à haute signal. Il utilise des commandes comme `gh project view` pour charger le contexte de la plateforme de projet. Der gh-issue-sequencer ist ein Tool zur Problemmgmt, das hilft, ein sequenzielles und hochsignifikantes Backlog zu maintaining. Es verwendet Befehle wie `gh project view`, um den Kontext der Projekttafel zu laden. O gh-issue-sequencer é uma ferramenta que ajuda a criar e manter uma lista de tarefas sequencial e de alta prioridade ИИ Агент gh-issue-sequencer помогает создавать и поддерживать последовательную и приоритетную очередь задач أداة غه-إيشو-سيكوينسر تساعد على إنشاء قائمة مهام متسلسلة وذات أولوية عالية how to use gh-issue-sequencer gh-issue-sequencer setup guide gh-issue-sequencer alternative gh-issue-sequencer vs trello gh-issue-sequencer install what is gh-issue-sequencer gh-issue-sequencer for AI agents sequential backlog management high-signal backlog creation GH Issue Sequencer AI工具 CLI命令 项目板上下文 顺序的高信号待办事项列表 工作流状态 阻塞和决策密集型问题 Loads project board context using `gh project view 5 --owner ll7 --format json` Maintains a goal state with exactly one issue `In progress` Creates a small, explicit queue with issues labeled as `Ready` Tracks remaining actionable issues with `Todo` or `Tracked` labels Blocks decision-heavy issues from silently mixing into ready work gh-issue-sequencer is a skill that creates and maintains a sequential, high-signal backlog for AI agents, using commands like `gh project view` to load project board context.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jtdesign7277-source/stratify/stratify-platform', 'community', 'jtdesign7277-source', 'stratify', 'jtdesign7277-source/stratify', 'stratify-platform', 1, 0, 44, '2026-03-01T00:47:36Z', '2026-03-06T07:14:34.571Z', 'cd724253295bc072c818c32381e915578049da2ceb8400e7078f70d5f0c5902a', '{"id":"jtdesign7277-source/stratify/stratify-platform","name":"stratify-platform","description":{"en":"The stratify-platform skill enables developers to efficiently manage tasks by following a quick start guide and execution workflow. It benefits developers working on Stratify product projects.","zh":"Stratify 平台是一个开发框架，提供了快速入门和开发指南，包括 UI、数据和混合任务的开发流程","ja":"Stratify プラットフォームは、開発者が効率的に AI エージェントを開発できるように設計された開発フレームワークです","ko":"Stratify 플랫폼은 개발자들이 효율적으로 개발할 수 있도록 설계된 개발 프레임워크로 개발 가이드와 워크플로우를 제공합니다","es":"La plataforma Stratify es una herramienta para desarrolladores que ofrece funcionalidades para la gestión de la interfaz de usuario y la lógica de datos, con recursos para el caché de Redis y el sistema de diseño","fr":"La plateforme Stratify est un outil pour les développeurs qui offre des fonctionnalités pour la gestion de l''interface utilisateur et de la logique de données, avec des ressources pour le cache Redis et le système de conception","de":"Die Stratify-Plattform ist ein Werkzeug für Entwickler, das Funktionen für die Verwaltung von Benutzeroberflächen und Datenlogik bietet, mit Ressourcen für Redis-Caching und Design-System","pt":"A plataforma Stratify é uma solução poderosa para desenvolvedores. Siga nosso guia para configurar e otimizar a plataforma.","ru":"Платформа Stratify - это мощное решение для разработчиков. Следуйте нашему руководству, чтобы настроить и оптимизировать платформу.","ar":"منصة Stratify هي حل قوي للمطورين. اتبع دليلنا لتحديد الإعداد وتحسين المنصة."},"seo":{"title":{"en":"stratify-platform: Setup Guide for AI Agents | AI Agent S...","zh":"Stratify 平台开发指南 - 快速入门和最佳实践","ja":"Stratify プラットフォームの設定方法 - AIエージェント開発ガイド","ko":"Stratify 플랫폼 개발 설정 가이드 - 효율적인 워크플로우","es":"Guía de Configuración de la Plataforma Stratify para Desa...","fr":"Guide de Mise en Route de la Plateforme Stratify pour les...","de":"Einrichtungsleitfaden für die Stratify-Plattform für Entw...","pt":"Guia de Configuração da Plataforma Stratify","ru":"Настройка Stratify Платформы: Лучшие Практики","ar":"إعداد منصة Stratify: دليل المستخدم"},"description":{"en":"Unlock the full potential of stratify-platform with our expert guide. Learn how to navigate platform-rules, design-system, and redis-caching for seamless tas...","zh":"了解 Stratify 平台的技术细节和开发流程，提高开发效率和代码质量","ja":"Stratify プラットフォームの開発方法とベストプラクティスを学び、AIエージェント開発を効率化する","ko":"Stratify 플랫폼의 개발 워크플로우와 기술 세부 정보를 익히고 개발 생산성을 향상시키는 방법","es":"Aprende a configurar y utilizar la plataforma Stratify con nuestros recursos y guías para desarrolladores, incluyendo pautas para UI/UX y caché de Redis","fr":"Découvrez comment configurer et utiliser la plateforme Stratify avec nos ressources et guides pour les développeurs, y compris des directives pour l''UI/UX et...","de":"Erfahren Sie, wie Sie die Stratify-Plattform konfigurieren und verwenden können, mit unseren Ressourcen und Anleitungen für Entwickler, einschließlich Richtl...","pt":"Aprenda a configurar a plataforma Stratify com nosso guia passo a passo. Descubra como otimizar o desempenho e a escalabilidade da sua aplicação.","ru":"Узнайте, как настроить платформу Stratify с нашей пошаговой инструкцией. Откройте для себя, как оптимизировать производительность и масштабируемость вашего п...","ar":"تعلم كيفية إعداد منصة Stratify مع دليلنا المتواصل. اكتشف كيفية تحسين الأداء والتنقل في تطبيقك."},"definition":{"en":"stratify-platform is a development framework that provides guidelines for task classification, UI/UX design, and data fetching using references like platform-rules.md and redis-caching.md.","zh":"Stratify 平台是一种开发框架，用于构建和管理 AI 应用程序","ja":"Stratify プラットフォームは、AI エージェントの開発と管理に使用される開発フレームワークです","ko":"Stratify 플랫폼은 AI 애플리케이션을 개발하고 관리하기 위한 개발 프레임워크입니다","es":"La plataforma Stratify es una herramienta de desarrollo que permite a los desarrolladores gestionar la interfaz de usuario y la lógica de datos de manera eficiente","fr":"La plateforme Stratify est un outil de développement qui permet aux développeurs de gérer l''interface utilisateur et la logique de données de manière efficace","de":"Die Stratify-Plattform ist ein Entwicklungstool, das es Entwicklern ermöglicht, die Benutzeroberfläche und die Datenlogik effizient zu verwalten","pt":"A plataforma Stratify é uma ferramenta de desenvolvimento que permite a criação de aplicações escaláveis e de alto desempenho.","ru":"Платформа Stratify - это инструмент для разработки, который позволяет создавать масштабируемые и высокопроизводительные приложения.","ar":"منصة Stratify هي أداة تطوير تسمح بإنشاء تطبيقات قابلة للتمديد وأداء عالي."},"features":{"en":["Classifies tasks as ui, data, or hybrid for efficient execution","Utilizes platform-rules.md for initial task setup and configuration","Leverages design-system.md for UI/UX design and development","Employs redis-caching.md for optimized data fetching and loading behavior","Supports execution workflow for streamlined task management"],"zh":["支持 UI、数据和混合任务的开发","提供快速入门和开发指南","包括 Redis 缓存和设计系统的支持","支持多种开发任务的分类和执行"],"ja":["UI、データ、ハイブリッド タスクの開発をサポート","クイックスタートと開発ガイドを提供","Redis キャッシングとデザインシステムをサポート","開発タスクの分類と実行をサポート"],"ko":["UI, 데이터, 하이브리드 태스크 개발 지원","개발 가이드와 빠른 시작 제공","Redis 캐싱과 디자인 시스템 지원","개발 태스크의 분류와 실행 지원"],"es":["Gestión de la interfaz de usuario con el sistema de diseño","Lógica de datos con caché de Redis","Flujo de trabajo de ejecución para tareas de UI y datos","Recursos para el desarrollo de aplicaciones híbridas","Compatibilidad con la gestión de la carga y el comportamiento de las pestañas"],"fr":["Gestion de l''interface utilisateur avec le système de conception","Logique de données avec cache Redis","Flux de travail d''exécution pour les tâches d''UI et de données","Ressources pour le développement d''applications hybrides","Compatibilité avec la gestion de la charge et du comportement des onglets"],"de":["Verwaltung der Benutzeroberfläche mit dem Design-System","Datenlogik mit Redis-Caching","Ausführungsworkflow für UI- und Datenaufgaben","Ressourcen für die Entwicklung von Hybrid-Anwendungen","Kompatibilität mit der Verwaltung von Ladeverhalten und Registerkarten"],"pt":["Suporte a UI/UX personalizadas","Otimização de desempenho com Redis caching","Flexibilidade na execução de tarefas de dados e lógica híbrida","Integração com sistemas de design","Suporte a múltiplos padrões de execução"],"ru":["Поддержка настраиваемых UI/UX","Оптимизация производительности с помощью Redis кэширования","Гибкость в выполнении задач данных и гибридной логики","Интеграция с системами дизайна","Поддержка нескольких моделей выполнения"],"ar":["دعم واجهات المستخدم واجهة المستخدم وواجهة المستخدم القابلة للتعديل","تحسين الأداء مع ذاكرة التخزين المؤقت Redis","المرونة في تنفيذ مهام البيانات والمنطق الهجين","التكامل مع أنظمة التصميم","دعم نماذج التنفيذ المتعددة"]},"keywords":{"en":["how to use stratify-platform","stratify-platform setup guide","stratify-platform vs competing platforms","stratify-platform install","what is stratify-platform","stratify-platform alternative","stratify-platform documentation","stratify-platform tutorial","stratify-platform best practices"],"zh":["Stratify 平台","AI 开发","开发框架","快速入门","开发指南","Redis 缓存","设计系统","混合任务开发"],"ja":["Stratify プラットフォーム","AI エージェント開発","開発フレームワーク","クイックスタート","開発ガイド","Redis キャッシング","デザインシステム","ハイブリッド タスク開発"],"ko":["Stratify 플랫폼","AI 개발","개발 프레임워크","개발 가이드","快速 시작","Redis 캐싱","디자인 시스템","하이브리드 태스크 개발"],"es":["plataforma Stratify","desarrollo de aplicaciones","gestión de la interfaz de usuario","lógica de datos","caché de Redis","sistema de diseño","flujo de trabajo de ejecución","desarrollo de aplicaciones híbridas"],"fr":["plateforme Stratify","développement d''applications","gestion de l''interface utilisateur","logique de données","cache Redis","système de conception","flux de travail d''exécution","développement d''applications hybrides"],"de":["Stratify-Plattform","Anwendungsentwicklung","Verwaltung der Benutzeroberfläche","Datenlogik","Redis-Caching","Design-System","Ausführungsworkflow","Hybrid-Anwendungsentwicklung"],"pt":["plataforma stratify","desenvolvimento de aplicações","otimização de desempenho","redis caching","ui/ux personalizadas","execução de tarefas de dados","lógica híbrida"],"ru":["платформа stratify","разработка приложений","оптимизация производительности","redis кэширование","настраиваемые ui/ux","выполнение задач данных","гибридная логика"],"ar":["منصة stratify","تطوير التطبيقات","تحسين الأداء","ذاكرة التخزين المؤقت redis","واجهات المستخدم وواجهة المستخدم القابلة للتعديل","تنفيذ مهام البيانات","المنطق الهجين"]}},"owner":"jtdesign7277-source","repo":"stratify","repoPath":"jtdesign7277-source/stratify","stars":1,"forks":0,"updatedAt":"2026-03-01T00:47:36Z","topics":[],"category":"community","skillMd":{"name":"stratify-platform","description":"Build, refactor, and review Stratify platform features while enforcing cache-first market-data flows, tab preloading, terminal-pro dark UI patterns, Vercel serverless API architecture, and production delivery conventions. Use when work touches Stratify dashboard components, API routes, strategy builder behavior, market data streaming, deployment readiness, or AI search result rendering.","bodyPreview":"# Stratify Platform\n\nFollow this skill for any Stratify product work.\n\n## Quick Start\n\n1. Read `references/platform-rules.md` first.\n2. If the task changes UI/UX, read `references/design-system.md` before editing files.\n3. If the task changes data fetching, API routes, tabs, or loading behavior, read `references/redis-caching.md` before editing files.\n4. If the task includes both UI and data logic, read both reference files.\n\n## Execution Workflow\n\n1. Classify the task as `ui`, `data`, or `hybri","body":"# Stratify Platform\n\nFollow this skill for any Stratify product work.\n\n## Quick Start\n\n1. Read `references/platform-rules.md` first.\n2. If the task changes UI/UX, read `references/design-system.md` before editing files.\n3. If the task changes data fetching, API routes, tabs, or loading behavior, read `references/redis-caching.md` before editing files.\n4. If the task includes both UI and data logic, read both reference files.\n\n## Execution Workflow\n\n1. Classify the task as `ui`, `data`, or `hybrid`.\n2. Map affected files and integration points before coding.\n3. Implement using Stratify hard rules (cache-first, no cold loads, error boundaries, Vercel-first APIs, Twelve Data `/quote`, `$` ticker formatting).\n4. Add or update preloading for adjacent tabs when data is shown in tabbed views.\n5. Ensure live data handoff uses cached snapshot first, then WebSocket updates.\n6. Validate no secrets are hardcoded and env vars are used consistently.\n7. Verify behavior with hard refresh and tab switching.\n\n## Output Contract\n\nWhen generating handoff prompts for Jeff:\n\n- Output `🟢 CODEX PROMPT` for UI/visual implementation tasks.\n- Output `🔵 CLAUDE CLI PROMPT` for code/logic implementation tasks.\n- If task includes both, output both blocks in that order.\n- Include Mission Control activity logging in all generated execution prompts by posting to `https://mission-control-seven-henna.vercel.app/api/activity` with `source`, `action`, `status`, and `duration`.\n\n## References\n\n- `references/platform-rules.md`: Canonical hard rules, architecture, delivery workflow, and search-result formatting.\n- `references/design-system.md`: Terminal-pro visual system, UI patterns, and component quality bar.\n- `references/redis-caching.md`: Cache-first fetch pattern, preloading behavior, and WebSocket handoff requirements.\n"},"lastSynced":"2026-03-06T07:14:34.571Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents working on Stratify product projects needing streamlined task management and execution workflow.","zh":"非常适合在Stratify产品项目中需要简化任务管理和执行工作流的开发代理","ja":"Stratify製品プロジェクトでタスク管理と実行ワークフローを簡素化する必要がある開発エージェントに最適","ko":"Stratify 제품 프로젝트에서 작업 관리와 실행 워크플ロー가 간소화되어야 하는 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo que trabajan en proyectos de productos Stratify que necesitan una gestión de tareas y un flujo de trabajo de ejecución optimizados.","fr":"Parfait pour les agents de développement qui travaillent sur des projets de produits Stratify nécessitant une gestion de tâches et un flux de travail d''exécution rationalisés.","de":"Perfekt für Entwicklungsmittel, die an Stratify-Produktprojekten arbeiten und eine optimierte Aufgabenverwaltung und Ausführungsworkflow benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que trabalham em projetos de produtos Stratify que necessitam de gerenciamento de tarefas e fluxo de trabalho de execução otimizados.","ru":"Идеально подходит для агентов разработки, работающих над проектами продуктов Stratify, требующих оптимизированного управления задачами и потоком выполнения.","ar":"مثالي لعميل التطوير الذي يعمل على مشاريع منتجات Stratify التي تحتاج إلى إدارة مهام وعمليات تشغيل منسقة"},"recommendation":{"en":"Empowers agents to efficiently manage tasks by following a structured quick start guide and execution workflow, utilizing reference files such as `platform-rules.md`, `design-system.md`, and `redis-caching.md` to ensure consistency and accuracy in UI/UX and data fetching tasks.","zh":"使代理能够通过遵循结构化的快速入门指南和执行工作流，利用诸如`platform-rules.md`、`design-system.md`和`redis-caching.md`的参考文件来确保UI/UX和数据获取任务的一致性和准确性","ja":"エージェントが構造化されたクイックスタートガイドと実行ワークフローに従ってタスクを効率的に管理できるようにし、`platform-rules.md`、`design-system.md`、`redis-caching.md`などのリファレンスファイルを使用して、UI/UXとデータ取得タスクのの一貫性と正確性を確保する","ko":"에이전트가 구조화된 빠른 시작 가이드와 실행 워크플로를 따르며 `platform-rules.md`, `design-system.md`, `redis-caching.md` 같은 참조 파일을 사용하여 UI/UX와 데이터 가져오기 작업의 일관성과 정확성을 보장하도록 함","es":"Habilita a los agentes a gestionar tareas de manera eficiente siguiendo una guía de inicio rápido estructurada y un flujo de trabajo de ejecución, utilizando archivos de referencia como `platform-rules.md`, `design-system.md` y `redis-caching.md` para asegurar la consistencia y la precisión en tareas de UI/UX y recuperación de datos.","fr":"Autonomise les agents pour gérer les tâches de manière efficace en suivant un guide de démarrage rapide structuré et un flux de travail d''exécution, en utilisant des fichiers de référence tels que `platform-rules.md`, `design-system.md` et `redis-caching.md` pour assurer la cohérence et la précision dans les tâches de UI/UX et de récupération de données.","de":"Ermöglicht es den Agenten, Aufgaben effizient zu verwalten, indem sie einer strukturierten Schnellstartanleitung und einem Ausführungsworkflow folgen und Referenzdateien wie `platform-rules.md`, `design-system.md` und `redis-caching.md` verwenden, um Konsistenz und Genauigkeit bei UI/UX- und Datenabrufaufgaben sicherzustellen.","pt":"Habilita os agentes a gerenciar tarefas de forma eficiente, seguindo um guia de início rápido estruturado e fluxo de trabalho de execução, utilizando arquivos de referência como `platform-rules.md`, `design-system.md` e `redis-caching.md` para garantir consistência e precisão em tarefas de UI/UX e recuperação de dados.","ru":"Наделяет агентов возможностью эффективно управлять задачами, следуя поструктурированному быстрому руководству и потоку выполнения, используя справочные файлы, такие как `platform-rules.md`, `design-system.md` и `redis-caching.md`, для обеспечения согласованности и точности задач UI/UX и извлечения данных.","ar":"تمكّن الوكيل من إدارة المهام بفعالية من خلال اتباع دليل بدء سريع منظم وعمليات تشغيل، باستخدام ملفات مرجعية مثل `platform-rules.md` و `design-system.md` و `redis-caching.md` لضمان الاتساق والدقة في مهام واجهة المستخدم وتصميم تجربة المستخدم وFetcher البيانات."},"useCases":{"en":["Automating Stratify product development workflows","Generating consistent UI/UX designs using the design system","Optimizing data fetching and caching using Redis"],"zh":["自动化Stratify产品开发工作流","使用设计系统生成一致的UI/UX设计","使用Redis优化数据获取和缓存"],"ja":["Stratify製品開発ワークフローの自動化","デザインシステムを使用して一貫性のあるUI/UXデザインを生成する","Redisを使用してデータ取得とキャッシングを最適化する"],"ko":["Stratify 제품 개발 워크플러의 자동화","디자인 시스템을 사용하여 일관된 UI/UX 디자인을 생성","Redis를 사용하여 데이터 가져오기와 캐싱을 최적화"],"es":["Automatización de flujos de trabajo de desarrollo de productos Stratify","Generación de diseños de UI/UX coherentes utilizando el sistema de diseño","Optimización de la recuperación y almacenamiento en caché de datos utilizando Redis"],"fr":["Automatisation des flux de travail de développement de produits Stratify","Génération de conceptions UI/UX cohérentes en utilisant le système de conception","Optimisation de la récupération et du stockage en cache des données en utilisant Redis"],"de":["Automatisierung von Entwicklungswerkfluss für Stratify-Produkte","Erzeugung konsistenter UI/UX-Designs unter Verwendung des Design-Systems","Optimierung des Abrufs und Zwischenspeicherns von Daten unter Verwendung von Redis"],"pt":["Automatizar fluxos de trabalho de desenvolvimento de produtos Stratify","Gerar projetos de design de UI/UX consistentes usando o sistema de design","Otimizar a recuperação e o cache de dados usando Redis"],"ru":["Автоматизировать рабочие потоки разработки продуктов Stratify","Генерировать последовательные проекты дизайна UI/UX, используя систему дизайна","Оптимизировать извлечение и кэширование данных с помощью Redis"],"ar":["توفير مسارات عمل автомاتيكية لتطوير منتجات Stratify","إنشاء تصاميم UI/UX متسقة باستخدام نظام التصميم","تحسين استرجاع البيانات وتخزينها باستخدام Redis"]},"limitations":{"en":["Requires access to Stratify product project files and references","Limited to Stratify platform-specific tasks and workflows"],"zh":["需要访问Stratify产品项目文件和参考资料","仅限于Stratify平台特定的任务和工作流"],"ja":["Stratify製品プロジェクトファイルとリファレンスへのアクセスが必要","Stratifyプラットフォーム特有のタスクとワークフローに限定される"],"ko":["Stratify 제품 프로젝트 파일과 참조 자료에 대한 액세스가 필요","Stratify 플랫폼 특정 작업 및 워크플로에만 제한"],"es":["Requiere acceso a archivos y referencias de proyectos de productos Stratify","Limitado a tareas y flujos de trabajo específicos de la plataforma Stratify"],"fr":["Nécessite un accès aux fichiers et références de projets de produits Stratify","Limité aux tâches et flux de travail spécifiques à la plate-forme Stratify"],"de":["Erfordert Zugriff auf Dateien und Referenzen von Stratify-Produktprojekten","Begrenzt auf Plattform-spezifische Aufgaben und Workflows von Stratify"],"pt":["Requer acesso a arquivos e referências de projetos de produtos Stratify","Limitado a tarefas e fluxos de trabalho específicos da plataforma Stratify"],"ru":["Требует доступа к файлам и справочным материалам проектов продуктов Stratify","Ограничен задачами и рабочими потоками, специфичными для платформы Stratify"],"ar":["يتطلب الوصول إلى ملفات ومراجع مشاريع منتجات Stratify","محدود بمهام وعمليات تشغيل محددة لمنصة Stratify"]},"version":4},"contentHash":"cd724253295bc072c818c32381e915578049da2ceb8400e7078f70d5f0c5902a","qualityScore":44}');
