INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jtdesign7277-source/stratify/stratify-platform', 'stratify-platform', 'jtdesign7277-source', 'stratify', 'community', 'stratify-platform jtdesign7277-source stratify community The stratify-platform skill enables developers to efficiently manage tasks by following a quick start guide and execution workflow. It benefits developers working on Stratify product projects. Stratify 平台是一个开发框架，提供了快速入门和开发指南，包括 UI、数据和混合任务的开发流程 Stratify プラットフォームは、開発者が効率的に AI エージェントを開発できるように設計された開発フレームワークです Stratify 플랫폼은 개발자들이 효율적으로 개발할 수 있도록 설계된 개발 프레임워크로 개발 가이드와 워크플로우를 제공합니다 La plataforma Stratify es una herramienta para desarrolladores que ofrece funcionalidades para la gestión de la interfaz de usuario y la lógica de datos, con recursos para el caché de Redis y el sistema de diseño La plateforme Stratify est un outil pour les développeurs qui offre des fonctionnalités pour la gestion de l''interface utilisateur et de la logique de données, avec des ressources pour le cache Redis et le système de conception Die Stratify-Plattform ist ein Werkzeug für Entwickler, das Funktionen für die Verwaltung von Benutzeroberflächen und Datenlogik bietet, mit Ressourcen für Redis-Caching und Design-System A plataforma Stratify é uma solução poderosa para desenvolvedores. Siga nosso guia para configurar e otimizar a plataforma. Платформа Stratify - это мощное решение для разработчиков. Следуйте нашему руководству, чтобы настроить и оптимизировать платформу. منصة Stratify هي حل قوي للمطورين. اتبع دليلنا لتحديد الإعداد وتحسين المنصة. how to use stratify-platform stratify-platform setup guide stratify-platform vs competing platforms stratify-platform install what is stratify-platform stratify-platform alternative stratify-platform documentation stratify-platform tutorial stratify-platform best practices Stratify 平台 AI 开发 开发框架 快速入门 开发指南 Redis 缓存 设计系统 混合任务开发 Classifies tasks as ui, data, or hybrid for efficient execution Utilizes platform-rules.md for initial task setup and configuration Leverages design-system.md for UI/UX design and development Employs redis-caching.md for optimized data fetching and loading behavior Supports execution workflow for streamlined task management stratify-platform is a development framework that provides guidelines for task classification, UI/UX design, and data fetching using references like platform-rules.md and redis-caching.md.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pkuppens/on_prem_rag/api-design', 'community', 'pkuppens', 'on_prem_rag', 'pkuppens/on_prem_rag', 'api-design', 1, 0, 44, '2026-03-02T16:07:14Z', '2026-03-07T01:55:03.378Z', '14fdc56f9cb88d847c7ab409f02d58aaea7b763bad621f703ce9f25edd2ed24e', '{"id":"pkuppens/on_prem_rag/api-design","name":"api-design","description":{"en":"The api-design skill helps developers design and refine API endpoints, leveraging lessons from v0 to v1 redesign. It benefits developers working on new routes, refactoring existing ones, or reviewing API changes.","zh":"API 设计技能用于设计新 API 端点、重构现有路由或审查 API 更改，包含 v0→v1 重构的经验教训","ja":"API デザインスキルは、新しい API エンドポイントを設計するために使用され、既存のルートをリファクタリングする、または API の変更をレビューするためのもので、v0→v1 リデザインの教訓を含む","ko":"API 디자인 스킬은 새로운 API 엔드포인트를 설계하거나 기존 라우터를 리팩토링하거나 API 변경을 검토하는 데 사용되며 v0→v1 리디자인의 교훈을 포함","es":"El diseño de API es crucial para desarrolladores. Nuestro enfoque combina reglas de HTTP, verbos y códigos de estado para una integración eficaz","fr":"La conception d''API est essentielle pour les développeurs. Notre approche combine des règles HTTP, des verbes et des codes d''état pour une intégration efficace","de":"Das API-Design ist für Entwickler von entscheidender Bedeutung. Unser Ansatz kombiniert HTTP-Regeln, Verben und Statuscodes für eine effektive Integration","pt":"O skill de API Design ajuda a criar APIs eficazes, refatorando rotas e revisando alterações de API. Incorpora lições da redesign de v0 para v1.","ru":"Навык API Design помогает создавать эффективные API, рефакторить маршруты и просматривать изменения API. Включает уроки из редизайна v0 в v1.","ar":"مهارة تصميم واجهة برمجة التطبيقات تساعد على إنشاء واجهات برمجة التطبيقات الفعالة، واعادة هيكلة المسارات ومراجعة التغييرات على واجهة برمجة التطبيقات. تشمل دروس من إعادة التصميم من v0 إلى v1."},"seo":{"title":{"en":"api-design: Best Practices for API Endpoints | AI Agent S...","zh":"API 设计最佳实践指南 - AIエージェント","ja":"API デザイン設定ガイド - AIエージェント","ko":"API 디자인 설정 가이드 - AI 에이전트","es":"Guía de Diseño de API: Mejores Prácticas para Desarrollad...","fr":"Conception d''API: Guide de Configuration pour les Dévelop...","de":"API-Design-Leitfaden: Best Practices für Entwickler","pt":"Guia de Configuração de API Design: Melhores Práticas par...","ru":"Настройка ИИ Агента API Design: Руководство по Лучшим Пра...","ar":"دليل تصميم واجهة برمجة التطبيقات: إرشادات لتصميم واجهات ب..."},"description":{"en":"Discover how to optimize API design with expert guidance on HTTP verbs, status codes, and OpenAPI documentation. Learn more and improve your API development ...","zh":"了解 API 设计的关键规则和最佳实践，包括 HTTP 动词和状态码，用于构建强大的 API","ja":"API デザインの重要なルールとベストプラクティスを学ぶ、HTTP 動詞とステータスコードを含む","ko":"API 디자인의 핵심 규칙과最佳实践을 알아보세요. HTTP 동사와 상태 코드 포함","es":"Aprende a diseñar API efectivas con nuestras mejores prácticas y reglas para HTTP, verbos y códigos de estado","fr":"Découvrez comment concevoir des API efficaces avec nos meilleures pratiques et règles pour HTTP, verbes et codes d''état","de":"Erfahren Sie, wie Sie effektive APIs entwerfen können, mit unseren Best Practices und Regeln für HTTP, Verben und Statuscodes","pt":"Aprenda a projetar APIs eficazes com o skill de API Design. Descubra como criar endpoints, refatorar rotas e revisar alterações de API de forma eficiente.","ru":"Узнайте, как проектировать эффективные API с помощью навыка API Design. Откройте для себя, как создавать конечные точки, рефакторить маршруты и просматривать...","ar":"تعلم كيفية تصميم واجهات برمجة التطبيقات الفعالة باستخدام مهارة تصميم واجهة برمجة التطبيقات. اكتشف كيفية إنشاء نقاط نهاية واعادة هيكلة المسارات ومراجعة التغيي..."},"definition":{"en":"api-design is a skill that provides guidelines for designing and optimizing API endpoints, including the use of HTTP verbs, status codes, and OpenAPI documentation.","zh":"API 设计是指设计和构建 API 的过程，包括定义 HTTP 动词和状态码","ja":"API デザインは、API を設計して構築するプロセスで、HTTP 動詞とステータスコードを定義することを含む","ko":"API 디자인은 API를 설계하고 구축하는 프로세스로 HTTP 동사와 상태 코드를 정의하는 것을 포함","es":"El diseño de API se refiere al proceso de creación de interfaces de programación de aplicaciones para interactuar con sistemas y servicios","fr":"La conception d''API fait référence au processus de création d''interfaces de programmation d''applications pour interagir avec des systèmes et des services","de":"Das API-Design bezeichnet den Prozess der Erstellung von Programmierschnittstellen für die Interaktion mit Systemen und Diensten","pt":"API Design é a prática de projetar e desenvolver interfaces de programação de aplicações eficazes.","ru":"API Design - это практика проектирования и разработки эффективных интерфейсов программирования приложений.","ar":"تصميم واجهة برمجة التطبيقات هو ممارسة تصميم وتنمية واجهات برمجة التطبيقات الفعالة"},"features":{"en":["Incorporates lessons from v0→v1 redesign for improved API endpoint design","Supports review of API documentation using OpenAPI, /docs, and /redoc","Provides guidance on choosing between new endpoints and extending existing ones","Helps with refactoring document upload, ask, query, or chat endpoints","Offers best practices for using HTTP verbs and status codes","Assists in deciding when to add new routes or routers"],"zh":["HTTP 动词和状态码的使用","API 端点的设计和重构","请求/响应模型的更改","文档上传、询问、查询或聊天端点的重构","API 文档的审查（OpenAPI、/docs、/redoc）"],"ja":["HTTP 動詞とステータスコードの使用","API エンドポイントの設計とリファクタリング","リクエスト/レスポンスモデルの変更","ドキュメントアップロード、問い合わせ、クエリ、またはチャットエンドポイントのリファクタリング","API ドキュメントのレビュー（OpenAPI、/docs、/redoc）"],"ko":["HTTP 동사와 상태 코드의 사용","API 엔드포인트의 설계 및 리팩토링","요청/응답 모델의 변경","문서 업로드, 조회, 쿼리 또는 채팅 엔드포인트의 리팩토링","API 문서의 검토（OpenAPI、/docs、/redoc）"],"es":["Reglas de HTTP y códigos de estado para una integración eficaz","Diseño de endpoints y rutas de API","Refactorización de documentos y modelos de solicitud/resolución","Revisión de la documentación de API (OpenAPI, /docs, /redoc)","Decisión entre nuevos endpoints y la extensión de los existentes"],"fr":["Règles HTTP et codes d''état pour une intégration efficace","Conception d''endpoints et de routes d''API","Refactoring de documents et de modèles de requête/réponse","Révision de la documentation d''API (OpenAPI, /docs, /redoc)","Décision entre de nouveaux endpoints et l''extension des existants"],"de":["HTTP-Regeln und Statuscodes für eine effektive Integration","Entwurf von Endpoints und API-Routen","Refactoring von Dokumenten und Anfrage/Antwort-Modellen","Überprüfung der API-Dokumentation (OpenAPI, /docs, /redoc)","Entscheidung zwischen neuen Endpoints und der Erweiterung bestehender"],"pt":["Criação de endpoints de API","Refatoração de rotas existentes","Revisão de alterações de API","Uso de verbos HTTP e códigos de status","Decisão entre novos endpoints e extensão de existentes"],"ru":["Создание конечных точек API","Рефакторинг существующих маршрутов","Просмотр изменений API","Использование глаголов HTTP и кодов состояния","Решение между новыми конечными точками и расширением существующих"],"ar":["إنشاء نقاط نهاية لواجهة برمجة التطبيقات","إعادة هيكلة المسارات الحالية","مراجعة التغييرات على واجهة برمجة التطبيقات","استخدام أفعال HTTP وأكواد الحالة","القرار بين نقاط نهاية جديدة وتمديد النقاط الحالية"]},"keywords":{"en":["how to use api-design","api-design best practices","api-design vs RESTful API","api-design setup guide","what is api-design","api-design alternative","api-design for AI agents","api-design and OpenAPI","api-design HTTP verbs","api-design status codes"],"zh":["API 设计","HTTP 动词","状态码","API 端点设计","API 重构","AIエージェント","API 设计最佳实践","API 设计指南"],"ja":["API デザイン","HTTP 動詞","ステータスコード","API エンドポイント設計","API リファクタリング","AIエージェント","API デザインベストプラクティス","API デザインガイド"],"ko":["API 디자인","HTTP 동사","상태 코드","API 엔드포인트 설계","API 리팩토링","AI 에이전트","API 디자인最佳实践","API 디자인 가이드"],"es":["diseño de API","reglas de HTTP","códigos de estado","endpoints de API","documentación de API","OpenAPI","refactorización de API","mejores prácticas de API"],"fr":["conception d''API","règles HTTP","codes d''état","endpoints d''API","documentation d''API","OpenAPI","refactoring d''API","meilleures pratiques d''API"],"de":["API-Design","HTTP-Regeln","Statuscodes","API-Endpunkte","API-Dokumentation","OpenAPI","API-Refactoring","Best Practices für APIs"],"pt":["API Design","desenvolvimento de API","criação de endpoints","refatoração de rotas","revisão de alterações de API","verbos HTTP","códigos de status","desenvolvedores de API"],"ru":["API Design","разработка API","создание конечных точек","рефакторинг маршрутов","просмотр изменений API","глаголы HTTP","коды состояния","разработчики API"],"ar":["تصميم واجهة برمجة التطبيقات","تنمية واجهة برمجة التطبيقات","إنشاء نقاط نهاية","إعادة هيكلة المسارات","مراجعة التغييرات على واجهة برمجة التطبيقات","أفعال HTTP","أكواد الحالة","مطورو واجهة برمجة التطبيقات"]}},"owner":"pkuppens","repo":"on_prem_rag","repoPath":"pkuppens/on_prem_rag","stars":1,"forks":0,"updatedAt":"2026-03-02T16:07:14Z","topics":[],"category":"community","skillMd":{"name":"api-design","description":"Enforce API design rules when adding or changing endpoints. Apply REST conventions, versioning, deduplication semantics, OpenAPI documentation.","bodyPreview":"# API Design Skill\n\nUse when designing new API endpoints, refactoring existing routes, or reviewing API changes. Incorporates lessons from the v0→v1 redesign.\n\n## When to Invoke\n\n- Adding a new route or router\n- Changing request/response models\n- Refactoring document upload, ask, query, or chat endpoints\n- Reviewing API documentation (OpenAPI, /docs, /redoc)\n- Deciding between new endpoint vs extending existing\n\n## Core Rules (from API_DESIGN.md)\n\n### 1. HTTP Verbs and Status Codes\n\n| Verb | Use","body":"# API Design Skill\n\nUse when designing new API endpoints, refactoring existing routes, or reviewing API changes. Incorporates lessons from the v0→v1 redesign.\n\n## When to Invoke\n\n- Adding a new route or router\n- Changing request/response models\n- Refactoring document upload, ask, query, or chat endpoints\n- Reviewing API documentation (OpenAPI, /docs, /redoc)\n- Deciding between new endpoint vs extending existing\n\n## Core Rules (from API_DESIGN.md)\n\n### 1. HTTP Verbs and Status Codes\n\n| Verb | Use | Idempotent |\n|------|-----|------------|\n| GET | Retrieve, list, health | Yes |\n| POST | Create, action (ask, transcribe) | No (unless designed) |\n| PUT | Replace resource | Yes |\n| DELETE | Remove | Yes |\n\n**Upload semantics (implemented)**:\n- New: 201 Created, `created: true`\n- Duplicate (hash match): 200 OK, `created: false` — no file saved, no processing\n\n### 2. Resource Naming\n\n- Plural nouns: `/api/documents`, not `/api/document`\n- Hierarchical: `/api/documents/{id}/chunks`\n- No verbs in URLs; use HTTP method\n- RPC-style actions OK for domain operations: `/api/ask`, `/api/ask/voice`\n\n### 3. New vs Extend\n\n**Create new** when: different resource, different contract, clear separation.\n**Extend** when: same resource, minor variant, additive params.\n\nExample: `/api/ask` + `/api/ask/voice` — extend. `/api/query` vs `/api/ask` — separate (chunks vs answer).\n\n### 4. Anti-Patterns (from current codebase)\n\n- **Duplicate endpoints**: `POST /api/documents/upload` and `POST /api/v1/upload` — consolidate in v1.\n- **Overlapping semantics**: document list by router — unify contract.\n- **Missing OpenAPI metadata**: add tags, summary, description, examples.\n\n### 5. Checklist Before PR\n\n- Correct HTTP verb\n- Consistent naming\n- OpenAPI tags, description, examples\n- Pydantic models for request/response\n- Unit tests for route\n- API_ENDPOINTS.md updated\n\n## References\n\n- [API_DESIGN.md](../../../docs/technical/API_DESIGN.md)\n- [FEATURE_DESIGN_GUIDELINES.md](../../../docs/technical/FEATURE_DESIGN_GUIDELINES.md)\n- [API_ENDPOINTS.md](../../../docs/technical/API_ENDPOINTS.md)\n- [.cursor/rules/api-design.mdc](../../rules/api-design.mdc)\n"},"lastSynced":"2026-03-07T01:55:03.378Z","agentAnalysis":{"suitability":{"en":"Ideal for API-focused Agents requiring structured endpoint design and refinement capabilities.","zh":"适用于需要结构化端点设计和完善能力的API焦点代理。","ja":"API に焦点を当てたエージェントが構造化されたエンドポイントの設計と改良機能を必要とする場合に最適です。","ko":"구조화된 엔드ポイント 설계 및 세부 사항 기능이 필요한 API 중점 에이전트에 적합합니다.","es":"Ideal para Agentes centrados en API que requieren diseño y refinamiento de puntos de conexión estructurados.","fr":"Idéal pour les agents axés sur l''API nécessitant une conception et un raffinement de points de terminaison structurés.","de":"Ideal für API-fokussierte Agenten, die ein strukturiertes Endpunkt-Design und Verfeinerungsfähigkeiten erfordern.","pt":"Ideal para Agentes focados em API que requerem design de endpoint estruturado e capacidades de refinamento.","ru":"Идеально для агентов, ориентированных на API, требующих структурированного дизайна конечных точек и возможностей совершенствования.","ar":"مثالي للوكلاء المهتمين بالواجهة البرمجية التي تتطلب تصميم نهاية نقطة منظم وقدرات تحسين."},"recommendation":{"en":"Empowers agents to design and refine API endpoints leveraging lessons from v0 to v1 redesign, incorporating HTTP verbs, status codes, and OpenAPI documentation standards.","zh":"赋予代理设计和完善API端点的能力，利用从v0到v1的重构经验，融入HTTP动词、状态代码和OpenAPI文档标准。","ja":"エージェントに API エンドポイントを設計および改良する機能を提供し、v0 から v1 へのリデザインから得られた教訓を活用し、HTTP 動詞、ステータス コード、および OpenAPI ドキュメント標準を取り入れています。","ko":"에이전트에게 API 엔드포인트를 설계하고 세부 사항을 변경할 수 있는 기능을 부여하여 v0에서 v1로의 재설계에서 얻은 교훈을 활용하고 HTTP 동사, 상태 코드 및 OpenAPI 문서 표준을 통합합니다.","es":"Habilita a los agentes a diseñar y refinar puntos de conexión de API aprovechando las lecciones de la redesignación de v0 a v1, incorporando verbos HTTP, códigos de estado y estándares de documentación de OpenAPI.","fr":"Permet aux agents de concevoir et de raffiner les points de terminaison de l''API en exploitant les leçons de la révision de v0 à v1, en intégrant les verbes HTTP, les codes d''état et les normes de documentation OpenAPI.","de":"Ermöglich es Agenten, API-Endpunkte zu entwerfen und zu verfeinern, indem sie die Lektionen aus der Neugestaltung von v0 bis v1 nutzen, HTTP-Verben, Statuscodes und OpenAPI-Dokumentationsstandards einbeziehen.","pt":"Habilita os agentes a projetar e aperfeiçoar endpoints de API aproveitando lições do redesenho da v0 para a v1, incorporando verbos HTTP, códigos de status e padrões de documentação OpenAPI.","ru":"Наделяет агентов возможностью проектировать и совершенствовать конечные точки API, используя уроки, извлеченные из переработки v0 в v1, включая глаголы HTTP, коды состояния и стандарты документации OpenAPI.","ar":"تمكين الوكلاء من تصميم ونعيم نقاط النهاية API باستخدام الدروس المستفادة من إعادة التصميم من v0 إلى v1 ، ودمج أفعال HTTP وأكواد الحالة ومعايير توثيق OpenAPI."},"useCases":{"en":["Refactoring existing API routes for improved performance","Designing new API endpoints with standardized HTTP verbs and status codes","Reviewing API changes for consistency and best practices"],"zh":["重构现有的API路由以提高性能","使用标准化的HTTP动词和状态代码设计新的API端点","查看API更改以确保一致性和最佳实践"],"ja":["パフォーマンスの向上のために既存の API ルートをリファクタリングする","標準化された HTTP 動詞とステータス コードを使用して新しい API エンドポイントを設計する","一貫性とベスト プラクティスを確保するために API の変更を確認する"],"ko":["성능을 개선하기 위해 기존 API 경로를 리팩토링하는 것","표준화된 HTTP 동사 및 상태 코드를 사용하여 새로운 API 엔드포인트를 설계하는 것","일관성 및 모범 사례를 보장하기 위해 API 변경 사항을 검토하는 것"],"es":["Reestructuración de rutas de API existentes para mejorar el rendimiento","Diseño de nuevos puntos de conexión de API con verbos HTTP y códigos de estado estandarizados","Revisión de cambios de API para la coherencia y las mejores prácticas"],"fr":["Réorganisation des routes API existantes pour améliorer les performances","Conception de nouveaux points de terminaison d''API avec des verbes HTTP et des codes d''état standardisés","Examen des modifications d''API pour la cohérence et les meilleures pratiques"],"de":["Umstrukturierung bestehender API-Routen für verbesserte Leistung","Entwurf neuer API-Endpunkte mit standardisierten HTTP-Verben und Statuscodes","Überprüfung von API-Änderungen auf Konsistenz und Best Practices"],"pt":["Reestruturação de rotas de API existentes para melhorar o desempenho","Projeto de novos endpoints de API com verbos HTTP e códigos de status padronizados","Revisão das alterações de API para consistência e boas práticas"],"ru":["Перепроектирование существующих маршрутов API для повышения производительности","Проектирование новых конечных точек API со стандартизированными глаголами HTTP и кодами состояния","Проверка изменений API на соответствие и лучшие практики"],"ar":["إعادة هيكلة مسارات الواجهة البرمجية الحالية لتحسين الأداء","تصميم نقاط نهاية واجهة برمجية جديدة مع أفعال HTTP وأكواد الحالة الموحدة","استعراض تغييرات الواجهة البرمجية للاتساق وأفضل الممارسات"]},"limitations":{"en":["Requires understanding of API design principles","Limited to API endpoint design and refinement"],"zh":["需要了解API设计原则","仅限API端点设计和完善"],"ja":["API デザインの原則を理解する必要がある","API エンドポイントの設計および改良に限定される"],"ko":["API 설계 원칙을 이해해야 함","API 엔드포인트 설계 및 세부 사항에만 제한됨"],"es":["Requiere comprensión de los principios de diseño de API","Limitado al diseño y refinamiento de puntos de conexión de API"],"fr":["Nécessite une compréhension des principes de conception d''API","Limité à la conception et au raffinement des points de terminaison d''API"],"de":["Benötigt Verständnis für API-Designprinzipien","Begrenzt auf API-Endpunkt-Design und Verfeinerung"],"pt":["Exige compreensão dos princípios de design de API","Limitado ao design e refinamento de endpoints de API"],"ru":["Требует понимания принципов дизайна API","Ограничен только дизайном и совершенствованием конечных точек API"],"ar":["يتطلب فهم مبادئ تصميم الواجهة البرمجية","محدود بتصميم نقاط النهاية واجهة برمجية وتنقيحها"]},"version":4},"contentHash":"14fdc56f9cb88d847c7ab409f02d58aaea7b763bad621f703ce9f25edd2ed24e","qualityScore":44}');
DELETE FROM skills_fts WHERE id = 'pkuppens/on_prem_rag/api-design';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pkuppens/on_prem_rag/api-design', 'api-design', 'pkuppens', 'on_prem_rag', 'community', 'api-design pkuppens on_prem_rag community The api-design skill helps developers design and refine API endpoints, leveraging lessons from v0 to v1 redesign. It benefits developers working on new routes, refactoring existing ones, or reviewing API changes. API 设计技能用于设计新 API 端点、重构现有路由或审查 API 更改，包含 v0→v1 重构的经验教训 API デザインスキルは、新しい API エンドポイントを設計するために使用され、既存のルートをリファクタリングする、または API の変更をレビューするためのもので、v0→v1 リデザインの教訓を含む API 디자인 스킬은 새로운 API 엔드포인트를 설계하거나 기존 라우터를 리팩토링하거나 API 변경을 검토하는 데 사용되며 v0→v1 리디자인의 교훈을 포함 El diseño de API es crucial para desarrolladores. Nuestro enfoque combina reglas de HTTP, verbos y códigos de estado para una integración eficaz La conception d''API est essentielle pour les développeurs. Notre approche combine des règles HTTP, des verbes et des codes d''état pour une intégration efficace Das API-Design ist für Entwickler von entscheidender Bedeutung. Unser Ansatz kombiniert HTTP-Regeln, Verben und Statuscodes für eine effektive Integration O skill de API Design ajuda a criar APIs eficazes, refatorando rotas e revisando alterações de API. Incorpora lições da redesign de v0 para v1. Навык API Design помогает создавать эффективные API, рефакторить маршруты и просматривать изменения API. Включает уроки из редизайна v0 в v1. مهارة تصميم واجهة برمجة التطبيقات تساعد على إنشاء واجهات برمجة التطبيقات الفعالة، واعادة هيكلة المسارات ومراجعة التغييرات على واجهة برمجة التطبيقات. تشمل دروس من إعادة التصميم من v0 إلى v1. how to use api-design api-design best practices api-design vs RESTful API api-design setup guide what is api-design api-design alternative api-design for AI agents api-design and OpenAPI api-design HTTP verbs api-design status codes API 设计 HTTP 动词 状态码 API 端点设计 API 重构 AIエージェント API 设计最佳实践 API 设计指南 Incorporates lessons from v0→v1 redesign for improved API endpoint design Supports review of API documentation using OpenAPI, /docs, and /redoc Provides guidance on choosing between new endpoints and extending existing ones Helps with refactoring document upload, ask, query, or chat endpoints Offers best practices for using HTTP verbs and status codes Assists in deciding when to add new routes or routers api-design is a skill that provides guidelines for designing and optimizing API endpoints, including the use of HTTP verbs, status codes, and OpenAPI documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frankxai/arcanea-ai-app/arcanea-react-best-practices', 'community', 'frankxai', 'arcanea-ai-app', 'frankxai/arcanea-ai-app', 'arcanea-react-best-practices', 1, 0, 44, '2026-03-04T23:47:20Z', '2026-03-06T07:19:46.935Z', '13a84c193d645815faf7c6a22530a023b87257a918f6475a04c5602991d761f5', '{"id":"frankxai/arcanea-ai-app/arcanea-react-best-practices","name":"arcanea-react-best-practices","description":{"en":"The arcanea-react-best-practices skill provides a comprehensive guide to building high-performance React applications using Next.js 16 App Router, React 19, and TypeScript strict. Developers can optimize their components and eliminate waterfalls with this skill.","zh":"Arcanea React 最佳实践指南，帮助您构建高性能的 Next.js 16 应用，使用 React 19、TypeScript strict、Supabase 和 Vercel AI SDK 6","ja":"Arcanea React ベストプラクティス - Next.js 16 アプリのパフォーマンスを向上させる React 19、TypeScript strict、Supabase、Vercel AI SDK 6 の使用方法","ko":"Arcanea React 최적화 가이드 - Next.js 16 애플리케이션의 성능을 향상시키는 React 19, TypeScript strict, Supabase, Vercel AI SDK 6의 사용 방법","es":"Arcanea React Best Practices proporciona un conjunto de reglas para mejorar el rendimiento de su aplicación, incluyendo la eliminación de waterfalls y la reducción del tamaño de bundles.","fr":"Arcanea React Best Practices fournit un ensemble de règles pour améliorer les performances de votre application, notamment l''élimination des waterfalls et la réduction de la taille des bundles.","de":"Arcanea React Best Practices bietet eine Reihe von Regeln, um die Leistung Ihrer Anwendung zu verbessern, einschließlich der Beseitigung von Waterfalls und der Reduzierung der Bundle-Größe.","pt":"O Arcanea React é uma plataforma que combina Next.js, React e TypeScript para desenvolver aplicações escaláveis e eficientes. Aprenda a configurar com as melhores práticas.","ru":"Arcanea React - это платформа, которая объединяет Next.js, React и TypeScript для разработки масштабируемых и эффективных приложений. Узнайте, как настроить с лучшими практиками - ИИ Агенты","ar":"Arcanea React هي منصة تجمع بين Next.js و React و TypeScript لتطوير تطبيقات قابلة للتوسعة والفعالة. تعلم كيفية إعداد بأفضل الممارسات - أدوات ذكاء اصطناعي"},"seo":{"title":{"en":"arcanea-react-best-practices: Next.js 16 App Router Setup...","zh":"Arcanea React 最佳实践指南 - Setup Guide","ja":"Arcanea React ベストプラクティス - AIエージェントの設定方法","ko":"Arcanea React 최적화 가이드 - AI 도구 설정 방법","es":"Guía de configuración de Arcanea React Best Practices","fr":"Guide de mise en place des meilleures pratiques Arcanea R...","de":"Einrichtungsleitfaden für Arcanea React Best Practices","pt":"Configuração de Melhores Práticas para Arcanea React","ru":"Настройка Лучших Практик для Arcanea React - ИИ Агенты","ar":"إعداد أفضل الممارسات ل Arcanea React - أدوات ذكاء اصطناعي"},"description":{"en":"Unlock the secrets of Arcanea React with our expert guide to Next.js 16 App Router, React 19, and TypeScript strict. Get started now and optimize your compon...","zh":"了解 Arcanea React 最佳实践，优化您的 Next.js 16 应用，利用 React 19、TypeScript strict、Supabase 和 Vercel AI SDK 6","ja":"Arcanea React のベストプラクティスを学び、Next.js 16 アプリを最適化する - React 19、TypeScript strict、Supabase、Vercel AI SDK 6 を使用","ko":"Arcanea React 최적화 방법을 배우고 Next.js 16 애플리케이션을 최적화하세요 - React 19, TypeScript strict, Supabase, Vercel AI SDK 6 사용","es":"Optimice su aplicación con las mejores prácticas de Arcanea React, incluyendo Next.js 16 App Router y React 19","fr":"Optimisez votre application avec les meilleures pratiques Arcanea React, notamment Next.js 16 App Router et React 19","de":"Optimieren Sie Ihre Anwendung mit den besten Praktiken von Arcanea React, einschließlich Next.js 16 App Router und React 19","pt":"Aprenda a configurar o Arcanea React com as melhores práticas para desenvolver aplicações escaláveis e eficientes com Next.js, React e TypeScript","ru":"Узнайте, как настроить Arcanea React с лучшими практиками для разработки масштабируемых и эффективных приложений с Next.js, React и TypeScript - ИИ Агенты","ar":"تعلم كيفية إعداد Arcanea React بأفضل الممارسات لتطوير تطبيقات قابلة للتوسعة والفعالة مع Next.js و React و TypeScript - أدوات ذكاء اصطناعي"},"definition":{"en":"arcanea-react-best-practices is a set of guidelines for building optimized React applications using Next.js 16 App Router, React 19, and TypeScript strict, ensuring efficient component flow and minimal waterfalls.","zh":"Arcanea React 最佳实践是指使用 Next.js 16、React 19、TypeScript strict、Supabase 和 Vercel AI SDK 6 构建高性能应用的方法","ja":"Arcanea React ベストプラクティスは、Next.js 16、React 19、TypeScript strict、Supabase、Vercel AI SDK 6 を使用して高パフォーマンスのアプリを構築する方法","ko":"Arcanea React 최적화는 Next.js 16, React 19, TypeScript strict, Supabase, Vercel AI SDK 6를 사용하여 고성능 애플리케이션을 구축하는 방법입니다","es":"Arcanea React Best Practices es un conjunto de reglas para mejorar la calidad y el rendimiento de aplicaciones React","fr":"Arcanea React Best Practices est un ensemble de règles pour améliorer la qualité et les performances des applications React","de":"Arcanea React Best Practices ist eine Reihe von Regeln, um die Qualität und Leistung von React-Anwendungen zu verbessern","pt":"O que é Arcanea React? É uma plataforma que combina tecnologias para desenvolver aplicações escaláveis e eficientes","ru":"Что такое Arcanea React? Это платформа, которая объединяет технологии для разработки масштабируемых и эффективных приложений - ИИ Агенты","ar":"ما هي Arcanea React? هي منصة تجمع بين التكنولوجيا لتطوير تطبيقات قابلة للتوسعة والفعالة - أدوات ذكاء اصطناعي"},"features":{"en":["Utilizes Next.js 16 App Router for efficient routing","Leverages React 19 for improved component performance","Enforces TypeScript strict for robust type checking","Integrates with Supabase for scalable data management","Optimizes component flow using Vercel AI SDK 6"],"zh":["Next.js 16 App Router 集成","React 19 支持","TypeScript strict 模式","Supabase 数据库支持","Vercel AI SDK 6 集成"],"ja":["Next.js 16 App Router の統合","React 19 のサポート","TypeScript strict モード","Supabase データベースのサポート","Vercel AI SDK 6 の統合"],"ko":["Next.js 16 App Router 통합","React 19 지원","TypeScript strict 모드","Supabase 데이터베이스 지원","Vercel AI SDK 6 통합"],"es":["Eliminación de waterfalls con async-","Reducción del tamaño de bundles","Integración con Next.js 16 App Router","Compatibilidad con React 19","Uso de TypeScript strict","Integración con Supabase y Vercel AI SDK 6"],"fr":["Élimination des waterfalls avec async-","Réduction de la taille des bundles","Intégration avec Next.js 16 App Router","Compatibilité avec React 19","Utilisation de TypeScript strict","Intégration avec Supabase et Vercel AI SDK 6"],"de":["Beseitigung von Waterfalls mit async-","Reduzierung der Bundle-Größe","Integration mit Next.js 16 App Router","Kompatibilität mit React 19","Verwendung von TypeScript strict","Integration mit Supabase und Vercel AI SDK 6"],"pt":["Utiliza Next.js 16 App Router para desenvolver aplicações escaláveis","Combina React 19 com TypeScript strict para melhorar a eficiência","Integra Supabase para gerenciar dados de forma eficaz","Utiliza Vercel AI SDK 6 para melhorar a inteligência artificial","Segui as 57 regras de melhores práticas da Vercel Engineering","Elimina waterfalls com a categoria de regras de prioridade 1"],"ru":["Использует Next.js 16 App Router для разработки масштабируемых приложений","Объединяет React 19 с TypeScript strict для повышения эффективности","Интегрирует Supabase для управления данными в эффективном порядке","Использует Vercel AI SDK 6 для улучшения искусственного интеллекта","Следует 57 правилам лучших практик от Vercel Engineering - ИИ Агенты","Устраняет водопады с категорией правил приоритета 1"],"ar":["يستخدم Next.js 16 App Router لتطوير تطبيقات قابلة للتوسعة","يجمع بين React 19 و TypeScript strict لتحسين الفعالية","يدمج Supabase لإدارة البيانات بفعالية","يستخدم Vercel AI SDK 6 لتحسين الذكاء الاصطناعي","يتبع 57 قاعدة لمعايير أفضل الممارسات من Vercel Engineering - أدوات ذكاء اصطناعي","يحذف المياه المتساقطة مع فئة قواعد الأولوية 1"]},"keywords":{"en":["how to use arcanea-react-best-practices","arcanea-react-best-practices setup guide","Next.js 16 App Router tutorial","React 19 optimization techniques","TypeScript strict best practices","arcanea-react-best-practices vs create-react-app"],"zh":["Arcanea React","Next.js 16","React 19","TypeScript strict","Supabase","Vercel AI SDK 6","AI 工具","前端开发最佳实践"],"ja":["Arcanea React","Next.js 16","React 19","TypeScript strict","Supabase","Vercel AI SDK 6","AI エージェント","フロントエンド開発ベストプラクティス"],"ko":["Arcanea React","Next.js 16","React 19","TypeScript strict","Supabase","Vercel AI SDK 6","AI 도구","프론트엔드 개발 최적화"],"es":["Arcanea React","mejores prácticas","Next.js 16 App Router","React 19","TypeScript strict","Supabase","Vercel AI SDK 6","eliminación de waterfalls","reducción del tamaño de bundles"],"fr":["Arcanea React","meilleures pratiques","Next.js 16 App Router","React 19","TypeScript strict","Supabase","Vercel AI SDK 6","élimination des waterfalls","réduction de la taille des bundles"],"de":["Arcanea React","beste Praktiken","Next.js 16 App Router","React 19","TypeScript strict","Supabase","Vercel AI SDK 6","Beseitigung von Waterfalls","Reduzierung der Bundle-Größe"],"pt":["Arcanea React","melhores práticas","Next.js","React","TypeScript","Supabase","Vercel AI SDK","desenvolvimento de aplicações","escalabilidade","eficiência"],"ru":["Arcanea React","лучшие практики","Next.js","React","TypeScript","Supabase","Vercel AI SDK","разработка приложений","масштабируемость","эффективность","ИИ Агенты"],"ar":["Arcanea React","أفضل الممارسات","Next.js","React","TypeScript","Supabase","Vercel AI SDK","تطوير التطبيقات","القدرة على التوسعة","الفعالية","أدوات ذكاء اصطناعي"]}},"owner":"frankxai","repo":"arcanea-ai-app","repoPath":"frankxai/arcanea-ai-app","stars":1,"forks":0,"updatedAt":"2026-03-04T23:47:20Z","topics":["ai-infrastructure","context-engineering","creative-intelligence","guardian-pattern","living-intelligence","multi-agent"],"category":"community","skillMd":{"name":"arcanea-react-best-practices","description":"React 19 and Next.js 16 performance optimization for the Arcanea platform. Use when writing, reviewing, or refactoring React components, data fetching logic, bundle optimization, or any frontend performance work. Triggers on: React components, Next.js pages, hooks, data fetching, bundle size, re-renders, Server Components, Client Components, hydration. Sourced from Vercel Engineerings official React best practices (57 rules, 8 categories) and adapted for the Arcanea stack.","version":"1.0.0","bodyPreview":"# Arcanea React Best Practices\n\n> *\"Leyla guards the Gate of Flow at 285 Hz. Your components must flow, not block. Every waterfall is a Flow violation.\"*\n\nAdapted from Vercel Engineering''s 57-rule guide for the Arcanea stack: **Next.js 16 App Router + React 19 + TypeScript strict + Supabase + Vercel AI SDK 6**.\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Eliminating Waterfalls | CRITICAL | `async-` |\n| 2 | Bundle Size","body":"# Arcanea React Best Practices\n\n> *\"Leyla guards the Gate of Flow at 285 Hz. Your components must flow, not block. Every waterfall is a Flow violation.\"*\n\nAdapted from Vercel Engineering''s 57-rule guide for the Arcanea stack: **Next.js 16 App Router + React 19 + TypeScript strict + Supabase + Vercel AI SDK 6**.\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Eliminating Waterfalls | CRITICAL | `async-` |\n| 2 | Bundle Size | CRITICAL | `bundle-` |\n| 3 | Server-Side | HIGH | `server-` |\n| 4 | Client Data Fetching | MEDIUM-HIGH | `client-` |\n| 5 | Re-render Optimization | MEDIUM | `rerender-` |\n| 6 | Rendering Performance | MEDIUM | `rendering-` |\n| 7 | JavaScript Performance | LOW-MEDIUM | `js-` |\n| 8 | Advanced Patterns | LOW | `advanced-` |\n\n---\n\n## 1. Eliminating Waterfalls (CRITICAL)\n\n### `async-parallel` — Use Promise.all for independent fetches\n```typescript\n// BAD — serial waterfall\nconst user = await getUser(id)\nconst posts = await getUserPosts(id) // waits for user unnecessarily\n\n// GOOD — parallel\nconst [user, posts] = await Promise.all([getUser(id), getUserPosts(id)])\n```\n\n### `async-defer-await` — Move await to where it''s actually needed\n```typescript\n// BAD\nasync function handler() {\n  const data = await fetchData() // awaited before branch\n  if (condition) return data\n  return null\n}\n\n// GOOD\nasync function handler() {\n  const dataPromise = fetchData() // start early\n  if (!condition) return null\n  return await dataPromise // await only when needed\n}\n```\n\n### `async-suspense-boundaries` — Stream content with Suspense\n```tsx\n// In Arcanea pages — wrap slow data in Suspense for progressive rendering\nexport default function LorePage() {\n  return (\n    <Suspense fallback={<GlassCardSkeleton />}>\n      <LoreContent /> {/* streams in independently */}\n    </Suspense>\n  )\n}\n```\n\n### `async-api-routes` — Start promises early in route handlers\n```typescript\n// app/api/guardians/route.ts\nexport async function GET() {\n  const guardianPromise = supabase.from(''guardians'').select() // start immediately\n  // ... validation/auth work ...\n  const { data } = await guardianPromise // await late\n  return Response.json(data)\n}\n```\n\n---\n\n## 2. Bundle Size (CRITICAL)\n\n### `bundle-barrel-imports` — Import directly, never from barrel files\n```typescript\n// BAD — pulls in entire barrel\nimport { Button, Card, Modal } from ''@/components/ui''\n\n// GOOD — direct imports\nimport { Button } from ''@/components/ui/button''\nimport { Card } from ''@/components/ui/card''\n```\n\n### `bundle-dynamic-imports` — Lazy-load heavy components\n```typescript\n// Heavy Arcanea components: GlobeMap, PromptEditor, LoreCanvas\nimport dynamic from ''next/dynamic''\n\nconst LoreCanvas = dynamic(() => import(''@/components/lore/LoreCanvas''), {\n  loading: () => <GlassCardSkeleton />,\n  ssr: false, // client-only canvas\n})\n```\n\n### `bundle-defer-third-party` — Analytics after hydration\n```typescript\n// In Arcanea layout — defer non-critical scripts\nimport { GoogleAnalytics } from ''@next/third-parties/google''\n// Renders after hydration automatically via next/third-parties\n```\n\n---\n\n## 3. Server-Side Performance (HIGH)\n\n### `server-cache-react` — Deduplicate DB calls per request\n```typescript\n// lib/supabase-cached.ts — use React.cache for per-request dedup\nimport { cache } from ''react''\nimport { supabase } from ''@/lib/supabase''\n\nexport const getGuardian = cache(async (gateName: string) => {\n  const { data } = await supabase\n    .from(''guardians'')\n    .select()\n    .eq(''gate'', gateName)\n    .single()\n  return data\n})\n// Multiple RSCs can call getGuardian(''Fire'') — only one DB query\n```\n\n### `server-auth-actions` — Always authenticate Server Actions\n```typescript\n// app/actions/prompt.ts\n''use server''\nimport { createServerClient } from ''@/lib/supabase-server''\n\nexport async function savePrompt(data: PromptData) {\n  const supabase = createServerClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) throw new Error(''Unauthorized'') // NEVER skip this\n  // ...\n}\n```\n\n### `server-parallel-fetching` — Restructure RSC to parallelize\n```typescript\n// BAD — sequential RSC\nasync function GuardianPage({ gate }: { gate: string }) {\n  const guardian = await getGuardian(gate) // serial\n  const godbeast = await getGodbeast(guardian.id) // waits\n}\n\n// GOOD — parallel RSC\nasync function GuardianPage({ gate }: { gate: string }) {\n  const [guardian, godbeast] = await Promise.all([\n    getGuardian(gate),\n    getGodBeastByGate(gate), // use gate directly\n  ])\n}\n```\n\n---\n\n## 4. Client Data Fetching (MEDIUM-HIGH)\n\n### `client-swr-dedup` — SWR/React Query for client fetches\n```typescript\n// Prefer SWR for client-side Arcanea data\nimport useSWR from ''swr''\n\nfunction useGuardians() {\n  return useSWR(''/api/guardians'', fetcher, {\n    revalidateOnFocus: false, // lore data doesn''t change often\n  })\n}\n```\n\n---\n\n## 5. Re-render Optimization (MEDIUM)\n\n### `rerender-memo` — Memoize expensive Arcanea components\n```typescript\n// Heavy visual components: GuardianCard, LoreGrid, GodBeastProfile\nimport { memo } from ''react''\n\nconst GuardianCard = memo(function GuardianCard({ guardian }: Props) {\n  return <div className=\"glass-card\">...</div>\n})\n```\n\n### `rerender-derived-state-no-effect` — Derive during render\n```typescript\n// BAD — unnecessary effect\nconst [filteredGuardians, setFiltered] = useState([])\nuseEffect(() => {\n  setFiltered(guardians.filter(g => g.element === selectedElement))\n}, [guardians, selectedElement])\n\n// GOOD — derive during render\nconst filteredGuardians = guardians.filter(g => g.element === selectedElement)\n```\n\n### `rerender-lazy-state-init` — Lazy init for expensive state\n```typescript\n// BAD — recalculates every render\nconst [state, setState] = useState(computeExpensiveDefault())\n\n// GOOD — only runs once\nconst [state, setState] = useState(() => computeExpensiveDefault())\n```\n\n### `rerender-transitions` — Non-urgent updates via startTransition\n```typescript\nimport { useTransition } from ''react''\n\nfunction GateFilter() {\n  const [isPending, startTransition] = useTransition()\n  \n  return (\n    <select onChange={e => startTransition(() => setGate(e.target.value))}>\n      {/* Gate filter won''t block urgent UI updates */}\n    </select>\n  )\n}\n```\n\n---\n\n## 6. Rendering Performance (MEDIUM)\n\n### `rendering-hoist-jsx` — Extract static JSX outside components\n```typescript\n// BAD — recreated every render\nfunction GuardianList() {\n  const header = <h2 className=\"text-gradient-aurora\">The Ten Gates</h2>\n  return <div>{header}{items}</div>\n}\n\n// GOOD — hoisted static\nconst HEADER = <h2 className=\"text-gradient-aurora\">The Ten Gates</h2>\nfunction GuardianList() {\n  return <div>{HEADER}{items}</div>\n}\n```\n\n### `rendering-conditional-render` — Ternary, not &&\n```typescript\n// BAD — renders \"0\" if count is 0\n{count && <Badge>{count}</Badge>}\n\n// GOOD\n{count > 0 ? <Badge>{count}</Badge> : null}\n```\n\n---\n\n## 7. JavaScript Performance (LOW-MEDIUM)\n\n### `js-index-maps` — Map for repeated lookups\n```typescript\n// BAD — O(n) per lookup\nfunction getGuardian(gate: string) {\n  return guardians.find(g => g.gate === gate)\n}\n\n// GOOD — O(1) lookup\nconst guardianMap = new Map(guardians.map(g => [g.gate, g]))\nconst getGuardian = (gate: string) => guardianMap.get(gate)\n```\n\n### `js-early-exit` — Return early from functions\n```typescript\n// GOOD Arcanea pattern\nfunction validateGateUnlock(user: User, gate: Gate): ValidationResult {\n  if (!user.authenticated) return { valid: false, reason: ''unauthenticated'' }\n  if (user.gatesOpen < gate.requiredRank) return { valid: false, reason: ''rank'' }\n  if (gate.locked) return { valid: false, reason: ''sealed'' }\n  return { valid: true }\n}\n```\n\n---\n\n## 8. Arcanea-Specific Patterns\n\n### AI SDK 6 — Vercel AI SDK streaming\n```typescript\n// app/api/guardian-chat/route.ts — AI SDK 6 pattern\nimport { streamText } from ''ai''\nimport { google } from ''@ai-sdk/google''\n\nexport async function POST(req: Request) {\n  const { messages } = await req.json()\n  const result = streamText({\n    model: google(''gemini-2.5-flash''),\n    messages,\n    maxOutputTokens: 2048, // NOT maxTokens (SDK 6 change)\n  })\n  return result.toUIMessageStreamResponse() // NOT toDataStreamResponse (SDK 6)\n}\n```\n\n### Supabase Auth in Server Components\n```typescript\n// Always use server-side auth for SSR\nimport { createServerClient } from ''@supabase/ssr''\nimport { cookies } from ''next/headers''\n\nexport async function getServerUser() {\n  const cookieStore = cookies()\n  const supabase = createServerClient(\n    process.env.NEXT_PUBLIC_SUPABASE_URL!,\n    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,\n    { cookies: { get: (name) => cookieStore.get(name)?.value } }\n  )\n  const { data: { user } } = await supabase.auth.getUser()\n  return user\n}\n```\n\n### Glass Components — Design System compliance\n```typescript\n// Always use Arcanean Design System classes\n// See: .arcanea/design/DESIGN_BIBLE.md\n\n// Glass tiers: glass-subtle (8px) | glass (16px) | glass-strong (24px) | liquid-glass (40px)\n// Text: text-gradient-aurora | text-gradient-gold | text-gradient-violet\n// Animations: float | pulse-glow | shimmer | cosmic-drift\n// FONTS: Inter everywhere (NO Cinzel in new code — MEMORY.md override)\n\nfunction GuardianCard({ guardian }: Props) {\n  return (\n    <div className=\"glass hover-lift glow-card\">\n      <h3 className=\"text-gradient-aurora\">{guardian.name}</h3>\n    </div>\n  )\n}\n```\n\n---\n\n## Quick Checklist\n\nBefore any React/Next.js PR in Arcanea:\n\n- [ ] No sequential awaits where Promise.all applies\n- [ ] Heavy components use `next/dynamic`\n- [ ] No barrel imports — direct imports only\n- [ ] Server Actions authenticate with Supabase before any mutation\n- [ ] `React.cache()` wraps repeated DB calls in same RSC tree\n- [ ] State derived during render, not in useEffect\n- [ ] Vercel AI SDK 6: `maxOutputTokens` and `toUIMessageStreamResponse`\n- [ ] Glass components use Design Bible classes\n- [ ] Fonts: Inter only (no Cinzel in new code)\n"},"lastSynced":"2026-03-06T07:19:46.935Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing high-performance React application development with Next.js 16 App Router and TypeScript strict","zh":"适合需要高性能React应用开发的前端代理，支持Next.js 16 App Router和TypeScript严格模式","ja":"高性能のReactアプリケーション開発を必要とするフロントエンドエージェントに適しています。Next.js 16 App RouterとTypeScript厳格モードをサポートしています","ko":"고성능 React 애플리케이션 개발이 필요한 프론트엔드 