 должен быть включен","Интегрируется специально с Supabase и Vercel AI SDK 6"],"ar":["يتطلب Next.js 16 App Router و React 19","يجب تمكين وضع strict من TypeScript","يتكامل على وجه التحديد مع Supabase و Vercel AI SDK 6"]},"version":4},"contentHash":"13a84c193d645815faf7c6a22530a023b87257a918f6475a04c5602991d761f5","qualityScore":44}');
