INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frankxai/arcanea-ai-app/arcanea-react-best-practices', 'arcanea-react-best-practices', 'frankxai', 'arcanea-ai-app', 'community', 'arcanea-react-best-practices frankxai arcanea-ai-app community ai-infrastructure context-engineering creative-intelligence guardian-pattern living-intelligence multi-agent The arcanea-react-best-practices skill provides a comprehensive guide to building high-performance React applications using Next.js 16 App Router, React 19, and TypeScript strict. Developers can optimize their components and eliminate waterfalls with this skill. Arcanea React 最佳实践指南，帮助您构建高性能的 Next.js 16 应用，使用 React 19、TypeScript strict、Supabase 和 Vercel AI SDK 6 Arcanea React ベストプラクティス - Next.js 16 アプリのパフォーマンスを向上させる React 19、TypeScript strict、Supabase、Vercel AI SDK 6 の使用方法 Arcanea React 최적화 가이드 - Next.js 16 애플리케이션의 성능을 향상시키는 React 19, TypeScript strict, Supabase, Vercel AI SDK 6의 사용 방법 Arcanea React Best Practices proporciona un conjunto de reglas para mejorar el rendimiento de su aplicación, incluyendo la eliminación de waterfalls y la reducción del tamaño de bundles. Arcanea React Best Practices fournit un ensemble de règles pour améliorer les performances de votre application, notamment l''élimination des waterfalls et la réduction de la taille des bundles. Arcanea React Best Practices bietet eine Reihe von Regeln, um die Leistung Ihrer Anwendung zu verbessern, einschließlich der Beseitigung von Waterfalls und der Reduzierung der Bundle-Größe. O Arcanea React é uma plataforma que combina Next.js, React e TypeScript para desenvolver aplicações escaláveis e eficientes. Aprenda a configurar com as melhores práticas. Arcanea React - это платформа, которая объединяет Next.js, React и TypeScript для разработки масштабируемых и эффективных приложений. Узнайте, как настроить с лучшими практиками - ИИ Агенты Arcanea React هي منصة تجمع بين Next.js و React و TypeScript لتطوير تطبيقات قابلة للتوسعة والفعالة. تعلم كيفية إعداد بأفضل الممارسات - أدوات ذكاء اصطناعي how to use arcanea-react-best-practices arcanea-react-best-practices setup guide Next.js 16 App Router tutorial React 19 optimization techniques TypeScript strict best practices arcanea-react-best-practices vs create-react-app Arcanea React Next.js 16 React 19 TypeScript strict Supabase Vercel AI SDK 6 AI 工具 前端开发最佳实践 Utilizes Next.js 16 App Router for efficient routing Leverages React 19 for improved component performance Enforces TypeScript strict for robust type checking Integrates with Supabase for scalable data management Optimizes component flow using Vercel AI SDK 6 arcanea-react-best-practices is a set of guidelines for building optimized React applications using Next.js 16 App Router, React 19, and TypeScript strict, ensuring efficient component flow and minimal waterfalls.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jeffrey-dot-li/lean-homology/draft', 'community', 'jeffrey-dot-li', 'lean-homology', 'jeffrey-dot-li/lean-homology', 'draft', 1, 0, 44, '2026-03-05T03:58:47Z', '2026-03-06T07:20:08.003Z', '3c154d665787e84cf6b08ce0d421bf440b41ace2c9f5a0f535233339697d34f6', '{"id":"jeffrey-dot-li/lean-homology/draft","name":"draft","description":{"en":"The draft skill generates Lean code for theorem and lemma structures, allowing developers to create compilable code directly in source files. This skill benefits developers working with Lean and Mathlib.","zh":"Draft 模式允许直接在源文件中编写 Lean 代码，实现自动化和高效开发","ja":"Draft モードは、AIエージェントを活用して Lean コードを直接ソースファイルに書き込み、開発効率を向上させる","ko":"Draft 기능은 Lean 코드를 직접 작성하여 개발 프로세스를 최적화하고 자동화합니다","es":"El modo Draft permite a los desarrolladores crear estructuras de teoremas y lemas en Lean, con capacidades como la búsqueda en Mathlib y la generación de código que se compila","fr":"Le mode Brouillon permet aux développeurs de créer des structures de théorèmes et de lemmes en Lean, avec des capacités telles que la recherche dans Mathlib et la génération de code qui se compile","de":"Der Draft-Modus ermöglicht es Entwicklern, Theoremen- und Lemmatastrukturen in Lean zu erstellen, mit Fähigkeiten wie der Suche in Mathlib und der Generierung von kompiliertem Code","pt":"O modo draft permite que você crie estruturas de teoremas e lemas necessárias para provar resultados maiores com código Lean compilável","ru":"Режим draft позволяет создавать структуры теорем и лемм, необходимых для доказательства более крупных результатов с помощью компилируемого кода Lean","ar":"وضع المسودة يسمح لك بإنشاء هياكل المبرهنة والлемا اللازمة لإثبات نتائج أكبر مع كود لين قابل للترجمة"},"seo":{"title":{"en":"Draft: Lean Code Generation for AI Agents | AI Agent Skill","zh":"Draft 模式设置指南 - 实现 Lean 代码自动化","ja":"Draft モードのベストプラクティス - AIエージェントを活用した Lean コード作成","ko":"Draft 기능 사용법 - Lean 코드를 직접 작성하는 방법","es":"Guía de configuración de Draft para desarrolladores de AI","fr":"Mode Brouillon : Guide de démarrage pour les développeurs...","de":"Draft-Modus: Einrichtungsleitfaden für Entwickler von KI-...","pt":"Guia de Configuração do Modo Draft para Ferramentas de In...","ru":"Настройка Режима Draft для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد وضع المسودة لآلات التعلم الاصطناعي"},"description":{"en":"Discover how to use the draft skill to generate Lean code and streamline your proof development process. Learn more and get started with draft today!","zh":"了解 Draft 模式的优势和用法，实现 Lean 代码的自动化和高效开发","ja":"Draft モードの特徴と使い方をマスターし、AIエージェントを活用した効率的な開発を実現","ko":"Draft 기능을 사용하여 Lean 코드를 직접 작성하고 개발 프로세스를 최적화하세요","es":"Descubre cómo configurar el modo Draft para desarrollar teoremas y lemas en Lean, con características como la búsqueda en Mathlib y la generación de código","fr":"Découvrez comment configurer le mode Brouillon pour développer des théorèmes et des lemmes en Lean, avec des fonctionnalités telles que la recherche dans Mat...","de":"Erfahren Sie, wie Sie den Draft-Modus für die Entwicklung von Theoremen und Lemmata in Lean einrichten, mit Funktionen wie der Suche in Mathlib und der Codeg...","pt":"Aprenda a configurar o modo draft para ferramentas de inteligência artificial e melhore sua produtividade com código Lean compilável","ru":"Узнайте, как настроить режим draft для ИИ агентов и повысьте свою производительность с помощью компилируемого кода Lean","ar":"تعلم كيفية إعداد وضع المسودة لأدوات التعلم الاصطناعي وزيادة إنتاجيتك مع كود لين قابل للترجمة"},"definition":{"en":"Draft is a skill that generates Lean code for theorem and lemma structures, enabling developers to create compilable code directly in source files.","zh":"Draft 模式是一种实现 Lean 代码自动化的功能","ja":"Draft モードは、AIエージェントを活用した Lean コード自動化機能のこと","ko":"Draft 기능은 Lean 코드를 직접 작성하는 자동화 기능입니다","es":"El modo Draft es una función que permite a los desarrolladores crear estructuras de teoremas y lemas en Lean","fr":"Le mode Brouillon est une fonctionnalité qui permet aux développeurs de créer des structures de théorèmes et de lemmes en Lean","de":"Der Draft-Modus ist eine Funktion, die es Entwicklern ermöglicht, Theoremen- und Lemmatastrukturen in Lean zu erstellen","pt":"O modo draft é uma funcionalidade que permite criar código Lean compilável para estruturas de teoremas e lemas","ru":"Режим draft - это функция, которая позволяет создавать компилируемый код Lean для структур теорем и лемм","ar":"وضع المسودة هو ميزة تسمح بإنشاء كود لين قابل للترجمة لهياكل المبرهنة والлемا"},"features":{"en":["Writes actual Lean code directly in source files","Supports research of existing Mathlib and project content","Produces sorry''d declarations that compile","Differs from the builtin /plan command","Enables topic and proof sketch development via $ARGUMENTS","Follows a procedure of researching first and then generating code"],"zh":["直接在源文件中编写 Lean 代码","实现自动化和高效开发","支持 Mathlib 和项目内搜索","编写编译后的 sorry 声明","集成 /plan 命令的功能"],"ja":["ソースファイル直接に Lean コードを書き込む","自動化と効率的な開発を実現","Mathlib とプロジェクト内検索をサポート","コンパイル可能な sorry 宣言を書き込む","/plan コマンドの機能を統合"],"ko":["소스 파일 직접에 Lean 코드를 작성","자동화와 효율적인 개발을 구현","Mathlib 과 프로젝트 내 검색을 지원","컴파일 가능한 sorry 선언을 작성","/plan 명령의 기능을 통합"],"es":["Búsqueda en Mathlib y el proyecto actual","Generación de código Lean que se compila","Creación de estructuras de teoremas y lemas","Integración con la línea de comandos de Lean","Compatibilidad con la declaración de código que se compila"],"fr":["Recherche dans Mathlib et le projet actuel","Génération de code Lean qui se compile","Création de structures de théorèmes et de lemmes","Intégration avec la ligne de commande de Lean","Compatibilité avec la déclaration de code qui se compile"],"de":["Suche in Mathlib und dem aktuellen Projekt","Generierung von Lean-Code, der sich kompiliert","Erstellung von Theoremen- und Lemmatastrukturen","Integration mit der Lean-Kommandozeile","Kompatibilität mit der Kompiliererklärung"],"pt":["Criação de estruturas de teoremas e lemas com código Lean compilável","Pesquisa em Mathlib e projetos para entender o que já existe","Geração de código Lean direto nos arquivos de origem","Suporte à declarações sorry para código que compila","Integração com o comando /plan para aprovação do usuário"],"ru":["Создание структур теорем и лемм с помощью компилируемого кода Lean","Поиск в Mathlib и проектах для понимания того, что уже существует","Генерация кода Lean напрямую в исходных файлах","Поддержка деклараций sorry для кода, который компилируется","Интеграция с командой /plan для утверждения пользователя"],"ar":["إنشاء هياكل المبرهنة والлемا مع كود لين قابل للترجمة","البحث في ماثلب ومشاريع لفهم ما موجود بالفعل","توليد كود لين مباشر في الملفات المصدر","دعم الإعلانات sorry للكود الذي يمكن ترجمته","التكامل مع الأمر /plan للموافقة المستخدم"]},"keywords":{"en":["how to use draft","what is draft","draft alternative","draft vs plan","draft install","draft setup guide","Lean code generation","Mathlib integration","theorem proof development"],"zh":["Draft 模式","Lean 代码自动化","AI 工具","Mathlib","自动化开发","高效开发","Lean 代码","源文件编写","编译后的代码"],"ja":["Draft モード","AIエージェント","Lean コード自動化","Mathlib","自動化開発","効率的な開発","Lean コード","ソースファイル書き込み","コンパイル可能なコード"],"ko":["Draft 기능","AI 도구","Lean 코드 자동화","Mathlib","자동화 개발","효율적인 개발","Lean 코드","소스 파일 작성","컴파일 가능한 코드"],"es":[" Draft para desarrolladores","Herramientas de AI para desarrolladores","Desarrollo de teoremas y lemas en Lean","Búsqueda en Mathlib","Generación de código Lean","Integración con la línea de comandos de Lean","Compatibilidad con la declaración de código que se compila","Guía de configuración de Draft"],"fr":["Mode Brouillon pour les développeurs","Outils d''IA pour les développeurs","Développement de théorèmes et de lemmes en Lean","Recherche dans Mathlib","Génération de code Lean","Intégration avec la ligne de commande de Lean","Compatibilité avec la déclaration de code qui se compile","Guide de démarrage du mode Brouillon"],"de":["Draft-Modus für Entwickler","KI-Tools für Entwickler","Entwicklung von Theoremen und Lemmata in Lean","Suche in Mathlib","Generierung von Lean-Code","Integration mit der Lean-Kommandozeile","Kompatibilität mit der Kompiliererklärung","Einrichtungsleitfaden für den Draft-Modus"],"pt":["modo draft","ferramentas de inteligência artificial","código Lean","teoremas","lemas","Mathlib","comando /plan","declarações sorry","compilável"],"ru":["режим draft","ИИ агенты","компилюемый код Lean","теоремы","леммы","Mathlib","команда /plan","декларации sorry","компиляция"],"ar":["وضع المسودة","آلات التعلم الاصطناعي","كود لين","المبرهنة","الлемا","ماثلب","الأمر /plan","الإعلانات sorry","الترجمة"]}},"owner":"jeffrey-dot-li","repo":"lean-homology","repoPath":"jeffrey-dot-li/lean-homology","stars":1,"forks":0,"updatedAt":"2026-03-05T03:58:47Z","topics":[],"category":"community","skillMd":{"name":"draft","description":"Draft sorryd theorem/lemma structure for a larger result from a proof sketch.","bodyPreview":"# Draft Mode\n\nDraft the theorem/lemma structure needed to prove a larger result.\n\n**This is NOT the builtin `/plan` command.** The builtin `/plan` enters a read-only planning mode that produces a markdown plan for user approval before any code is written. `/draft` writes actual Lean code — sorry''d declarations that compile — directly in the source files.\n\nTopic / proof sketch: $ARGUMENTS\n\n## Procedure\n\n1. **Research first** — search Mathlib and this project to understand what already exists.\n2.","body":"# Draft Mode\n\nDraft the theorem/lemma structure needed to prove a larger result.\n\n**This is NOT the builtin `/plan` command.** The builtin `/plan` enters a read-only planning mode that produces a markdown plan for user approval before any code is written. `/draft` writes actual Lean code — sorry''d declarations that compile — directly in the source files.\n\nTopic / proof sketch: $ARGUMENTS\n\n## Procedure\n\n1. **Research first** — search Mathlib and this project to understand what already exists.\n2. Work **interactively** with the user to decompose the proof into lemmas.\n3. Write all declarations with `sorry` proofs — **no filled proofs in this mode**.\n4. Each lemma should be **provable independently in ~30 lines or fewer**.\n5. Verify each `sorry`''d statement compiles with `lean_diagnostic_messages` before moving on.\n6. Present the full dependency structure: which lemmas feed into which.\n\n## Decomposition principle\n\nThe top-level theorem should read like a proof outline — each step composing named lemmas with simple plumbing (`rw`, `exact`, `simp`, `apply`). If the top-level proof still needs >10 lines of non-trivial tactics at any step, a lemma might be missing from the decomposition.\n\nPrefer **general, reusable lemma statements** over proof-specific helpers. A good decomposition builds tools (e.g., `sigmaι_cancel`, `sigmaι_comp_fst_eq`) that apply beyond the current theorem.\n\n## Output\n\nA compilable file (or section) of `sorry`''d declarations with clear names and docstrings. Iterate with the user until the decomposition is right.\n\n## Rules\n\n- Every declaration must compile (with sorry) after writing.\n- Use clear, descriptive names following Mathlib conventions.\n- Include `/-- ... -/` docstrings explaining the mathematical content.\n"},"lastSynced":"2026-03-06T07:20:08.003Z","agentAnalysis":{"suitability":{"en":"Perfect for Math-focused Agents needing Lean code generation for theorem and lemma structures.","zh":"适用于需要精简代码生成的数学专注代理，用于定理和引理结构。","ja":"数学に焦点を当てたエージェントが、定理と補題の構造に対するスリムなコード生成を必要とする場合に最適です。","ko":"정리와 보조정리 구조를 위한 Trim한 코드 생성이 필요한 수학을 중점으로 하는 에이전트에게 적합합니다.","es":"Ideal para Agentes centrados en matemáticas que necesitan generación de código Lean para estructuras de teoremas y lemas.","fr":"Parfait pour les Agents axés sur les mathématiques ayant besoin d''une génération de code Lean pour les structures de théorèmes et de lemmes.","de":"Perfekt für mathematikorientierte Agents, die Lean-Code-Generierung für Theorem- und Lemma-Strukturen benötigen.","pt":"Perfeito para Agentes focados em Matemática que precisam de geração de código Lean para estruturas de teorema e lema.","ru":"Идеально подходит для агентов, ориентированных на математику, которым необходима генерация скудного кода Lean для теорем и структур лемм.","ar":"مثالي للوكلاء المتميزين في الرياضيات الذين يحتاجون إلى توليد رمز Lean صغير لهياكل المبرهنة والлемا."},"recommendation":{"en":"Empowers agents to generate compilable Lean code directly in source files, utilizing Mathlib and supporting theorem and lemma structures, enabling efficient proof development and validation via Lean and Mathlib protocols.","zh":"赋予代理直接在源文件中生成可编译的Lean代码的能力，利用Mathlib并支持定理和引理结构，从而实现通过Lean和Mathlib协议的高效证明开发和验证。","ja":"Mathlibを利用し、定理と補題の構造をサポートして、エージェントが直接ソースファイル内でコンパイル可能なLeanコードを生成できるようにし、LeanとMathlibのプロトコルを通じた効率的な証明開発と検証を可能にします。","ko":"Mathlib를 활용하여 정리와 보조정리 구조를 지원하고 에이전트가 직접 소스 파일 내에서 컴파일 가능한 Lean 코드를 생성할 수 있도록 하여, Lean과 Mathlib 프로토콜을 통해 효율적인 증명 개발 및 검증을 가능하게 합니다.","es":"Permite a los agents generar código Lean compilable directamente en los archivos fuente, utilizando Mathlib y dando soporte a estructuras de teoremas y lemas, permitiendo un desarrollo y validación eficiente de pruebas mediante los protocolos de Lean y Mathlib.","fr":"Permet aux agents de générer du code Lean compilable directement dans les fichiers sources, en utilisant Mathlib et en prenant en charge les structures de théorèmes et de lemmes, permettant un développement et une validation efficaces des preuves via les protocoles Lean et Mathlib.","de":"Ermöglicht Agents, kompilierbaren Lean-Code direkt in Quelldateien zu generieren, unter Verwendung von Mathlib und mit Unterstützung für Theorem- und Lemma-Strukturen, was eine effiziente Beweisentwicklung und -validierung über Lean- und Mathlib-Protokolle ermöglicht.","pt":"Habilita os agentes a gerar código Lean compilável diretamente em arquivos de origem, utilizando Mathlib e suportando estruturas de teorema e lema, permitindo o desenvolvimento e validação eficientes de provas por meio dos protocolos Lean e Mathlib.","ru":"Наделяет агентов возможностью генерировать компилируемый код Lean直接 в исходных файлах, используя Mathlib и поддерживая теоремы и структуры лемм, обеспечивая эффективное развитие и проверку доказательств через протоколы Lean и Mathlib.","ar":"تمكّن الوكلاء من توليد رمز Lean قابل للترجمة مباشرة في الملفات المصدر، مستخدمين Mathlib وداعمين هياكل المبرهنة والлемا، ممّا يسمح بالتطوير والتحقق الفعالين للبراهين عن طريق بروتوكولات Lean و Mathlib."},"useCases":{"en":["Drafting theorem structures for complex mathematical proofs","Generating lemma code for validation and verification","Creating compilable Lean code for direct integration into source files"],"zh":["为复杂数学证明草拟定理结构","为验证和验证生成引理代码","为直接集成到源文件中创建可编译的Lean代码"],"ja":["複雑な数学的証明のための定理構造のドラフト作成","検証とバリデーションのための補題コードの生成","ソースファイルへの直接統合のためのコンパイル可能なLeanコードの作成"],"ko":["복잡한 수학적 증명의 정리 구조 초안 작성","검증 및 검사 위한 보조정리 코드 생성","소스 파일 직접 통합을 위한 컴파일 가능한 Lean 코드 생성"],"es":["Redacción de estructuras de teoremas para demostraciones matemáticas complejas","Generación de código de lemas para validación y verificación","Creación de código Lean compilable para integración directa en archivos fuente"],"fr":["Rédaction de structures de théorèmes pour des preuves mathématiques complexes","Génération de code de lemmes pour validation et vérification","Création de code Lean compilable pour une intégration directe dans les fichiers sources"],"de":["Entwurf von Theorem-Strukturen für komplexe mathematische Beweise","Generierung von Lemma-Code für Validierung und Verifizierung","Erstellung von kompilierbarem Lean-Code zur direkten Integration in Quelldateien"],"pt":["Criar estruturas de teorema para provas matemáticas complexas","Gerar código de lema para validação e verificação","Criar código Lean compilável para integração direta em arquivos de origem"],"ru":["Создание структур теорем для сложных математических доказательств","Генерация кода лемм для проверки и верификации","Создание компилируемого кода Lean для прямой интеграции в исходные файлы"],"ar":["إنشاء هياكل مبرهنة لبراهين رياضية معقدة","توليد رمز لема للتحقق والتحقيق","إنشاء رمز Lean قابل للترجمة لمصادر الملفات مباشرة"]},"limitations":{"en":["Requires knowledge of Lean and Mathlib","Limited to Lean code generation","Needs access to Mathlib and project resources for research"],"zh":["需要了解Lean和Mathlib","仅限于Lean代码生成","需要访问Mathlib和项目资源进行研究"],"ja":["LeanとMathlibの知識が必要","Leanコード生成のみ","研究のためのMathlibとプロジェクトリソースへのアクセスが必要"],"ko":["Lean과 Mathlib에 대한 지식이 필요","Lean 코드 생성만 가능","연구를 위한 Mathlib와 프로젝트 리소스에 대한 접근이 필요"],"es":["Requiere conocimiento de Lean y Mathlib","Limitado a la generación de código Lean","Necesita acceso a Mathlib y recursos del proyecto para investigación"],"fr":["Nécessite une connaissance de Lean et Mathlib","Limité à la génération de code Lean","Nécessite un accès à Mathlib et aux ressources du projet pour la recherche"],"de":["Erfordert Kenntnisse in Lean und Mathlib","Beschränkt sich auf die Lean-Code-Generierung","Benötigt Zugang zu Mathlib und Projektressourcen für die Recherche"],"pt":["Exige conhecimento de Lean e Mathlib","Limitado à geração de código Lean","Necessita acesso a Mathlib e recursos de projeto para pesquisa"],"ru":["Требует знания Lean и Mathlib","Ограничен генерацией кода Lean","Требует доступа к Mathlib и ресурсам проекта для исследований"],"ar":["يتطلب معرفة Lean و Mathlib","محدود بتوليد رمز Lean","يحتاج إلى الوصول إلى Mathlib وموارد المشروع لأغراض البحث"]},"version":4},"contentHash":"3c154d665787e84cf6b08ce0d421bf440b41ace2c9f5a0f535233339697d34f6","qualityScore":44}');
