INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeffrey-dot-li/lean-homology/draft', 'draft', 'jeffrey-dot-li', 'lean-homology', 'community', 'draft jeffrey-dot-li lean-homology community The draft skill generates Lean code for theorem and lemma structures, allowing developers to create compilable code directly in source files. This skill benefits developers working with Lean and Mathlib. Draft 模式允许直接在源文件中编写 Lean 代码，实现自动化和高效开发 Draft モードは、AIエージェントを活用して Lean コードを直接ソースファイルに書き込み、開発効率を向上させる Draft 기능은 Lean 코드를 직접 작성하여 개발 프로세스를 최적화하고 자동화합니다 El modo Draft permite a los desarrolladores crear estructuras de teoremas y lemas en Lean, con capacidades como la búsqueda en Mathlib y la generación de código que se compila Le mode Brouillon permet aux développeurs de créer des structures de théorèmes et de lemmes en Lean, avec des capacités telles que la recherche dans Mathlib et la génération de code qui se compile Der Draft-Modus ermöglicht es Entwicklern, Theoremen- und Lemmatastrukturen in Lean zu erstellen, mit Fähigkeiten wie der Suche in Mathlib und der Generierung von kompiliertem Code O modo draft permite que você crie estruturas de teoremas e lemas necessárias para provar resultados maiores com código Lean compilável Режим draft позволяет создавать структуры теорем и лемм, необходимых для доказательства более крупных результатов с помощью компилируемого кода Lean وضع المسودة يسمح لك بإنشاء هياكل المبرهنة والлемا اللازمة لإثبات نتائج أكبر مع كود لين قابل للترجمة how to use draft what is draft draft alternative draft vs plan draft install draft setup guide Lean code generation Mathlib integration theorem proof development Draft 模式 Lean 代码自动化 AI 工具 Mathlib 自动化开发 高效开发 Lean 代码 源文件编写 编译后的代码 Writes actual Lean code directly in source files Supports research of existing Mathlib and project content Produces sorry''d declarations that compile Differs from the builtin /plan command Enables topic and proof sketch development via $ARGUMENTS Follows a procedure of researching first and then generating code Draft is a skill that generates Lean code for theorem and lemma structures, enabling developers to create compilable code directly in source files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Project-X-Vietnam/landing-page/feature-dev', 'community', 'Project-X-Vietnam', 'landing-page', 'Project-X-Vietnam/landing-page', 'feature-dev', 0, 0, 44, '2026-03-01T19:41:10Z', '2026-03-07T03:48:42.811Z', 'c6cee929ff7ebdae9aed26d13daaf381214f7ccd7a51f625de15ed3217490531', '{"id":"Project-X-Vietnam/landing-page/feature-dev","name":"feature-dev","description":{"en":"The feature-dev skill provides a structured 7-phase workflow for implementing features from discovery to completion, benefiting developers working on complex tasks.","zh":"Feature Development是一种结构化的7阶段工作流程，用于实现新功能，从发现到完成，包括PXV设计系统和代码重用","ja":"Feature Developmentは、新しい機能の実装から完成までの7段階のワークフローであり、PXVデザインシステムとコードの再利用を含みます","ko":"Feature Development는 새로운 기능을 구현하는 데 필요한 7단계 워크플로우로, PXV 디자인 시스템과 코드 재사용을 포함","es":"Feature-dev es un flujo de trabajo de 7 fases para implementar características desde la descubierta hasta la finalización, utilizando componentes reutilizables y el sistema de diseño PXV","fr":"Feature-dev est un flux de travail de 7 phases pour mettre en place des fonctionnalités depuis la découverte jusqu''à la finalisation, en utilisant des composants réutilisables et le système de design PXV","de":"Feature-dev ist ein 7-Phasen-Workflow zur Implementierung von Funktionen von der Entdeckung bis zur Fertigstellung, unter Verwendung von wiederverwendbaren Komponenten und dem PXV-Designsystem","pt":"O Feature-Dev é uma estrutura de trabalho de 7 fases para implementar features de forma eficiente, desde a descoberta até a conclusão","ru":"Feature-Dev - это 7-фазная рабочая структура для эффективной реализации функций от открытия до завершения","ar":"Feature-Dev هو هيكل عمل من 7 مراحل لتنفيذ الميزات بفعالية، من مرحلة الاكتشاف إلى الانتهاء"},"seo":{"title":{"en":"feature-dev: 7-Phase Workflow Setup Guide | AI Agent Skill","zh":"Feature Development Setup Guide -  AIエージェント最佳实践","ja":"Feature Development ベストプラクティス - AIエージェントを使用した開発","ko":"Feature Development 설정 가이드 - AI 에이전트를 사용한 기능 개발","es":"Guía de configuración de feature-dev para desarrollo de c...","fr":"Guide de mise en place de feature-dev pour le développeme...","de":"Einrichtungsleitfaden für feature-dev zur Entwicklung von...","pt":"Guia de Configuração do Feature-Dev: Melhores Práticas pa...","ru":"ИИ Агенты: Руководство по Настройке Feature-Dev для Разра...","ar":"دليل إعداد Feature-Dev: أفضل الممارسات للاستفادة من أدوات..."},"description":{"en":"Streamline feature implementation with feature-dev''s structured workflow. Learn how to apply its core principles and best practices today!","zh":"了解Feature Development的7阶段工作流程，用于实现新功能，从发现到完成，包括PXV设计系统和代码重用","ja":"Feature Developmentの7段階ワークフローを学び、機能の実装から完成までをAIエージェントで効率化","ko":"Feature Development의 7단계 워크플로우를 알아보고, 새로운 기능을 구현하는 데 필요한 프로세스를 AI 에이전트로 최적화","es":"Aprende a implementar características de manera estructurada con feature-dev, una herramienta de desarrollo de características para AI Agentes","fr":"Découvrez comment mettre en place des fonctionnalités de manière structurée avec feature-dev, un outil de développement de fonctionnalités pour les AI Tools","de":"Erfahren Sie, wie Sie Funktionen strukturiert implementieren können mit feature-dev, einem Entwicklungstool für Features für KI-Agents","pt":"Aprenda a implementar features de forma eficiente com o Feature-Dev, uma estrutura de trabalho de 7 fases para desenvolvedores","ru":"Узнайте, как эффективно реализовывать функции с помощью Feature-Dev, 7-фазной рабочей структуры для разработчиков ИИ Агентов","ar":"تعرف على كيفية تنفيذ الميزات بفعالية باستخدام Feature-Dev، وهي هيكل عمل من 7 مراحل لاستفادة من أدوات الذكاء الاصطناعي"},"definition":{"en":"feature-dev is a workflow for implementing features through a 7-phase process, emphasizing reuse of existing components and adherence to design systems like PXV.","zh":"Feature Development是指实现新功能的结构化过程，包括7阶段工作流程和PXV设计系统","ja":"Feature Developmentとは、新しい機能を実装するための構造化されたプロセスであり、7段階のワークフローとPXVデザインシステムを含む","ko":"Feature Development는 새로운 기능을 구현하는 데 필요한 구조화된 프로세스로, 7단계 워크플로우와 PXV 디자인 시스템을 포함","es":"Feature-dev es un enfoque estructurado para desarrollar características de software, que implica reutilizar componentes y seguir el sistema de diseño PXV","fr":"Feature-dev est une approche structurée pour développer des fonctionnalités logicielles, qui consiste à réutiliser des composants et à suivre le système de design PXV","de":"Feature-dev ist ein strukturierter Ansatz zur Entwicklung von Softwarefunktionen, der die Wiederverwendung von Komponenten und die Verwendung des PXV-Designsystems beinhaltet","pt":"O que é Feature-Dev? É uma abordagem estruturada para implementar features de forma eficiente","ru":"Что такое Feature-Dev? Это структурированный подход к эффективной реализации функций","ar":"ما هو Feature-Dev؟ هو نهج منظم لتنفيذ الميزات بفعالية"},"features":{"en":["Implements a 7-phase workflow for feature development","Supports integration builds via API, form, etc.","Follows PXV design system for consistent design","Reusable component implementation to reduce redundancy","Suitable for tasks involving 3+ files","Guides implementation of new pages or sections"],"zh":["7阶段工作流程","PXV设计系统","代码重用","新功能实现","功能开发最佳实践","AIエージェント集成"],"ja":["7段階ワークフロー","PXVデザインシステム","コードの再利用","新機能の実装","機能開発ベストプラクティス","AIエージェントとの連携"],"ko":["7단계 워크플로우","PXV 디자인 시스템","코드 재사용","새로운 기능 구현","기능 개발 최적화","AI 에이전트 연동"],"es":["Flujo de trabajo de 7 fases para implementar características","Reutilización de componentes existentes","Seguimiento del sistema de diseño PXV","Implementación de características desde la descubierta hasta la finalización","Integración con APIs y formularios","Desarrollo de características que afectan 3 o más archivos"],"fr":["Flux de travail de 7 phases pour mettre en place des fonctionnalités","Réutilisation de composants existants","Suivi du système de design PXV","Mise en place de fonctionnalités depuis la découverte jusqu''à la finalisation","Intégration avec des API et des formulaires","Développement de fonctionnalités qui affectent 3 ou plusieurs fichiers"],"de":["7-Phasen-Workflow zur Implementierung von Funktionen","Wiederverwendung von bestehenden Komponenten","Verwendung des PXV-Designsystems","Implementierung von Funktionen von der Entdeckung bis zur Fertigstellung","Integration mit APIs und Formularen","Entwicklung von Funktionen, die 3 oder mehr Dateien betreffen"],"pt":["Implementação de novas páginas ou seções","Adição de componentes significativos ou recursos","Construção de integrações (API, formulários, etc.)","Reutilização de componentes existentes","Seguimento do sistema de design PXV"],"ru":["Реализация новых страниц или разделов","Добавление значимых компонентов или функций","Строительство интеграций (API, формы и т. д.)","Переиспользование существующих компонентов","Следование системе дизайна PXV"],"ar":["تنفيذ صفحات أو أقسام جديدة","إضافة مكونات هامة أو ميزات","بناء التكاملات (واجهات برمجة التطبيقات، النماذج، إلخ)","إعادة استخدام المكونات الحالية","اتباع نظام تصميم PXV"]},"keywords":{"en":["how to use feature-dev","feature-dev workflow guide","feature-dev vs agile development","feature-dev install","feature-dev setup for AI agents","what is feature-dev in software development","feature-dev best practices","feature-dev alternative workflows","feature-dev and PXV design system"],"zh":["Feature Development","AIエージェント","PXV设计系统","代码重用","新功能实现","功能开发最佳实践","AI工具","开发工作流程"],"ja":["Feature Development","AIエージェント","PXVデザインシステム","コードの再利用","新機能の実装","機能開発ベストプラクティス","AIツール","開発ワークフロー"],"ko":["Feature Development","AI 에이전트","PXV 디자인 시스템","코드 재사용","새로운 기능 구현","기능 개발 최적화","AI 도구","개발 워크플로우"],"es":["feature-dev","desarrollo de características","AI Agentes","flujo de trabajo de 7 fases","reutilización de componentes","sistema de diseño PXV","implementación de características","integración con APIs","desarrollo de software"],"fr":["feature-dev","développement de fonctionnalités","AI Tools","flux de travail de 7 phases","réutilisation de composants","système de design PXV","mise en place de fonctionnalités","intégration avec des API","développement de logiciels"],"de":["feature-dev","Entwicklung von Funktionen","KI-Agents","7-Phasen-Workflow","Wiederverwendung von Komponenten","PXV-Designsystem","Implementierung von Funktionen","Integration mit APIs","Softwareentwicklung"],"pt":["Feature-Dev","desenvolvimento de features","implementação de recursos","estrutura de trabalho","melhores práticas para desenvolvedores","desenvolvimento de software","engenharia de software"],"ru":["Feature-Dev","ИИ Агенты","разработка функций","реализация функций","рабочая структура","лучшие практики для разработчиков","разработка программного обеспечения","инженерия программного обеспечения"],"ar":["Feature-Dev","أدوات الذكاء الاصطناعي","تنفيذ الميزات","بناء التكاملات","هيكل العمل","أفضل الممارسات للاستفادة من أدوات الذكاء الاصطناعي","تطوير البرمجيات","هندسة البرمجيات"]}},"owner":"Project-X-Vietnam","repo":"landing-page","repoPath":"Project-X-Vietnam/landing-page","stars":0,"forks":0,"updatedAt":"2026-03-01T19:41:10Z","topics":[],"category":"community","skillMd":{"name":"feature-dev","description":"End-to-end feature implementation workflow. Triggers on implement feature, build feature, develop, create feature.","bodyPreview":"# Feature Development\n\nA structured 7-phase workflow for implementing features from discovery to completion.\n\n## When to Use\n\n- Implementing a new page or section\n- Adding a significant component or feature\n- Building an integration (API, form, etc.)\n- Any task that touches 3+ files\n\n## When NOT to Use\n\n- Bug fixes (just fix directly)\n- Simple text/style changes\n- Adding a single small component\n\n## Core Principles\n\n- Reuse existing components before creating new ones\n- Follow the PXV design sys","body":"# Feature Development\n\nA structured 7-phase workflow for implementing features from discovery to completion.\n\n## When to Use\n\n- Implementing a new page or section\n- Adding a significant component or feature\n- Building an integration (API, form, etc.)\n- Any task that touches 3+ files\n\n## When NOT to Use\n\n- Bug fixes (just fix directly)\n- Simple text/style changes\n- Adding a single small component\n\n## Core Principles\n\n- Reuse existing components before creating new ones\n- Follow the PXV design system (colors, typography, spacing)\n- Mobile-first responsive design\n- Animate thoughtfully with Framer Motion\n\n## The 7 Phases\n\n### Phase 1: Discovery\n\n**Goal**: Understand what needs to be built.\n\n1. Read the user''s request carefully\n2. Identify the feature''s purpose and scope\n3. List expected deliverables (pages, components, API routes)\n4. Identify any external dependencies or data sources\n\n### Phase 2: Exploration\n\n**Goal**: Understand the existing codebase context.\n\n**Actions**:\n1. Read `AGENTS.md` for architecture overview\n2. Identify similar existing implementations (reference examples)\n3. Check `components/ui/` for reusable primitives\n4. Check `components/` for reusable custom components\n5. Review `tailwind.config.ts` and `globals.css` for available design tokens\n\n**Output**: List of reusable code and patterns found.\n\n### Phase 3: Questions\n\n**Goal**: Resolve ambiguity before coding.\n\n1. List any unclear requirements\n2. Ask the user targeted questions (max 3-5)\n3. Propose defaults for minor decisions\n4. Confirm the approach before proceeding\n\n### Phase 4: Architecture\n\n**Goal**: Design the solution structure.\n\n**Actions**:\n1. Define the component tree\n2. List new files to create and existing files to modify\n3. Define TypeScript interfaces for data shapes\n4. Plan the responsive layout (mobile → desktop)\n5. Plan animations and transitions\n\n**Output**: Component tree + file list + key interfaces.\n\n### Phase 5: Implementation\n\n**Goal**: Write the code.\n\n**Order**:\n1. Types/interfaces\n2. Utility functions (`lib/`)\n3. UI components (bottom-up: primitives → composites → page)\n4. Page assembly\n5. API routes (if needed)\n6. Animations (last)\n\n**Rules**:\n- Use `\"use client\"` only when needed (state, effects, browser APIs)\n- Use shadcn/ui primitives as building blocks\n- Use `cn()` for conditional classes\n- Use Framer Motion `whileInView` for scroll animations\n- Test each component as you build\n\n### Phase 6: Review\n\n**Goal**: Self-review the implementation.\n\n**Checklist**:\n- [ ] TypeScript: no `any` types, proper interfaces\n- [ ] Responsive: works on mobile (320px), tablet (768px), desktop (1280px)\n- [ ] Design system: uses PXV brand colors and typography\n- [ ] Components: reuses existing ui/ components\n- [ ] Accessibility: alt text, semantic HTML, keyboard navigation\n- [ ] Performance: images optimized, no unnecessary re-renders\n- [ ] Animations: smooth, no layout shifts, `viewport={{ once: true }}`\n\n### Phase 7: Summary\n\n**Goal**: Report what was built.\n\n**Output**:\n- Files created/modified\n- Components added\n- Key decisions made\n- Any follow-up tasks or known limitations\n\n## Related Skills\n\n| Skill | When to Chain |\n|-------|--------------|\n| planning | Before feature-dev, to break a large feature into phases |\n| web-test | After feature-dev, to test in browser |\n| review-pr | After feature-dev, to review code quality |\n| git-commit | After feature-dev, to commit and push |\n"},"lastSynced":"2026-03-07T03:48:42.811Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured workflows for complex feature implementation.","zh":"适合需要结构化工作流程来实现复杂功能的开发代理。","ja":"複雑な機能の実装に構造化されたワークフローを必要とする開発エージェントに最適です。","ko":"복잡한 기능 구현을 위한 구조화된 워크플로가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren flujos de trabajo estructurados para la implementación de características complejas.","fr":"Idéal pour les agents de développement nécessitant des flux de travail structurés pour la mise en œuvre de fonctionnalités complexes.","de":"Ideal für Entwicklungssagenten, die strukturierte Workflows für die Implementierung komplexer Funktionen benötigen.","pt":"Ideal para Agentes de Desenvolvimento que necessitam de fluxos de trabalho estruturados para implementação de recursos complexos.","ru":"Идеально подходит для агентов разработки, требующих структурированных рабочих процессов для реализации сложных функций.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى سير عمل منظم لتنفيذ ميزات معقدة."},"recommendation":{"en":"Empowers agents to implement features efficiently by following a 7-phase workflow, reusing existing components, and adhering to the PXV design system, ensuring consistency and reducing development time.","zh":"通过遵循7阶段工作流程、重用现有组件和遵守PXV设计系统，能够高效地实现功能，确保一致性并减少开发时间。","ja":"7つのフェーズのワークフローに従い、既存のコンポーネントを再利用し、PXVデザインシステムに準拠することで、機能を効率的に実装し、一貫性を確保し、開発時間を短縮します。","ko":"7단계 워크플로를 따르고 기존 컴포넌트를 재사용하며 PXV 디자인 시스템을 준수함으로써 기능을 효율적으로 구현하여 일관성을 보장하고 개발 시간을 단축합니다.","es":"Habilita a los agentes a implementar características de manera eficiente siguiendo un flujo de trabajo de 7 fases, reutilizando componentes existentes y ajustándose al sistema de diseño PXV, garantizando la coherencia y reduciendo el tiempo de desarrollo.","fr":"Permet aux agents de mettre en œuvre des fonctionnalités de manière efficace en suivant un flux de travail de 7 phases, en réutilisant des composants existants et en respectant le système de conception PXV, garantissant ainsi la cohérence et réduisant le temps de développement.","de":"Ermöglicht es Agenten, Funktionen effizient zu implementieren, indem sie einem 7-Phasen-Workflow folgen, bestehende Komponenten wiederverwenden und sich an das PXV-Designsystem halten, um Konsistenz zu gewährleisten und die Entwicklungzeit zu verkürzen.","pt":"Habilita os agentes a implementar recursos de forma eficiente, seguindo um fluxo de trabalho de 7 fases, reutilizando componentes existentes e aderindo ao sistema de design PXV, garantindo consistência e reduzindo o tempo de desenvolvimento.","ru":"Наделяет агентов возможностью эффективно реализовывать функции, следуя 7-фазовому рабочему процессу, переиспользуя существующие компоненты и придерживаясь системы дизайна PXV, обеспечивая последовательность и сокращая время разработки.","ar":"يمنح الوكلاء القدرة على تنفيذ الميزات بفعالية من خلال اتباع سير عمل من 7 مراحل، وإعادة استخدام المكونات الحالية، والالتزام بنظام التصميم PXV، مما يضمن الاتساق وتقليل وقت التطوير."},"useCases":{"en":["Implementing new page or section features","Adding significant components or integrations","Building APIs or form integrations"],"zh":["实现新的页面或部分功能","添加重要组件或集成","构建API或表单集成"],"ja":["新しいページまたはセクションの機能を実装する","重要なコンポーネントまたは統合を追加する","APIまたはフォームの統合を構築する"],"ko":["새로운 페이지 또는 섹션 기능 구현","중요 컴포넌트 또는 통합 추가","API 또는 폼 통합 구축"],"es":["Implementar nuevas características de página o sección","Agregar componentes o integraciones significativas","Crear API o integraciones de formularios"],"fr":["Mettre en œuvre de nouvelles fonctionnalités de page ou de section","Ajouter des composants ou des intégrations significatifs","Créer des API ou des intégrations de formulaires"],"de":["Implementierung neuer Seiteneigenschaften oder -abschnitte","Hinzufügen bedeutender Komponenten oder Integrationen","Erstellen von APIs oder Formularentwicklungen"],"pt":["Implementação de novos recursos de página ou seção","Adição de componentes ou integrações significativas","Construção de APIs ou integrações de formulários"],"ru":["Реализация новых функций страницы или раздела","Добавление значительных компонентов или интеграций","Создание API или интеграций форм"],"ar":["تنفيذ ميزات جديدة للصفحة أو القسم","إضافة مكونات أو تكاملات مهمة","بناء APIs أو تكاملات الاستمارات"]},"limitations":{"en":["Not suitable for bug fixes or simple text/style changes","Requires adherence to the PXV design system"],"zh":["不适合用于错误修复或简单的文本/样式更改","需要遵守PXV设计系统"],"ja":["バグの修正または単純なテキスト/スタイルの変更には適していない","PXVデザインシステムに準拠する必要がある"],"ko":["버그 수정 또는 단순한 텍스트/스타일 변경에는 적합하지 않음","PXV 디자인 시스템을 준수해야 함"],"es":["No es adecuado para correcciones de errores o cambios simples de texto/estilo","Requiere adherirse al sistema de diseño PXV"],"fr":["N''est pas adapté pour les corrections de bogues ou les modifications simples de texte/style","Exige de se conformer au système de conception PXV"],"de":["Nicht geeignet für Fehlerbehebungen oder einfache Text-/Stiländerungen","Erfordert die Einhaltung des PXV-Designsystems"],"pt":["Não é adequado para correções de bugs ou alterações simples de texto/estilo","Requer aderência ao sistema de design PXV"],"ru":["Не подходит для исправления ошибок или простых изменений текста/стиля","Требует соблюдения системы дизайна PXV"],"ar":["لا يصلح لتصحيح الأخطاء أو تغييرات بسيطة للنص/النمط","يتطلب الالتزام بنظام التصميم PXV"]},"version":4},"contentHash":"c6cee929ff7ebdae9aed26d13daaf381214f7ccd7a51f625de15ed3217490531","qualityScore":44}');
