INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Project-X-Vietnam/landing-page/feature-dev', 'feature-dev', 'Project-X-Vietnam', 'landing-page', 'community', 'feature-dev Project-X-Vietnam landing-page community The feature-dev skill provides a structured 7-phase workflow for implementing features from discovery to completion, benefiting developers working on complex tasks. Feature Development是一种结构化的7阶段工作流程，用于实现新功能，从发现到完成，包括PXV设计系统和代码重用 Feature Developmentは、新しい機能の実装から完成までの7段階のワークフローであり、PXVデザインシステムとコードの再利用を含みます Feature Development는 새로운 기능을 구현하는 데 필요한 7단계 워크플로우로, PXV 디자인 시스템과 코드 재사용을 포함 Feature-dev es un flujo de trabajo de 7 fases para implementar características desde la descubierta hasta la finalización, utilizando componentes reutilizables y el sistema de diseño PXV Feature-dev est un flux de travail de 7 phases pour mettre en place des fonctionnalités depuis la découverte jusqu''à la finalisation, en utilisant des composants réutilisables et le système de design PXV Feature-dev ist ein 7-Phasen-Workflow zur Implementierung von Funktionen von der Entdeckung bis zur Fertigstellung, unter Verwendung von wiederverwendbaren Komponenten und dem PXV-Designsystem O Feature-Dev é uma estrutura de trabalho de 7 fases para implementar features de forma eficiente, desde a descoberta até a conclusão Feature-Dev - это 7-фазная рабочая структура для эффективной реализации функций от открытия до завершения Feature-Dev هو هيكل عمل من 7 مراحل لتنفيذ الميزات بفعالية، من مرحلة الاكتشاف إلى الانتهاء how to use feature-dev feature-dev workflow guide feature-dev vs agile development feature-dev install feature-dev setup for AI agents what is feature-dev in software development feature-dev best practices feature-dev alternative workflows feature-dev and PXV design system Feature Development AIエージェント PXV设计系统 代码重用 新功能实现 功能开发最佳实践 AI工具 开发工作流程 Implements a 7-phase workflow for feature development Supports integration builds via API, form, etc. Follows PXV design system for consistent design Reusable component implementation to reduce redundancy Suitable for tasks involving 3+ files Guides implementation of new pages or sections feature-dev is a workflow for implementing features through a 7-phase process, emphasizing reuse of existing components and adherence to design systems like PXV.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fulfon/lusena-dawn/shopify-expert', 'community', 'fulfon', 'lusena-dawn', 'fulfon/lusena-dawn', 'shopify-expert', 0, 0, 44, '2026-03-06T12:59:22.226Z', '2026-03-06T14:12:31.528Z', 'ce496a25af2e2a9c11c179fa4131e1a18f141080460641536ef2f840074c9fd6', '{"id":"fulfon/lusena-dawn/shopify-expert","name":"shopify-expert","description":{"en":"The Shopify-Expert skill is designed for senior Shopify developers, providing expertise in theme development, headless commerce, and custom checkout solutions. It helps developers build high-performing stores with optimized checkout flows.","zh":"Shopify Expert 是一位高级 Shopify 开发者，专注于主题开发、Headless Commerce 和自定义结账解决方案","ja":"Shopify エキスパートは、テーマ開発、ヘッドレス コマース、カスタム チェックアウト ソリューションを専門とするシニア Shopify 開発者です","ko":"Shopify Expert는 테마 개발, 헤드리스 커머스, 커스텀 결제 솔루션을 전문으로 하는 시니어 Shopify 개발자입니다","es":"El experto en Shopify es un desarrollador senior con experiencia en desarrollo de temas con Liquid, comercio headless con Storefront API y soluciones de checkout personalizadas","fr":"L''expert Shopify est un développeur senior avec une expérience approfondie dans le développement de thèmes avec Liquid, le commerce headless avec Storefront API et les solutions de checkout personnalisées","de":"Der Shopify-Experte ist ein Senior-Entwickler mit Erfahrung in der Entwicklung von Themes mit Liquid, Headless-Commerce mit Storefront API und benutzerdefinierten Checkout-Lösungen","pt":"O Shopify Expert é um especialista em desenvolvimento de temas e comércio headless para Shopify, com habilidades em Liquid, Storefront API e checkout personalizado","ru":"ИИ Агент Shopify Expert - это специалист по разработке тем и headless коммерции для Shopify, с навыками в Liquid, Storefront API и настраиваемом checkout","ar":"خبير Shopify هو خبير في تطوير المواضيع والتجارة بدون رأس لشوبيفاي، مع مهارات في Liquid و Storefront API و Checkout المخصص"},"seo":{"title":{"en":"Shopify-Expert: Mastering Headless Commerce and Custom Ch...","zh":"Shopify Expert Setup Guide - Liquid 和 Headless Commerce 解决方案","ja":"Shopify エキスパート設定ガイド - Liquid と Headless Commerce ソリューション","ko":"Shopify Expert 설정 가이드 - Liquid 및 Headless Commerce 솔루션","es":"Guía de configuración para Shopify Expert con Liquid y St...","fr":"Guide de mise en place pour les experts Shopify avec Liqu...","de":"Einrichtungsleitfaden für Shopify-Experten mit Liquid und...","pt":"Guia de Configuração do Shopify Expert","ru":"ИИ Агент Shopify Expert: Руководство по Настройке","ar":"دليل إعداد خبير Shopify"},"description":{"en":"Unlock the full potential of Shopify with our expert skill, featuring theme development, Storefront API, and custom checkout solutions. Learn how to build hi...","zh":"了解 Shopify Expert 的功能和特点，包括主题开发、Headless Commerce 和自定义结账解决方案","ja":"Shopify エキスパートの機能と特徴を紹介します。テーマ開発、ヘッドレス コマース、カスタム チェックアウト ソリューションなど","ko":"Shopify Expert의 기능과 특징을 살펴보세요. 테마 개발, 헤드리스 커머스, 커스텀 결제 솔루션 등","es":"Aprende a configurar y optimizar tu tienda Shopify con nuestro experto en desarrollo de temas, comercio headless y soluciones de checkout personalizadas","fr":"Découvrez comment configurer et optimiser votre boutique Shopify avec notre expert en développement de thèmes, commerce headless et solutions de checkout per...","de":"Erfahren Sie, wie Sie Ihren Shopify-Shop mit unserem Experten für Theme-Entwicklung, Headless-Commerce und benutzerdefinierten Checkout-Lösungen konfiguriere...","pt":"Aprenda a configurar e otimizar o Shopify com o nosso especialista, incluindo tema de desenvolvimento com Liquid e comércio headless com Storefront API","ru":"Узнайте, как настроить и оптимизировать Shopify с помощью нашего эксперта, включая разработку темы с Liquid и headless коммерции с Storefront API","ar":"تعرف على كيفية إعداد وتحسين Shopify باستخدام خبيرنا، بما في ذلك تطوير المواضيع باستخدام Liquid والتجارة بدون رأس مع Storefront API"},"definition":{"e