INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fulfon/lusena-dawn/shopify-expert', 'shopify-expert', 'fulfon', 'lusena-dawn', 'community', 'shopify-expert fulfon lusena-dawn community The Shopify-Expert skill is designed for senior Shopify developers, providing expertise in theme development, headless commerce, and custom checkout solutions. It helps developers build high-performing stores with optimized checkout flows. Shopify Expert 是一位高级 Shopify 开发者，专注于主题开发、Headless Commerce 和自定义结账解决方案 Shopify エキスパートは、テーマ開発、ヘッドレス コマース、カスタム チェックアウト ソリューションを専門とするシニア Shopify 開発者です Shopify Expert는 테마 개발, 헤드리스 커머스, 커스텀 결제 솔루션을 전문으로 하는 시니어 Shopify 개발자입니다 El experto en Shopify es un desarrollador senior con experiencia en desarrollo de temas con Liquid, comercio headless con Storefront API y soluciones de checkout personalizadas L''expert Shopify est un développeur senior avec une expérience approfondie dans le développement de thèmes avec Liquid, le commerce headless avec Storefront API et les solutions de checkout personnalisées Der Shopify-Experte ist ein Senior-Entwickler mit Erfahrung in der Entwicklung von Themes mit Liquid, Headless-Commerce mit Storefront API und benutzerdefinierten Checkout-Lösungen O Shopify Expert é um especialista em desenvolvimento de temas e comércio headless para Shopify, com habilidades em Liquid, Storefront API e checkout personalizado ИИ Агент Shopify Expert - это специалист по разработке тем и headless коммерции для Shopify, с навыками в Liquid, Storefront API и настраиваемом checkout خبير Shopify هو خبير في تطوير المواضيع والتجارة بدون رأس لشوبيفاي، مع مهارات في Liquid و Storefront API و Checkout المخصص shopify expert definition how to use shopify expert shopify expert vs shopify plus shopify expert setup guide shopify expert theme development shopify expert headless commerce shopify expert custom checkout shopify expert install shopify expert alternative shopify expert tutorial Shopify Expert Shopify 开发 Liquid Headless Commerce Storefront API 自定义结账解决方案 高性能商店建设 Develops custom Shopify themes using Liquid Implements headless commerce solutions with Storefront API Builds custom Shopify apps with app architecture expertise Optimizes checkout flows for conversion-optimized results Achieves sub-2s load times for high-performing stores Extends checkout functionality with custom solutions Shopify-expert is a senior Shopify developer skill with expertise in theme development using Liquid, headless commerce with Storefront API, and custom Shopify app development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('deadronos/gpu-conway-life/r3f-best-practices', 'community', 'deadronos', 'gpu-conway-life', 'deadronos/gpu-conway-life', 'r3f-best-practices', 0, 0, 44, '2026-03-07T01:49:01.572Z', '2026-03-07T02:07:59.368Z', '4782e1666bd52b07a958a83671af91c66a54313cdd7e61269bff0ebc6772dad7', '{"id":"deadronos/gpu-conway-life/r3f-best-practices","name":"r3f-best-practices","description":{"en":"The r3f-best-practices skill provides a comprehensive guide for React Three Fiber and the Poimandres ecosystem, helping developers optimize performance and write efficient R3F components.","zh":"React Three Fiber 最佳实践指南，包含 60+ 条规则，帮助开发者优化性能和渲染","ja":"React Three Fiber ベストプラクティスガイド、60 を超えるルールを提供してパフォーマンスとレンダリングを最適化","ko":"React Three Fiber 최적화 가이드, 60개 이상의 규칙을 통해 성능과 렌더링을 최적화","es":"Guía de mejores prácticas para React Three Fiber y el ecosistema de Poimandres, con 60+ reglas para optimizar el rendimiento y la configuración","fr":"Guide de bonnes pratiques pour React Three Fiber et l''écosystème de Poimandres, avec 60+ règles pour optimiser les performances et la configuration","de":"Leitfaden für Best Practices für React Three Fiber und das Poimandres-Ökosystem, mit 60+ Regeln für die Optimierung von Leistung und Konfiguration","pt":"O guia de melhores práticas para React Three Fiber fornece dicas e orientações para escrever componentes eficientes e otimizar o desempenho","ru":"Руководство по лучшим практикам для React Three Fiber предоставляет советы и рекомендации по написанию эффективных компонентов и оптимизации производительности для ИИ Агентов","ar":"دليل أفضل الممارسات ل React Three Fiber يقدم نصائح وتوجيهات لكتابة مكونات فعالة وتحسين الأداء لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"r3f-best-practices: Comprehensive Guide for React Three F...","zh":"React Three Fiber 最佳实践指南","ja":"React Three Fiber ベストプラクティスガイド","ko":"React Three Fiber 최적화 가이드","es":"Mejores Prácticas de React Three Fiber: Guía de Configura...","fr":"Bonnes Pratiques de React Three Fiber: Guide de Mise en P...","de":"Best Practices für React Three Fiber: Einrichtungsleitfaden","pt":"Guia de Configuração para r3f-best-practices: Melhores Pr...","ru":"Руководство по настройке r3f-best-practices: Лучшие практ...","ar":"دليل الإعداد لأفضل الممارسات r3f: إرشادات وتوجيهات ل Reac..."},"description":{"en":"Unlock optimized performance in React Three Fiber with our expert guide, featuring 60+ rules and best practices for R3F components, Drei helpers, and Zustand...","zh":"提高 React Three Fiber 项目性能，了解 60+ 条最佳实践，优化渲染和状态管理","ja":"React Three Fiber プロジェクトのパフォーマンスを向上させるため、60 を超えるベストプラクティスを学ぶ","ko":"React Three Fiber 프로젝트 성능 향상을 위한 60개 이상의 최적화 전략","es":"Aprende a optimizar el rendimiento de React Three Fiber con nuestras mejores prácticas y guías de configuración para una integración perfecta con Three.js","fr":"Améliorez les performances de React Three Fiber avec nos meilleures pratiques et guides de configuration pour une intégration parfaite avec Three.js","de":"Erfahren Sie, wie Sie die Leistung von React Three Fiber optimieren können, mit unseren Best Practices und Konfigurationsleitfäden für eine perfekte Integrat...","pt":"Aprenda a otimizar o desempenho do React Three Fiber com nossas melhores práticas e dicas para escrita de componentes eficientes","ru":"Узнайте, как оптимизировать производительность React Three Fiber с помощью наших лучших практик и советов по написанию эффективных компонентов для ИИ Агентов","ar":"تعلم كيفية تحسين أداء React Three Fiber باستخدام إرشاداتنا وأفضل الممارسات لكتابة المكونات الفعالة لأدوات الذكاء الاصطناعي"},"definition":{"en":"r3f-best-practices is a set of guidelines for React Three Fiber, covering 11 categories and 60+ rules to improve performance, optimize re-renders, and manage state with Zustand.","zh":"React Three Fiber 最佳实践是指一组优化 React Three Fiber 项目性能的规则和建议","ja":"React Three Fiber ベストプラクティスは、React Three Fiber プロジェクトのパフォーマンスを最適化するためのルールと推奨事項のセット","ko":"React Three Fiber 최적화는 React Three Fiber 프로젝트 성능을 향상시키기 위한 규칙과 제안의 집합","es":"React Three Fiber es un renderizador de React para Three.js, que proporciona una forma eficiente de integrar gráficos 3D en aplicaciones web","fr":"React Three Fiber est un renderisseur de React pour Three.js, qui offre un moyen efficace d''intégrer des graphiques 3D dans des applications web","de":"React Three Fiber ist ein Render-Engine für React und Three.js, die eine effiziente Möglichkeit bietet, 3D-Grafiken in Webanwendungen zu integrieren","pt":"r3f-best-practices é um guia de configuração para React Three Fiber que fornece regras e diretrizes para escrever componentes eficientes","ru":"r3f-best-practices - это руководство по настройке для React Three Fiber, которое предоставляет правила и рекомендации по написанию эффективных компонентов для ИИ Агентов","ar":"r3f-best-practices هو دليل إعداد ل React Three Fiber يقدم قواعد وتوجيهات لكتابة مكونات فعالة لأدوات الذكاء الاصطناعي"},"features":{"en":["Provides 60+ rules across 11 categories for optimized React Three Fiber performance","Covers best practices for writing new R3F components and optimizing re-renders","Includes guidelines for using Drei helpers correctly and managing state with Zustand","Offers expert advice on implementing post-processing and physics in R3F","Supports the Poimandres ecosystem, including @react-three/fiber and @r"],"zh":["优化渲染和状态管理","使用 Drei 辅助函数","管理 Zustand 状态","实现后处理和物理效果","覆盖 @react-three/fiber 和 @r 库"],"ja":["レンダリングと状態管理の最適化","Drei ヘルパー関数の使用","Zustand 状態の管理","ポストプロセッシングと物理効果の実装","@react-three/fiber と @r ライブラリのカバー"],"ko":["렌더링과 상태 관리 최적화","Drei 헬퍼 함수 사용","Zustand 상태 관리","포스트 프로세싱과 물리 효과 구현","@react-three/fiber와 @r 라이브러리 커버"],"es":["Optimización de rendimiento con 60+ reglas","Integración perfecta con Three.js","Uso de Drei helpers para una configuración más sencilla","Gestión de estado con Zustand","Implementación de post-procesamiento y física"],"fr":["Optimisation des performances avec 60+ règles","Intégration parfaite avec Three.js","Utilisation des helpers Drei pour une configuration plus simple","Gestion d''état avec Zustand","Mise en œuvre de post-traitement et de physique"],"de":["Leistungsoptimierung mit 60+ Regeln","Perfekte Integration mit Three.js","Verwendung von Drei-Hilfen für eine einfachere Konfiguration","Zustandsverwaltung mit Zustand","Implementierung von Post-Verarbeitung und Physik"],"pt":["Otimização de desempenho com regras de re-renderização","Uso correto de helpers Drei","Gerenciamento de estado com Zustand","Implementação de pós-processamento e física","Cobertura do ecossistema @react-three/fiber","Mais de 60 regras em 11 categorias"],"ru":["Оптимизация производительности с помощью правил переотрисовки","Правильное использование хелперов Drei","Управление состоянием с помощью Zustand","Реализация постобработки и физики","Покрытие экосистемы @react-three/fiber","Более 60 правил в 11 категориях для ИИ Агентов"],"ar":["تحسين الأداء باستخدام قواعد إعادة الرسم","استخدام صحيح للمساعدين Drei","إدارة الحالة مع Zustand","تنفيذ المعالجة التالية والفيزياء","تغطية نظام إدارة الإعدادات @react-three/fiber","أكثر من 60 قاعدة في 11 فئة لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use r3f-best-practices","r3f-best-practices setup guide","react three fiber optimization","r3f-best-practices vs react-three-fiber","r3f-best-practices install","react three fiber best practices","what is r3f-best-practices","r3f-best-practices alternative","r3f-best-practices tutorial"],"zh":["React Three Fiber","最佳实践","性能优化","渲染优化","状态管理","Drei","Zustand","后处理","物理效果"],"ja":["React Three Fiber","ベストプラクティス","パフォーマンス最適化","レンダリング最適化","状態管理","Drei","Zustand","ポストプロセッシング","物理効果"],"ko":["React Three Fiber","최적화 가이드","성능 향상","렌더링 최적화","상태 관리","Drei","Zustand","포스트 프로세싱","물리 효과"],"es":["React Three Fiber","Mejores prácticas de React","Optimización de rendimiento de Three.js","Integración de gráficos 3D en aplicaciones web","Drei helpers","Zustand","Post-procesamiento y física"],"fr":["React Three Fiber","Bonnes pratiques de React","Optimisation des performances de Three.js","Intégration de graphiques 3D dans des applications web","Helpers Drei","Zustand","Post-traitement et physique"],"de":["React Three Fiber","Best Practices für React","Leistungsoptimierung von Three.js","Integration von 3D-Grafiken in Webanwendungen","Drei-Hilfen","Zustand","Post-Verarbeitung und Physik"],"pt":["React Three Fiber","melhores práticas","otimização de desempenho","Drei helpers","Zustand","pós-processamento","física","ecossistema @react-three/fiber","desenvolvimento de componentes","guias de configuração"],"ru":["React Three Fiber","лучшие практики","оптимизация производительности","Drei хелперы","Zustand","постобработка","физика","экосистема @react-three/fiber","разработка компонентов","руководства по настройке для ИИ Агентов"],"ar":["React Three Fiber","أفضل الممارسات","تحسين الأداء","مساعدين Drei","Zustand","المعالجة التالية","الفيزياء","نظام إدارة الإعدادات @react-three/fiber","تطوير المكونات","دلائل الإعداد لأدوات الذكاء الاصطناعي"]}},"owner":"deadronos","repo":"gpu-conway-life","repoPath":"deadronos/gpu-conway-life","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.572Z","topics":[],"category":"community","skillMd":{"name":"r3f-best-practices","description":"React Three Fiber (R3F) and Poimandres ecosystem best practices. Use when writing, reviewing, or optimizing R3F code. Triggers on tasks involving @react-three/fiber, @react-three/drei, zustand, @react-three/postprocessing, @react-three/rapier, or leva.","version":"1.0.0","bodyPreview":"# React Three Fiber Best Practices\n\nComprehensive guide for React Three Fiber and the Poimandres ecosystem. Contains 60+ rules across 11 categories, prioritized by impact.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing new R3F components\n- Optimizing R3F performance (re-renders are the #1 issue)\n- Using Drei helpers correctly\n- Managing state with Zustand\n- Implementing post-processing or physics\n\n## Ecosystem Coverage\n\n- **@react-three/fiber** - React renderer for Three.js\n- **@r","body":"# React Three Fiber Best Practices\n\nComprehensive guide for React Three Fiber and the Poimandres ecosystem. Contains 60+ rules across 11 categories, prioritized by impact.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing new R3F components\n- Optimizing R3F performance (re-renders are the #1 issue)\n- Using Drei helpers correctly\n- Managing state with Zustand\n- Implementing post-processing or physics\n\n## Ecosystem Coverage\n\n- **@react-three/fiber** - React renderer for Three.js\n- **@react-three/drei** - Useful helpers and abstractions\n- **@react-three/postprocessing** - Post-processing effects\n- **@react-three/rapier** - Physics engine\n- **zustand** - State management\n- **leva** - Debug GUI\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Performance & Re-renders | CRITICAL | `perf-` |\n| 2 | useFrame & Animation | CRITICAL | `frame-` |\n| 3 | Component Patterns | HIGH | `component-` |\n| 4 | Canvas & Setup | HIGH | `canvas-` |\n| 5 | Drei Helpers | MEDIUM-HIGH | `drei-` |\n| 6 | Loading & Suspense | MEDIUM-HIGH | `loading-` |\n| 7 | State Management | MEDIUM | `state-` |\n| 8 | Events & Interaction | MEDIUM | `events-` |\n| 9 | Post-processing | MEDIUM | `postpro-` |\n| 10 | Physics (Rapier) | LOW-MEDIUM | `physics-` |\n| 11 | Leva (Debug GUI) | LOW | `leva-` |\n\n## Quick Reference\n\n### 1. Performance & Re-renders (CRITICAL)\n\n- `perf-never-set-state-in-useframe` - NEVER call setState in useFrame\n- `perf-isolate-state` - Isolate components that need React state\n- `perf-zustand-selectors` - Use Zustand selectors, not entire store\n- `perf-transient-subscriptions` - Use transient subscriptions for continuous values\n- `perf-memo-components` - Memoize expensive components\n- `perf-keys-for-lists` - Use stable keys for dynamic lists\n- `perf-avoid-inline-objects` - Avoid creating objects/arrays in JSX\n- `perf-dispose-auto` - Understand R3F auto-dispose behavior\n\n### 2. useFrame & Animation (CRITICAL)\n\n- `frame-priority` - Use priority for execution order\n- `frame-delta-time` - Always use delta for animations\n- `frame-conditional-subscription` - Disable useFrame when not needed\n- `frame-destructure-state` - Destructure only what you need\n- `frame-render-on-demand` - Use invalidate() for on-demand rendering\n- `frame-avoid-heavy-computation` - Move heavy work outside useFrame\n\n### 3. Component Patterns (HIGH)\n\n- `component-jsx-elements` - Use JSX for Three.js objects\n- `component-attach-prop` - Use attach for non-standard properties\n- `component-primitive` - Use primitive for existing objects\n- `component-extend` - Use extend() for custom classes\n- `component-forwardref` - Use forwardRef for reusable components\n- `component-dispose-null` - Set dispose={null} on shared resources\n\n### 4. Canvas & Setup (HIGH)\n\n- `canvas-size-container` - Canvas fills parent container\n- `canvas-camera-default` - Configure camera via prop\n- `canvas-gl-config` - Configure WebGL context\n- `canvas-shadows` - Enable shadows at Canvas level\n- `canvas-frameloop` - Choose appropriate frameloop mode\n- `canvas-events` - Configure event handling\n- `canvas-linear-flat` - Use linear/flat for correct colors\n\n### 5. Drei Helpers (MEDIUM-HIGH)\n\n- `drei-use-gltf` - useGLTF with preloading\n- `drei-use-texture` - useTexture for texture loading\n- `drei-environment` - Environment for realistic lighting\n- `drei-orbit-controls` - OrbitControls from Drei\n- `drei-html` - Html for DOM overlays\n- `drei-text` - Text for 3D text\n- `drei-instances` - Instances for optimized instancing\n- `drei-use-helper` - useHelper for debug visualization\n- `drei-bounds` - Bounds to fit camera\n- `drei-center` - Center to center objects\n- `drei-float` - Float for floating animation\n\n### 6. Loading & Suspense (MEDIUM-HIGH)\n\n- `loading-suspense` - Wrap async components in Suspense\n- `loading-preload` - Preload assets with useGLTF.preload\n- `loading-use-progress` - useProgress for loading UI\n- `loading-lazy-components` - Lazy load heavy components\n- `loading-error-boundary` - Handle loading errors\n\n### 7. State Management (MEDIUM)\n\n- `state-zustand-store` - Create focused Zustand stores\n- `state-avoid-objects-in-store` - Be careful with Three.js objects\n- `state-subscribeWithSelector` - Fine-grained subscriptions\n- `state-persist` - Persist state when needed\n- `state-separate-concerns` - Separate stores by concern\n\n### 8. Events & Interaction (MEDIUM)\n\n- `events-pointer-events` - Use pointer events on meshes\n- `events-stop-propagation` - Prevent event bubbling\n- `events-cursor-pointer` - Change cursor on hover\n- `events-raycast-filter` - Filter raycasting\n- `events-event-data` - Understand event data structure\n\n### 9. Post-processing (MEDIUM)\n\n- `postpro-effect-composer` - Use EffectComposer\n- `postpro-common-effects` - Common effects reference\n- `postpro-selective-bloom` - SelectiveBloom for optimized glow\n- `postpro-custom-shader` - Create custom effects\n- `postpro-performance` - Optimize post-processing\n\n### 10. Physics Rapier (LOW-MEDIUM)\n\n- `physics-setup` - Basic Rapier setup\n- `physics-body-types` - dynamic, fixed, kinematic\n- `physics-colliders` - Choose appropriate colliders\n- `physics-events` - Handle collision events\n- `physics-api-ref` - Use ref for physics API\n- `physics-performance` - Optimize physics\n\n### 11. Leva (LOW)\n\n- `leva-basic` - Basic Leva usage\n- `leva-folders` - Organize with folders\n- `leva-conditional` - Hide in production\n\n## How to Use\n\nRead individual rule files for detailed explanations and code examples:\n\n```\nrules/perf-never-set-state-in-useframe.md\nrules/drei-use-gltf.md\nrules/state-zustand-selectors.md\n```\n\n## Full Compiled Document\n\nFor the complete guide with all rules expanded: `../R3F_BEST_PRACTICES.md`\n\n## Critical Patterns\n\n### NEVER setState in useFrame\n\n```jsx\n// BAD - 60 re-renders per second!\nfunction BadComponent() {\n  const [position, setPosition] = useState(0);\n  useFrame(() => {\n    setPosition(p => p + 0.01); // NEVER DO THIS\n  });\n  return <mesh position-x={position} />;\n}\n\n// GOOD - Mutate refs directly\nfunction GoodComponent() {\n  const meshRef = useRef();\n  useFrame(() => {\n    meshRef.current.position.x += 0.01;\n  });\n  return <mesh ref={meshRef} />;\n}\n```\n\n### Zustand Selectors\n\n```jsx\n// BAD - Re-renders on ANY store change\nconst store = useGameStore();\n\n// GOOD - Only re-renders when playerX changes\nconst playerX = useGameStore(state => state.playerX);\n\n// BETTER - No re-renders, direct mutation\nuseFrame(() => {\n  const { value } = useStore.getState();\n  ref.current.position.x = value;\n});\n```\n\n### Drei useGLTF\n\n```jsx\nimport { useGLTF } from ''@react-three/drei'';\n\nfunction Model() {\n  const { scene } = useGLTF(''/model.glb'');\n  return <primitive object={scene} />;\n}\n\n// Preload for instant loading\nuseGLTF.preload(''/model.glb'');\n```\n\n### Suspense Loading\n\n```jsx\nfunction App() {\n  return (\n    <Canvas>\n      <Suspense fallback={<Loader />}>\n        <Model />\n      </Suspense>\n    </Canvas>\n  );\n}\n```\n"},"lastSynced":"2026-03-07T02:07:59.368Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing optimized React Three Fiber performance and best practices for the Poimandres ecosystem.","zh":"非常适合需要优化React Three Fiber性能和遵循Poimandres生态系统最佳实践的前端代理。","ja":"React Three Fiberのパフォーマンスを最適化し、Poimandresエコシステムのベストプラクティスに従う必要があるフロントエンドエージェントに最適です。","ko":"React Three Fiber 성능을 최적화하고 Poimandres 생태계의 모범 사례에 따라야 하는 프런트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan un rendimiento optimizado de React Three Fiber y las mejores prácticas para el ecosistema de Poimandres.","fr":"Parfait pour les agents Frontend ayant besoin d''un rendimiento optimisé de React Three Fiber et des meilleures pratiques pour l''écosystème de Poimandres.","de":"Perfekt für Frontend-Agents, die ein optimiertes React Three Fiber-Performance und die besten Praktiken für das Poimandres-Ökosystem benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de desempenho otimizado do React Three Fiber e melhores práticas para o ecossistema Poimandres.","ru":"Идеально подходит для агентов Frontend, которым необходим оптимизированный性能 React Three Fiber и лучшие практики для экосистемы Poimandres.","ar":"مثالي لعميل واجهة المستخدم الذين يحتاجون إلى أداء محسّن لبرنامج React Three Fiber وأفضل الممارسات لنظام بيئة Poimandres."},"recommendation":{"en":"Empowers agents to write efficient R3F components, optimize performance, and correctly utilize Drei helpers and Zustand state management, all while following 60+ rules across 11 categories for optimal impact, utilizing libraries like @react-three/fiber and implementing post-processing or physics.","zh":"赋予代理编写高效的R3F组件、优化性能、正确利用Drei助手和Zustand状态管理的能力，同时遵循11个类别中的60多条规则以实现最佳效果，利用像@react-three/fiber这样的库，并实现后处理或物理。","ja":"エージェントが効率的なR3Fコンポーネントを記述し、パフォーマンスを最適化し、DreiヘルパーとZustandステート管理を正しく利用する能力を付与し、11のカテゴリにわたる60を超えるルールに従って最大の影響を与え、@react-three/fiberなどのライブラリを利用し、ポストプロセッシングまたは物理を実装する。","ko":"에이전트가 효율적인 R3F 컴포넌트를 작성하고 성능을 최적화하며 Drei 헬퍼와 Zustand 상태 관리를 올바르게 사용할 수 있도록 하며, 최대 영향을 주기 위해 11개 범주에 걸쳐 60개 이상의 규칙을 따르며, @react-three/fiber와 같은 라이브러리를 사용하고 후처리 또는 물리학을 구현할 수 있습니다.","es":"Habilita a los agentes a escribir componentes R3F eficientes, optimizar el rendimiento y utilizar correctamente los ayudantes Drei y la gestión de estado Zustand, todo mientras sigue 60+ reglas en 11 categorías para un impacto óptimo, utilizando bibliotecas como @react-three/fiber e implementando post-procesamiento o física.","fr":"Permet aux agents d''écrire des composants R3F efficaces, d''optimiser les performances et d''utiliser correctement les aides Drei et la gestion d''état Zustand, le tout en suivant 60+ règles dans 11 catégories pour un impact optimal, en utilisant des bibliothèques comme @react-three/fiber et en implémentant un post-traitement ou de la physique.","de":"Ermöglicht es Agenten, effiziente R3F-Komponenten zu schreiben, die Leistung zu optimieren und die Drei-Helfer und die Zustandverwaltung Zustand korrekt zu verwenden, all dies unter Einhaltung von 60+ Regeln in 11 Kategorien für einen optimalen Einfluss, unter Verwendung von Bibliotheken wie @react-three/fiber und Implementierung von Postbearbeitung oder Physik.","pt":"Habilita os agentes a escrever componentes R3F eficientes, otimizar o desempenho e utilizar corretamente os helpers Drei e gerenciamento de estado Zustand, tudo isso seguindo 60+ regras em 11 categorias para impacto ótimo, utilizando bibliotecas como @react-three/fiber e implementando pós-processamento ou física.","ru":"Наделяет агентов возможностью писать эффективные компоненты R3F, оптимизировать производительность и правильно использовать помощников Drei и управление состоянием Zustand, все это при соблюдении 60+ правил в 11 категориях для оптимального воздействия, используя библиотеки как @react-three/fiber и реализуя постобработку или физику.","ar":"تمكّن العميل من كتابة مكونات R3F فعالة، وتحسين الأداء، واستخدام مساعدات Drei وإدارة الحالة Zustand بشكل صحيح، مع اتباع 60+ قاعدة في 11 فئة لتحقيق تأثير مثالي، باستخدام مكتبات مثل @react-three/fiber وتنفيذ المعالجة اللاحقة أو الفيزياء."},"useCases":{"en":["Optimizing R3F component re-renders for improved performance","Implementing correct Drei helper usage for enhanced functionality","Managing state with Zustand for efficient data handling"],"zh":["优化R3F组件的重新渲染以提高性能","实现正确的Drei助手使用以增强功能","使用Zustand管理状态以高效处理数据"],"ja":["パフォーマンスの向上のためにR3Fコンポーネントの再描画を最適化する","機能を強化するためにDreiヘルパーの正しい使用を実装する","データを効率的に処理するためにZustandを使用してステートを管理する"],"ko":["성능을 개선하기 위해 R3F 컴포넌트의 재렌더링을 최적화하는 것","기능을 강화하기 위해 Drei 헬퍼의 올바른 사용을 구현하는 것","데이터를 효율적으로 처리하기 위해 Zustand를 사용하여 상태를 관리하는 것"],"es":["Optimizar las re-representaciones de componentes R3F para una mejor rendimiento","Implementar el uso correcto de los ayudantes Drei para una funcionalidad mejorada","Gestionar el estado con Zustand para un manejo de datos eficiente"],"fr":["Optimiser les ré-représentations de composants R3F pour de meilleures performances","Implémenter l''utilisation correcte des aides Drei pour une fonctionnalité améliorée","Gérer l''état avec Zustand pour une gestion de données efficace"],"de":["Optimieren der Neuzeichnung von R3F-Komponenten für eine bessere Leistung","Korrekte Implementierung der Drei-Helfer für eine verbesserte Funktionalität","Verwalten des Zustands mit Zustand für eine effiziente Datenverwaltung"],"pt":["Otimizar re-renderizações de componentes R3F para melhorar o desempenho","Implementar uso correto de helpers Drei para funcionalidade aprimorada","Gerenciar estado com Zustand para manipulação de dados eficiente"],"ru":["Оптимизировать повторную перерисовку компонентов R3F для улучшения производительности","Реализовать правильное использование помощников Drei для улучшения функциональности","Управлять состоянием с помощью Zustand для эффективного xử lý данных"],"ar":["تحسين إعادة عرض مكونات R3F لتحسين الأداء","تنفيذ استخدام مساعدات Drei بشكل صحيح لتحسين الوظائف","إدارة الحالة مع Zustand لمعالجة البيانات الفعالة"]},"limitations":{"en":["Requires knowledge of React Three Fiber and the Poimandres ecosystem","Specific to @react-three/fiber and related libraries"],"zh":["需要了解React Three Fiber和Poimandres生态系统","特定于@react-three/fiber和相关库"],"ja":["React Three FiberとPoimandresエコシステムの知識が必要","@react-three/fiberと関連ライブラリに特有"],"ko":["React Three Fiber와 Poimandres 생태계에 대한 지식이 필요함","@react-three/fiber와 관련 라이브러리에 특정됨"],"es":["Requiere conocimiento de React Three Fiber y del ecosistema de Poimandres","Específico para @react-three/fiber y bibliotecas relacionadas"],"fr":["Nécessite des connaissances en React Three Fiber et dans l''écosystème de Poimandres","Spécifique à @react-three/fiber et aux bibliothèques associées"],"de":["Benötigt Kenntnisse von React Three Fiber und dem Poimandres-Ökosystem","Spezifisch für @react-three/fiber und verwandte Bibliotheken"],"pt":["Requer conhecimento de React Three Fiber e do ecossistema Poimandres","Específico para @react-three/fiber e bibliotecas relacionadas"],"ru":["Требует знаний React Three Fiber и экосистемы Poimandres","Специфичен для @react-three/fiber и связанных библиотек"],"ar":["يتطلب معرفة برنامج React Three Fiber ونظام بيئة Poimandres","محدد لمكتبة @react-three/fiber والمكتبات المرتبطة بها"]},"version":4},"contentHash":"4782e1666bd52b07a958a83671af91c66a54313cdd7e61269bff0ebc6772dad7","qualityScore":44}');
