INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macho715/file/autosort-ledger-audit', 'community', 'macho715', 'file', 'macho715/file', 'autosort-ledger-audit', 0, 0, 44, '2026-03-03T14:18:39Z', '2026-03-07T04:14:38.749Z', '5fb8529c45ba940f1b38972e886f7dc12261bed331772f7967cf8462d45e5c3c', '{"id":"macho715/file/autosort-ledger-audit","name":"autosort-ledger-audit","description":{"en":"The autosort-ledger-audit skill audits ledger files for issues like missing fields and overwrite suspicions. It benefits developers by automating ledger checks.","zh":"autosort-ledger-audit 是一种用于检查和审计 ledger 文件的工具，支持检查最近 N 行记录","ja":"autosort-ledger-audit はレジャーファイルをチェックおよび監査するツールで、最近の N 行のレコードをチェックできます","ko":"autosort-ledger-audit는 ledger 파일을 점검하고 감사하는 도구로, 최근 N라인을 확인할 수 있습니다","es":"Autosort-ledger-audit es una herramienta de auditoría de registros de ledger que verifica la integridad de los datos y detecta problemas como campos omitidos o sobrescritos","fr":"Autosort-ledger-audit est un outil d''audit de journaux de ledger qui vérifie l''intégrité des données et détecte des problèmes tels que des champs manquants ou écrasés","de":"Autosort-ledger-audit ist ein Tool zur Überprüfung von Ledger-Einträgen, das die Integrität der Daten überprüft und Probleme wie fehlende oder überschriebene Felder erkennt","pt":"O autosort-ledger-audit é uma ferramenta de auditoria de ledger que verifica a integridade dos dados e detecta problemas como campos em falta ou sobrescritos","ru":"autosort-ledger-audit - это инструмент аудита ведgers, который проверяет целостность данных и обнаруживает проблемы, такие как пропущенные поля или перезаписанные данные с помощью ИИ Агенты","ar":"autosort-ledger-audit هو أداة تدقيق سجلات تقوم بفحص سلامة البيانات واكتشاف المشكلات مثل الحقول المفقودة أو المَحوّزة"},"seo":{"title":{"en":"autosort-ledger-audit: Ledger Audit Setup Guide | AI Agen...","zh":"autosort-ledger-audit 设置指南 - AI工具","ja":"autosort-ledger-audit のベストプラクティス - AIエージェント","ko":"autosort-ledger-audit 설정 가이드 - AI 에이전트","es":"Guía de configuración de autosort-ledger-audit para audit...","fr":"Guide de mise en place de autosort-ledger-audit pour les ...","de":"Einrichtungsleitfaden für autosort-ledger-audit zur Überp...","pt":"Guia de Configuração do autosort-ledger-audit: Auditoria ...","ru":"Настройка autosort-ledger-audit: 자동атический аудит ведger...","ar":"دليل إعداد autosort-ledger-audit: تدقيق سجلات 자동اتي"},"description":{"en":"Discover how autosort-ledger-audit simplifies ledger audits with automated checks and reporting. Get started with our AI agent skill today!","zh":"了解 autosort-ledger-audit 的功能和特点，包括 ledger 文件路径、检查范围和必要字段等","ja":"autosort-ledger-audit の機能と特徴を紹介します。レジャーファイルパス、チェック範囲、必須フィールドなど","ko":"autosort-ledger-audit의 기능과 특징을 알아보세요. ledger 파일 경로, 점검 범위, 필수 필드 등","es":"Aprenda a utilizar autosort-ledger-audit para auditar registros de ledger y detectar problemas como campos omitidos o sobrescritos","fr":"Découvrez comment utiliser autosort-ledger-audit pour auditer les journaux de ledger et détecter des problèmes tels que des champs manquants ou écrasés","de":"Erfahren Sie, wie Sie autosort-ledger-audit verwenden können, um Ledger-Einträge zu überprüfen und Probleme wie fehlende oder überschriebene Felder zu erkennen","pt":"Aprenda a configurar o autosort-ledger-audit para auditorias de ledger automatizadas e melhore a segurança dos seus dados","ru":"Узнайте, как настроить autosort-ledger-audit для автоматического аудита ведgers и улучшения безопасности данных с помощью ИИ Агенты","ar":"تعرف على كيفية إعداد autosort-ledger-audit لتدقيق سجلات خود động وتحسين أمان البيانات"},"definition":{"en":"autosort-ledger-audit is a skill that automates ledger audits, checking for required fields and suspicious patterns in ledger files.","zh":"autosort-ledger-audit 是一种 AI 工具，用于检查和审计 ledger 文件的完整性和准确性","ja":"autosort-ledger-audit はレジャーファイルの完全性と正確性をチェックおよび監査する AI エージェントです","ko":"autosort-ledger-audit는 ledger 파일의 완전성과 정확성을 점검하고 감사하는 AI 에이전트입니다","es":"Autosort-ledger-audit es una herramienta de auditoría de registros de ledger que verifica la integridad de los datos","fr":"Autosort-ledger-audit est un outil d''audit de journaux de ledger qui vérifie l''intégrité des données","de":"Autosort-ledger-audit ist ein Tool zur Überprüfung von Ledger-Einträgen, das die Integrität der Daten überprüft","pt":"O autosort-ledger-audit é uma ferramenta de auditoria de ledger que automatiza a verificação de dados","ru":"autosort-ledger-audit - это инструмент автоматического аудита ведgers","ar":"autosort-ledger-audit هو أداة تدقيق سجلات خود động"},"features":{"en":["Checks ledger files for required fields like before, after, reason, ts, run_id, action, and sha256","Detects prohibited patterns like delete, remove, unlink, overwrite, and replace","Supports dev rename detection by comparing before and after filenames","Allows specification of audit scope, including recent lines (default 200)","Generates reports based on audit results"],"zh":["支持检查最近 N 行记录","检查 ledger 文件路径和必要字段","支持检测 delete/remove/unlink/overwrite/replace 等操作","支持 Dev rename 检测","支持 Quarantine 规则检查"],"ja":["最近の N 行のレコードをチェックする機能","レジャーファイルパスと必須フィールドをチェックする機能","delete/remove/unlink/overwrite/replace などの操作を検知する機能","Dev rename を検知する機能","Quarantine ルールをチェックする機能"],"ko":["최근 N라인의 기록을 확인하는 기능","ledger 파일 경로와 필수 필드를 확인하는 기능","delete/remove/unlink/overwrite/replace 등의 작업을 탐지하는 기능","Dev rename을 탐지하는 기능","Quarantine 규칙을 점검하는 기능"],"es":["Verificación de campos obligatorios como before, after, reason, ts, run_id, action y sha256","Detección de patrones prohibidos como delete, remove, unlink, overwrite y replace","Detección de renombramiento de dev con `after filename != before filename`","Verificación de la cuarentena según las reglas establecidas","Soporte para la verificación de los últimos N registros (por defecto 200)","Compatibilidad con archivos de registro en formato JSONL"],"fr":["Vérification des champs obligatoires tels que before, after, reason, ts, run_id, action et sha256","Détection de modèles interdits tels que delete, remove, unlink, overwrite et replace","Détection de renommage de dev avec `after filename != before filename`","Vérification de la quarantaine selon les règles établies","Prise en charge de la vérification des derniers N enregistrements (par défaut 200)","Compatibilité avec les fichiers de journal au format JSONL"],"de":["Überprüfung von Pflichtfeldern wie before, after, reason, ts, run_id, action und sha256","Erkennung von verbotenen Mustern wie delete, remove, unlink, overwrite und replace","Erkennung von Dev-Umbenennungen mit `after filename != before filename`","Überprüfung der Quarantäne nach den festgelegten Regeln","Unterstützung für die Überprüfung der letzten N Einträge (Standard 200)","Kompatibilität mit Logdateien im JSONL-Format"],"pt":["Verificação de campos obrigatórios como before, after, reason, ts, run_id, action e sha256","Detecção de padrões proibidos como delete, remove, unlink, overwrite e replace","Prevenção de renomeação de arquivos de desenvolvimento","Verificação de uso de quarantine"],"ru":["Проверка обязательных полей, таких как before, after, reason, ts, run_id, action и sha256","Обнаружение запрещенных паттернов, таких как delete, remove, unlink, overwrite и replace с помощью ИИ Агенты","Предотвращение переименования файлов разработки","Проверка использования карантина"],"ar":["فحص الحقول الإجبارية مثل before, after, reason, ts, run_id, action و sha256","اكتشاف الأنماط المحظورة مثل delete, remove, unlink, overwrite و replace","منع إعادة تسمية ملفات التطوير","فحص استخدام الحجر الصحي"]},"keywords":{"en":["how to use autosort-ledger-audit","autosort-ledger-audit setup guide","ledger audit tools","autosort-ledger-audit alternative","autosort-ledger-audit vs manual audit","automated ledger checking","ledger file analysis","dev rename detection"],"zh":["AI 工具","ledger 文件检查","autosort-ledger-audit","レジャーファイル監査","检查最近 N 行记录","必要字段检查","Dev rename 检测"],"ja":["AI エージェント","レジャーファイルチェック","autosort-ledger-audit","レジャーファイル監査","最近の N 行のレコードをチェック","必須フィールドをチェック","Dev rename を検知"],"ko":["AI 에이전트","ledger 파일 점검","autosort-ledger-audit","레저 파일 감사","최근 N라인의 기록을 확인","필수 필드를 확인","Dev rename을 탐지"],"es":["autosort-ledger-audit","auditoría de registros de ledger","herramienta de auditoría","verificación de integridad de datos","detección de problemas de registro","renombramiento de dev","cuarentena de registros","JSONL","Herramientas de AI para la auditoría"],"fr":["autosort-ledger-audit","audit de journaux de ledger","outil d''audit","vérification de l''intégrité des données","détection de problèmes de journal","renommeage de dev","quarantaine de journaux","JSONL","Outils d''IA pour l''audit"],"de":["autosort-ledger-audit","Überprüfung von Ledger-Einträgen","Tool zur Überprüfung","Überprüfung der Integrität der Daten","Erkennung von Problemen mit Einträgen","Umbenennung von Dev","Quarantäne von Einträgen","JSONL","AI-Tools für die Überprüfung"],"pt":["auditoria de ledger","autosort-ledger-audit","ferramenta de auditoria","segurança de dados","integridade de dados","campo obrigatório","padrão proibido"],"ru":["аудит ведgers","autosort-ledger-audit","инструмент аудита","безопасность данных","целостность данных","обязательное поле","запрещенный паттерн","ИИ Агенты"],"ar":["تدقيق سجلات","autosort-ledger-audit","أداة تدقيق","أمان البيانات","سلامة البيانات","حقل إجباري","نمط محظور"]}},"owner":"macho715","repo":"file","repoPath":"macho715/file","stars":0,"forks":0,"updatedAt":"2026-03-03T14:18:39Z","topics":[],"category":"community","skillMd":{"name":"autosort-ledger-audit","description":"autosort ledger.jsonl의 무결성/정책 위반을 감사(audit)한다. before/after, decision, confidence, reason, timestamp, run_id 필드 누락/위반 탐지에 사용.","bodyPreview":"# autosort-ledger-audit\n\n## When to Use\n- \"ledger가 제대로 남았나?\", \"이동 로그 감사\", \"정리 결과 리포트\"\n- 이슈: 누락 필드, overwrite 의심, quarantine 미사용, dev rename 의심\n\n## Inputs\n- ledger 파일 경로(예: `C:\\_AUTOSORT\\logs\\ledger.jsonl` 또는 실제 경로)\n- 점검 범위: 최근 N라인(기본 200)\n\n## Checks\n- 필수 필드: before, after, reason, ts, run_id, action, sha256 (decision/confidence는 cache.json에 있음, ledger 감사 시 참고)\n- 금지 패턴: delete/remove/unlink/overwrite/replace\n- Dev rename 금지: Dev 분류(코드/레포/설정)에서 `after filename != before filename` 탐지\n- Quarantine 규","body":"# autosort-ledger-audit\n\n## When to Use\n- \"ledger가 제대로 남았나?\", \"이동 로그 감사\", \"정리 결과 리포트\"\n- 이슈: 누락 필드, overwrite 의심, quarantine 미사용, dev rename 의심\n\n## Inputs\n- ledger 파일 경로(예: `C:\\_AUTOSORT\\logs\\ledger.jsonl` 또는 실제 경로)\n- 점검 범위: 최근 N라인(기본 200)\n\n## Checks\n- 필수 필드: before, after, reason, ts, run_id, action, sha256 (decision/confidence는 cache.json에 있음, ledger 감사 시 참고)\n- 금지 패턴: delete/remove/unlink/overwrite/replace\n- Dev rename 금지: Dev 분류(코드/레포/설정)에서 `after filename != before filename` 탐지\n- Quarantine 규칙: ambiguity/conflict/failure는 quarantine으로 라우팅됐는지\n\n## Outputs\n- Summary: total lines / violations count\n- Violations table: type | count | sample line numbers | action\n- Recommendation: 룰 추가 여부(\"같은 오류 2회 이상\"일 때만)\n"},"lastSynced":"2026-03-07T04:14:38.749Z","agentAnalysis":{"suitability":{"en":"Ideal for Ledger Analysis Agents requiring automated audit capabilities for ledger files","zh":"适合需要对账本文件进行自动化审计的账本分析代理","ja":"台帳分析エージェントが台帳ファイルの自動化監査機能を必要とする場合に適しています","ko":"원장 파일에 대한 자동 감사 기능을 필요로 하는 원장 분석 에이전트에 적합합니다","es":"Ideal para Agentes de Análisis de Ledger que requieren capacidades de auditoría automatizada para archivos de ledger","fr":"Idéal pour les agents d''analyse de Ledger nécessitant des capacités d''audit automatisées pour les fichiers de ledger","de":"Ideal für Ledger-Analyse-Agents, die automatisierte Prüfkapazitäten für Ledger-Dateien erfordern","pt":"Ideal para Agentes de Análise de Ledger que exigem capacidades de auditoria automatizada para arquivos de ledger","ru":"Идеально для Агентов Анализа Ledger, требующих автоматизированных возможностей аудита для файлов леджера","ar":"مثالي لعمليات تحليل دفتر الأستاذ التي تتطلب قدرات تدقيق أوتوماتيكية لملفات دفتر الأستاذ"},"recommendation":{"en":"Empowers agents to detect issues like missing fields and overwrite suspicions in ledger files, utilizing JSONL file format and performing checks on fields such as before, after, reason, ts, run_id, action, and sha256, while also identifying dev rename suspicions and quarantine usage","zh":"赋予代理检测台帳文件中缺失字段和覆盖疑虑等问题的能力，利用JSONL文件格式并对字段（如before、after、reason、ts、run_id、action和sha256）进行检查，同时识别开发者重命名疑虑和隔离区使用","ja":"エージェントが台帳ファイルのフィールド不足や上書きの疑いなどの問題を検出する能力を付与します。JSONLファイル形式を利用し、before、after、reason、ts、run_id、action、sha256などのフィールドに対してチェックを実行します。また、開発者名の変更の疑いや隔離使用の検出も行います","ko":"에이전트가 원장 파일에서 필드 누락 및 덮어쓰기 의심 등 문제를 감지하는 기능을 제공합니다. JSONL 파일 형식을 사용하며 before, after, reason, ts, run_id, action 및 sha256 등의 필드를 확인합니다. 개발자 이름 변경 의심 및 격리 사용도 식별합니다","es":"Habilita a los agentes a detectar problemas como campos que faltan y sospechas de sobrescritura en archivos de ledger, utilizando el formato de archivo JSONL y realizando comprobaciones en campos como antes, después, razón, ts, run_id, acción y sha256, además de identificar sospechas de renombrado de dev y uso de cuarentena","fr":"Permet aux agents de détecter des problèmes tels que des champs manquants et des soupçons de surécriture dans les fichiers de ledger, en utilisant le format de fichier JSONL et en effectuant des vérifications sur des champs tels que avant, après, raison, ts, run_id, action et sha256, ainsi que d''identifier des soupçons de renommage de dev et d''utilisation de quarantaine","de":"Ermöglicht es den Agents, Probleme wie fehlende Felder und Überschreibungsverdacht in Ledger-Dateien zu erkennen, indem sie das JSONL-Dateiformat verwenden und Prüfungen in Feldern wie vor, nach, Grund, ts, run_id, Aktion und sha256 durchführen, sowie Entwicklervorlagen-Verdacht und Quarantäne-Nutzung zu identifizieren","pt":"Habilita os agentes a detectar problemas como campos ausentes e suspeitas de sobrescrita em arquivos de ledger, utilizando o formato de arquivo JSONL e realizando verificações em campos como before, after, reason, ts, run_id, action e sha256, além de identificar suspeitas de renomeação de dev e uso de quarentena","ru":"Наделяет агентов возможностью обнаруживать проблемы, такие как отсутствующие поля и подозрения в перезаписи в файлах леджера, используя формат файла JSONL и выполняя проверки полей, таких как before, after, reason, ts, run_id, action и sha256, а также выявляя подозрения в переименовании dev и использовании карантина","ar":"تمكّن الوكلاء من كشف مشاكل مثل الحقول الناقصة والشكوك في الكتابة فوق ملفات دفتر الأستاذ، باستخدام تنسيق ملف JSONL وإجراء فحوصات على حقول مثل before و after و reason و ts و run_id و action و sha256، بالإضافة إلى تحديد شكوك إعادة تسمية التطوير واستخدام الحجر الصحي"},"useCases":{"en":["Auditing ledger files for missing fields and overwrite suspicions","Automating ledger checks for issues like quarantine misuse and dev rename suspicions","Generating reports on ledger audit results, including detected issues and suspicious activity"],"zh":["对台帳文件进行审计以检测缺失字段和覆盖疑虑","自动执行台帳检查以检测隔离区误用和开发者重命名疑虑","生成台帳审计结果报告，包括检测到的问题和可疑活动"],"ja":["フィールド不足や上書きの疑いなどの問題を検出するために台帳ファイルを監査する","隔離区の誤用や開発者名の変更の疑いなどの問題を検出するために台帳の自動チェックを実行する","監査結果のレポートを生成し、検出された問題や可疑な活動を含む"],"ko":["필드 누락 및 덮어쓰기 의심 등을 감지하기 위한 원장 파일 감사","격리 사용 및 개발자 이름 변경 의심 등 문제를 감지하기 위한 원장 자동 체크","감사 결과 보고서 생성, 감지된 문제 및 의심스러운 활동 포함"],"es":["Auditoría de archivos de ledger para detectar campos que faltan y sospechas de sobrescritura","Automatización de comprobaciones de ledger para problemas como mal uso de cuarentena y sospechas de renombrado de dev","Generación de informes sobre los resultados de la auditoría de ledger, incluyendo problemas detectados y actividad sospechosa"],"fr":["Audit des fichiers de ledger pour détecter des champs manquants et des soupçons de surécriture","Automatisation des vérifications de ledger pour des problèmes tels que mauvaise utilisation de quarantaine et soupçons de renommage de dev","Génération de rapports sur les résultats de l''audit de ledger, incluant les problèmes détectés et l''activité suspecte"],"de":["Prüfung von Ledger-Dateien auf fehlende Felder und Überschreibungsverdacht","Automatisierung von Ledger-Prüfungen für Probleme wie Quarantäne-Missbrauch und Entwicklervorlagen-Verdacht","Generierung von Berichten über die Ergebnisse der Ledger-Prüfung, einschließlich erkannter Probleme und verdächtiger Aktivitäten"],"pt":["Auditoria de arquivos de ledger para campos ausentes e suspeitas de sobrescrita","Automação de verificações de ledger para problemas como uso indevido de quarentena e suspeitas de renomeação de dev","Geração de relatórios sobre resultados de auditoria de ledger, incluindo problemas detectados e atividade suspeita"],"ru":["Аудит файлов леджера на отсутствующие поля и подозрения в перезаписи","Автоматизация проверок леджера на проблемы, такие как злоупотребление карантином и подозрения в переименовании dev","Генерация отчетов о результатах аудита леджера, включая обнаруженные проблемы и подозрительную активность"],"ar":["تدقيق ملفات دفتر الأستاذ للحصول على حقول ناقصة وشكوك في الكتابة فوق","تأتمة فحوصات دفتر الأستاذ لمشاكل مثل سوء استخدام الحجر الصحي وشكوك إعادة تسمية التطوير","генерация تقارير عن نتائج تدقيق دفتر الأستاذ، بما في ذلك المشاكل المحتملة والنشاط المشبوه"]},"limitations":{"en":["Requires access to ledger files in JSONL format","Limited to auditing recent N lines (default 200) of the ledger file"],"zh":["需要访问JSONL格式的台帳文件","仅限对台帳文件的最近N行（默认200）进行审计"],"ja":["JSONL形式の台帳ファイルへのアクセスが必要","台帳ファイルの最近のN行（デフォルト200）のみを監査することができる"],"ko":["JSONL 형식의 원장 파일에 대한 액세스가 필요합니다","원장 파일의 최근 N行(기본값 200)만 감사할 수 있습니다"],"es":["Requiere acceso a archivos de ledger en formato JSONL","Limitado a la auditoría de las últimas N líneas (predeterminado 200) del archivo de ledger"],"fr":["Nécessite un accès aux fichiers de ledger au format JSONL","Limité à l''audit des dernières N lignes (par défaut 200) du fichier de ledger"],"de":["Benötigt Zugriff auf Ledger-Dateien im JSONL-Format","Begrenzt auf die Prüfung der letzten N Zeilen (Standard 200) der Ledger-Datei"],"pt":["Exige acesso a arquivos de ledger no formato JSONL","Limitado à auditoria de linhas recentes N (padrão 200) do arquivo de ledger"],"ru":["Требует доступа к файлам леджера в формате JSONL","Ограничен аудитом последних N строк (по умолчанию 200) файла леджера"],"ar":["يتطلب الوصول إلى ملفات دفتر الأستاذ بتنسيق JSONL","محدود بالتدقيق من السطور الأخيرة N (الافتراضي 200) من ملف دفتر الأستاذ"]},"version":4},"contentHash":"5fb8529c45ba940f1b38972e886f7dc12261bed331772f7967cf8462d45e5c3c","qualityScore":44}');
