INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('macho715/file/autosort-ledger-audit', 'autosort-ledger-audit', 'macho715', 'file', 'community', 'autosort-ledger-audit macho715 file community The autosort-ledger-audit skill audits ledger files for issues like missing fields and overwrite suspicions. It benefits developers by automating ledger checks. autosort-ledger-audit 是一种用于检查和审计 ledger 文件的工具，支持检查最近 N 行记录 autosort-ledger-audit はレジャーファイルをチェックおよび監査するツールで、最近の N 行のレコードをチェックできます autosort-ledger-audit는 ledger 파일을 점검하고 감사하는 도구로, 최근 N라인을 확인할 수 있습니다 Autosort-ledger-audit es una herramienta de auditoría de registros de ledger que verifica la integridad de los datos y detecta problemas como campos omitidos o sobrescritos Autosort-ledger-audit est un outil d''audit de journaux de ledger qui vérifie l''intégrité des données et détecte des problèmes tels que des champs manquants ou écrasés Autosort-ledger-audit ist ein Tool zur Überprüfung von Ledger-Einträgen, das die Integrität der Daten überprüft und Probleme wie fehlende oder überschriebene Felder erkennt O autosort-ledger-audit é uma ferramenta de auditoria de ledger que verifica a integridade dos dados e detecta problemas como campos em falta ou sobrescritos autosort-ledger-audit - это инструмент аудита ведgers, который проверяет целостность данных и обнаруживает проблемы, такие как пропущенные поля или перезаписанные данные с помощью ИИ Агенты autosort-ledger-audit هو أداة تدقيق سجلات تقوم بفحص سلامة البيانات واكتشاف المشكلات مثل الحقول المفقودة أو المَحوّزة how to use autosort-ledger-audit autosort-ledger-audit setup guide ledger audit tools autosort-ledger-audit alternative autosort-ledger-audit vs manual audit automated ledger checking ledger file analysis dev rename detection AI 工具 ledger 文件检查 autosort-ledger-audit レジャーファイル監査 检查最近 N 行记录 必要字段检查 Dev rename 检测 Checks ledger files for required fields like before, after, reason, ts, run_id, action, and sha256 Detects prohibited patterns like delete, remove, unlink, overwrite, and replace Supports dev rename detection by comparing before and after filenames Allows specification of audit scope, including recent lines (default 200) Generates reports based on audit results autosort-ledger-audit is a skill that automates ledger audits, checking for required fields and suspicious patterns in ledger files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shivbardolabs/ShipOS/draft-nda', 'community', 'shivbardolabs', 'ShipOS', 'shivbardolabs/ShipOS', 'draft-nda', 0, 0, 44, '2026-03-06T23:40:18Z', '2026-03-07T13:13:41.199Z', 'e37a613bae8038220aac1e45f73596a419920015abe28d4a012d339a0e018247', '{"id":"shivbardolabs/ShipOS/draft-nda","name":"draft-nda","description":{"en":"The draft-nda skill helps draft detailed Non-Disclosure Agreements between parties, covering information types and jurisdiction. It provides plain-language explanations for accessibility.","zh":"draft-nda技能帮助创建保密协议，涵盖信息类型、管辖权等，使用AIエージェント实现详细、清晰、专业的文档","ja":"draft-ndaスキルは、情報タイプ、管轄区域などをカバーした詳細な非開示契約の作成を支援します","ko":"draft-nda 스킬은 정보 유형, 재판 관할권 등을 포함한 상세한 비공개 협약의 작성을 지원합니다","es":"Draft-nda es una herramienta para crear acuerdos de confidencialidad detallados y claros. Ayuda a establecer cláusulas que requieren revisión legal y proporciona explicaciones en lenguaje plano.","fr":"Draft-nda est un outil pour établir des accords de non-divulgation détaillés et clairs. Il aide à définir des clauses qui nécessitent un examen juridique et fournit des explications en langage clair.","de":"Draft-nda ist ein Tool zur Erstellung von umfassenden und klaren Vertraulichkeitsvereinbarungen. Es hilft bei der Festlegung von Klauseln, die eine rechtliche Überprüfung erfordern, und bietet Erklärungen in einfacher Sprache.","pt":"O draft-nda é uma ferramenta para criar Acordos de Não Divulgação detalhados e claros. Ele cobre tipos de informações, jurisdição e cláusulas que requerem revisão legal","ru":"draft-nda - это инструмент для создания подробных и ясных Конфиденциальных Соглашений. Он охватывает типы информации, юрисдикцию и пункты, требующие юридического рассмотрения","ar":"draft-nda هو أداة لإنشاء اتفاقيات سرية مفصلة وواضحة. وهي تغطي أنواع المعلومات والولاية القضائية والبنود التي تتطلب مراجعة قانونية"},"seo":{"title":{"en":"draft-nda: NDA Drafting Setup Guide | AI Agent Skill","zh":"draft-nda Setup Guide: 使用AIエージェント创建保密协议","ja":"draft-nda ベストプラクティス: AIエージェントを使用した非開示契約の作成","ko":"draft-nda 가이드: AI 도구를 사용한 비공개 협약 초안","es":"Guía de configuración de draft-nda para acuerdos de confi...","fr":"Meilleures pratiques pour la mise en place de draft-nda p...","de":"Einrichtungsleitfaden für draft-nda zur Erstellung von Ve...","pt":"Guia de Configuração do draft-nda: Crie Acordos de Não Di...","ru":"ИИ Агенты: Руководство по Настройке draft-nda для Создани...","ar":"دليل ضبط draft-nda: إنشاء اتفاقيات سرية محترفة"},"description":{"en":"Discover how to create comprehensive Non-Disclosure Agreements with draft-nda. Learn to draft clear and professional NDAs between parties and get started today!","zh":"了解draft-nda技能，使用AIエージェント创建详细、清晰、专业的保密协议，涵盖信息类型、管辖权等","ja":"draft-ndaスキルを使用して、情報タイプ、管轄区域などをカバーした詳細な非開示契約を作成する方法を学びます","ko":"draft-nda 스킬을 사용하여 정보 유형, 재판 관할권 등을 포함한 상세한 비공개 협약을 작성하는 방법을 배웁니다","es":"Aprende a configurar y utilizar draft-nda para crear acuerdos de confidencialidad claros y profesionales con explicaciones en lenguaje plano","fr":"Découvrez comment configurer et utiliser draft-nda pour établir des accords de non-divulgation détaillés et accessibles avec des explications en langage clair","de":"Erfahren Sie, wie Sie draft-nda einrichten und verwenden können, um umfassende und professionelle Vertraulichkeitsvereinbarungen mit Erklärungen in einfacher...","pt":"Aprenda a criar Acordos de Não Divulgação claros e profissionais com o draft-nda. Descubra como proteger informações confidenciais com nosso guia de configur...","ru":"Изучите, как создать подробные и ясные Конфиденциальные Соглашения с помощью draft-nda. Узнайте, как защитить конфиденциальную информацию с нашим руководство...","ar":"تعلم كيفية إنشاء اتفاقيات سرية واضحة ومحترفة مع draft-nda. اكتشف كيفية حماية المعلومات السرية مع دليلنا للضبط"},"definition":{"en":"draft-nda is a skill for drafting comprehensive Non-Disclosure Agreements, marking clauses that require legal review and providing clear explanations.","zh":"draft-nda是使用AIエージェント创建保密协议的技能，用于帮助创建详细、清晰、专业的非开示契约","ja":"draft-ndaは、AIエージェントを使用して非開示契約を作成するスキルです","ko":"draft-nda는 AI 도구를 사용하여 비공개 협약을 작성하는 스킬입니다","es":"Draft-nda es una herramienta de inteligencia artificial para crear acuerdos de confidencialidad","fr":"Draft-nda est un outil d''intelligence artificielle pour établir des accords de non-divulgation","de":"Draft-nda ist ein KI-Tool zur Erstellung von Vertraulichkeitsvereinbarungen","pt":"O que é draft-nda? É uma ferramenta para criar Acordos de Não Divulgação profissionais e claros","ru":"Что такое draft-nda? Это инструмент для создания профессиональных и ясных Конфиденциальных Соглашений","ar":"ما هو draft-nda؟ هو أداة لإنشاء اتفاقيات سرية محترفة وواضحة"},"features":{"en":["Drafts comprehensive Non-Disclosure Agreements between two parties","Covers information types and jurisdiction in the agreement","Clearly marks clauses that require legal review","Provides plain-language explanations for document accessibility"],"zh":["创建详细、清晰、专业的保密协议","涵盖信息类型、管辖权等","使用AIエージェント实现自动化文档创建","提供明确的法律审查要求","支持多种语言和地域的保密协议创建"],"ja":["詳細な非開示契約の作成","情報タイプ、管轄区域などをカバー","AIエージェントを使用した自動化ドキュメント作成","明確な法律レビュー要求の提供","多言語および地域の非開示契約作成をサポート"],"ko":["詳細한 비공개 협약의 작성","정보 유형, 재판 관할권 등을 포함","AI 도구를 사용한 자동화 문서 작성","명확한 법적 검토 요구 사항 제공","다중 언어 및 지역의 비공개 협약 작성 지원"],"es":["Creación de acuerdos de confidencialidad detallados y claros","Establecimiento de cláusulas que requieren revisión legal","Explicaciones en lenguaje plano para facilitar la comprensión","Cobertura de tipos de información y jurisdicción","Marcado claro de cláusulas que requieren revisión legal"],"fr":["Création d''accords de non-divulgation détaillés et clairs","Définition de clauses qui nécessitent un examen juridique","Explications en langage clair pour faciliter la compréhension","Couverture de types d''information et de juridiction","Marquage clair de clauses qui nécessitent un examen juridique"],"de":["Erstellung von umfassenden und klaren Vertraulichkeitsvereinbarungen","Festlegung von Klauseln, die eine rechtliche Überprüfung erfordern","Erklärungen in einfacher Sprache zur Erleichterung des Verständnisses","Abdeckung von Informationen und Gerichtsbarkeit","Klares Markieren von Klauseln, die eine rechtliche Überprüfung erfordern"],"pt":["Criação de Acordos de Não Divulgação detalhados e claros","Cobertura de tipos de informações e jurisdição","Identificação de cláusulas que requerem revisão legal","Explicações em linguagem simples para acessibilidade","Proteção de informações confidenciais"],"ru":["Создание подробных и ясных Конфиденциальных Соглашений","Охват типов информации и юрисдикции","Определение пунктов, требующих юридического рассмотрения","Объяснения на простом языке для доступности","Защита конфиденциальной информации"],"ar":["إنشاء اتفاقيات سرية مفصلة وواضحة","التغطية لأنواع المعلومات والولاية القضائية","تحديد البنود التي تتطلب مراجعة قانونية","الشرح بلغة بسيطة للوصول","حماية المعلومات السرية"]},"keywords":{"en":["how to use draft-nda","what is draft-nda","draft-nda alternative","draft-nda setup guide","NDAs for confidentiality agreements","draft-nda vs traditional drafting methods"],"zh":["draft-nda","AIエージェント","保密协议","非开示契约","信息类型","管辖权","自动化文档创建","法律审查"],"ja":["draft-nda","AIエージェント","非開示契約","情報タイプ","管轄区域","自動化ドキュメント作成","法律レビュー"],"ko":["draft-nda","AI 도구","비공개 협약","정보 유형","재판 관할권","자동화 문서 작성","법적 검토"],"es":["acuerdos de confidencialidad","herramientas de inteligencia artificial","draft-nda","acuerdos de no divulgación","creación de acuerdos","revisión legal","explicaciones en lenguaje plano"],"fr":["accords de non-divulgation","outils d''intelligence artificielle","draft-nda","accords de confidentialité","création d''accords","examen juridique","explications en langage clair"],"de":["Vertraulichkeitsvereinbarungen","KI-Tools","draft-nda","Vertraulichkeitsabkommen","Erstellung von Vereinbarungen","rechtliche Überprüfung","Erklärungen in einfacher Sprache"],"pt":["draft-nda","Acordo de Não Divulgação","Confidencialidade","Proteção de informações","Guia de configuração","Criar Acordos de Não Divulgação","Legislação","Contratos"],"ru":["draft-nda","ИИ Агенты","Конфиденциальное Соглашение","Защита информации","Руководство по настройке","Создание Конфиденциальных Соглашений","Юрисдикция","Юридические документы"],"ar":["draft-nda","أداة الذكاء الاصطناعي","اتفاقية سرية","حماية المعلومات","دليل الضبط","إنشاء اتفاقيات سرية","الولاية القضائية","الوثائق القانونية"]}},"owner":"shivbardolabs","repo":"ShipOS","repoPath":"shivbardolabs/ShipOS","stars":0,"forks":0,"updatedAt":"2026-03-06T23:40:18Z","topics":[],"category":"community","skillMd":{"name":"draft-nda","description":"Draft a detailed Non-Disclosure Agreement between two parties covering information types, jurisdiction, and clauses needing legal review. Use when creating confidentiality agreements or preparing an NDA for a partnership.","bodyPreview":"# NDA (Non-Disclosure Agreement) Drafting\n\nYou are an experienced legal document specialist with expertise in confidentiality agreements. Your role is to help draft detailed, clear, and professional Non-Disclosure Agreements between parties.\n\n## Purpose\nDraft a comprehensive Non-Disclosure Agreement (NDA) between two parties. The NDA covers information types, jurisdiction, and clearly marks clauses that require legal review. Provide plain-language explanations to make the document accessible.\n\n#","body":"# NDA (Non-Disclosure Agreement) Drafting\n\nYou are an experienced legal document specialist with expertise in confidentiality agreements. Your role is to help draft detailed, clear, and professional Non-Disclosure Agreements between parties.\n\n## Purpose\nDraft a comprehensive Non-Disclosure Agreement (NDA) between two parties. The NDA covers information types, jurisdiction, and clearly marks clauses that require legal review. Provide plain-language explanations to make the document accessible.\n\n## Important Disclaimer\n**This is for informational purposes only and does not constitute legal advice. Always have a licensed attorney review the final document before execution. NDAs are legally binding contracts; professional legal review is essential.**\n\n## Input Arguments\n- `$COMPANY_ONE_NAME`: Name of the first party/company\n- `$COMPANY_ONE_ADDRESS`: Address of the first party/company\n- `$COMPANY_ONE_REPS`: Names and titles of representatives (e.g., \"John Smith, CEO; Jane Doe, General Counsel\")\n- `$COMPANY_TWO_NAME`: Name of the second party/company\n- `$COMPANY_TWO_ADDRESS`: Address of the second party/company\n- `$COMPANY_TWO_REPS`: Names and titles of representatives\n- `$INFORMATION_TYPES`: Types of information to be shared (e.g., \"business plans, customer lists, technical specifications, pricing data, source code\")\n- `$JURISDICTION`: Governing jurisdiction (e.g., \"State of California, United States\" or \"England and Wales\")\n\n## Process\n\n### Step 1: Clarify Requirements\nBefore drafting, note down:\n- Are both parties companies or is one an individual?\n- What specific types of information will be shared?\n- Is this one-way (only one party shares) or mutual (both parties share)?\n- What is the geographic jurisdiction?\n- What is the intended duration of the NDA?\n\n### Step 2: Structure the NDA\nOrganize the NDA in standard sections:\n\n1. **Preamble** (Parties, definitions, effective date)\n2. **Definitions** (What is \"Confidential Information\"?)\n3. **Obligation to Maintain Confidentiality** (Core obligation)\n4. **Permitted Disclosures** (Exceptions to confidentiality)\n5. **Term and Duration** (How long does the NDA last?)\n6. **Return or Destruction of Information** (What happens after?)\n7. **Remedies** (Consequences for breach)\n8. **General Provisions** (Governing law, jurisdiction, severability)\n\n### Step 3: Use Plain Language\nWrite each section in clear, accessible language. Avoid legal jargon where possible. Define terms the first time they''re used.\n\n### Step 4: Highlight Clauses Needing Legal Review\nMark sections with [⚠️ LEGAL REVIEW REQUIRED] where customization or specific legal expertise is needed. Include explanations of what should be reviewed.\n\n### Step 5: Provide Context\nInclude brief notes explaining:\n- Why each section is important\n- What decisions need to be made by the parties\n- Common pitfalls or considerations\n\n## NDA Template Structure\n\nPresent the draft NDA in this order:\n\n**[COVER NOTE]**\nA brief note explaining the NDA''s purpose, the parties involved, and key provisions.\n\n**[FULL NDA DOCUMENT]**\nThe complete agreement ready for customization.\n\n**[NOTES ON KEY CLAUSES]**\nExplanations of important sections and what may need legal customization.\n\n---\n\n## Key Sections to Include\n\n### Preamble\n- Introduce both parties clearly with full legal names and addresses\n- State the purpose: exploring a potential business relationship, partnership, merger, etc.\n- Define the \"Effective Date\"\n\n### Definitions\n- **Confidential Information**: Specify what is considered confidential (business plans, financial data, technical specs, customer lists, etc.). Include scope.\n- **Excluded Information**: Clarify what is NOT confidential (publicly available information, information independently developed, information received from third parties without confidentiality obligations)\n\n### Obligations\n- Describe the receiving party''s duty to keep information confidential\n- Specify approved uses of the information\n- Outline permitted disclosures (to employees, advisors, on a need-to-know basis)\n- [⚠️ LEGAL REVIEW REQUIRED] Standard of care (e.g., \"same care as own confidential information, but no less than reasonable care\")\n\n### Permitted Disclosures\n- Specify who can be told (employees, advisors, consultants on a need-to-know basis)\n- Include a requirement that recipients also agree to confidentiality\n- Add exception for legally required disclosures (with notice requirement, if possible)\n\n### Term and Duration\n- Define the period during which information is being shared\n- Define how long confidentiality obligations survive after the relationship ends\n- [⚠️ LEGAL REVIEW REQUIRED] Consider different durations for different information types (trade secrets may require longer protection)\n\n### Return or Destruction\n- Specify that the receiving party must return or securely destroy confidential information upon request or upon termination\n- Option to certify in writing that destruction is complete\n- Consider: does the receiving party keep one copy for legal compliance?\n\n### Remedies\n- [⚠️ LEGAL REVIEW REQUIRED] State that breach may cause irreparable harm and that injunctive relief is available\n- Clarify that remedies are in addition to other legal remedies available\n\n### General Provisions\n- **Governing Law and Jurisdiction**: Specify which state or country''s laws govern (e.g., California or England)\n- [⚠️ LEGAL REVIEW REQUIRED] Dispute resolution process (litigation, arbitration, mediation)\n- **Severability**: If one provision is invalid, others remain in force\n- **Entire Agreement**: This NDA supersedes prior discussions\n- **Amendments**: Specify that NDA can only be modified in writing, signed by both parties\n- **Counterparts**: Parties can sign separate copies\n\n---\n\n## Content Guidelines\n\n- **Plain Language**: Write for a primary-school-educated reader. Avoid Latin phrases, unnecessary legal terms.\n- **Clarity over Precision**: Choose clear language first. Legal precision can be refined by attorneys.\n- **Examples**: Where helpful, include examples of what is/isn''t confidential information.\n- **Specific Information Types**: Use the $INFORMATION_TYPES provided to make the agreement specific, not generic.\n- **Mutual or One-Way**: If $INFORMATION_TYPES suggests only one party is sharing, note this as a one-way NDA. If both, use mutual language.\n\n---\n\n## Output Format\n\nPresent the NDA in three parts:\n\n### Part 1: Summary\nBullet-point overview of:\n- Parties involved\n- Information types covered\n- Key duration and terms\n- Jurisdiction\n\n### Part 2: Full NDA Document\nA complete, ready-to-customize NDA document.\n\n### Part 3: Customization Notes\nGuidance on:\n- Sections marked for legal review\n- Decisions parties need to make\n- Common modifications based on situation\n- Next steps (legal review, signing process)\n\n---\n\n## Important Reminders\n\n- This is a starting point, not final legal advice\n- Jurisdictions vary widely; have a lawyer in the relevant jurisdiction review\n- Some industries (tech, pharma, finance) have specific NDA conventions\n- Consider mutual vs. one-way requirements\n- Think about duration: How long should the information be protected?\n- Always have an attorney review before any party signs\n"},"lastSynced":"2026-03-07T13:13:41.199Z","agentAnalysis":{"suitability":{"en":"Perfect for Contract Analysis Agents needing precise Non-Disclosure Agreement drafting capabilities.","zh":"适合需要精确的非披露协议（NDA）草拟能力的合同分析代理","ja":"非公開契約（NDA）作成能力が必要な契約分析エージェントに最適","ko":"정확한 비공개 계약서(NDA) 초안 작성 기능이 필요한 계약 분석 에이전트에게 적합","es":"Perfecto para Agentes de Análisis de Contratos que necesitan capacidades de redacción de Acuerdos de No Divulgación precisas.","fr":"Parfait pour les Agents d''Analyse de Contrats ayant besoin de capacités de rédaction d''Accords de Non-Divulgation précises.","de":"Perfekt für Vertragsanalyseagenten, die präzise Fähigkeiten zur Erstellung von Vertraulichkeitsvereinbarungen benötigen.","pt":"Perfeito para Agentes de Análise de Contrato que necessitam de capacidades de elaboração de Acordos de Não Divulgação precisas.","ru":"Идеально для агентов анализа контрактов, которым необходимы точные возможности составления соглашений о неразглашении.","ar":"مثالي لعمليات تحليل العقود التي تحتاج إلى قدرات دقيقة لصياغة اتفاقيات النفاذ غير المصرح به."},"recommendation":{"en":"Empowers agents to generate comprehensive NDAs covering information types, jurisdiction, and providing plain-language explanations for accessibility, utilizing legal document templates and clause review protocols.","zh":"赋予代理生成全面覆盖信息类型、管辖权，并提供可访问性明确语言解释的NDA，利用法律文档模板和条款审查协议","ja":"エージェントが情報の種類、管轄区域を網羅し、可読性の高い明確な解説を提供する包括的なNDAを作成できるようにし、法的文書テンプレートや条項レビューのプロトコルを利用する","ko":"에이전트가 정보 유형, 관할 지역을 포함하고 접근성에 대한 명확한 언어 설명을 제공하는 포괄적인 NDA를 생성할 수 있도록 하며, 법적 문서 템플릿 및 조항 검토 프로토콜을 활용","es":"Habilita a los agentes a generar Acuerdos de No Divulgación completos que cubren tipos de información, jurisdicción y proporcionan explicaciones en lenguaje llano para la accesibilidad, utilizando plantillas de documentos legales y protocolos de revisión de cláusulas.","fr":"Permet aux agents de générer des Accords de Non-Divulgation complets couvrant les types d''informations, la juridiction et fournissant des explications en langage clair pour l''accessibilité, en utilisant des modèles de documents juridiques et des protocoles d''examen de clauses.","de":"Ermächtigt Agenten, umfassende Vertraulichkeitsvereinbarungen zu generieren, die Informationenstypen, Rechtsordnung und einfache Sprache für die Zugänglichkeit abdecken und dabei rechtliche Dokumentvorlagen und Klauselprüfprotokolle verwenden.","pt":"Habilita os agentes a gerar NDAs abrangentes que cobrem tipos de informações, jurisdição e fornecem explicações em linguagem clara para acessibilidade, utilizando modelos de documentos legais e protocolos de revisão de cláusulas.","ru":"Наделяет агентов возможностью создавать всесторонние НДА, покрывающие типы информации, юрисдикцию и предоставляющие объяснения на простом языке для доступности, используя шаблоны юридических документов и протоколы проверки пунктов.","ar":"تمكّن الوكلاء من إنشاء اتفاقيات نفاذ غير مصرح به شاملة تغطي أنواع المعلومات والولاية القضائية وتوفر تفسيرات بلغة بسيطة للوصول، باستخدام قوالب وثائق قانونية وبروتوكولات مراجعة الشروط."},"useCases":{"en":["Drafting mutual NDAs between business partners","Generating one-way NDAs for sensitive information sharing","Reviewing and marking clauses requiring legal review"],"zh":["为商业伙伴之间起草相互的NDA","为敏感信息共享生成单向NDA","审查并标记需要法律审查的条款"],"ja":["ビジネスパートナー間の相互NDAの作成","機密情報の共有のための単方向NDAの生成","法的なレビューが必要な条項のレビューとマーキング"],"ko":["사업 파트너 간의 상호 NDA 초안 작성","민감한 정보 공유를 위한 일방적 NDA 생성","법적 검토가 필요한 조항의 검토 및 표시"],"es":["Redacción de Acuerdos de No Divulgación mutuos entre socios comerciales","Generación de Acuerdos de No Divulgación unidireccionales para el intercambio de información confidencial","Revisión y marcado de cláusulas que requieren revisión legal"],"fr":["Rédaction d''Accords de Non-Divulgation mutuels entre partenaires commerciaux","Génération d''Accords de Non-Divulgation unidirectionnels pour le partage d''informations sensibles","Révision et marquage de clauses nécessitant une révision juridique"],"de":["Erstellung gegenseitiger Vertraulichkeitsvereinbarungen zwischen Geschäftspartnern","Generierung einseitiger Vertraulichkeitsvereinbarungen für den Austausch sensibler Informationen","Überprüfung und Markierung von Klauseln, die eine rechtliche Überprüfung erfordern"],"pt":["Elaboração de NDAs mútuas entre parceiros de negócios","Geração de NDAs unidirecionais para compartilhamento de informações sensíveis","Revisão e marcação de cláusulas que exigem revisão jurídica"],"ru":["Составление взаимных НДА между деловыми партнерами","Генерация односторонних НДА для обмена конфиденциальной информацией","Проверка и пометка пунктов, требующих юридического рассмотрения"],"ar":["صياغة اتفاقيات نفاذ غير مصرح به متبادلة بين شركاء الأعمال","إنشاء اتفاقيات نفاذ غير مصرح به ذات اتجاه واحد لمشاركة المعلومات الحساسة","مراجعة وتعليم البنود التي تتطلب مراجعة قانونية"]},"limitations":{"en":["Requires legal expertise for review and validation","Limited to standard NDA templates and clauses"],"zh":["需要法律专业知识进行审查和验证","仅限于标准NDA模板和条款"],"ja":["レビューと検証には法的専門知識が必要","標準のNDAテンプレートと条項に限定される"],"ko":["검토 및 검증을 위해 법적 전문 지식이 필요","표준 NDA 템플릿 및 조항으로 제한"],"es":["Requiere experiencia jurídica para la revisión y validación","Limitado a plantillas y cláusulas de Acuerdos de No Divulgación estándar"],"fr":["Nécessite une expertise juridique pour la révision et la validation","Limité à des modèles et des clauses d''Accords de Non-Divulgation standard"],"de":["Benötigt juristische Fachkenntnisse für die Überprüfung und Validierung","Begrenzt auf Standard-Vorlagen und -Klauseln für Vertraulichkeitsvereinbarungen"],"pt":["Exige especialização jurídica para revisão e validação","Limitado a modelos e cláusulas de NDA padrão"],"ru":["Требует юридической экспертизы для проверки и подтверждения","Ограничен стандартными шаблонами и пунктами НДА"],"ar":["يتطلب خبرة قانونية لمراجعة الصحة","محدود بنماذج وبنود اتفاقيات النفاذ غير المصرح به القياسية"]},"version":4},"contentHash":"e37a613bae8038220aac1e45f73596a419920015abe28d4a012d339a0e018247","qualityScore":44}');
