INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shivbardolabs/ShipOS/draft-nda', 'draft-nda', 'shivbardolabs', 'ShipOS', 'community', 'draft-nda shivbardolabs ShipOS community The draft-nda skill helps draft detailed Non-Disclosure Agreements between parties, covering information types and jurisdiction. It provides plain-language explanations for accessibility. draft-nda技能帮助创建保密协议，涵盖信息类型、管辖权等，使用AIエージェント实现详细、清晰、专业的文档 draft-ndaスキルは、情報タイプ、管轄区域などをカバーした詳細な非開示契約の作成を支援します draft-nda 스킬은 정보 유형, 재판 관할권 등을 포함한 상세한 비공개 협약의 작성을 지원합니다 Draft-nda es una herramienta para crear acuerdos de confidencialidad detallados y claros. Ayuda a establecer cláusulas que requieren revisión legal y proporciona explicaciones en lenguaje plano. Draft-nda est un outil pour établir des accords de non-divulgation détaillés et clairs. Il aide à définir des clauses qui nécessitent un examen juridique et fournit des explications en langage clair. Draft-nda ist ein Tool zur Erstellung von umfassenden und klaren Vertraulichkeitsvereinbarungen. Es hilft bei der Festlegung von Klauseln, die eine rechtliche Überprüfung erfordern, und bietet Erklärungen in einfacher Sprache. O draft-nda é uma ferramenta para criar Acordos de Não Divulgação detalhados e claros. Ele cobre tipos de informações, jurisdição e cláusulas que requerem revisão legal draft-nda - это инструмент для создания подробных и ясных Конфиденциальных Соглашений. Он охватывает типы информации, юрисдикцию и пункты, требующие юридического рассмотрения draft-nda هو أداة لإنشاء اتفاقيات سرية مفصلة وواضحة. وهي تغطي أنواع المعلومات والولاية القضائية والبنود التي تتطلب مراجعة قانونية how to use draft-nda what is draft-nda draft-nda alternative draft-nda setup guide NDAs for confidentiality agreements draft-nda vs traditional drafting methods draft-nda AIエージェント 保密协议 非开示契约 信息类型 管辖权 自动化文档创建 法律审查 Drafts comprehensive Non-Disclosure Agreements between two parties Covers information types and jurisdiction in the agreement Clearly marks clauses that require legal review Provides plain-language explanations for document accessibility draft-nda is a skill for drafting comprehensive Non-Disclosure Agreements, marking clauses that require legal review and providing clear explanations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shinpr/agentic-code/documentation-criteria', 'community', 'shinpr', 'agentic-code', 'shinpr/agentic-code', 'documentation-criteria', 35, 3, 44, '2026-03-02T14:33:29Z', '2026-03-06T06:38:05.520Z', 'd44ef2ecfa66db6c6aeec22525a38f071cde63e7934d40d85c6054294ed84a31', '{"id":"shinpr/agentic-code/documentation-criteria","name":"documentation-criteria","description":{"en":"The documentation-criteria skill enables developers to create systematic, test-first workflows with quality gates for AI coding agents. It supports Agentic coding framework powered by AGENTS.md.","zh":"Agentic AI 文档创建标准提供系统化的工作流程和质量门槛，支持 Cursor、Codex、Gemini CLI 和 AI 编码代理","ja":"Agentic AI ドキュメント作成基準は、システム化されたワークフローと品質ゲートを提供し、Cursor、Codex、Gemini CLI、AI コーディングエージェントをサポート","ko":"Agentic AI 문서 생성 기준은 시스템화된 워크플로우와 품질 게이트를 제공하며 Cursor, Codex, Gemini CLI 및 AI 코딩 에이전트를 지원합니다","es":"Los criterios de documentación de AGENTS.md permiten flujos de trabajo sistemáticos y de prueba para Cursor, Codex y Gemini CLI","fr":"Les critères de documentation d''AGENTS.md permettent des flux de travail systématiques et de test pour Cursor, Codex et Gemini CLI","de":"Die Dokumentationskriterien von AGENTS.md ermöglichen systematische und testgesteuerte Workflows für Cursor, Codex und Gemini CLI","pt":"O framework Agentic fornece um fluxo de trabalho sistemático para a criação de documentação de alta qualidade com critérios claros para Cursor, Codex, Gemini CLI e agentes de codificação AI.","ru":"Фреймворк Agentic обеспечивает системный рабочий процесс для создания качественной документации с четкими критериями для Cursor, Codex, Gemini CLI и агентов кодирования ИИ.","ar":"يقدم إطار العمل Agentic تدفق عمل منهجي لإنشاء توثيق ذي جودة عالية مع معايير واضحة لمحوّل Cursor و Codex و Gemini CLI ووكلاء البرمجة الإصطناعية"},"seo":{"title":{"en":"documentation-criteria: Setup Guide for AI Agents | Agent...","zh":"文档标准设置指南 - Agentic AI 文档创建标准","ja":"ドキュメント基準設定ガイド - Agentic AI ドキュメント作成基準","ko":"문서 기준 설정 가이드 - Agentic AI 문서 생성 기준","es":"Criterios de documentación: Guía de configuración para AG...","fr":"Critères de documentation : Guide de mise en place pour A...","de":"Dokumentationskriterien: Einrichtungsleitfaden für AGENTS.md","pt":"Guia de Configuração de Critérios de Documentação para Fe...","ru":"Настройка Критериев Документации для ИИ Агентов и Инструм...","ar":"دليل إعداد معايير توثيق أدوات الإتصال الإصطناعي"},"description":{"en":"Discover how to implement documentation-criteria for systematic workflows with quality gates. Learn to automate with Cursor, Codex, Gemini CLI, and AI coding...","zh":"了解 Agentic AI 文档创建标准，实现高效的文档管理和自动化测试","ja":"Agentic AI ドキュメント作成基準をご存じください。効率的なドキュメント管理と自動テストを実現","ko":"Agentic AI 문서 생성 기준을 알아보세요. 효율적인 문서 관리와 자동 테스트를 실현합니다","es":"Aprende a configurar los criterios de documentación para AGENTS.md y mejora la productividad con Gemini CLI, Cursor y Codex","fr":"Découvrez comment configurer les critères de documentation pour AGENTS.md et améliorer la productivité avec Gemini CLI, Cursor et Codex","de":"Erfahren Sie, wie Sie die Dokumentationskriterien für AGENTS.md konfigurieren und die Produktivität mit Gemini CLI, Cursor und Codex verbessern","pt":"Aprenda a configurar critérios de documentação para ferramentas de inteligência artificial com o framework Agentic e melhorar a produtividade do seu time de ...","ru":"Узнайте, как настроить критерии документации для ИИ агентов и инструментов с помощью фреймворка Agentic и повысьте производительность своей команды разработки","ar":"تعرف على كيفية إعداد معايير توثيق لأدوات الإتصال الإصطناعي باستخدام إطار العمل Agentic وتحسين إنتاجية فريق التطوير"},"definition":{"en":"documentation-criteria is a systematic approach to creating documentation with quality gates for AI coding agents, using a test-first workflow with tools like Cursor, Codex, and Gemini CLI.","zh":"Agentic AI 文档创建标准是一套系统化的文档管理和自动化测试标准","ja":"Agentic AI ドキュメント作成基準は、システム化されたドキュメント管理と自動テストの標準です","ko":"Agentic AI 문서 생성 기준은 시스템화된 문서 관리와 자동 테스트의 기준입니다","es":"Los criterios de documentación son un conjunto de reglas para la creación de documentación en AGENTS.md","fr":"Les critères de documentation sont un ensemble de règles pour la création de documentation dans AGENTS.md","de":"Die Dokumentationskriterien sind eine Sammlung von Regeln für die Erstellung von Dokumentationen in AGENTS.md","pt":"Critérios de documentação são regras que definem quando e como criar documentação para projetos de desenvolvimento de software","ru":"Критерии документации - это правила, определяющие, когда и как создавать документацию для проектов разработки программного обеспечения","ar":"معايير التوثيق هي قواعد تحدد متى وكيف يتم إنشاء توثيق لمشاريع تطوير البرمجيات"},"features":{"en":["Implements Creation Decision Matrix for conditional document creation","Supports PRD, ADR, Design Doc, and Work Plan document types","Automates workflows with quality gates for Cursor, Codex, and Gemini CLI","Enables test-first workflows for AI coding agents","Provides conditional logic for document creation based on file count (1-2, 3-5, 6+ files)"],"zh":["支持 Cursor、Codex、Gemini CLI 和 AI 编码代理","系统化的工作流程和质量门槛","自动化测试和文档管理","支持 PRD、ADR、Design Doc 和 Work Plan 文档","条件决策矩阵用于文档创建"],"ja":["Cursor、Codex、Gemini CLI、AI コーディングエージェントをサポート","システム化されたワークフローと品質ゲート","自動テストとドキュメント管理","PRD、ADR、Design Doc、Work Plan ドキュメントをサポート","条件判断マトリックスによるドキュメント作成"],"ko":["Cursor, Codex, Gemini CLI 및 AI 코딩 에이전트 지원","시스템화된 워크플로우와 품질 게이트","자동 테스트와 문서 관리","PRD, ADR, Design Doc 및 Work Plan 문서 지원","조건 판단 행렬을 통한 문서 생성"],"es":["Flujos de trabajo sistemáticos con Gemini CLI","Creación de documentación automatizada con Codex","Soporte para Cursor y otros agentes de codificación","Matriz de decisión para la creación de documentación","Recomendaciones para la creación de documentación según el número de archivos"],"fr":["Flux de travail systématiques avec Gemini CLI","Création de documentation automatisée avec Codex","Prise en charge de Cursor et d''autres agents de codage","Matrice de décision pour la création de documentation","Recommandations pour la création de documentation en fonction du nombre de fichiers"],"de":["Systematische Workflows mit Gemini CLI","Automatisierte Dokumentenerstellung mit Codex","Unterstützung für Cursor und andere Codierungsagenten","Entscheidungsmatrix für die Dokumentenerstellung","Empfehlungen für die Dokumentenerstellung basierend auf der Anzahl der Dateien"],"pt":["Fluxo de trabalho sistemático com qualidade de portas para Cursor, Codex e Gemini CLI","Criação de documentação de alta qualidade com critérios claros","Suporte a agentes de codificação AI para automação de tarefas","Integração com o framework Agentic para melhorar a produtividade","Critérios de documentação personalizáveis para atender às necessidades do projeto"],"ru":["Системный рабочий процесс с качеством ворот для Cursor, Codex и Gemini CLI","Создание качественной документации с четкими критериями","Поддержка агентов кодирования ИИ для автоматизации задач","Интеграция с фреймворком Agentic для повышения производительности","Настраиваемые критерии документации для удовлетворения потребностей проекта"],"ar":["تدفق عمل منهجي مع جودة أبواب لمحوّل Cursor و Codex و Gemini CLI","إنشاء توثيق ذي جودة عالية مع معايير واضحة","دعم وكلاء البرمجة الإصطناعية للآليّة Tasks","التكامل مع إطار العمل Agentic لتحسين الإنتاجية","معايير توثيق قابلة للتخصيص لتناسب احتياجات المشروع"]},"keywords":{"en":["how to use documentation-criteria","documentation-criteria setup guide","agentic coding framework tutorial","ai coding agents workflow automation","documentation-criteria vs traditional workflows","gemini cli documentation","codex ai agent integration","cursor workflow automation","test-first workflow with quality gates","documentation-criteria install"],"zh":["Agentic AI","文档创建标准","自动化测试","文档管理","Cursor","Codex","Gemini CLI","AI 编码代理","条件决策矩阵"],"ja":["Agentic AI","ドキュメント作成基準","自動テスト","ドキュメント管理","Cursor","Codex","Gemini CLI","AI コーディングエージェント","条件判断マトリックス"],"ko":["Agentic AI","문서 생성 기준","자동 테스트","문서 관리","Cursor","Codex","Gemini CLI","AI 코딩 에이전트","조건 판단 행렬"],"es":["AGENTS.md","criterios de documentación","Gemini CLI","Cursor","Codex","agentes de codificación","documentación automatizada","productividad para desarrolladores"],"fr":["AGENTS.md","critères de documentation","Gemini CLI","Cursor","Codex","agents de codage","documentation automatisée","productivité pour les développeurs"],"de":["AGENTS.md","Dokumentationskriterien","Gemini CLI","Cursor","Codex","Codierungsagenten","automatisierte Dokumentation","Produktivität für Entwickler"],"pt":["critérios de documentação","ferramentas de inteligência artificial","framework Agentic","Cursor","Codex","Gemini CLI","agentes de codificação AI","automação de tarefas","produtividade de desenvolvimento"],"ru":["критерии документации","ИИ агенты","фреймворк Agentic","Cursor","Codex","Gemini CLI","агенты кодирования ИИ","автоматизация задач","производительность разработки"],"ar":["معايير التوثيق","أدوات الإتصال الإصطناعي","إطار العمل Agentic","محوّل Cursor","Codex","Gemini CLI","وكلاء البرمجة الإصطناعية","آليّة المهام","إنتاجية التطوير"]}},"owner":"shinpr","repo":"agentic-code","repoPath":"shinpr/agentic-code","stars":35,"forks":3,"updatedAt":"2026-03-02T14:33:29Z","topics":["agent-skills","agentic-ai","agentic-workflow","ai-agents","automation","codex","cursor","developer-tools","gemini-cli","llm-orchestration","productivity","prompt-engineering","skills"],"category":"community","skillMd":{"name":"documentation-criteria","description":"Guides PRD, ADR, Design Doc, and Work Plan creation. Use when: planning features, writing specs, or creating technical documents.","bodyPreview":"# Documentation Creation Criteria\n\n## Creation Decision Matrix\n\n| Condition | Required Documents | Creation Order |\n|-----------|-------------------|----------------|\n| New Feature Addition | PRD → [ADR] → Design Doc → Work Plan | After PRD approval |\n| ADR Conditions Met (see below) | ADR → Design Doc → Work Plan | Start immediately |\n| 6+ Files | ADR → Design Doc → Work Plan (Required) | Start immediately |\n| 3-5 Files | Design Doc → Work Plan (Recommended) | Start immediately |\n| 1-2 Files |","body":"# Documentation Creation Criteria\n\n## Creation Decision Matrix\n\n| Condition | Required Documents | Creation Order |\n|-----------|-------------------|----------------|\n| New Feature Addition | PRD → [ADR] → Design Doc → Work Plan | After PRD approval |\n| ADR Conditions Met (see below) | ADR → Design Doc → Work Plan | Start immediately |\n| 6+ Files | ADR → Design Doc → Work Plan (Required) | Start immediately |\n| 3-5 Files | Design Doc → Work Plan (Recommended) | Start immediately |\n| 1-2 Files | None | Direct implementation |\n\n## ADR Creation Conditions (Required if Any Apply)\n\n### 1. Type System Changes\n- **Adding nested types/structures with 3+ levels**: e.g., `A { B { C { D } } }`\n  - Rationale: Deep nesting has high complexity and wide impact scope\n- **Changing/deleting types used in 3+ locations**\n  - Rationale: Multiple location impacts require careful consideration\n- **Data representation responsibility changes** (e.g., transfer object→domain model)\n  - Rationale: Conceptual model changes affect design philosophy\n\n### 2. Data Flow Changes\n- **Storage location changes** (DB→File, Memory→Cache)\n- **Processing order changes with 3+ steps**\n  - Example: \"Input→Validation→Save\" to \"Input→Save→Async Validation\"\n- **Data passing method changes** (props→Context, direct reference→events)\n\n### 3. Architecture Changes\n- Layer addition, responsibility changes, component relocation\n\n### 4. External Dependency Changes\n- Library/framework/external API introduction or replacement\n\n### 5. Complex Implementation Logic (Regardless of Scale)\n- Managing 3+ states\n- Coordinating 5+ asynchronous processes\n\n## Detailed Document Definitions\n\n### PRD (Product Requirements Document)\n\n**Purpose**: Define business requirements and user value\n\n**Includes**:\n- Business requirements and user value\n- Success metrics and KPIs (measurable format)\n- User stories and use cases\n- MoSCoW prioritization (Must/Should/Could/Won''t)\n- MVP and Future phase separation\n- User journey diagram\n- Scope boundary diagram\n\n**Excludes**:\n- Technical implementation details (→Design Doc)\n- Technical selection rationale (→ADR)\n- **Implementation phases** (→Work Plan)\n- **Task breakdown** (→Work Plan)\n\n### ADR (Architecture Decision Record)\n\n**Purpose**: Record technical decisions\n\n**Includes**:\n- Decision (what was selected)\n- Rationale (why that selection was made)\n- Option comparison (minimum 3 options) and trade-offs\n- Architecture impact\n- Principled implementation guidelines\n\n**Excludes**:\n- Implementation schedule, duration (→Work Plan)\n- Detailed implementation procedures (→Design Doc)\n- Specific code examples (→Design Doc)\n- Resource assignments (→Work Plan)\n\n### Design Document\n\n**Purpose**: Define technical implementation\n\n**Includes**:\n- **Existing codebase analysis** (required)\n  - Implementation path mapping (both existing and new)\n  - Integration point clarification (connection points with existing code even for new implementations)\n- Technical implementation approach (vertical/horizontal/hybrid)\n- **Technical dependencies and implementation constraints** (required implementation order)\n- Interface and type definitions\n- Data flow and component design\n- **E2E verification procedures at integration points**\n- **Acceptance criteria (measurable format)**\n- Change impact map (clearly specify direct impact/indirect impact/no ripple effect)\n- Complete enumeration of integration points\n- Data contract clarification\n- **Agreement checklist** (agreements with stakeholders)\n- **Code inspection evidence** (inspected files/functions during investigation)\n- **Field propagation map** (when fields cross component boundaries)\n- **Data representation decision** (when introducing new structures)\n- **Applicable standards** (explicit/implicit classification)\n- **Prerequisite ADRs** (including common ADRs)\n\n**Required Structural Elements**:\n```yaml\nChange Impact Map:\n  Change Target: [Component/Feature]\n  Direct Impact: [Files/Functions]\n  Indirect Impact: [Data format/Processing time]\n  No Ripple Effect: [Unaffected features]\n\nAPI Contract Change Matrix:\n  Existing: [Function/operation signature]\n  New: [Function/operation signature]\n  Conversion Required: [Yes/No]\n  Compatibility Strategy: [Approach]\n```\n\n**Excludes**:\n- Why that technology was chosen (→Reference ADR)\n- When to implement, duration (→Work Plan)\n- Who will implement (→Work Plan)\n\n### Work Plan\n\n**Purpose**: Implementation task management and progress tracking\n\n**Includes**:\n- Task breakdown and dependencies (maximum 2 levels)\n- Schedule and duration estimates\n- **Copy E2E verification procedures from Design Doc** (cannot delete, can add)\n- **Stage 4 Quality Assurance Stage (required)**\n- Progress records (checkbox format)\n\n**Excludes**:\n- Technical rationale (→ADR)\n- Design details (→Design Doc)\n\n**Stage Division Criteria**:\n1. **Stage 1: Foundation Implementation** - Type definitions, interfaces, test preparation\n2. **Stage 2: Core Feature Implementation** - Business logic, unit tests\n3. **Stage 3: Integration Implementation** - External connections, presentation layer\n4. **Stage 4: Quality Assurance (Required)** - Acceptance criteria achievement, all tests passing, quality checks\n\n**Three Elements of Task Completion Definition**:\n1. **Implementation Complete**: Code is functional\n2. **Quality Complete**: Tests, type checks, linting pass\n3. **Integration Complete**: Verified connection with other components\n\n## Creation Process\n\n1. **Problem Analysis**: Change scale assessment, ADR condition check\n   - Identify explicit and implicit project standards before investigation\n2. **ADR Option Consideration** (ADR only): Compare 3+ options, specify trade-offs\n3. **Creation**: Use templates, include measurable conditions\n4. **Approval**: \"Accepted\" after review enables implementation\n\n## Storage Locations\n\n| Document | Path | Naming Convention | Template |\n|----------|------|------------------|----------|\n| PRD | `docs/prd/` | `[feature-name]-prd.md` | `template-en.md` |\n| ADR | `docs/adr/` | `ADR-[4-digits]-[title].md` | `template-en.md` |\n| Design Doc | `docs/design/` | `[feature-name]-design.md` | `template-en.md` |\n| Work Plan | `docs/plans/` | `YYYYMMDD-{type}-{description}.md` | `template-en.md` |\n\n*Note: Work plans are stored in `docs/plans/` and excluded by `.gitignore`\n\n## ADR Status\n`Proposed` → `Accepted` → `Deprecated`/`Superseded`/`Rejected`\n\n## AI Automation Rules\n- 5+ files: Suggest ADR creation\n- Type/data flow change detected: ADR mandatory\n- Check existing ADRs before implementation\n\n## Diagram Requirements\n\nRequired diagrams for each document (using mermaid notation):\n\n| Document | Required Diagrams | Purpose |\n|----------|------------------|---------|\n| PRD | User journey diagram, Scope boundary diagram | Clarify user experience and scope |\n| ADR | Option comparison diagram (when needed) | Visualize trade-offs |\n| Design Doc | Architecture diagram, Data flow diagram | Understand technical structure |\n| Work Plan | Phase structure diagram, Task dependency diagram | Clarify implementation order |\n\n## Common ADR Relationships\n1. **At creation**: Identify common technical areas (logging, error handling, async processing, etc.), reference existing common ADRs\n2. **When missing**: Consider creating necessary common ADRs\n3. **Design Doc**: Specify common ADRs in \"Prerequisite ADRs\" section\n4. **Compliance check**: Verify design aligns with common ADR decisions\n"},"lastSynced":"2026-03-06T06:38:05.520Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing systematic test-first workflows with quality gates for AI coding agents, powered by AGENTS.md","zh":"适合需要系统化测试优先工作流和 AI 编码代理质量门的开发代理，支持由 AGENTS.md 提供的 AI 编码代理","ja":"開発エージェントが体系的なテストファーストのワークフローと AI コーディングエージェントの品質ゲートを必要とする場合に最適です。AGENTS.md によって提供される AI コーディングエージェントを使用しています","ko":"개발 에이전트가 체계적인 테스트 우선 워크플로와 AI 코딩 에이전트의 품질 게이트가 필요한 경우에 완벽합니다. AGENTS.md 에 의해 제공되는 AI 코딩 에이전트를 사용합니다","es":"Perfecto para agentes de desarrollo que necesitan flujos de trabajo sistemáticos de prueba primero con puertas de calidad para agentes de codificación de IA, impulsados por AGENTS.md","fr":"Parfait pour les agents de développement ayant besoin de flux de travail systématiques de test en premier avec des portes de qualité pour les agents de codage IA, alimentés par AGENTS.md","de":"Perfekt für Entwicklungsmittel, die systematische testgetriebene Workflows mit Qualitätsprüfungen für KI-Coding-Agenten benötigen, angetrieben von AGENTS.md","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de fluxos de trabalho sistemáticos de teste em primeiro lugar com portas de qualidade para agentes de codificação de IA, impulsionados por AGENTS.md","ru":"Идеально подходит для агентов разработки, которым требуются системные тестовые рабочие процессы с воротами качества для агентов кодирования ИИ, работающих на основе AGENTS.md","ar":"مثالي لعملاقة التطوير الذين يحتاجون إلى تدفقات عمل منهجية لاختبارات أولوية مع بوابات جودة للوكلاء البرمجيين للذكاء الاصطناعي، مدعومة من قبل AGENTS.md"},"recommendation":{"en":"Empowers agents to create comprehensive content analysis using Creation Decision Matrix, supporting PRD, ADR, Design Doc, and Work Plan documents, with systematic test-first workflows and quality gates for AI coding agents","zh":"赋予代理创建综合内容分析的能力，使用创建决策矩阵，支持 PRD、ADR、设计文档和工作计划文档，并具有系统化的测试优先工作流和 AI 编码代理的质量门","ja":"エージェントが包括的なコンテンツ分析を作成する能力を付与します。Creation Decision Matrix を使用して、PRD、ADR、設計ドキュメント、ワークプランドキュメントをサポートします。さらに、体系的なテストファーストのワークフローと AI コーディングエージェントの品質ゲートを提供します","ko":"에이전트가 포괄적인 콘텐츠 분석을 생성할 수 있는 능력을 부여합니다. 생성 결정 매트릭스를 사용하여 PRD, ADR, 설계 문서, 작업 계획 문서를 지원하며, 체계적인 테스트 우선 워크플로와 AI 코딩 에이전트의 품질 게이트를 제공합니다","es":"Habilita a los agentes a crear un análisis de contenido integral utilizando la Matriz de Decisión de Creación, que admite documentos PRD, ADR, Design Doc y Work Plan, con flujos de trabajo sistemáticos de prueba primero y puertas de calidad para agentes de codificación de IA","fr":"Permet aux agents de créer une analyse de contenu complète en utilisant la Matrice de Décision de Création, qui prend en charge les documents PRD, ADR, Design Doc et Work Plan, avec des flux de travail systématiques de test en premier et des portes de qualité pour les agents de codage IA","de":"Ermächtigt die Mittel, umfassende Inhaltsanalysen unter Verwendung der Entscheidungsmatrix für die Erstellung zu erstellen, die PRD-, ADR-, Design-Dokument- und Arbeitsplan-Dokumente unterstützt, mit systematischen testgetriebenen Workflows und Qualitätsprüfungen für KI-Coding-Agenten","pt":"Habilita os agentes a criar análises de conteúdo abrangentes usando a Matriz de Decisão de Criação, suportando documentos PRD, ADR, Design Doc e Work Plan, com fluxos de trabalho sistemáticos de teste em primeiro lugar e portas de qualidade para agentes de codificação de IA","ru":"Наделяет агентов возможностью создавать всесторонние анализы контента с помощью Матрицы решений по созданию, поддерживающей документы PRD, ADR, Design Doc и Work Plan, с системными тестовыми рабочими процессами и воротами качества для агентов кодирования ИИ","ar":"تمكّن الوكلاء من إنشاء تحليلات محتوى شاملة باستخدام مصفوفة قرارات الإنشاء، داعمة لوثائق PRD و ADR و Design Doc و خطة العمل، مع تدفقات عمل منهجية لاختبارات أولوية وبوابات جودة للوكلاء البرمجيين للذكاء الاصطناعي"},"useCases":{"en":["Automating documentation creation for new feature additions","Generating Architecture Decision Records (ADRs) for complex projects","Creating design documents and work plans for projects with 6+ files"],"zh":["自动创建新功能添加的文档","为复杂项目生成架构决策记录 (ADRs)","为具有 6+ 个文件的项目创建设计文档和工作计划"],"ja":["新機能追加のドキュメントを作成する自動化","複雑なプロジェクトのアーキテクチャ決定レコード (ADRs) を生成する","6 個以上のファイルを持つプロジェクトの設計ドキュメントとワークプランを作成する"],"ko":["새로운 기능 추가에 대한 문서 자동 생성","복잡한 프로젝트의 아키텍처 결정 레코드 (ADRs) 생성","6개 이상의 파일을 가진 프로젝트의 설계 문서와 작업 계획 생성"],"es":["Automatización de la creación de documentación para nuevas adiciones de características","Generación de Registros de Decisiones de Arquitectura (ADRs) para proyectos complejos","Creación de documentos de diseño y planes de trabajo para proyectos con 6+ archivos"],"fr":["Automatisation de la création de documentation pour les nouvelles additions de fonctionnalités","Génération d''Enregistrements de Décision d''Architecture (ADRs) pour les projets complexes","Création de documents de conception et de plans de travail pour les projets avec 6+ fichiers"],"de":["Automatisierung der Dokumentenerstellung für neue Funktionsadditionen","Generierung von Architekturentscheidungsregistern (ADRs) für komplexe Projekte","Erstellung von Designdokumenten und Arbeitsplänen für Projekte mit 6+ Dateien"],"pt":["Automatizar a criação de documentação para novas adições de recursos","Gerar Registros de Decisões de Arquitetura (ADRs) para projetos complexos","Criar documentos de design e planos de trabalho para projetos com 6+ arquivos"],"ru":["Автоматизировать создание документации для новых добавлений функций","Генерировать Записи решений по архитектуре (ADRs) для сложных проектов","Создавать документы дизайна и планы работы для проектов с 6+ файлами"],"ar":["تخصيص إنشاء وثائق لاضافات الميزات الجديدة","إنشاء سجلات قرارات الهيكل (ADRs) للمشاريع المعقدة","إنشاء وثائق التصميم وخطط العمل للمشاريع التي تحتوي على 6+ ملفات"]},"limitations":{"en":["Requires AGENTS.md framework","Limited to specific document types (PRD, ADR, Design Doc, Work Plan)"],"zh":["需要 AGENTS.md 框架","仅限于特定的文档类型 (PRD, ADR, 设计文档, 工作计划)"],"ja":["AGENTS.md フレームワークを必要とする","特定のドキュメントタイプ (PRD, ADR, 設計ドキュメント, ワークプラン) のみに限定される"],"ko":["AGENTS.md 프레임워크가 필요합니다","특정 문서 유형 (PRD, ADR, 설계 문서, 작업 계획) 만 지원합니다"],"es":["Requiere el framework AGENTS.md","Limitado a tipos de documentos específicos (PRD, ADR, Design Doc, Work Plan)"],"fr":["Nécessite le framework AGENTS.md","Limité à des types de documents spécifiques (PRD, ADR, Design Doc, Work Plan)"],"de":["Benötigt das AGENTS.md-Framework","Begrenzt auf bestimmte Dokumententypen (PRD, ADR, Design-Dokument, Arbeitsplan)"],"pt":["Requer o framework AGENTS.md","Limitado a tipos de documentos específicos (PRD, ADR, Design Doc, Work Plan)"],"ru":["Требует фреймворка AGENTS.md","Ограничен конкретными типами документов (PRD, ADR, Design Doc, Work Plan)"],"ar":["يتطلب إطار العمل AGENTS.md","محدود بنوع معين من الوثائق (PRD و ADR و Design Doc و خطة العمل)"]},"version":4},"contentHash":"d44ef2ecfa66db6c6aeec22525a38f071cde63e7934d40d85c6054294ed84a31","qualityScore":44}');
