INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shinpr/agentic-code/documentation-criteria', 'documentation-criteria', 'shinpr', 'agentic-code', 'community', 'documentation-criteria shinpr agentic-code community agent-skills agentic-ai agentic-workflow ai-agents automation codex cursor developer-tools gemini-cli llm-orchestration productivity prompt-engineering skills The documentation-criteria skill enables developers to create systematic, test-first workflows with quality gates for AI coding agents. It supports Agentic coding framework powered by AGENTS.md. Agentic AI 文档创建标准提供系统化的工作流程和质量门槛，支持 Cursor、Codex、Gemini CLI 和 AI 编码代理 Agentic AI ドキュメント作成基準は、システム化されたワークフローと品質ゲートを提供し、Cursor、Codex、Gemini CLI、AI コーディングエージェントをサポート Agentic AI 문서 생성 기준은 시스템화된 워크플로우와 품질 게이트를 제공하며 Cursor, Codex, Gemini CLI 및 AI 코딩 에이전트를 지원합니다 Los criterios de documentación de AGENTS.md permiten flujos de trabajo sistemáticos y de prueba para Cursor, Codex y Gemini CLI Les critères de documentation d''AGENTS.md permettent des flux de travail systématiques et de test pour Cursor, Codex et Gemini CLI Die Dokumentationskriterien von AGENTS.md ermöglichen systematische und testgesteuerte Workflows für Cursor, Codex und Gemini CLI O framework Agentic fornece um fluxo de trabalho sistemático para a criação de documentação de alta qualidade com critérios claros para Cursor, Codex, Gemini CLI e agentes de codificação AI. Фреймворк Agentic обеспечивает системный рабочий процесс для создания качественной документации с четкими критериями для Cursor, Codex, Gemini CLI и агентов кодирования ИИ. يقدم إطار العمل Agentic تدفق عمل منهجي لإنشاء توثيق ذي جودة عالية مع معايير واضحة لمحوّل Cursor و Codex و Gemini CLI ووكلاء البرمجة الإصطناعية how to use documentation-criteria documentation-criteria setup guide agentic coding framework tutorial ai coding agents workflow automation documentation-criteria vs traditional workflows gemini cli documentation codex ai agent integration cursor workflow automation test-first workflow with quality gates documentation-criteria install Agentic AI 文档创建标准 自动化测试 文档管理 Cursor Codex Gemini CLI AI 编码代理 条件决策矩阵 Implements Creation Decision Matrix for conditional document creation Supports PRD, ADR, Design Doc, and Work Plan document types Automates workflows with quality gates for Cursor, Codex, and Gemini CLI Enables test-first workflows for AI coding agents Provides conditional logic for document creation based on file count (1-2, 3-5, 6+ files) documentation-criteria is a systematic approach to creating documentation with quality gates for AI coding agents, using a test-first workflow with tools like Cursor, Codex, and Gemini CLI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('oimiragieo/agent-studio/container-expert', 'community', 'oimiragieo', 'agent-studio', 'oimiragieo/agent-studio', 'container-expert', 17, 0, 44, '2026-03-06T12:49:46Z', '2026-03-06T13:02:32.723Z', '964030ad7f8bafe82ca19da81c4a3a54b2c2e6ba9a32ffd762b255e3aff1b4f9', '{"id":"oimiragieo/agent-studio/container-expert","name":"container-expert","description":{"en":"The container-expert skill helps developers write better code by applying established guidelines and best practices for container orchestration. It benefits developers working with Docker, Kubernetes, Helm, and service mesh.","zh":"Container Expert 是一款AI代理，专精于容器编排技术，包括Docker、Kubernetes、Helm和服务网格。它通过审查代码合规性、提供改进建议和架构指导，帮助开发者遵循最佳实践。","ja":"Container Expertは、Docker、Kubernetes、Helm、サービスメッシュを含むコンテナオーケストレーションに特化したAIエージェントです。コードレビューとベストプラクティスに基づく改善提案を行います。","ko":"Container Expert는 Docker, Kubernetes, Helm 및 서비스 메시를 포함한 컨테이너 오케스트레이션에 깊은 지식을 가진 AI 에이전트입니다. 코드 검토 및 모범 사례를 통해 개발자를 지원합니다.","es":"El experto en contenedores te ayuda a escribir mejor código aplicando las mejores prácticas en contenedorización","fr":"L''expert en conteneurs vous aide à écrire un meilleur code en appliquant les meilleures pratiques en conteneurisation","de":"Der Container-Experte hilft Ihnen, besseren Code zu schreiben, indem er bewährte Verfahren in der Containervirtualisierung anwendet","pt":"O Container Expert é um AI Agent especializado que ajuda desenvolvedores a aplicar as melhores práticas de orquestração de containers. Ele revisa código, sugere melhorias e fornece orientação técnica para Docker, Kubernetes, Helm e Service Mesh.","ru":"Container Expert — это специализированный ИИ Агент, который помогает разработчикам применять лучшие практики оркестрации контейнеров. Он проверяет код, предлагает улучшения и предоставляет технические рекомендации по Docker, Kubernetes, Helm и Service Mesh.","ar":"Container Expert هي أداة ذكاء اصطناعي متخصصة تساعد المطورين على تطبيق أفضل ممارسات أوركسترة الحاويات. تقوم بمراجعة التعليمات البرمجية، واقتراح تحسينات، وتقديم إرشادات فنية لـ Docker و Kubernetes و Helm و Service Mesh."},"seo":{"title":{"en":"container-expert: Kubernetes Optimization Guide | AI Agen...","zh":"Container Expert AI 代理：Docker 和 Kubernetes 最佳实践指南","ja":"Container Expert AIエージェント：DockerとKubernetesのベストプラクティス","ko":"Container Expert AI 에이전트: Docker 및 Kubernetes 모범 사례 가이드","es":"Guía de configuración de contenedores con experto en cont...","fr":"Guide de mise en place de conteneurs avec l''expert en con...","de":"Container-Setup-Leitfaden mit Container-Experte","pt":"Container Expert AI Agent: Melhores Práticas para Docker ...","ru":"Container Expert ИИ Агент: Лучшие практики для Docker и K...","ar":"Container Expert أداة الذكاء الاصطناعي: أفضل الممارسات لـ..."},"description":{"en":"Unlock expert container orchestration with container-expert. Learn how to refactor code for Docker, Kubernetes, and Helm compliance. Get started now!","zh":"这款AI代理专为容器专家设计，可审查Docker和Kubernetes代码的合规性，提供架构指导并帮助重构代码。利用AI提升您的容器化技能和部署最佳实践。","ja":"このAIエージェントは、DockerとKubernetesのコードをレビューし、ベストプラクティスに準拠しているかをチェックします。アーキテクチャガイダンスを提供し、コードのリファクタリングを支援。","ko":"이 AI 에이전트는 Docker 및 Kubernetes 코드의 모범 사례 준수를 검토하고, 아키텍처 지침을 제공하며 코드 리팩토링을 도와줍니다. 컨테이너 기술을 향상시키세요.","es":"Mejora tu código con nuestro experto en contenedores, que te ayuda a aplicar las mejores prácticas en Docker, Kubernetes, Helm y Service Mesh","fr":"Améliorez votre code avec notre expert en conteneurs, qui vous aide à appliquer les meilleures pratiques en Docker, Kubernetes, Helm et Service Mesh","de":"Verbessern Sie Ihren Code mit unserem Container-Experten, der Ihnen hilft, bewährte Verfahren in Docker, Kubernetes, Helm und Service Mesh anzuwenden","pt":"Use o AI Agent Container Expert para revisar código, refatorar para melhores práticas e obter orientação em Docker, Kubernetes, Helm e Service Mesh. Otimize ...","ru":"Используйте ИИ Агент Container Expert для проверки кода, рефакторинга по лучшим практикам и получения руководства по Docker, Kubernetes, Helm и Service Mesh....","ar":"استخدم أداة الذكاء الاصطناعي Container Expert لمراجعة التعليمات البرمجية، وإعادة الهيكلة وفقًا لأفضل الممارسات، والحصول على إرشادات حول Docker و Kubernetes و..."},"definition":{"en":"container-expert is a skill that provides deep knowledge of container orchestration, including Docker, Kubernetes, Helm, and service mesh, to help developers write better code.","zh":"Container Expert 是一个AI驱动的工具，专为容器技术专家设计。它提供代码审查、架构建议和重构帮助，确保Docker和Kubernetes部署符合行业最佳实践和指南。","ja":"Container Expertは、コンテナ技術の専門家向けに設計されたAI駆動のツールです。DockerとKubernetesのデプロイメントが業界のベストプラクティスに準拠していることを保証します。","ko":"Container Expert는 컨테이너 기술 전문가를 위해 설계된 AI 기반 도구입니다. Docker 및 Kubernetes 배포가 업계 모범 사례를 준수하도록 코드 검토 및 아키텍처 조언을 제공합니다.","es":"Un experto en contenedores es un agente de inteligencia artificial que ayuda a los desarrolladores a escribir mejor código en Docker, Kubernetes y Service Mesh","fr":"Un expert en conteneurs est un agent d''intelligence artificielle qui aide les développeurs à écrire un meilleur code en Docker, Kubernetes et Service Mesh","de":"Ein Container-Experte ist ein künstliches Intelligenz-Tool, das Entwicklern hilft, besseren Code in Docker, Kubernetes und Service Mesh zu schreiben","pt":"Container Expert é um AI Agent que atua como um especialista em orquestração de containers. Ele auxilia desenvolvedores a revisar código, refatorar para conformidade com padrões e fornece orientação em tecnologias como Docker, Kubernetes e Helm.","ru":"Container Expert — это ИИ Агент, который выступает в качестве эксперта по оркестрации контейнеров. Он помогает разработчикам проверять код, рефакторить для соответствия стандартам и предоставляет руководство по таким технологиям, как Docker, Kubernetes и Helm.","ar":"Container Expert هي أداة ذكاء اصطناعي تعمل كخبير في أوركسترة الحاويات. تساعد المطورين على مراجعة التعليمات البرمجية، وإعادة الهيكلة للامتثال للمعايير، وتقديم إرشادات حول تقنيات مثل Docker و Kubernetes و Helm."},"features":{"en":["Reviews code for best practice compliance with Docker and Kubernetes","Suggests improvements based on domain patterns for Helm deployments","Explains why certain approaches are preferred for service mesh implementations","Helps refactor code to meet container orchestration standards","Provides architecture guidance for containerized applications"],"zh":["审查Docker和Kubernetes代码的最佳实践合规性","基于领域模式提供改进建议","解释首选方法的原因","帮助重构代码以满足标准","提供容器架构指导","支持Helm和服务网格技术"],"ja":["DockerとKubernetesのコードのベストプラクティスコンプライアンスをレビュー","ドメインパターンに基づいた改善提案","推奨アプローチの理由を説明","標準を満たすためのコードリファクタリングを支援","コンテナアーキテクチャのガイダンスを提供","Helmとサービスメッシュ技術をサポート"],"ko":["Docker 및 Kubernetes 코드의 모범 사례 준수 검토","도메인 패턴 기반 개선 제안","선호되는 접근 방식의 이유 설명","표준을 충족하기 위한 코드 리팩토링 지원","컨테이너 아키텍처 지침 제공","Helm 및 서비스 메시 기술 지원"],"es":["Revisión de código para cumplimiento de mejores prácticas","Sugerencias de mejora basadas en patrones de dominio","Explicación de enfoques preferidos en Docker y Kubernetes","Ayuda para refactorizar código para cumplir con los estándares","Orientación arquitectónica para contenedores y Service Mesh"],"fr":["Révision de code pour la conformité aux meilleures pratiques","Suggestions d''amélioration basées sur des modèles de domaine","Explication des approches préférées en Docker et Kubernetes","Aide pour réorganiser le code pour répondre aux normes","Orientations architecturales pour les conteneurs et Service Mesh"],"de":["Code-Überprüfung für die Einhaltung bewährter Verfahren","Vorschläge für Verbesserungen basierend auf Domänenmustern","Erklärung bevorzugter Ansätze in Docker und Kubernetes","Hilfe bei der Refaktorisierung von Code, um Standards zu erfüllen","Architekturleitfäden für Containervirtualisierung und Service Mesh"],"pt":["Revisão de código para conformidade com melhores práticas de containers","Sugestões de melhorias baseadas em padrões de domínio para Docker e Kubernetes","Explicações técn