INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LeeAeron/AceStep/acestep-docs', 'acestep-docs', 'LeeAeron', 'AceStep', 'community', 'acestep-docs LeeAeron AceStep community The acestep-docs skill provides a portable fork of a powerful local music generation model, supporting CUDA devices for enhanced performance, benefiting developers and music enthusiasts alike. ACE-Step 文档提供了本地音乐生成模型的设置指南和教程，支持 CUDA 设备，帮助开发者快速上手 ACE-Step ドキュメントでは、ローカル音楽生成モデルの設定ガイドとチュートリアルを提供し、CUDA デバイスをサポートします ACE-Step 문서는 로컬 음악 생성 모델의 설정 가이드와 튜토리얼을 제공하며 CUDA 장치를 지원하여 개발자가 빠르게 시작할 수 있습니다 acestep-docs es un modelo de generación de música local que supera a la mayoría de las alternativas comerciales, con soporte para dispositivos CUDA acestep-docs est un modèle de génération de musique local qui surpasse la plupart des alternatives commerciales, avec prise en charge des appareils CUDA acestep-docs ist ein lokales Musikgenerierungsmodell, das die meisten kommerziellen Alternativen übertrifft, mit Unterstützung für CUDA-Geräte O ACE-Step é um modelo de geração de música local poderoso que suporta dispositivos CUDA. Aprenda a configurá-lo e a utilizá-lo ACE-Step - это мощная модель генерации музыки, поддерживающая устройства CUDA. Узнайте, как установить и использовать ее ACE-Step هو نموذج توليد الموسيقى المحلية الأكثر قدرة، الذي يدعم أجهزة CUDA. تعرف على كيفية إعداده واستخدامه how to use acestep-docs acestep-docs alternative acestep-docs setup guide what is acestep-docs acestep-docs vs commercial music generation models acestep-docs install with CUDA support acestep-docs music generation tutorial acestep-docs project overview acestep-docs model zoo acestep-docs startup commands ACE-Step 文档 本地音乐生成模型 CUDA 设备 设置指南 教程 最佳实践 AIエージェント 音乐生成工具 Supports CUDA devices for accelerated music generation Includes README.md for installation and startup commands Provides Tutorial.md for getting started with best practices Offers ABOUT.md for project overview and architecture details Allows access to model zoo for diverse music generation options Enables startup with specific commands for customized music generation acestep-docs is a documentation skill for the ACE-Step music generation system, offering guides, tutorials, and project overviews.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('srid/AI/nix', 'community', 'srid', 'AI', 'srid/AI', 'nix', 0, 0, 44, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:19.159Z', '076a9e2b1215bd389023d9e194be279ca8e98958f94f5d750d8ab33736519c6f', '{"id":"srid/AI/nix","name":"nix","description":{"en":"The nix skill provides expert guidelines for nix development, benefiting AI agents and developers. It ensures consistent and reproducible builds using nix.","zh":"Nix开发指南，介绍flake-parts、nixpkgs-fmt和writeShellApplication的使用","ja":"Nix開発のガイド。flake-parts、nixpkgs-fmt、writeShellApplicationの使用方法を紹介","ko":"Nix 설정 가이드: flake-parts, nixpkgs-fmt, writeShellApplication 사용법","es":"Nix es una herramienta de configuración para codificar con eficiencia. Utiliza flake-parts y nixpkgs-fmt para crear y formatear flakes.","fr":"Nix est un outil de configuration pour coder avec efficacité. Utilisez flake-parts et nixpkgs-fmt pour créer et formater des flakes.","de":"Nix ist ein Konfigurationswerkzeug für die effiziente Codierung. Verwenden Sie flake-parts und nixpkgs-fmt, um Flakes zu erstellen und zu formatieren.","pt":"O Nix é uma ferramenta de configuração para codificação que utiliza flake-parts e nixpkgs-fmt para garantir a qualidade do código.","ru":"Nix - это инструмент настройки для разработки, использующий flake-parts и nixpkgs-fmt для обеспечения качества кода.","ar":"نيكس هو أداة إعداد للبرمجة التي تستخدم flake-parts و nixpkgs-fmt لضمان جودة الكود."},"seo":{"title":{"en":"nix: Setup Guide for AI Agents | Nix Development Best Pra...","zh":"Nix Setup Guide: AI工具配置最佳实践","ja":"Nix開発ベストプラクティス: AIエージェント設定","ko":"Nix 설정 가이드: AI 도구 개발 모범 사례","es":"Guía de Configuración de Nix para Desarrolladores","fr":"Guide de Configuration Nix pour les Développeurs","de":"Nix-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração Nix para Desenvolvedores","ru":"ИИ Агенты: Настройка Nix для Разработчиков","ar":"إعداد نيكس للبرمجة: دليل المستخدم"},"description":{"en":"Discover how to optimize your AI setup with nix. Learn expert guidelines and best practices for nix development, including flake-parts and nixpkgs-fmt.","zh":"了解Nix开发最佳实践，包括flake-parts、nixpkgs-fmt和writeShellApplication","ja":"Nix開発のベストプラクティスを学び、flake-parts、nixpkgs-fmt、writeShellApplicationを使用する","ko":"Nix 개발 모범 사례에 대해 알아보세요. flake-parts, nixpkgs-fmt, writeShellApplication 사용","es":"Aprende a configurar Nix para codificar con eficiencia. Descubre las mejores prácticas y características clave para desarrolladores.","fr":"Découvrez comment configurer Nix pour coder avec efficacité. Explorez les meilleures pratiques et les fonctionnalités clés pour les développeurs.","de":"Erfahren Sie, wie Sie Nix für die effiziente Codierung konfigurieren. Entdecken Sie die besten Praktiken und wichtigsten Funktionen für Entwickler.","pt":"Aprenda a configurar o Nix para codificação com as melhores práticas e ferramentas como flake-parts e nixpkgs-fmt","ru":"Изучите настройку Nix для разработки с использованием лучших практик и инструментов, таких как flake-parts и nixpkgs-fmt","ar":"تعلم كيفية إعداد نيكس للبرمجة مع أفضل الممارسات والأدوات مثل flake-parts و nixpkgs-fmt"},"definition":{"en":"nix is a package manager that enables reproducible and declarative configuration of AI setups, ensuring consistent builds and deployments.","zh":"Nix是用于配置和管理AI工具的开发环境","ja":"Nixは、AIエージェントの開発環境を構成し管理するためのツール","ko":"Nix는 AI 도구의 개발 환경을 구성하고 관리하기 위한 도구","es":"Nix es un sistema de gestión de paquetes y configuración para desarrolladores.","fr":"Nix est un système de gestion de paquets et de configuration pour les développeurs.","de":"Nix ist ein Paket- und Konfigurationsmanagement-System für Entwickler.","pt":"Nix é uma ferramenta de configuração para codificação que automatiza a validação e formatação do código","ru":"Nix - это инструмент настройки для разработки, автоматизирующий проверку и форматирование кода","ar":"نيكس هو أداة إعداد للبرمجة التي تutomatiza التحقق والتنسيق الكود"},"features":{"en":["Utilizes flake-parts for creating new flakes","Formats code with nixpkgs-fmt for consistency","Employs writeShellApplication for shell scripts with strict bash options","Runs ShellCheck validation for error-free scripts","Automatically sets meta.description for better documentation"],"zh":["使用flake-parts创建新flakes","使用nixpkgs-fmt格式化代码","使用writeShellApplication创建shell脚本","自动运行ShellCheck验证","设置严格的bash选项"],"ja":["flake-partsを使用して新しいflakesを作成","nixpkgs-fmtを使用してコードを整形","writeShellApplicationを使用してshellスクリプトを作成","ShellCheck検証を自動実行","厳格なbashオプションを設定"],"ko":["flake-parts를 사용하여 새 플레이크 생성","nixpkgs-fmt를 사용하여 코드 형식화","writeShellApplication를 사용하여 쉘 스크립트 생성","ShellCheck 검증 자동 실행","严格한 bash 옵션 설정"],"es":["Utiliza flake-parts para crear nuevos flakes","Formatea con nixpkgs-fmt después de los cambios","Utiliza writeShellApplication para scripts de shell","Validación automática con ShellCheck","Opciones estrictas de bash (set -euo pipefail)"],"fr":["Utilisez flake-parts pour créer de nouveaux flakes","Formatez avec nixpkgs-fmt après les modifications","Utilisez writeShellApplication pour les scripts shell","Validation automatique avec ShellCheck","Options bash strictes (set -euo pipefail)"],"de":["Verwenden Sie flake-parts, um neue Flakes zu erstellen","Formatieren Sie mit nixpkgs-fmt nach Änderungen","Verwenden Sie writeShellApplication für Shell-Skripte","Automatische Validierung mit ShellCheck","Strenge Bash-Optionen (set -euo pipefail)"],"pt":["Utiliza flake-parts para criar novos flakes","Formatado com nixpkgs-fmt após alterações","Utiliza writeShellApplication para scripts de shell","Validação automática com ShellCheck","Opções de shell estritas (set -euo pipefail)"],"ru":["Использует flake-parts для создания новых flakes","Форматирование с помощью nixpkgs-fmt после изменений","Использует writeShellApplication для shell-скриптов","Автоматическая проверка с помощью ShellCheck","Строгие опции shell (set -euo pipefail)"],"ar":["يستخدم flake-parts لإنشاء flakes جديدة","تنسيق مع nixpkgs-fmt بعد التحديثات","يستخدم writeShellApplication لسكريبتات Shell","التحقق التلقائي مع ShellCheck","خيارات Shell الصارمة (set -euo pipefail)"]},"keywords":{"en":["nix setup guide","nix development best practices","how to use nix for AI","nix vs other package managers","nix install for AI agents","nix alternative for reproducible builds"],"zh":["Nix开发","AI工具配置","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","bash选项"],"ja":["Nix開発","AIエージェント設定","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","bashオプション"],"ko":["Nix 설정","AI 도구 개발","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","bash 옵션"],"es":["nix para desarrolladores","guía de configuración de nix","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","configuración de nix","desarrollo con nix","herramientas de desarrollo de nix"],"fr":["nix pour les développeurs","guide de configuration de nix","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","configuration de nix","développement avec nix","outils de développement de nix"],"de":["nix für entwickler","nix-konfigurationsleitfaden","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","nix-konfiguration","entwicklung mit nix","nix-entwicklertools"],"pt":["nix configuração","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","desenvolvimento de software","ferramentas de codificação"],"ru":["настройка nix","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","разработка программного обеспечения","инструменты для разработки"],"ar":["إعداد نيكس","flake-parts","nixpkgs-fmt","writeShellApplication","ShellCheck","تطوير البرمجيات","أدوات البرمجة"]}},"owner":"srid","repo":"AI","repoPath":"srid/AI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"nix","description":"Expert Nix development assistance. Use when working with Nix code, .nix files, flakes, NixOS configuration, or when user mentions Nix, flake-parts, nixpkgs.","bodyPreview":"# Nix Development\n\n## Guidelines\n\n- Use **flake-parts** when creating new flakes\n- Format with **nixpkgs-fmt** after changes\n- Use **writeShellApplication** for shell scripts (not writeShellScriptBin)\n  - Automatically runs ShellCheck validation\n  - Sets strict bash options (`set -euo pipefail`)\n  - Fix ALL ShellCheck warnings without ignoring them\n  - Add **meta.description**\n\n## Building with Nix\n\nWhen running `nix build`:\n- **ALWAYS** use `--print-out-paths` flag so final build path is printe","body":"# Nix Development\n\n## Guidelines\n\n- Use **flake-parts** when creating new flakes\n- Format with **nixpkgs-fmt** after changes\n- Use **writeShellApplication** for shell scripts (not writeShellScriptBin)\n  - Automatically runs ShellCheck validation\n  - Sets strict bash options (`set -euo pipefail`)\n  - Fix ALL ShellCheck warnings without ignoring them\n  - Add **meta.description**\n\n## Building with Nix\n\nWhen running `nix build`:\n- **ALWAYS** use `--print-out-paths` flag so final build path is printed\n- **NEVER** run with timeout - allow command to finish completely\n- If command doesn''t finish OR final out path is not shown, consider it **FAILED**\n- On failure, investigate logs without hallucinating - look at actual error messages\n\n## Home-Manager Module\n\nWhen adding a home-manager module to a project:\n\n1. Module: `nix/modules/home-manager/<name>.nix` - options & config with systemd (Linux) + launchd (Darwin)\n2. Export: `nix/modules/flake/<name>-module.nix` - `flake.homeManagerModules.<name> = ../home-manager/<name>.nix;`\n3. Example: `nix/examples/home-manager/flake.nix` - homeConfiguration + checks.runNixOSTest\n4. CI: Add to `vira.hs` build.flakes: `\"./nix/examples/home-manager\" { overrideInputs = [(\"<name>\", \".\")] }`\n5. Format: `nixpkgs-fmt` all .nix files"},"lastSynced":"2026-03-08T02:00:19.159Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing consistent and reproducible builds using nix","zh":"非常适合需要使用nix进行一致性和可复制构建的DevOps代理","ja":"nixを使用して一貫性と再現性のあるビルドを必要とするDevOpsエージェントに最適","ko":"nix를 사용하여 일관성과 재현 가능한 빌드를 필요로 하는 DevOps 에이전트에게 적합","es":"Perfecto para agentes de DevOps que necesitan compilaciones consistentes y reproducibles utilizando nix","fr":"Parfait pour les agents DevOps ayant besoin de builds cohérents et reproductibles en utilisant nix","de":"Perfekt für DevOps-Agents, die konsistente und reproduzierbare Builds mit nix benötigen","pt":"Perfeito para agentes DevOps que precisam de compilações consistentes e reproduzíveis usando nix","ru":"Идеально подходит для агентов DevOps, которым необходимы последовательные и воспроизводимые сборки с использованием nix","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى عمليات بناء متسقة وقابلة للتكرار باستخدام nix"},"recommendation":{"en":"Empowers agents to ensure deterministic builds with nix, utilizing flake-parts for creating new flakes, nixpkgs-fmt for formatting, and writeShellApplication for shell scripts, while enforcing strict bash options and ShellCheck validation","zh":"赋予代理确保使用nix进行确定性构建的能力，利用flake-parts创建新的flake，nixpkgs-fmt进行格式化，writeShellApplication用于shell脚本，同时强制执行严格的bash选项和ShellCheck验证","ja":"エージェントがnixを使用して決定論的なビルドを保証する能力を与え、flake-partsを使用して新しいflakeを作成し、nixpkgs-fmtを使用してフォーマットし、writeShellApplicationを使用してシェルスクリプトを作成し、同時に厳格なbashオプションとShellCheckの検証を強制する","ko":"에이전트가 nix를 사용하여 결정론적인 빌드를 보장할 수 있는 능력을 부여하며, flake-parts를 사용하여 새로운 flake를 생성하고, nixpkgs-fmt를 사용하여 포맷팅하고, writeShellApplication을 사용하여 셸 스크립트를 생성하며,同時에 엄격한 bash 옵션과 ShellCheck 검증을 강제한다","es":"Habilita a los agentes a garantizar builds deterministas con nix, utilizando flake-parts para crear nuevos flakes, nixpkgs-fmt para el formato y writeShellApplication para scripts de shell, mientras se aplican estrictas opciones de bash y validación de ShellCheck","fr":"Permet aux agents de garantir des builds déterministes avec nix, en utilisant flake-parts pour créer de nouvelles flakes, nixpkgs-fmt pour le formatage et writeShellApplication pour les scripts shell, tout en appliquant des options de bash strictes et une validation ShellCheck","de":"Ermächtigt Agenten, deterministische Builds mit nix sicherzustellen, indem flake-parts für die Erstellung neuer Flakes, nixpkgs-fmt für das Formatieren und writeShellApplication für Shell-Skripte verwendet werden, während dabei strenge Bash-Optionen und ShellCheck-Validierung durchgesetzt werden","pt":"Habilita os agentes a garantir compilações determinísticas com nix, utilizando flake-parts para criar novos flakes, nixpkgs-fmt para formatação e writeShellApplication para scripts de shell, enquanto impõe opções strict bash e validação ShellCheck","ru":"Позволяет агентам обеспечивать детерминированные сборки с помощью nix, используя flake-parts для создания новых flakes, nixpkgs-fmt для форматирования и writeShellApplication для скриптов shell, а также обеспечивает строгие опции bash и проверку ShellCheck","ar":"يمنح الوكلاء ضمان بناء محدد مع nix، باستخدام flake-parts لإنشاء flakes جديدة، و nixpkgs-fmt للتنسيق، و writeShellApplication لبرامج Shell، مع فرض خيارات bash صارمة وتحقق ShellCheck"},"useCases":{"en":["Automating nix build processes with --print-out-paths flag","Generating reproducible environments using flake-parts","Debugging shell scripts with ShellCheck validation and strict bash options"],"zh":["使用--print-out-paths标志自动化nix构建过程","使用flake-parts生成可复制的环境","使用ShellCheck验证和严格的bash选项调试shell脚本"],"ja":["--print-out-pathsフラグを使用してnixビルドプロセスを自動化する","flake-partsを使用して再現可能な環境を生成する","ShellCheckの検証と厳格なbashオプションを使用してシェルスクリプトをデバッグする"],"ko":["--print-out-paths 플래그를 사용하여 nix 빌드 프로세스를 자동화하는 것","flake-parts를 사용하여 재현 가능한 환경을 생성하는 것","ShellCheck 검증과 엄격한 bash 옵션을 사용하여 셸 스크립트를 디버깅하는 것"],"es":["Automatizar procesos de compilación de nix con la bandera --print-out-paths","Generar entornos reproducibles utilizando flake-parts","Depurar scripts de shell con validación de ShellCheck y opciones de bash estrictas"],"fr":["Automatiser les processus de build de nix avec le drapeau --print-out-paths","Générer des environnements reproductibles en utilisant flake-parts","Déboguer les scripts shell avec une validation ShellCheck et des options de bash strictes"],"de":["Automatisieren von nix-Build-Prozessen mit der --print-out-paths-Flagge","Erstellen von reproduzierbaren Umgebungen unter Verwendung von flake-parts","Debuggen von Shell-Skripten mit ShellCheck-Validierung und strengen Bash-Optionen"],"pt":["Automatizar processos de compilação nix com a flag --print-out-paths","Gerar ambientes reproduzíveis usando flake-parts","Depurar scripts de shell com validação ShellCheck e opções strict bash"],"ru":["Автоматизировать процессы сборки nix с флагом --print-out-paths","Генерировать воспроизводимые среды с помощью flake-parts","Отлаживать скрипты shell с помощью проверки ShellCheck и строгих опций bash"],"ar":["تحسين عمليات بناء nix مع علم --print-out-paths","توليد بيئات قابلة للتكرار باستخدام flake-parts","تصحيح أخطاء برامج Shell باستخدام التحقق من ShellCheck وخيارات bash الصارمة"]},"limitations":{"en":["Requires nix installation","Limited to nix-based builds","Mandatory use of --print-out-paths flag with nix build"],"zh":["需要nix安装","仅限nix-based构建","必须使用--print-out-paths标志与nix构建"],"ja":["nixのインストールが必要","nixベースのビルドのみ","--print-out-pathsフラグをnixビルドで使用する必要がある"],"ko":["nix 설치가 필요","nix 기반 빌드만 해당","nix 빌드에서 --print-out-paths 플래그를 사용해야 함"],"es":["Requiere instalación de nix","Limitado a builds basados en nix","Uso obligatorio de la bandera --print-out-paths con nix build"],"fr":["Nécessite l''installation de nix","Limité aux builds basés sur nix","Utilisation obligatoire du drapeau --print-out-paths avec nix build"],"de":["Erfordert nix-Installation","Begrenzt auf nix-basierte Builds","Verpflichtende Verwendung der --print-out-paths-Flagge mit nix build"],"pt":["Requer instalação do nix","Limitado a compilações baseadas em nix","Uso obrigatório da flag --print-out-paths com a compilação nix"],"ru":["Требует установки nix","Ограничен сборками на основе nix","Обязательное использование флага --print-out-paths с сборкой nix"],"ar":["يتطلب تثبيت nix","محدود بالعمليات القائمة على nix","استخدام обязا علم --print-out-paths مع عملية بناء nix"]},"version":4},"contentHash":"076a9e2b1215bd389023d9e194be279ca8e98958f94f5d750d8ab33736519c6f","qualityScore":44}');
