INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('srid/AI/nix', 'nix', 'srid', 'AI', 'community', 'nix srid AI community The nix skill provides expert guidelines for nix development, benefiting AI agents and developers. It ensures consistent and reproducible builds using nix. Nix开发指南，介绍flake-parts、nixpkgs-fmt和writeShellApplication的使用 Nix開発のガイド。flake-parts、nixpkgs-fmt、writeShellApplicationの使用方法を紹介 Nix 설정 가이드: flake-parts, nixpkgs-fmt, writeShellApplication 사용법 Nix es una herramienta de configuración para codificar con eficiencia. Utiliza flake-parts y nixpkgs-fmt para crear y formatear flakes. Nix est un outil de configuration pour coder avec efficacité. Utilisez flake-parts et nixpkgs-fmt pour créer et formater des flakes. Nix ist ein Konfigurationswerkzeug für die effiziente Codierung. Verwenden Sie flake-parts und nixpkgs-fmt, um Flakes zu erstellen und zu formatieren. O Nix é uma ferramenta de configuração para codificação que utiliza flake-parts e nixpkgs-fmt para garantir a qualidade do código. Nix - это инструмент настройки для разработки, использующий flake-parts и nixpkgs-fmt для обеспечения качества кода. نيكس هو أداة إعداد للبرمجة التي تستخدم flake-parts و nixpkgs-fmt لضمان جودة الكود. nix setup guide nix development best practices how to use nix for AI nix vs other package managers nix install for AI agents nix alternative for reproducible builds Nix开发 AI工具配置 flake-parts nixpkgs-fmt writeShellApplication ShellCheck bash选项 Utilizes flake-parts for creating new flakes Formats code with nixpkgs-fmt for consistency Employs writeShellApplication for shell scripts with strict bash options Runs ShellCheck validation for error-free scripts Automatically sets meta.description for better documentation nix is a package manager that enables reproducible and declarative configuration of AI setups, ensuring consistent builds and deployments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('resend/react-email/react-email', 'community', 'resend', 'react-email', 'resend/react-email', 'react-email', 0, 0, 44, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:33.380Z', '3e1c597c4292eaf8555211ba75d7afc57552e21a6657a470ca0e3ef6b934dcae', '{"id":"resend/react-email/react-email","name":"react-email","description":{"en":"react-email allows developers to build and send HTML emails using React components, working across all major email clients. It provides a modern, component-based approach to email development.","zh":"React Email 是一个使用 React 组件构建和发送 HTML 邮件的现代方法","ja":"React Email は、React コンポーネントを使用して HTML メールを構築して送信するためのモダンなアプローチ","ko":"React Email은 React 컴포넌트를 사용하여 HTML 이메일을 구축하고 보내는 현대적인 방법","es":"React Email es una forma moderna de desarrollar correos electrónicos utilizando componentes de React. Crea y envía correos electrónicos HTML con facilidad","fr":"React Email est une approche moderne pour développer des emails à l''aide de composants React. Créez et envoyez des emails HTML facilement","de":"React Email ist eine moderne Methode, um E-Mails mit React-Komponenten zu entwickeln. Erstellen und senden Sie HTML-E-Mails einfach","pt":"O react-email é uma ferramenta que permite criar e enviar emails usando componentes React. Ele oferece uma abordagem moderna e baseada em componentes para o desenvolvimento de emails.","ru":"React-email - это инструмент, который позволяет создавать и отправлять электронные письма с помощью компонентов React. Он предлагает современный и компонентный подход к разработке электронной почты.","ar":"react-email هو أداة تسمح بإنشاء وارسال البريد الإلكتروني باستخدام مكونات React. وهو يقدم نهجًا حديثًا ومتجزأًا لتطوير البريد الإلكتروني."},"seo":{"title":{"en":"react-email: Build and Send Emails with React | AI Agent ...","zh":"React Email Setup Guide - 使用 React 构建和发送 HTML 邮件","ja":"React Email入門 - Reactコンポーネントを使ったHTMLメールの構築","ko":"React Email 시작하기 - React로 HTML 이메일을 구축하고 보내기","es":"Guía de configuración de React Email para desarrolladores","fr":"Guide de démarrage de React Email pour les développeurs","de":"Einrichtungsleitfaden für React Email-Entwickler","pt":"Guia de Configuração do React Email","ru":"ИИ Агенты: Руководство по настройке React Email","ar":"دليل إعداد React Email"},"description":{"en":"Discover how to create HTML emails using React components with react-email. Get started with our setup guide and learn how to send emails across all major em...","zh":"使用 React Email 构建和发送 HTML 邮件。使用 create-email CLI 快速开始您的项目","ja":"React Email を使用して HTML メールを構築して送信します。create-email CLI でプロジェクトを開始","ko":"React Email을 사용하여 HTML 이메일을 구축하고 보냅니다. create-email CLI로 프로젝트를 시작","es":"Aprende a crear y enviar correos electrónicos con React utilizando componentes y una CLI dedicada","fr":"Découvrez comment créer et envoyer des emails avec React en utilisant des composants et une CLI dédiée","de":"Erfahren Sie, wie Sie mit React und einer speziellen CLI E-Mails erstellen und senden können","pt":"Aprenda a criar e enviar emails usando componentes React com o react-email. Descubra como instalar e usar essa ferramenta.","ru":"Узнайте, как создавать и отправлять электронные письма с помощью компонентов React и инструмента react-email. Получите информацию об установке и использовании.","ar":"تعلم كيفية إنشاء وارسال البريد الإلكتروني باستخدام مكونات React مع react-email. اكتشف كيفية التثبيت والاستخدام."},"definition":{"en":"react-email is a modern, component-based approach to email development that allows building and sending HTML emails using React components.","zh":"React Email 是一种使用 React 组件构建和发送 HTML 邮件的技术","ja":"React Email は、React コンポーネントを使用して HTML メールを構築して送信する技術","ko":"React Email은 React 컴포넌트를 사용하여 HTML 이메일을 구축하고 보내는 기술","es":"React Email es un enfoque de desarrollo de correos electrónicos basado en componentes que utiliza React","fr":"React Email est une approche de développement d''emails basée sur des composants qui utilise React","de":"React Email ist ein komponentenbasiertes Verfahren zur Entwicklung von E-Mails, das React verwendet","pt":"O react-email é uma ferramenta de desenvolvimento de emails que usa componentes React para criar emails HTML.","ru":"React-email - это инструмент разработки электронной почты, который использует компоненты React для создания HTML-писем.","ar":"react-email هو أداة تطوير البريد الإلكتروني التي تستخدم مكونات React لإنشاء بريد إلكتروني HTML."},"features":{"en":["Scaffolds a new React Email project using the create-email CLI","Creates a folder called `react-email-starter` with sample email templates","Supports installation using npm, yarn, pnpm, and bun","Generates HTML emails using React components","Works across all major email clients"],"zh":["使用 React 组件构建 HTML 邮件","支持 create-email CLI 快速开始项目","兼容所有主要的电子邮件客户端","使用 npm、yarn、pnpm 或 bun 安装","包含样本电子邮件模板"],"ja":["React コンポーネントを使用して HTML メールを構築","create-email CLI を使用してプロジェクトを開始","主要な電子メールクライアントをすべてサポート","npm、yarn、pnpm、または bun を使用してインストール","サンプル電子メールテンプレートを含む"],"ko":["React 컴포넌트를 사용하여 HTML 이메일을 구축","create-email CLI를 사용하여 프로젝트를 시작","주요한 이메일 클라이언트를 모두 지원","npm, yarn, pnpm 또는 bun을 사용하여 설치","샘플 이메일 템플릿을 포함"],"es":["Crea correos electrónicos HTML utilizando componentes de React","Utiliza la CLI create-email para inicializar proyectos","Compatibilidad con npm, yarn, pnpm y bun","Plantillas de correo electrónico de ejemplo incluidas","Funciona en todos los clientes de correo electrónico principales"],"fr":["Créez des emails HTML à l''aide de composants React","Utilisez la CLI create-email pour initialiser des projets","Compatibilité avec npm, yarn, pnpm et bun","Modèles d''email exemples inclus","Fonctionne sur tous les clients de messagerie principaux"],"de":["Erstellen Sie HTML-E-Mails mithilfe von React-Komponenten","Verwenden Sie die create-email-CLI, um Projekte zu initialisieren","Kompatibilität mit npm, yarn, pnpm und bun","Beispiel-E-Mail-Vorlagen sind enthalten","Funktioniert auf allen wichtigen E-Mail-Clients"],"pt":["Criação de emails HTML usando componentes React","Instalação via CLI com create-email","Suporte a npm, yarn, pnpm e bun","Abordagem moderna e baseada em componentes","Compatibilidade com todos os principais clientes de email"],"ru":["Создание HTML-писем с помощью компонентов React","Установка через CLI с create-email","Поддержка npm, yarn, pnpm и bun","Современный и компонентный подход","Совместимость со всеми основными клиентами электронной почты"],"ar":["إنشاء بريد إلكتروني HTML باستخدام مكونات React","التثبيت عبر CLI مع create-email","الدعم لنpm، yarn، pnpm وbun","نهج حديث ومتجزأ","التوافق مع جميع العملاء الرئيسيين للبريد الإلكتروني"]},"keywords":{"en":["how to use react-email","what is react-email","react-email alternative","react-email vs emailjs","react-email install","react-email setup guide","react email template","create email with react","react email component"],"zh":["React Email","HTML 邮件","React 组件","create-email CLI","电子邮件构建","React Email 教程","AIエージェント","电子邮件开发"],"ja":["React Email","HTML メール","React コンポーネント","create-email CLI","電子メール構築","React Email 入門","AIエージェント","電子メール開発"],"ko":["React Email","HTML 이메일","React 컴포넌트","create-email CLI","이메일 구축","React Email 시작하기","AI 에이전트","이메일 개발"],"es":["react email","desarrollo de correos electrónicos","componentes de react","cli create-email","correo electrónico html","plantillas de correo electrónico","npm react email","yarn react email","pnpm react email","bun react email"],"fr":["react email","développement d''emails","composants react","cli create-email","email html","modèles d''email","npm react email","yarn react email","pnpm react email","bun react email"],"de":["react email","e-mail-entwicklung","react-komponenten","create-email-cli","html-e-mail","e-mail-vorlagen","npm react email","yarn react email","pnpm react email","bun react email"],"pt":["react email","criar email com react","enviar email com react","desenvolvimento de emails","componentes react","CLI create-email","npm react email","yarn react email","pnpm react email","bun react email"],"ru":["react email","создать электронное письмо с react","отправить электронное письмо с react","разработка электронной почты","компоненты react","CLI create-email","npm react email","yarn react email","pnpm react email","bun react email"],"ar":["react email","إنشاء بريد إلكتروني مع react","ارسال بريد إلكتروني مع react","تطوير البريد الإلكتروني","مكونات react","CLI create-email","npm react email","yarn react email","pnpm react email","bun react email"]}},"owner":"resend","repo":"react-email","repoPath":"resend/react-email","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"react-email","description":"Use when creating HTML email templates with React components - welcome emails, password resets, notifications, order confirmations, newsletters, or transactional emails.","version":"1.1.0","bodyPreview":"# React Email\n\nBuild and send HTML emails using React components - a modern, component-based approach to email development that works across all major email clients.\n\n## Installation\n\nYou need to scaffold a new React Email project using the create-email CLI. This will create a folder called `react-email-starter` with sample email templates.\n\nUsing npm:\n```sh\nnpx create-email@latest\n```\n\nUsing yarn:\n```sh\nyarn create email\n```\n\nUsing pnpm:\n```sh\npnpm create email\n```\n\nUsing bun:\n```sh\nbun create","body":"# React Email\n\nBuild and send HTML emails using React components - a modern, component-based approach to email development that works across all major email clients.\n\n## Installation\n\nYou need to scaffold a new React Email project using the create-email CLI. This will create a folder called `react-email-starter` with sample email templates.\n\nUsing npm:\n```sh\nnpx create-email@latest\n```\n\nUsing yarn:\n```sh\nyarn create email\n```\n\nUsing pnpm:\n```sh\npnpm create email\n```\n\nUsing bun:\n```sh\nbun create email\n```\n\n## Navigate to Project Directory\n\nYou must change into the newly created project folder:\n\n```sh\ncd react-email-starter\n```\n\n## Install Dependencies\n\nYou need to install all project dependencies before running the development server.\n\nUsing npm:\n```sh\nnpm install\n```\n\nUsing yarn:\n```sh\nyarn\n```\n\nUsing pnpm:\n```sh\npnpm install\n```\n\nUsing bun:\n```sh\nbun install\n```\n\n## Start the Development Server\n\nYour task is to start the local preview server to view and edit email templates.\n\nUsing npm:\n```sh\nnpm run dev\n```\n\nUsing yarn:\n```sh\nyarn dev\n```\n\nUsing pnpm:\n```sh\npnpm dev\n```\n\nUsing bun:\n```sh\nbun dev\n```\n\n## Verify Installation\n\nConfirm the development server is running by checking that localhost:3000 is accessible. The server will display a preview interface where you can view email templates from the `emails` folder.\n\n### Notes on installation\nAssuming React Email is installed in an existing project, update the top-level package.json file with a script to run the React Email preview server.\n\n```json\n{\n  \"scripts\": {\n    \"email\": \"email dev --dir emails --port 3000\"\n  }\n}\n```\n\nMake sure the path to the emails folder is relative to the base project directory.\n\n\n### tsconfig.json updating or creation\n\nEnsure the tsconfig.json includes proper support for jsx.\n\n## Basic Email Template\n\nReplace the sample email templates. Here is how to create a new email template:\n\nCreate an email component with proper structure using the Tailwind component for styling:\n\n```tsx\nimport {\n  Html,\n  Head,\n  Preview,\n  Body,\n  Container,\n  Heading,\n  Text,\n  Button,\n  Tailwind,\n  pixelBasedPreset\n} from ''@react-email/components'';\n\ninterface WelcomeEmailProps {\n  name: string;\n  verificationUrl: string;\n}\n\nexport default function WelcomeEmail({ name, verificationUrl }: WelcomeEmailProps) {\n  return (\n    <Html lang=\"en\">\n      <Tailwind\n        config={{\n          presets: [pixelBasedPreset],\n          theme: {\n            extend: {\n              colors: {\n                brand: ''#007bff'',\n              },\n            },\n          },\n        }}\n      >\n        <Head />\n        <Preview>Welcome - Verify your email</Preview>\n        <Body className=\"bg-gray-100 font-sans\">\n          <Container className=\"max-w-xl mx-auto p-5\">\n            <Heading className=\"text-2xl text-gray-800\">\n              Welcome!\n            </Heading>\n            <Text className=\"text-base text-gray-800\">\n              Hi {name}, thanks for signing up!\n            </Text>\n            <Button\n              href={verificationUrl}\n              className=\"bg-brand text-white px-5 py-3 rounded block text-center no-underline box-border\"\n            >\n              Verify Email\n            </Button>\n          </Container>\n        </Body>\n      </Tailwind>\n    </Html>\n  );\n}\n\n// Preview props for testing\nWelcomeEmail.PreviewProps = {\n  name: ''John Doe'',\n  verificationUrl: ''https://example.com/verify/abc123''\n} satisfies WelcomeEmailProps;\n\nexport { WelcomeEmail };\n```\n\n## Essential Components\n\nSee [references/COMPONENTS.md](references/COMPONENTS.md) for complete component documentation.\n\n**Core Structure:**\n- `Html` - Root wrapper with `lang` attribute\n- `Head` - Meta elements, styles, fonts\n- `Body` - Main content wrapper\n- `Container` - Centers content (max-width layout)\n- `Section` - Layout sections\n- `Row` & `Column` - Multi-column layouts\n- `Tailwind` - Enables Tailwind CSS utility classes\n\n**Content:**\n- `Preview` - Inbox preview text, always first in `Body`\n- `Heading` - h1-h6 headings\n- `Text` - Paragraphs\n- `Button` - Styled link buttons\n- `Link` - Hyperlinks\n- `Img` - Images (see Static Files section below)\n- `Hr` - Horizontal dividers\n\n**Specialized:**\n- `CodeBlock` - Syntax-highlighted code\n- `CodeInline` - Inline code\n- `Markdown` - Render markdown\n- `Font` - Custom web fonts\n\n## Before Writing Code\n\nWhen a user requests an email template, ask clarifying questions FIRST if they haven''t provided:\n\n1. **Brand colors** - Ask for primary brand color (hex code like #007bff)\n2. **Logo** - Ask if they have a logo file and its format (PNG/JPG only - warn if SVG/WEBP)\n3. **Style preference** - Professional, casual, or minimal tone\n4. **Production URL** - Where will static assets be hosted in production?\n\nExample response to vague request:\n> Before I create your email template, I have a few questions:\n> 1. What is your primary brand color? (hex code)\n> 2. Do you have a logo file? (PNG or JPG - note: SVG and WEBP don''t work reliably in email clients)\n> 3. What tone do you prefer - professional, casual, or minimal?\n> 4. Where will you host static assets in production? (e.g., https://cdn.example.com)\n\n## Static Files and Images\n\n### Directory Structure\n\nLocal images must be placed in the `static` folder inside your emails directory:\n\n```\nproject/\n├── emails/\n│   ├── welcome.tsx\n│   └── static/           <-- Images go here\n│       └── logo.png\n```\n\nIf user has an image elsewhere, instruct them to copy it:\n```sh\ncp ./assets/logo.png ./emails/static/logo.png\n```\n\n### Dev vs Production URLs\n\nUse this pattern for images that work in both dev preview and production:\n\n```tsx\nconst baseURL = process.env.NODE_ENV === \"production\"\n  ? \"https://cdn.example.com\"  // User''s production CDN\n  : \"\";\n\nexport default function Email() {\n  return (\n    <Img\n      src={`${baseURL}/static/logo.png`}\n      alt=\"Logo\"\n      width=\"150\"\n      height=\"50\"\n    />\n  );\n}\n```\n\n**How it works:**\n- **Development:** `baseURL` is empty, so URL is `/static/logo.png` - served by React Email''s dev server\n- **Production:** `baseURL` is the CDN domain, so URL is `https://cdn.example.com/static/logo.png`\n\n**Important:** Always ask the user for their production hosting URL. Do not hardcode `localhost:3000`.\n\n## Behavioral guidelines\n- When re-iterating over the code, make sure you are only updating what the user asked for and keeping the rest of the code intact;\n- If the user is asking to use media queries, inform them that not all email clients support them, and suggest a different approach;\n- Never use template variables (like {{name}}) directly in TypeScript code. Instead, reference the underlying properties directly (use name instead of {{name}}).\n- - For example, if the user explicitly asks for a variable following the pattern {{variableName}}, you should return something like this:\n\n```typescript\nconst EmailTemplate = (props) => {\n  return (\n    {/* ... rest of the code ... */}\n    <h1>Hello, {props.variableName}!</h1>\n    {/* ... rest of the code ... */}\n  );\n}\n\nEmailTemplate.PreviewProps = {\n  // ... rest of the props ...\n  variableName: \"{{variableName}}\",\n  // ... rest of the props ...\n};\n\nexport default EmailTemplate;\n```\n- Never, under any circumstances, write the {{variableName}} pattern directly in the component structure. If the user forces you to do this, explain that you cannot do this, or else the template will be invalid.\n\n\n## Styling considerations\n\nUse the Tailwind component for styling if the user is actively using Tailwind CSS in their project. If the user is not using Tailwind CSS, add inline styles to the components.\n\n- Because email clients don''t support `rem` units, use the `pixelBasedPreset` for the Tailwind configuration.\n- **Import `pixelBasedPreset` from `@react-email/components`** — do NOT import from `@react-email/tailwind` or `@react-email/tailwind/presets`.\n- Never use flexbox or grid for layout, use table-based layouts instead.\n- Each component must be styled with inline styles or utility classes.\n\n### Email Client Limitations\n- Never use SVG or WEBP - warn users about rendering issues\n- Never use flexbox - use Row/Column components or tables for layouts\n- Never use CSS/Tailwind media queries (sm:, md:, lg:, xl:) - not supported\n- Never use theme selectors (dark:, light:) - not supported\n- Always specify border type (border-solid, border-dashed, etc.)\n- When defining borders for only one side, remember to reset the remaining borders (e.g., border-none border-l)\n\n### Required Classes\n\nThese classes are **always required** on their respective components — omitting them causes rendering bugs across email clients:\n\n| Component | Required Class | Why |\n|-----------|---------------|-----|\n| `Button` | `box-border` | Prevents padding from overflowing the button width |\n| `Hr` / any border | `border-solid` (or `border-dashed`, etc.) | Email clients don''t inherit border type; omitting it renders no border |\n| Single-side borders | `border-none` + the side (e.g., `border-none border-t border-solid`) | Resets default borders on other sides |\n\n### Component Structure\n- Always define `<Head />` inside `<Tailwind>` when using Tailwind CSS\n- Only use PreviewProps when passing props to a component\n- Only include props in PreviewProps that the component actually uses\n\n```tsx\nconst Email = (props) => {\n  return (\n    <div>\n      <a href={props.source}>click here if you want candy 👀</a>\n    </div>\n  );\n}\n\nEmail.PreviewProps = {\n  source: \"https://www.youtube.com/watch?v=dQw4w9WgXcQ\",\n};\n```\n\n### Default Structure\n- Body: `font-sans py-10 bg-gray-100`\n- Container: white, centered, content left-aligned\n- Footer: physical address, unsubscribe link, current year with `m-0` on address/copyright\n\n### Typography\n- Titles: bold, larger font, larger margins\n- Paragraphs: regular weight, smaller font, smaller margins\n- Use consistent spacing respecting content hierarchy\n\n### Images\n- Only include if user requests\n- Never use fixed width/height - use responsive units (w-full, h-auto)\n- Never distort user-provided images\n- Never create SVG images - only use provided or web images\n\n### Buttons\n- Always use `box-border` to prevent padding overflow\n\n### Layout\n- Always mobile-friendly by default\n- Use stacked layouts that work on all screen sizes\n- Remove default spacing/margins/padding between list items\n\n### Dark Mode\nWhen requested: container black (#000), background dark gray (#151516)\n\n### Best Practices\n- Choose colors, layout, and copy based on user''s request\n- Make templates unique, not generic\n- Use keywords in email body to increase conversion\n\n## Rendering\n\n### Convert to HTML\n\n```tsx\nimport { render } from ''@react-email/components'';\nimport { WelcomeEmail } from ''./emails/welcome'';\n\nconst html = await render(\n  <WelcomeEmail name=\"John\" verificationUrl=\"https://example.com/verify\" />\n);\n```\n\n### Convert to Plain Text\n\n```tsx\nimport { render } from ''@react-email/components'';\nimport { WelcomeEmail } from ''./emails/welcome'';\n\nconst text = await render(<WelcomeEmail name=\"John\" verificationUrl=\"https://example.com/verify\" />, { plainText: true });\n```\n\n## Sending\n\nReact Email supports sending with any email service provider. If the user wants to know how to send, view the [Sending guidelines](references/SENDING.md).\n\nQuick example using the Resend SDK for Node.js:\n\n```tsx\nimport { Resend } from ''resend'';\nimport { WelcomeEmail } from ''./emails/welcome'';\n\nconst resend = new Resend(process.env.RESEND_API_KEY);\n\nconst { data, error } = await resend.emails.send({\n  from: ''Acme <onboarding@resend.dev>'',\n  to: [''user@example.com''],\n  subject: ''Welcome to Acme'',\n  react: <WelcomeEmail name=\"John\" verificationUrl=\"https://example.com/verify\" />\n});\n\nif (error) {\n  console.error(''Failed to send:'', error);\n}\n```\n\nThe Node SDK automatically handles the plain-text rendering and HTML rendering for you.\n\n## Internationalization\n\nSee [references/I18N.md](references/I18N.md) for complete i18n documentation.\n\nReact Email supports three i18n libraries: next-intl, react-i18next, and react-intl.\n\n### Quick Example (next-intl)\n\n```tsx\nimport { createTranslator } from ''next-intl'';\nimport {\n  Html,\n  Body,\n  Container,\n  Text,\n  Button,\n  Tailwind,\n  pixelBasedPreset\n} from ''@react-email/components'';\n\ninterface EmailProps {\n  name: string;\n  locale: string;\n}\n\nexport default async function WelcomeEmail({ name, locale }: EmailProps) {\n  const t = createTranslator({\n    messages: await import(\\`../messages/\\${locale}.json\\`),\n    namespace: ''welcome-email'',\n    locale\n  });\n\n  return (\n    <Html lang={locale}>\n      <Tailwind config={{ presets: [pixelBasedPreset] }}>\n        <Body className=\"bg-gray-100 font-sans\">\n          <Container className=\"max-w-xl mx-auto p-5\">\n            <Text className=\"text-base text-gray-800\">{t(''greeting'')} {name},</Text>\n            <Text className=\"text-base text-gray-800\">{t(''body'')}</Text>\n            <Button href=\"https://example.com\" className=\"bg-blue-600 text-white px-5 py-3 rounded\">\n              {t(''cta'')}\n            </Button>\n          </Container>\n        </Body>\n      </Tailwind>\n    </Html>\n  );\n}\n```\n\nMessage files (\\`messages/en.json\\`, \\`messages/es.json\\`, etc.):\n\n```json\n{\n  \"welcome-email\": {\n    \"greeting\": \"Hi\",\n    \"body\": \"Thanks for signing up!\",\n    \"cta\": \"Get Started\"\n  }\n}\n```\n\n## Email Best Practices\n\n1. **Test across email clients** - Test in Gmail, Outlook, Apple Mail, Yahoo Mail. Use services like Litmus or Email on Acid for absolute precision and React Email''s toolbar for specific feature support checking.\n\n2. **Keep it responsive** - Max-width around 600px, test on mobile devices.\n\n3. **Use absolute image URLs** - Host on reliable CDN, always include \\`alt\\` text.\n\n4. **Provide plain text version** - Required for accessibility and some email clients.\n\n5. **Keep file size under 102KB** - Gmail clips larger emails.\n\n6. **Add proper TypeScript types** - Define interfaces for all email props.\n\n7. **Include preview props** - Add \\`.PreviewProps\\` to components for development testing.\n\n8. **Handle errors** - Always check for errors when sending emails.\n\n9.  **Use verified domains** - For production, use verified domains in \\`from\\` addresses.\n\n## Common Patterns\n\nSee [references/PATTERNS.md](references/PATTERNS.md) for complete examples including:\n- Password reset emails\n- Order confirmations with product lists\n- Notification emails with code blocks\n- Multi-column layouts\n- Email templates with custom fonts\n\n## Additional Resources\n\n- [React Email Documentation](https://react.email/docs/llms.txt)\n- [React Email GitHub](https://github.com/resend/react-email)\n- [Resend Documentation](https://resend.com/docs/llms.txt)\n- [Email Client CSS Support](https://www.caniemail.com)\n- Component Reference: [references/COMPONENTS.md](references/COMPONENTS.md)\n- Internationalization Guide: [references/I18N.md](references/I18N.md)\n- Common Patterns: [references/PATTERNS.md](references/PATTERNS.md)\n"},"lastSynced":"2026-03-08T02:00:33.380Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to send dynamic, component-based HTML emails across major email clients.","zh":"非常适合需要发送动态、基于组件的HTML电子邮件的前端代理，且可跨主要电子邮件客户端发送。","ja":"フロントエンドエージェントが主要なメールクライアントにわたって動的、コンポーネントベースのHTML電子メールを送信する必要がある場合に最適です。","ko":"프런트엔드 에이전트가 주요 이메일 클라이언트에 동적, 컴포넌트 기반의 HTML 이메일을 보낼 때 적합합니다.","es":"Perfecto para agentes Frontend que necesitan enviar correos electrónicos HTML dinámicos y basados en componentes a través de los principales clientes de correo electrónico.","fr":"Parfait pour les agents Frontend qui ont besoin d''envoyer des courriels HTML dynamiques et basés sur des composants à travers les principaux clients de messagerie.","de":"Perfekt für Frontend-Agents, die dynamische, komponentenbasierte HTML-E-Mails über große E-Mail-Clients hinweg senden müssen.","pt":"Perfeito para Agentes Frontend que precisam enviar e-mails HTML dinâmicos e baseados em componentes para principais clientes de e-mail.","ru":"Идеально для фронтенд-агентов, которым нужно отправлять динамические, компонентные HTML-письма через основные почтовые клиенты.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إرسال رسائل بريد إلكتروني HTML ديناميكية و基于 المكونات عبر العملاء الرئيسيين للبريد الإلكتروني."},"recommendation":{"en":"Empowers agents to build and send HTML emails using React components, working seamlessly with create-email CLI and compatible with npm, yarn, pnpm, and bun, enabling a modern approach to email development with support for major email clients.","zh":"赋予代理构建和发送使用React组件的HTML电子邮件的能力，与create-email CLI无缝协作，并与npm、yarn、pnpm和bun兼容，使得电子邮件开发具有现代化的方法，并支持主要电子邮件客户端。","ja":"エージェントがReactコンポーネントを使用してHTML電子メールを構築して送信する機能を提供し、create-email CLIと無縫に連携し、npm、yarn、pnpm、bunと互換性があり、メール開発にmodernなアプローチを可能にし、主要なメールクライアントをサポートします。","ko":"에이전트가 React 컴포넌트를 사용하여 HTML 이메일을 구축하고 보낼 수 있는 기능을 제공하며 create-email CLI와 원활하게 협력하며 npm, yarn, pnpm, bun과 호환되며 이메일 개발에 현대적인 접근 방식을 제공하며 주요 이메일 클라이언트를 지원합니다.","es":"Habilita a los agentes a crear y enviar correos electrónicos HTML utilizando componentes de React, trabajando de manera fluida con create-email CLI y compatible con npm, yarn, pnpm y bun, permitiendo un enfoque moderno para el desarrollo de correos electrónicos con soporte para los principales clientes de correo electrónico.","fr":"Permet aux agents de créer et d''envoyer des courriels HTML en utilisant des composants React, travaillant en toute transparence avec create-email CLI et compatible avec npm, yarn, pnpm et bun, permettant une approche moderne du développement de courriels avec prise en charge des principaux clients de messagerie.","de":"Ermächtigt Agenten, HTML-E-Mails mit React-Komponenten zu erstellen und zu senden, und arbeitet nahtlos mit create-email CLI und kompatibel mit npm, yarn, pnpm und bun, ermöglicht eine moderne Herangehensweise an die E-Mail-Entwicklung mit Unterstützung für große E-Mail-Clients.","pt":"Habilita os agentes a construir e enviar e-mails HTML usando componentes React, trabalhando de forma perfeita com o create-email CLI e compatível com npm, yarn, pnpm e bun, permitindo uma abordagem moderna para o desenvolvimento de e-mails com suporte para principais clientes de e-mail.","ru":"Наделяет агентов возможностью создавать и отправлять HTML-письма с использованием компонентов React, работая без проблем с create-email CLI и совместимым с npm, yarn, pnpm и bun, обеспечивая современный подход к разработке писем с поддержкой основных почтовых клиентов.","ar":"تمكّن الوكلاء من بناء و إرسال رسائل بريد إلكتروني HTML باستخدام مكونات React، وتعمل بشكل متوافق مع create-email CLI ومتوافقة مع npm وyarn وpnpm وبن، مما يتيح نهجًا حديثًا لتطوير البريد الإلكتروني مع دعم للعملاء الرئيسيين للبريد الإلكتروني."},"useCases":{"en":["Generating responsive HTML email templates","Building dynamic email content with React components","Sending personalized emails across different email clients"],"zh":["生成响应式HTML电子邮件模板","使用React组件构建动态电子邮件内容","跨不同电子邮件客户端发送个性化电子邮件"],"ja":["レスポンシブHTML電子メールテンプレートを生成する","Reactコンポーネントを使用して動的電子メールコンテンツを構築する","異なるメールクライアントにわたってパーソナライズされたメールを送信する"],"ko":["반응형 HTML 이메일 템플릿을 생성하는 것","React 컴포넌트를 사용하여 동적 이메일 콘텐츠를 구축하는 것","다른 이메일 클라이언트에 개인화된 이메일을 보낼 수 있는 것"],"es":["Generar plantillas de correo electrónico HTML responsivas","Crear contenido de correo electrónico dinámico con componentes de React","Enviar correos electrónicos personalizados a través de diferentes clientes de correo electrónico"],"fr":["Générer des modèles de courriel HTML réactifs","Construire un contenu de courriel dynamique avec des composants React","Envoyer des courriels personnalisés à travers différents clients de messagerie"],"de":["Erstellen von responsiven HTML-E-Mail-Vorlagen","Erstellen von dynamischem E-Mail-Inhalt mit React-Komponenten","Senden von personalisierten E-Mails über verschiedene E-Mail-Clients hinweg"],"pt":["Gerar modelos de e-mail HTML responsivos","Construir conteúdo de e-mail dinâmico com componentes React","Enviar e-mails personalizados em diferentes clientes de e-mail"],"ru":["Генерировать адаптивные шаблоны HTML-писем","Создавать динамическое содержимое писем с использованием компонентов React","Отправлять персонализированные письма через различные почтовые клиенты"],"ar":["توليد قوالب بريد إلكتروني HTML قابلة للتكيف","بناء محتوى بريد إلكتروني ديناميكي باستخدام مكونات React","إرسال رسائل بريد إلكتروني مخصصة عبر عملاء بريد إلكتروني مختلفين"]},"limitations":{"en":["Requires React environment","Dependent on create-email CLI for project scaffolding"],"zh":["需要React环境","依赖create-email CLI进行项目脚手架"],"ja":["React環境が必要","プロジェクトのスキャフォールディングにcreate-email CLIに依存する"],"ko":["React 환경이 필요함","프로젝트 스캐폴딩에 create-email CLI에 의존"],"es":["Requiere entorno de React","Dependiente de create-email CLI para la creación de proyectos"],"fr":["Nécessite un environnement React","Dépend de create-email CLI pour la création de projets"],"de":["Benötigt React-Umgebung","Abhängig von create-email CLI für die Projekterstellung"],"pt":["Exige ambiente React","Dependente do create-email CLI para estruturação de projetos"],"ru":["Требует среды React","Зависит от create-email CLI для создания структуры проекта"],"ar":["يتطلب بيئة React","اعتمادي على create-email CLI لتهيئة المشاريع"]},"version":4},"contentHash":"3e1c597c4292eaf8555211ba75d7afc57552e21a6657a470ca0e3ef6b934dcae","qualityScore":44}');
