INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('resend/react-email/react-email', 'react-email', 'resend', 'react-email', 'community', 'react-email resend react-email community react-email allows developers to build and send HTML emails using React components, working across all major email clients. It provides a modern, component-based approach to email development. React Email 是一个使用 React 组件构建和发送 HTML 邮件的现代方法 React Email は、React コンポーネントを使用して HTML メールを構築して送信するためのモダンなアプローチ React Email은 React 컴포넌트를 사용하여 HTML 이메일을 구축하고 보내는 현대적인 방법 React Email es una forma moderna de desarrollar correos electrónicos utilizando componentes de React. Crea y envía correos electrónicos HTML con facilidad React Email est une approche moderne pour développer des emails à l''aide de composants React. Créez et envoyez des emails HTML facilement React Email ist eine moderne Methode, um E-Mails mit React-Komponenten zu entwickeln. Erstellen und senden Sie HTML-E-Mails einfach O react-email é uma ferramenta que permite criar e enviar emails usando componentes React. Ele oferece uma abordagem moderna e baseada em componentes para o desenvolvimento de emails. React-email - это инструмент, который позволяет создавать и отправлять электронные письма с помощью компонентов React. Он предлагает современный и компонентный подход к разработке электронной почты. react-email هو أداة تسمح بإنشاء وارسال البريد الإلكتروني باستخدام مكونات React. وهو يقدم نهجًا حديثًا ومتجزأًا لتطوير البريد الإلكتروني. how to use react-email what is react-email react-email alternative react-email vs emailjs react-email install react-email setup guide react email template create email with react react email component React Email HTML 邮件 React 组件 create-email CLI 电子邮件构建 React Email 教程 AIエージェント 电子邮件开发 Scaffolds a new React Email project using the create-email CLI Creates a folder called `react-email-starter` with sample email templates Supports installation using npm, yarn, pnpm, and bun Generates HTML emails using React components Works across all major email clients react-email is a modern, component-based approach to email development that allows building and sending HTML emails using React components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('onejs/one/railway', 'community', 'onejs', 'one', 'onejs/one', 'railway', 0, 0, 44, '2026-03-08T01:57:15.291Z', '2026-03-08T02:01:01.355Z', '0b1d143f60e544227737f86b7486e0d88424d18364bfa00083e529fc85821b7f', '{"id":"onejs/one/railway","name":"railway","description":{"en":"Railway is a React framework for targeting web and native platforms with a single Vite plugin, enabling seamless cross-platform deployment. It benefits developers seeking to ship cross-platform projects efficiently.","zh":"Railway 是一个新的 React 框架，使用 Vite 实现跨平台开发，简化您的开发流程","ja":"Railway は、Vite を使用してクロスプラットフォーム開発を実現する新しい React フレームワークです","ko":"Railway는 Vite를 사용하여 크로스 플랫폼 개발을 구현하는 새로운 React 프레임워크입니다","es":"Railway es un framework de React que permite desplegar proyectos de forma cruzada con un solo plugin de Vite y código compartido","fr":"Railway est un framework React qui permet de déployer des projets de manière croisée avec un seul plugin Vite et du code partagé","de":"Railway ist ein React-Framework, das die Bereitstellung von Projekten mit einem einzigen Vite-Plugin und geteiltem Code ermöglicht","pt":"O Railway é um framework React que permite desenvolver aplicações web e nativas com um único plugin Vite e código compartilhado.","ru":"Railway - это фреймворк React, который позволяет разрабатывать веб- и мобильные приложения с одним плагином Vite и общим кодом.","ar":"Railway هو إطار عمل React يسمح بتطوير التطبيقات الويب والأصلية مع مشغل Vite واحد ورمز مشترك."},"seo":{"title":{"en":"Railway: Cross-Platform Deployment Setup Guide | AI Agent...","zh":"Railway Setup Guide: 使用 React 和 Vite 实现跨平台开发","ja":"Railway セットアップガイド: React と Vite でクロスプラットフォーム開発を実現","ko":"Railway 설정 가이드: React와 Vite로 크로스 플랫폼 개발을 구현","es":"Guía de configuración de Railway: Despliegue de proyectos...","fr":"Guide de configuration de Railway: Déploiement de projets...","de":"Railway-Setup-Anleitung: Bereitstellung von React-Projekten","pt":"Guia de Configuração do Railway: Desenvolvimento Cross-Pl...","ru":"Настройка Railway: Руководство по созданию кроссплатформе...","ar":"دليل إعداد Railway: تطوير التطبيقات المتعددة المنصات مع R..."},"description":{"en":"Discover how to deploy and manage Railway cloud platform projects with ease. Get started with Railway CLI and unlock cross-platform capabilities today!","zh":"了解 Railway 框架，使用 React 和 Vite 实现跨平台开发，简化您的开发流程","ja":"Railway フレームワークの詳細、React と Vite を使用したクロスプラットフォーム開発の実現方法","ko":"Railway 프레임워크에 대해 알아보세요. React와 Vite를 사용하여 크로스 플랫폼 개발을 간소화하세요","es":"Aprende a configurar Railway para desplegar proyectos de React de forma cruzada con un solo plugin de Vite y código compartido","fr":"Découvrez comment configurer Railway pour déployer des projets React de manière croisée avec un seul plugin Vite et du code partagé","de":"Erfahren Sie, wie Sie Railway konfigurieren, um React-Projekte mit einem einzigen Vite-Plugin und geteiltem Code bereitzustellen","pt":"Aprenda a configurar o Railway para desenvolver aplicações web e nativas com React e Vite, e descubra como implantar projetos na nuvem","ru":"Узнайте, как настроить Railway для разработки веб- и мобильных приложений с React и Vite, и как развертывать проекты в облаке","ar":"تعلم كيفية تكوين Railway لتطوير التطبيقات الويب والأصلية مع React و Vite، واكتشف كيفية نشر المشاريع على السحابة"},"definition":{"en":"Railway is a React framework that allows developers to target web and native platforms using a single Vite plugin, enabling fully shared code and streamlined deployment.","zh":"Railway 是一个使用 Vite 实现跨平台开发的 React 框架","ja":"Railway は、Vite を使用してクロスプラットフォーム開発を実現する React フレームワーク","ko":"Railway는 Vite를 사용하여 크로스 플랫폼 개발을 구현하는 React 프레임워크","es":"Railway es un framework de React que permite desplegar proyectos de forma cruzada","fr":"Railway est un framework React qui permet de déployer des projets de manière croisée","de":"Railway ist ein React-Framework für die Bereitstellung von Projekten","pt":"O Railway é um framework de desenvolvimento cross-plataforma que utiliza React e Vite para criar aplicações web e nativas.","ru":"Railway - это кроссплатформенный фреймворк разработки, использующий React и Vite для создания веб- и мобильных приложений.","ar":"Railway هو إطار عمل متعددة المنصات للتنمية التي تستخدم React و Vite لإنشاء التطبيقات الويب والأصلية."},"features":{"en":["Deploys and manages Railway cloud platform projects via Railway CLI","Supports browser-based login and headless/SSH environments with pairing code","Utilizes Vite plugin for shared code and cross-platform deployment","Employs environment variables for CI/CD, including RAILWAY_TOKEN","Enables project token management for deploy, redeploy, and logs access"],"zh":["使用 Vite 实现跨平台开发","支持 React 和 native 应用","提供 Railway CLI 部署和管理工具","支持环境变量配置","提供项目 token 和日志功能"],"ja":["Vite を使用してクロスプラットフォーム開発を実現","React と native アプリケーションのサポート","Railway CLI デプロイと管理ツールの提供","環境変数の設定をサポート","プロジェクトトークンとログ機能の提供"],"ko":["Vite를 사용하여 크로스 플랫폼 개발을 구현","React와 네이티브 애플리케이션 지원","Railway CLI 배포 및 관리 도구 제공","환경 변수 설정 지원","프로젝트 토큰 및 로그 기능 제공"],"es":["Despliegue de proyectos de React con un solo plugin de Vite","Código compartido para proyectos web y nativos","CLI para la gestión de proyectos de Railway","Autenticación mediante navegador o entorno headless","Variables de entorno para CI/CD"],"fr":["Déploiement de projets React avec un seul plugin Vite","Code partagé pour les projets web et natifs","CLI pour la gestion de projets Railway","Authentification via navigateur ou environnement headless","Variables d''environnement pour CI/CD"],"de":["Bereitstellung von React-Projekten mit einem einzigen Vite-Plugin","Geteilter Code für Web- und Native-Projekte","CLI für die Verwaltung von Railway-Projekten","Authentifizierung über Browser oder Headless-Umgebung","Umgebungsvariablen für CI/CD"],"pt":["Desenvolvimento cross-plataforma com React","Uso de um único plugin Vite para web e nativo","Código compartilhado para reduzir a complexidade","Implantação de projetos na nuvem com o Railway CLI","Autenticação com login baseado em navegador ou sem navegador"],"ru":["Кроссплатформенная разработка с React","Использование одного плагина Vite для веб- и мобильных приложений","Общий код для снижения сложности","Развертывание проектов в облаке с помощью Railway CLI","Аутентификация с помощью браузерного или бесбраузерного входа"],"ar":["التطوير المتعدد المنصات مع React","استخدام مشغل Vite واحد للتطبيقات الويب والأصلية","رمز مشترك لتقليل التعقيد","نشر المشاريع على السحابة باستخدام Railway CLI","التحقق بｊواسطة تسجيل الدخول المعتمد على المتصفح أو بدون متصفح"]},"keywords":{"en":["how to use railway","railway alternative","railway install","what is railway","railway vs react native","railway setup guide","railway cli tutorial","cross-platform deployment with railway"],"zh":["Railway 框架","React 跨平台开发","Vite 框架","Railway CLI","环境变量配置","项目 token","日志功能","AI エージェント"],"ja":["Railway フレームワーク","React クロスプラットフォーム開発","Vite フレームワーク","Railway CLI","環境変数設定","プロジェクトトークン","ログ機能","AI エージェント"],"ko":["Railway 프레임워크","React 크로스 플랫폼 개발","Vite 프레임워크","Railway CLI","환경 변수 설정","프로젝트 토큰","로그 기능","AI 에이전트"],"es":["Railway framework","React proyectos","Vite plugin","despliegue cruzado","código compartido","CLI Railway","autenticación headless","variables de entorno CI/CD"],"fr":["Framework Railway","Projets React","Plugin Vite","déploiement croisé","code partagé","CLI Railway","authentification headless","variables d''environnement CI/CD"],"de":["Railway-Framework","React-Projekte","Vite-Plugin","Bereitstellung von Projekten","geteilter Code","Railway-CLI","Authentifizierung headless","Umgebungsvariablen CI/CD"],"pt":["Railway","React","Vite","desenvolvimento cross-plataforma","implantação de projetos na nuvem","autenticação com login","código compartilhado","plugin Vite","Railway CLI"],"ru":["Railway","React","Vite","кроссплатформенная разработка","развертывание проектов в облаке","аутентификация с входом","общий код","плагин Vite","Railway CLI"],"ar":["Railway","React","Vite","التطوير المتعدد المنصات","نشر المشاريع على السحابة","التحقق بｊواسطة تسجيل الدخول","رمز مشترك","مشغل Vite","Railway CLI"]}},"owner":"onejs","repo":"one","repoPath":"onejs/one","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.291Z","topics":[],"category":"community","skillMd":{"name":"railway","description":">-","version":"1.0.0","bodyPreview":"# Railway CLI\n\nDeploy and manage Railway cloud platform projects.\n\n## Installation\n\n```bash\nbrew install railway\n# or: npm i -g @railway/cli\n# or: bash <(curl -fsSL cli.new)\n```\n\n## Authentication\n\n```bash\nrailway login              # Browser-based login\nrailway login --browserless  # For headless/SSH environments (prints pairing code)\nrailway logout             # Disconnect from account\n```\n\n**Environment Variables for CI/CD:**\n- `RAILWAY_TOKEN` - Project token (deploy, redeploy, logs only)\n- `","body":"# Railway CLI\n\nDeploy and manage Railway cloud platform projects.\n\n## Installation\n\n```bash\nbrew install railway\n# or: npm i -g @railway/cli\n# or: bash <(curl -fsSL cli.new)\n```\n\n## Authentication\n\n```bash\nrailway login              # Browser-based login\nrailway login --browserless  # For headless/SSH environments (prints pairing code)\nrailway logout             # Disconnect from account\n```\n\n**Environment Variables for CI/CD:**\n- `RAILWAY_TOKEN` - Project token (deploy, redeploy, logs only)\n- `RAILWAY_API_TOKEN` - Account token (full access including init, link)\n\n## Project Management\n\n```bash\nrailway init               # Create new project\nrailway link               # Link current directory to existing project/environment\nrailway service            # Link to specific service in project\nrailway environment        # Switch linked environment (default: production)\n```\n\n## Deployment\n\n```bash\nrailway up                 # Deploy with build logs\nrailway up --detach        # Deploy and return immediately (no logs)\nrailway redeploy           # Redeploy current service\n```\n\n## Local Development\n\n```bash\nrailway run <cmd>          # Run command locally with Railway env vars\nrailway run npm start      # Example: start dev server with Railway vars\nrailway shell              # Open shell with Railway environment loaded\n```\n\n## Logs & Debugging\n\n```bash\nrailway logs               # View service logs\nrailway ssh                # SSH into running service\nrailway ssh -- ls          # Execute single command via SSH\n```\n\n**SSH with specific target:**\n```bash\nrailway ssh --project=<ID> --environment=<ID> --service=<ID>\n```\n\n## Database & Services\n\n```bash\nrailway add                # Provision database (Postgres, MySQL, Redis, MongoDB)\n```\n\n## Common Workflows\n\n### Deploy a new project\n```bash\nrailway login\nrailway init\nrailway up\n```\n\n### Link existing project and deploy\n```bash\nrailway login\nrailway link\nrailway up\n```\n\n### Run local dev with production database\n```bash\nrailway link\nrailway run npm run dev\n```\n\n### View logs for debugging\n```bash\nrailway logs\n# or SSH in for interactive debugging\nrailway ssh\n```\n\n## User Invocation\n\n- `/railway` - Show status and common commands\n- `/railway deploy` - Deploy current directory\n- `/railway logs` - View service logs\n- `/railway ssh` - Connect to service\n\n## Agent Response Protocol\n\n**For `/railway` or `/railway status`:**\n1. Check if logged in: `railway whoami`\n2. Check linked project: `railway status`\n3. Report current state and suggest next actions\n\n**For `/railway deploy`:**\n1. Verify logged in and linked\n2. Run `railway up` and report results\n3. On failure, suggest fixes\n\n**For `/railway logs`:**\n1. Run `railway logs` (add `--help` to see filtering options)\n2. Summarize recent activity\n\n**For `/railway ssh`:**\n1. Run `railway ssh` for interactive session\n2. Or `railway ssh -- <command>` for one-off commands\n"},"lastSynced":"2026-03-08T02:01:01.355Z","agentAnalysis":{"suitability":{"en":"Ideal for Cross-Platform Agents seeking efficient deployment and management of web and native projects using React and Vite.","zh":"适用于寻求使用 React 和 Vite 进行 Web 和原生项目高效部署和管理的跨平台代理。","ja":"React と Vite を使用した Web とネイティブ プロジェクトの効率的なデプロイと管理を求めるクロスプラットフォーム エージェントに最適です。","ko":"React와 Vite를 사용하여 웹 및 네이티브 프로젝트를 효율적으로 배포 및 관리하려는 크로스 플랫폼 에이전트에 적합합니다.","es":"Ideal para agentes de plataforma cruzada que buscan una implementación y gestión eficientes de proyectos web y nativos utilizando React y Vite.","fr":"Idéal pour les agents de plateforme croisée qui recherchent un déploiement et une gestion efficaces de projets web et natifs utilisant React et Vite.","de":"Ideal für Cross-Platform-Agents, die eine effiziente Bereitstellung und Verwaltung von Web- und Native-Projekten mit React und Vite suchen.","pt":"Ideal para Agentes de Plataforma Cruzada que buscam implantação e gerenciamento eficientes de projetos web e nativos usando React e Vite.","ru":"Идеально подходит для агентов с поддержкой нескольких платформ, которые обеспечивают эффективное развертывание и управление веб- и родными проектами с использованием React и Vite.","ar":"مثالي لعميل متعدد المنصات يسعى إلى نشر وإدارة مشاريع الويب والأصلية بكفاءة باستخدام React و Vite."},"recommendation":{"en":"Empowers agents to seamlessly deploy and manage projects on the Railway cloud platform using the Railway CLI, leveraging environment variables like RAILWAY_TOKEN for CI/CD pipelines and protocols such as browser-based login and headless/SSH authentication.","zh":"赋予代理在 Railway 云平台上使用 Railway CLI 无缝地部署和管理项目的能力，利用环境变量如 RAILWAY_TOKEN 进行 CI/CD 流水线和协议，如基于浏览器的登录和无头/SSH 身份验证。","ja":"Railway CLI を使用して Railway クラウド プラットフォーム上でプロジェクトをシームレスにデプロイおよび管理できるようにエージェントをEmpowerし、RAILWAY_TOKEN などの環境変数を使用して CI/CD パイプラインおよびブラウザーベースのログインやヘッドレス/SSH 認証などのプロトコルを利用します。","ko":"Railway CLI를 사용하여 Railway 클라우드 플랫폼에서 프로젝트를無혐結으로 배포 및 관리할 수 있는 에이전트를 강화하여 RAILWAY_TOKEN와 같은 환경 변수를 사용하여 CI/CD 파이프라인 및 브라우저 기반 로그인 및 헤드리스/SSH 인증과 같은 프로토콜을 활용합니다.","es":"Permite a los agentes implementar y gestionar proyectos de manera transparente en la plataforma de Railway en la nube utilizando el Railway CLI, aprovechando variables de entorno como RAILWAY_TOKEN para tuberías de CI/CD y protocolos como el inicio de sesión basado en navegador y la autenticación headless/SSH.","fr":"Permet aux agents de déployer et de gérer des projets de manière transparente sur la plateforme Railway en ligne utilisant le Railway CLI, en exploitant des variables d''environnement comme RAILWAY_TOKEN pour les pipelines de CI/CD et des protocoles tels que la connexion basée sur navigateur et l''authentification headless/SSH.","de":"Ermöglicht es Agenten, Projekte nahtlos auf der Railway-Cloud-Plattform bereitzustellen und zu verwalten, indem sie den Railway CLI verwenden und Umgebungsvariablen wie RAILWAY_TOKEN für CI/CD-Pipelines und Protokolle wie browserbasierte Anmeldung und headless/SSH-Authentifizierung nutzen.","pt":"Habilita os agentes a implantar e gerenciar projetos na plataforma de nuvem Railway de forma transparente, usando o Railway CLI, aproveitando variáveis de ambiente como RAILWAY_TOKEN para pipelines de CI/CD e protocolos como login baseado em navegador e autenticação headless/SSH.","ru":"Наделяет агентов возможностью бесшовного развертывания и управления проектами на облачной платформе Railway, используя Railway CLI, используя переменные окружения, такие как RAILWAY_TOKEN для конвейеров CI/CD и протоколов, таких как вход в систему на основе браузера и аутентификация headless/SSH.","ar":"يمكّن الوكلاء من نشر وإدارة المشاريع على منصة سكة حديد السحابية بسهولة، باستخدام واجهة سكة حديد الخطوة، واستخدام متغيرات البيئة مثل RAILWAY_TOKEN لأنابيب CI/CD وبروتوكولات مثل تسجيل الدخول المبني على المتصفح والتحقق من الهوية الخفيّة / SSH."},"useCases":{"en":["Deploying cross-platform React projects","Managing Railway cloud platform projects via CLI","Authenticating with Railway using browser-based or headless/SSH methods"],"zh":["部署跨平台 React 项目","通过 CLI 管理 Railway 云平台项目","使用基于浏览器或无头/SSH 方法进行 Railway 身份验证"],"ja":["クロスプラットフォーム React プロジェクトのデプロイ","Railway クラウド プラットフォーム プロジェクトの CLI による管理","ブラウザーベースまたはヘッドレス/SSH メソッドを使用した Railway の認証"],"ko":["크로스 플랫폼 React 프로젝트 배포","Railway 클라우드 플랫폼 프로젝트의 CLI를 통한 관리","브라우저 기반 또는 헤드리스/SSH 방법을 사용한 Railway 인증"],"es":["Implementación de proyectos React de plataforma cruzada","Gestión de proyectos de la plataforma de Railway en la nube a través de CLI","Autenticación con Railway mediante métodos basados en navegador o headless/SSH"],"fr":["Déploiement de projets React de plateforme croisée","Gestion de projets de la plateforme Railway en ligne via CLI","Authentification avec Railway à l''aide de méthodes basées sur navigateur ou headless/SSH"],"de":["Bereitstellung von Cross-Platform-React-Projekten","Verwaltung von Railway-Cloud-Plattform-Projekten über CLI","Authentifizierung mit Railway mithilfe von browserbasierten oder headless/SSH-Methoden"],"pt":["Implantação de projetos React de plataforma cruzada","Gerenciamento de projetos da plataforma de nuvem Railway via CLI","Autenticação com Railway usando métodos baseados em navegador ou headless/SSH"],"ru":["Развертывание кроссплатформенных проектов React","Управление проектами облачной платформы Railway через CLI","Аутентификация с Railway с помощью методов на основе браузера или headless/SSH"],"ar":["نشر مشاريع React متعددة المنصات","إدارة مشاريع منصة سكة حديد السحابية عبر واجهة سكة حديد الخطوة","التحقق من الهوية مع سكة حديد باستخدام طرق متصفح أو خفية / SSH"]},"limitations":{"en":["Requires Railway account and project token","Dependent on Vite plugin for cross-platform functionality"],"zh":["需要 Railway 账户和项目令牌","依赖 Vite 插件进行跨平台功能"],"ja":["Railway アカウントとプロジェクト トークンが必要","クロスプラットフォーム機能のために Vite プラグインに依存"],"ko":["Railway 계정 및 프로젝트 토큰이 필요","크로스 플랫폼 기능을 위해 Vite 플러그인에 의존"],"es":["Requiere una cuenta de Railway y un token de proyecto","Depende del plugin de Vite para la funcionalidad de plataforma cruzada"],"fr":["Nécessite un compte Railway et un jeton de projet","Dépend du plugin Vite pour la fonctionnalité de plateforme croisée"],"de":["Benötigt ein Railway-Konto und ein Projekttoken","Hängt vom Vite-Plugin für die Cross-Platform-Funktionalität ab"],"pt":["Exige conta Railway e token de projeto","Dependente do plug-in Vite para funcionalidade de plataforma cruzada"],"ru":["Требует учетной записи Railway и токена проекта","Зависит от плагина Vite для функциональности нескольких платформ"],"ar":["يتطلب حساب سكة حديد وتوكن مشروع","يعتمد على مكون إضافي Vite للوظائف متعددة المنصات"]},"version":4},"contentHash":"0b1d143f60e544227737f86b7486e0d88424d18364bfa00083e529fc85821b7f","qualityScore":44}');
