INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('onejs/one/railway', 'railway', 'onejs', 'one', 'community', 'railway onejs one community Railway is a React framework for targeting web and native platforms with a single Vite plugin, enabling seamless cross-platform deployment. It benefits developers seeking to ship cross-platform projects efficiently. Railway 是一个新的 React 框架，使用 Vite 实现跨平台开发，简化您的开发流程 Railway は、Vite を使用してクロスプラットフォーム開発を実現する新しい React フレームワークです Railway는 Vite를 사용하여 크로스 플랫폼 개발을 구현하는 새로운 React 프레임워크입니다 Railway es un framework de React que permite desplegar proyectos de forma cruzada con un solo plugin de Vite y código compartido Railway est un framework React qui permet de déployer des projets de manière croisée avec un seul plugin Vite et du code partagé Railway ist ein React-Framework, das die Bereitstellung von Projekten mit einem einzigen Vite-Plugin und geteiltem Code ermöglicht O Railway é um framework React que permite desenvolver aplicações web e nativas com um único plugin Vite e código compartilhado. Railway - это фреймворк React, который позволяет разрабатывать веб- и мобильные приложения с одним плагином Vite и общим кодом. Railway هو إطار عمل React يسمح بتطوير التطبيقات الويب والأصلية مع مشغل Vite واحد ورمز مشترك. how to use railway railway alternative railway install what is railway railway vs react native railway setup guide railway cli tutorial cross-platform deployment with railway Railway 框架 React 跨平台开发 Vite 框架 Railway CLI 环境变量配置 项目 token 日志功能 AI エージェント Deploys and manages Railway cloud platform projects via Railway CLI Supports browser-based login and headless/SSH environments with pairing code Utilizes Vite plugin for shared code and cross-platform deployment Employs environment variables for CI/CD, including RAILWAY_TOKEN Enables project token management for deploy, redeploy, and logs access Railway is a React framework that allows developers to target web and native platforms using a single Vite plugin, enabling fully shared code and streamlined deployment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AbdullahMalik17/Digital-FTE/project-designer', 'community', 'AbdullahMalik17', 'Digital-FTE', 'AbdullahMalik17/Digital-FTE', 'project-designer', 0, 0, 44, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:24.571Z', 'be9afe077fb8de8e86bf0353270766ce89e79dc6af018df8236f47f7e29b8d5b', '{"id":"AbdullahMalik17/Digital-FTE/project-designer","name":"project-designer","description":{"en":"The project-designer skill guides developers through structured ideation, architectural decision-making, and strategic planning for AI/ML agents, web applications, and mobile projects. It benefits developers and project managers seeking to create comprehensive project designs.","zh":"Project Designer 通过系统分析、特性增强和技术推荐，帮助您将初步项目概念转化为全面、精良的设计","ja":"Project Designer は、構造化設計と戦略的計画で AIエージェントと Web アプリケーションを開発するためのガイドを提供します","ko":"Project Designer는 체계적인 아이디어 생성, 아키텍처 결정 및 전략적 계획을 통해 AI 프로젝트를 설계하는 데 도움을 줍니다","es":"El diseñador de proyectos es una habilidad que te guía a través de la ideación estructurada, la toma de decisiones arquitectónicas y la planificación estratégica para proyectos de AI/ML, aplicaciones web y móviles","fr":"Le concepteur de projets est une compétence qui vous guide à travers l''idéation structurée, la prise de décision architecturale et la planification stratégique pour les projets d''IA/ML, les applications web et mobiles","de":"Der Projekt-Designer ist eine Fähigkeit, die Sie durch die strukturierte Ideenfindung, die architektonische Entscheidungsfindung und die strategische Planung für KI/ML-Projekte, Webanwendungen und Mobile-Projekte führt","pt":"O Project Designer é uma habilidade que transforma conceitos iniciais de projeto em designs abrangentes através de análise sistemática e recomendações de tecnologia","ru":"Project Designer - это навык, который превращает первоначальные концепции проекта в комплексные диза