INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fulviomanente/IQRight_Local/error-report', 'error-report', 'fulviomanente', 'IQRight_Local', 'community', 'error-report fulviomanente IQRight_Local community The error-report skill analyzes ERROR messages in IQRight server logs, providing insights for developers to debug and improve their code. It benefits developers working with RaspberryServer and RaspberryScanner. 错误报告技能用于分析RaspberryServer和RaspberryScanner中的ERROR消息，帮助开发者优化代码 エラーレポートスキルは、RaspberryServerとRaspberryScannerのERRORメッセージを分析し、開発者がコードを最適化するのに役立ちます 오류 보고 기능은 RaspberryServer와 RaspberryScanner의 ERROR 메시지를 분석하여 개발자가 코드를 최적화하는 데 도움이 됩니다 El informe de errores analiza todos los mensajes de error en los registros del servidor IQRight, cuenta el número total de errores y los categoriza por tipo Le rapport d''erreurs analyse tous les messages d''erreur dans les journaux du serveur IQRight, comptabilise le nombre total d''erreurs et les catégorise par type Der Fehlerbericht analysiert alle Fehlermeldungen in den Server-Logs von IQRight, zählt die Gesamtzahl der Fehler und kategorisiert sie nach Typ O error-report é uma ferramenta para análise de logs de erro no RaspberryServer e RaspberryScanner, permitindo a contagem e categorização de erros Error-report - это инструмент для анализа журналов ошибок в RaspberryServer и RaspberryScanner, позволяющий подсчитывать и категоризировать ошибки с помощью ИИ Агентов تقرير الأخطاء error-report هو أداة لتحليل سجلات الأخطاء في RaspberryServer وRaspberryScanner، مما يسمح بتحليل الأخطاء وتقاريرها error-report setup guide how to use error-report error-report alternative error-report vs log analysis tools error-report install what is error-report error-report for RaspberryServer error-report for RaspberryScanner error-report error analysis error-report debugging workflow 错误报告 RaspberryServer RaspberryScanner ERROR消息 代码优化 LoRa错误 日志分析 错误分类 Counts total ERROR lines in logs/IQRight_Daemon.debug and rotated logs Categorizes ERROR lines by message pattern, including LoRa Errors Identifies specific error types, such as ''Error in sendDataScanner'' and ''Failed to send response to scanner'' Groups errors by known categories, including ''LoRaTransceiver'' object attribute errors Analyzes logs to detect method name bugs, such as ''create_packet'' vs ''create_data_packet'' Supports error analysis for RaspberryServer and RaspberryScanner code error-report is a skill that analyzes ERROR messages in IQRight server logs, categorizing errors by type and providing error counts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('netz98/n98-magerun2/magerun-release', 'community', 'netz98', 'n98-magerun2', 'netz98/n98-magerun2', 'magerun-release', 0, 0, 44, '2026-03-08T01:57:15.323Z', '2026-03-08T02:02:59.770Z', '8b0fdde0cb88fdf414332d1201db39e64fb8c939b77205fe0340c4a1c2b7a358', '{"id":"netz98/n98-magerun2/magerun-release","name":"magerun-release","description":{"en":"This AI agent skill executes the technical release process for the n98-magerun2 command-line tool. It is designed for Magento developers and DevOps engineers responsible for maintaining and releasing new versions of the Swiss Army knife for Magento.","zh":"magerun-release是Magento开发、运维和DevOps的瑞士军刀，提供一系列经过测试的命令行命令，节省工作时间","ja":"magerun-releaseはMagento開発、運用、DevOpsのための多機能ツールで、テスト済みのコマンドラインコマンドを提供する","ko":"magerun-release는 Magento 개발, 운영, DevOps를 위한 멀티 툴로 테스트된 명령행 명령을 제공하여 작업 시간을 절약합니다","es":"magerun-release es una herramienta de línea de comandos para desarrolladores de Magento que proporciona un conjunto de comandos para ahorrar tiempo y mejorar la eficiencia","fr":"magerun-release est un outil de ligne de commande pour les développeurs Magento qui propose un ensemble de commandes pour gagner du temps et améliorer l''efficacité","de":"magerun-release ist ein Kommandozeilen-Tool für Magento-Entwickler, das eine Reihe von Befehlen zur Zeitersparnis und Effizienzsteigerung bietet","pt":"O magerun-release é uma ferramenta essencial para desenvolvedores Magento, fornecendo comandos de linha de comando personalizáveis e extensíveis para otimizar o workflow.","ru":"Magerun-release - это важнейший инструмент для разработчиков Magento, предоставляющий настраиваемые и расширяемые команды строкой для оптимизации рабочего процесса.","ar":"ماجيرن-ريليز هو أداة أساسية للمطورين ماجنتو، يوفر أوامر سطر الأوامر القابلة للتعديل والتوسعة لتحسين تدفق العمل."},"seo":{"title":{"en":"magerun-rel