INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('netz98/n98-magerun2/magerun-release', 'magerun-release', 'netz98', 'n98-magerun2', 'community', 'magerun-release netz98 n98-magerun2 community This AI agent skill executes the technical release process for the n98-magerun2 command-line tool. It is designed for Magento developers and DevOps engineers responsible for maintaining and releasing new versions of the Swiss Army knife for Magento. magerun-release是Magento开发、运维和DevOps的瑞士军刀，提供一系列经过测试的命令行命令，节省工作时间 magerun-releaseはMagento開発、運用、DevOpsのための多機能ツールで、テスト済みのコマンドラインコマンドを提供する magerun-release는 Magento 개발, 운영, DevOps를 위한 멀티 툴로 테스트된 명령행 명령을 제공하여 작업 시간을 절약합니다 magerun-release es una herramienta de línea de comandos para desarrolladores de Magento que proporciona un conjunto de comandos para ahorrar tiempo y mejorar la eficiencia magerun-release est un outil de ligne de commande pour les développeurs Magento qui propose un ensemble de commandes pour gagner du temps et améliorer l''efficacité magerun-release ist ein Kommandozeilen-Tool für Magento-Entwickler, das eine Reihe von Befehlen zur Zeitersparnis und Effizienzsteigerung bietet O magerun-release é uma ferramenta essencial para desenvolvedores Magento, fornecendo comandos de linha de comando personalizáveis e extensíveis para otimizar o workflow. Magerun-release - это важнейший инструмент для разработчиков Magento, предоставляющий настраиваемые и расширяемые команды строкой для оптимизации рабочего процесса. ماجيرن-ريليز هو أداة أساسية للمطورين ماجنتو، يوفر أوامر سطر الأوامر القابلة للتعديل والتوسعة لتحسين تدفق العمل. how to use magerun-release what is magerun-release magerun-release vs manual release magerun-release alternative magerun-release install n98-magerun2 release process automate magento 2 tool release magento 2 cli tool versioning magerun-release Magento开发 Magento运维 DevOps 命令行工具 语义版本控制 Git版本管理 模块API Analyzes git history using `git log $(git describe --tags --abbrev=0)..HEAD --oneline` to identify changes Determines the next version number by following semantic versioning (SemVer) principles Updates the version constant within the `\N98\Magento\Application` PHP class Provides structured instructions for releasing a new version of n98-magerun2 magerun-release is an AI agent skill that manages the technical release cycle for the n98-magerun2 Magento developer tool. It automates key steps like investigating git commit logs since the last tag, determining the next semantic version number, and updating the core application version constant.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cartridge-gg/controller/codegen', 'community', 'cartridge-gg', 'controller', 'cartridge-gg/controller', 'codegen', 0, 0, 44, '2026-03-08T01:57:15.324Z', '2026-03-08T02:03:00.218Z', '0df21ed58b1f0fce55915e9b80e852a978ef39c5a62ae720c7b94a75a3c65dd8', '{"id":"cartridge-gg/controller/codegen","name":"codegen","description":{"en":"The codegen skill regenerates GraphQL types from API schema, ensuring type safety and streamlining development workflow for developers working with on-chain games and GraphQL APIs.","zh":"CodeGen 是一种用于无缝玩耍链上游戏的自托管嵌入式账户。它可以通过GraphQL代码生成来设置和使用","ja":"CodeGenは、オンチェーンゲームを無制限にプレイするための自己顧客管理埋め込みアカウントです。GraphQLコード生成を使用して設定と使用が可能です","ko":"CodeGen은 온체인 게임을 원활하게 즐길 수 있는 자체 관리 임베디드 계정입니다. GraphQL 코드 생성을 통해 설정 및 사용이 가능합니다","es":"Codegen es un skill que permite regenerar tipos GraphQL desde el esquema de API para juegos en cadena. Ayuda a mantener la integridad de los tipos y a prevenir errores.","fr":"Codegen est un skill qui permet de régénérer les types GraphQL à partir du schéma d''API pour les jeux sur chaîne. Il aide à maintenir l''intégrité des types et à prévenir les erreurs.","de":"Codegen ist ein Skill, der die Regenerierung von GraphQL-Typen aus dem API-Schema für On-Chain-Spiele ermöglicht. Er hilft, die Integrität der Typen zu erhalten und Fehler zu vermeiden.","pt":"O codegen é uma ferramenta para regenerar tipos GraphQL de esquemas de API, melhorando a experiência de desenvolvimento com tipos precisos","ru":"Codegen - это инструмент для регенерации типов GraphQL из схем API, улучшающий опыт разработки с точными типами и ИИ Агентами","ar":"كودجين هو أداة لإعادة إنشاء أنواع جرافول من مخططات واجهة برمجة التطبيقات، مما يحسن من تجربة التطوير مع أنواع دقيقة"},"seo":{"title":{"en":"codegen: GraphQL Regeneration Setup Guide | AI Agent Skill","zh":"CodeGen_SETUP GUIDE：自托管嵌入式账户用于链上游戏","ja":"CodeGen_Setupガイド：オンチェーンゲーム用の自己顧客管理埋め込みアカウント","ko":"CodeGenセットアップ 가이드: 온체인 게임을 위한 자체 관리 임베디드 계정","es":"Guía de configuración de Codegen para juegos en cadena","fr":"Guide de configuration de Codegen pour les jeux sur chaîne","de":"Codegen-Setup-Leitfaden für On-Chain-Spiele","pt":"Guia de Configuração do Codegen para Desenvolvedores","ru":"Настройка Codegen: ИИ Агенты для Разработчиков","ar":"دليل إعداد كودجين للمطورين"},"description":{"en":"Discover how to regenerate GraphQL types with codegen. Learn how to setup and use this skill to streamline your development workflow and ensure type safety","zh":"CodeGen 是一种自托管嵌入式账户，用于无缝玩耍链上游戏。了解CodeGen的设置和使用方法，提高开发效率","ja":"CodeGenは、オンチェーンゲームを無制限にプレイするための自己顧客管理埋め込みアカウントです。セットアップ方法と使用方法を学び、開発効率を向上させましょう","ko":"CodeGen은 온체인 게임을 원활하게 즐길 수 있는 자체 관리 임베디드 계정입니다. 설정 방법과 사용 방법을 알아보고 개발 효율을 높여보세요","es":"Aprende a configurar Codegen para regenerar tipos GraphQL desde el esquema de API y mejorar tus juegos en cadena","fr":"Découvrez comment configurer Codegen pour régénérer les types GraphQL à partir du schéma d''API et améliorer vos jeux sur chaîne","de":"Erfahren Sie, wie Sie Codegen konfigurieren, um GraphQL-Typen aus dem API-Schema neu zu generieren und Ihre On-Chain-Spiele zu verbessern","pt":"Aprenda a configurar o codegen para regenerar tipos GraphQL de esquemas de API e melhorar a experiência de desenvolvimento","ru":"Узнайте, как настроить codegen для регенерации типов GraphQL из схем API и улучшить опыт разработки с ИИ Агентами","ar":"تعرف على كيفية إعداد كودجين لإعادة إنشاء أنواع جرافول من مخططات واجهة برمجة التطبيقات وتحسين تجربة التطوير"},"definition":{"en":"codegen is a skill that regenerates GraphQL types from API schema, enabling seamless integration with on-chain games and ensuring type safety","zh":"CodeGen是一种GraphQL代码生成工具，用于生成API类型和验证","ja":"CodeGenはGraphQLコード生成ツールであり、APIタイプの生成と検証に使用されます","ko":"CodeGen은 API 유형 생성 및 검증을 위한 GraphQL 코드 생성 도구입니다","es":"Codegen es un skill que regenera tipos GraphQL desde el esquema de API pa