INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pelith/Project-Remora-Frontend/viem', 'viem', 'pelith', 'Project-Remora-Frontend', 'community', 'viem pelith Project-Remora-Frontend community Viem is a modern TypeScript interface for Ethereum, ensuring correct patterns for contract interactions and client setup. It benefits developers working with Ethereum smart contracts. Viem是现代以太坊TypeScript接口，确保合约交互、客户端设置和类型安全的正确模式 Viemは現代のEthereum TypeScriptインターフェースであり、コントラクトの相互作用、クライアントの設定、タイプセーフティの正しいパターンを保証する Viem은 현대적인 이더리움 TypeScript 인터페이스로, 계약 상호 작용, 클라이언트 설정 및 유형 안전성의 올바른 패턴을 보장합니다 Viem es una interfaz de TypeScript para Ethereum que garantiza patrones correctos para la interacción con contratos y la configuración del cliente Viem est une interface TypeScript pour Ethereum qui assure des modèles corrects pour l''interaction avec les contrats et la configuration du client Viem ist eine TypeScript-Schnittstelle für Ethereum, die korrekte Muster für die Interaktion mit Verträgen und die Client-Konfiguration gewährleistet O Viem é uma interface moderna em TypeScript para Ethereum, garantindo padrões corretos para interações de contrato, setup de cliente e segurança de tipo. Viem - это современный TypeScript-интерфейс для Ethereum, обеспечивающий правильные шаблоны для взаимодействия с контрактами, настройки клиента и типовой безопасности. Viem هو واجهة حديثة مبنية على TypeScript لأثيريوم، يضمن أنماطا صحيحة لتفاعل العقد والعميل وأمان النوع. how to use viem viem ethereum client viem vs web3.js viem install guide viem setup tutorial what is viem viem alternative viem type safety viem contract interactions Viem 以太坊 TypeScript 合约交互 客户端设置 类型安全 AIエージェント 区块链开发 Imports Ethereum clients via `createPublicClient` and `createWalletClient` Supports HTTP requests using `http` from ''viem'' Utilizes `mainnet` from ''viem/chains'' for chain configuration Enables account management with `privateKeyToAccount` from ''viem/accounts'' Ensures type safety for contract interactions Provides a quick reference guide for common use cases Viem is a TypeScript interface for Ethereum, providing a modern approach to client setup, contract interactions, and type safety.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agude/agude.github.io/copyedit', 'community', 'agude', 'agude.github.io', 'agude/agude.github.io', 'copyedit', 0, 0, 44, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:33.294Z', '116a4e46c699c7424195a8106c4500e9c509fdc37d51a0721d9663606f7dc975', '{"id":"agude/agude.github.io/copyedit","name":"copyedit","description":{"en":"The copyedit skill edits drafts for alexgude.com, preserving voice and style. It offers grammar and polish modes for tailored editing solutions.","zh":"copyedit是一种代码编辑工具，提供语法和润色模式，帮助开发者提高代码质量","ja":"copyeditは、AIエージェントを利用した文法とポリッシュモードを備えたコード編集ツールです","ko":"copyedit는 문법 및 다듬기 모드를 제공하는 코드 편집 도구로 개발자에게 코드 품질을 높이는 데 도움을 줍니다","es":"Copyedit es una habilidad que edita borradores para alexgude.com mientras mantiene la voz y el estilo. Ofrece dos modos: grammar y polish","fr":"Copyedit est une compétence qui édite les brouillons pour alexgude.com tout en préservant la voix et le style. Elle propose deux modes : grammar et polish","de":"Copyedit ist eine Fähigkeit, die Entwürfe für alexgude.com bearbeitet und Stil und Stimme beibehält. Sie bietet zwei Modi: grammar und polish","pt":"O copyedit é uma habilidade que edita rascunhos para alexgude.com, preservando a voz e o estilo do autor. Ele oferece dois modos: grammar e polish","ru":"Copyedit - это навык, который редактирует черновики для alexgude.com, сохраняя голос и стиль автора. Он предлагает два режима: grammar и polish","ar":"أداة Copyedit هي مهارة تعمل على تحرير المسودات لموقع alexgude.com مع الحفاظ على صوت وأسلوب الكاتب. وهي توفر وضعين: تحرير النحو وتحسين الأسلوب"},"seo":{"title":{"en":"Copyedit: AI-Powered Editing for alexgude.com | AI Agent ...","zh":"copyedit 技术设置指南：语法和润色模式","ja":"copyedit AIエージェントのベストプラクティス：文法とポリッシュモード","ko":"copyedit 개발자 가이드: 문법 및 다듬기 모드","es":"Guía de configuración de copyedit para editores de sitios...","fr":"Configurer copyedit pour améliorer la qualité de votre co...","de":"Copyedit-Setup-Anleitung für Entwickler und Redakteure","pt":"Guia de Configuração do Copyedit para Desenvolvedores","ru":"Настройка ИИ Агента Copyedit: Руководство для Разработчиков","ar":"دليل إعداد أداة Copyedit الإلكترونية للاستخدام مع مواقع ا..."},"description":{"en":"Discover how to refine your drafts with the copyedit skill. Learn to fix grammar, polish content, and preserve voice with AI-driven editing solutions. Get st...","zh":"了解copyedit的技术细节，包括语法和润色模式，提高代码质量和开发效率","ja":"copyedit AIエージェントの機能と使い方を紹介します。文法とポリッシュモードの違いを理解して、開発の生産性を上げましょう","ko":"copyedit의 문법 및 다듬기 모드를 사용하여 개발 효율성을 높이고 코드 품질을 개선하는 방법을 알아보세요","es":"Aprende a utilizar copyedit para mejorar la calidad de tus textos en alexgude.com. Descubre cómo corregir errores y mejorar la claridad","fr":"Découvrez comment utiliser copyedit pour améliorer la qualité de vos contenus. Corrigez les erreurs et améliorez la clarté de vos textes","de":"Erfahren Sie, wie Sie copyedit verwenden, um die Qualität Ihrer Texte zu verbessern. Korrigieren Sie Fehler und verbessern Sie die Klarheit","pt":"Aprenda a utilizar o copyedit para melhorar a clareza e coerência do conteúdo do seu site, preservando o estilo e a voz do autor","ru":"Узнайте, как использовать ИИ Агент Copyedit для улучшения ясности и связности контента вашего сайта, сохраняя стиль и голос автора","ar":"تعلم كيفية استخدام أداة Copyedit لتحسين وضوح ومواءمة المحتوى على موقعك الإلكتروني مع الحفاظ على الأسلوب وصوت الكاتب"},"definition":{"en":"copyedit is a skill that edits content while preserving the original voice and style, offering modes for grammar and polish editing.","zh":"copyedit是一种代码编辑工具，用于检查和改进代码的语法和风格","ja":"copyeditとは、コードの文法とスタイルをチェックし改善するAIエージェントツールのこと","ko":"copyedit는 코드의 문법과 스타일을 확인하고 개선하는 코드 편집 도구입니다","es":"Copyedit es una herramienta de edición de textos que corrige errores y mejora la claridad mientras mantiene la voz y el estilo","fr":"Copyedit est un outil d''édition de texte qui corrige les erreurs et améliore la clarté tout en préservant la voix et le style","de":"Copyedit ist ein Textbearbeitungstool, das Fehler korrigiert und die Klarheit verbessert, während es Stil und Stimme beibehält","pt":"Copyedit é uma ferramenta de edição de texto que melhora a clareza e coerência do conteúdo","ru":"Copyedit - это инструмент редактирования текста, который улучшает ясность и связность контента","ar":"أداة Copyedit هي أداة تحرير النص التي تحسن وضوح ومواءمة المحتوى"},"features":{"en":["Fixes spelling, grammar, and punctuation errors via `/copyedit grammar` command","Improves clarity and coherence with `/copyedit polish` command","Preserves original voice and style in edited content","Supports two editing modes: grammar and polish","Asks for mode specification if none is provided"],"zh":["语法模式：检查拼写、语法和标点错误","润色模式：改进代码清晰度和连贯性","保留代码风格和语气","支持命令行接口（CLI）","提高代码质量和开发效率"],"ja":["文法モード：スペル、文法、句読点のエラーをチェック","ポリッシュモード：コードの明確性と一貫性を向上","コードのスタイルとトーンを保持","コマンドラインインターフェース（CLI）をサポート","コード品質と開発生産性を向上"],"ko":["문법 모드:拼写、문법 및 구두점 오류를 확인","다듬기 모드: 코드의 명확성과 일관성을 개선","코드 스타일과 톤을 유지","명령줄 인터페이스（CLI）를 지원","코드 품질과 개발 효율성을 높임"],"es":["Modo grammar para corregir errores de ortografía y gramática","Modo polish para mejorar la claridad y la coherencia","Preservación de la voz y el estilo en ambos modos","Uso de comandos CLI para ejecutar copyedit","Compatibilidad con alexgude.com","Edición de textos en tiempo real"],"fr":["Mode grammar pour corriger les erreurs d''orthographe et de grammaire","Mode polish pour améliorer la clarté et la cohérence","Préservation de la voix et du style dans les deux modes","Utilisation de commandes CLI pour exécuter copyedit","Compatibilité avec alexgude.com","Édition de textes en temps réel"],"de":["Grammar-Modus zur Korrektur von Rechtschreib- und Grammatikfehlern","Polish-Modus zur Verbesserung der Klarheit und Kohärenz","Beibehaltung von Stil und Stimme in beiden Modi","Verwendung von CLI-Befehlen zum Ausführen von copyedit","Kompatibilität mit alexgude.com","Echtzeit-Textbearbeitung"],"pt":["Modo grammar para correção de erros de ortografia, gramática e pontuação","Modo polish para melhoria da clareza e coerência do texto","Preservação da voz e do estilo do autor","Uso de comandos CLI para execução dos modos","Integração com react e python para desenvolvimento de aplicações"],"ru":["Режим grammar для исправления ошибок орфографии, грамматики и пунктуации","Режим polish для улучшения ясности и связности текста","Сохранение голоса и стиля автора","Использование команд CLI для выполнения режимов","Интеграция с react и python для разработки приложений"],"ar":["وضع تحرير النحو لتصحيح الأخطاء النحوية والإملائية والترقيم","وضع تحسين الأسلوب لتحسين وضوح ومواءمة النص","الحفاظ على صوت وأسلوب الكاتب","استخدام أوامر CLI لتنفيذ الوضعين","التكامل مع react وpython لتنمية التطبيقات"]},"keywords":{"en":["how to use copyedit","copyedit alternative","copyedit setup guide","what is copyedit","copyedit vs grammarly","install copyedit skill","copyedit polish mode","ai-powered editing tools","content editing solutions"],"zh":["copyedit","代码编辑工具","语法检查","润色模式","代码质量","开发效率","AI代码编辑","代码风格检查"],"ja":["copyedit","AIエージェント","コード編集ツール","文法チェック","ポリッシュモード","コード品質","開発生産性","AIコード編集","コードスタイルチェック"],"ko":["copyedit","코드 편집 도구","문법 확인","다듬기 모드","코드 품질","개발 효율성","AI 코드 편집","코드 스타일 확인"],"es":["copyedit","herramientas de edición de textos","corrección de errores","mejora de la claridad","preservación de la voz y el estilo","alexgude.com","desarrollo web","edición de contenido","herramientas de AI para editores"],"fr":["copyedit","outils d''édition de texte","correction d''erreurs","amélioration de la clarté","préservation de la voix et du style","alexgude.com","développement web","édition de contenu","outils d''IA pour éditeurs"],"de":["copyedit","Textbearbeitungstools","Fehlerkorrektur","Klarheitsverbesserung","Beibehaltung von Stil und Stimme","alexgude.com","Webentwicklung","Inhaltsbearbeitung","KI-Tools für Redakteure"],"pt":["copyedit","edicao de texto","melhoria da clareza","coerência do conteúdo","react","python","CLI","desenvolvimento de aplicações"],"ru":["copyedit","редактирование текста","улучшение ясности","связность контента","react","python","CLI","разработка приложений"],"ar":["أداة Copyedit","تحرير النص","تحسين الوضوح","مواءمة المحتوى","react","python","CLI","تنمية التطبيقات"]}},"owner":"agude","repo":"agude.github.io","repoPath":"agude/agude.github.io","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"copyedit","description":"Edit blog posts and book reviews. Use `/copyedit grammar` for spelling/grammar only, or `/copyedit polish` for fuller editing. Preserves the authors voice and style.","bodyPreview":"# Copyedit Skill\n\nEdit drafts for alexgude.com while preserving voice and style.\n\n## Usage\n\n- `/copyedit grammar` --- Fix only spelling, grammar, and punctuation. Change nothing else.\n- `/copyedit polish` --- Fix errors, improve clarity, reword for coherence. Preserve voice.\n\nIf no mode is specified, ask which mode to use.\n\n## Instructions\n\n### Grammar Mode\n\nFix ONLY:\n- Spelling errors\n- Grammar mistakes (subject-verb agreement, tense consistency)\n- Punctuation errors\n- Typos\n\n### Polish Mode\n\nF","body":"# Copyedit Skill\n\nEdit drafts for alexgude.com while preserving voice and style.\n\n## Usage\n\n- `/copyedit grammar` --- Fix only spelling, grammar, and punctuation. Change nothing else.\n- `/copyedit polish` --- Fix errors, improve clarity, reword for coherence. Preserve voice.\n\nIf no mode is specified, ask which mode to use.\n\n## Instructions\n\n### Grammar Mode\n\nFix ONLY:\n- Spelling errors\n- Grammar mistakes (subject-verb agreement, tense consistency)\n- Punctuation errors\n- Typos\n\n### Polish Mode\n\nFollow this prompt:\n> Fix errors, make it clearer. Reword to make the arguments and sentences more coherent. Use the same sort of words I''m using, don''t substitute fancy synonyms. Maintain my voice.\n\nYou may:\n- Fix all grammar/spelling issues\n- Restructure sentences for clarity\n- Improve flow between ideas\n- Cut unnecessary words\n\nYou must:\n- Preserve the author''s vocabulary---don''t upgrade \"good\" to \"exceptional\"\n- Keep the same level of formality\n- Maintain opinions and judgments as written\n- Preserve all Liquid tags and formatting exactly\n\n## Output Format\n\n**Add the edited copy to the bottom of the article, separated by a markdown HR break.**\n\nFor grammar mode, just change in place, and also list the changes made so the author can review them.\n\n## Voice & Style Guide\n\nSee [references/STYLE.md](references/STYLE.md) for the complete style guide.\n\nKey points:\n- **Tone**: First-person, conversational but substantive, direct and opinionated\n- **Vocabulary**: Simple, direct words. \"great\", \"fun\", \"loved\"---not \"exceptional\", \"delightful\", \"adored\"\n- **Hedging**: Avoid. Say \"I didn''t like it\" not \"I perhaps didn''t fully appreciate it\"\n- **Em-dashes**: Do NOT add em-dashes. LLMs overuse them. Only keep existing ones if appropriate.\n- **Contractions**: Use naturally, don''t insert needlessly.\n- **Oxford comma**: Yes\n\n### Anti-patterns (never do these)\n\n- Don''t add too many em-dashes (---)\n- Don''t add emojis\n- Don''t add exclamation marks unless the original has them\n- Don''t use \"delve\", \"tapestry\", \"nuanced\", \"compelling\"\n- Don''t add hedging words (\"perhaps\", \"somewhat\", \"rather\")\n- Don''t make it sound more formal or academic\n- Don''t add superlatives or intensifiers\n- Don''t stack comma-separated adjectives (\"brutal, high-stakes\", \"dark, gritty\"). Pick one.\n\n## Book Review Structure\n\nSee [references/BOOK-REVIEWS.md](references/BOOK-REVIEWS.md) for details on book review structure.\n\nKey constraints:\n- **First paragraph**: Uses `{{ page.title }}`, `{{ page.book_authors }}`, etc. No custom plugin tags. This paragraph is pulled out for social media previews, so it must stand alone.\n- **After first paragraph**: `{% capture %}` blocks define template variables, then prose continues using those variables.\n- **Paragraph 2 transition**: The challenge is prose flow---don''t repeat too much of what paragraph 1 just said. Find a new angle or continue the thought. Generally the author has already tried to do this but help them a bit.\n- **References to other works**: These create backlinks, so mentioning other books/authors is encouraged, but again the author will have filled in most of these. You may suggest others.\n\n## Plugin Reference\n\nSee [references/PLUGINS.md](references/PLUGINS.md) for the full plugin reference.\n\nCommon tags you''ll encounter:\n- `{% book_link \"Title\" %}` --- link to a book\n- `{% author_link \"Name\" %}` --- link to an author (supports `possessive`, `link_text=`)\n- `{% series_link \"Series\" %}` --- link to a series\n- `{% capture var %}...{% endcapture %}` --- define reusable variables\n\nDo not modify these tags. Preserve them exactly as written.\n"},"lastSynced":"2026-03-08T02:03:33.294Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing advanced text refinement and editing capabilities, particularly those focused on grammar and style preservation.","zh":"适用于需要高级文本精炼和编辑功能的语言代理，特别是那些注重语法和风格保留的代理。","ja":"文法とスタイルの保全に焦点を当てた高度なテキストの精製と編集機能を必要とする言語エージェントに最適です。","ko":"문법과 스타일 보존에 중점을 둔 고급 텍스트 정련 및 편집 기능이 필요한 언어 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan capacidades de refinamiento y edición de texto avanzadas, particularmente aquellos centrados en la preservación de la gramática y el estilo.","fr":"Parfait pour les Agents de Langage ayant besoin de capacités de raffinement et d''édition de texte avancées, en particulier ceux axés sur la préservation de la grammaire et du style.","de":"Perfekt für Sprachagenten, die erweiterte Textverfeinerungs- und Bearbeitungsfunktionen benötigen, insbesondere solche, die auf die Bewahrung von Grammatik und Stil ausgerichtet sind.","pt":"Perfeito para Agentes de Linguagem que precisam de recursos avançados de refinamento e edição de texto, particularmente aqueles focados na preservação da gramática e do estilo.","ru":"Идеально подходит для языковых агентов, которым необходимы продвинутые возможности редактирования и уточнения текста, особенно тех, которые фокусируются на сохранении грамматики и стиля.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى تعديلات وتحرير متقدمة للنص، ولا سيما أولئك الذين يركزون على الحفاظ على القواعد والأسلوب."},"recommendation":{"en":"Empowers agents to refine text drafts with precision, offering grammar and polish modes that leverage subject-verb agreement, tense consistency, and punctuation correction to enhance clarity and coherence while preserving the original voice and style.","zh":"赋予代理以精确的方式精炼文本草稿，提供语法和润色模式，利用主谓一致、时态一致性和标点符号更正来提高清晰度和连贯性，同时保留原始的声音和风格。","ja":"エージェントが主題動詞の一致、時制の一貫性、句読点の修正を利用して明確性と一貫性を高め、元の声とスタイルを保ったまま、精密にテキストの下書きを精製できるようにします。","ko":"주제-동사 일치, 시제 일관성, 구두점 교정을 활용하여 명확성과 일관성을 높이며, 원래的声音과 스타일을 보존하는 동시에 에이전트가 정밀하게 텍스트 초안을 정련할 수 있도록 합니다.","es":"Habilita a los agentes a perfeccionar borradores de texto con precisión, ofreciendo modos de gramática y pulido que aprovechan la concordancia sujeto-verbo, la coherencia de los tiempos y la corrección de puntuación para mejorar la claridad y la coherencia mientras se preserva la voz y el estilo originales.","fr":"Permet aux agents de raffiner les brouillons de texte avec précision, offrant des modes de grammaire et de polissage qui exploitent l''accord sujet-verbe, la cohérence des temps et la correction de la ponctuation pour améliorer la clarté et la cohérence tout en préservant la voix et le style d''origine.","de":"Ermöglicht es den Agenten, Textentwürfe mit Präzision zu verfeinern und bietet Grammatik- und Poliermodi, die die Übereinstimmung von Subjekt und Verb, die Konsistenz der Zeiten und die Korrektur der Interpunktion nutzen, um Klarheit und Kohärenz zu verbessern und dabei die ursprüngliche Stimme und den Stil zu bewahren.","pt":"Habilita os agentes a refinar esboços de texto com precisão, oferecendo modos de gramática e polimento que utilizam a concordância sujeito-verbo, a consistência de tempo, e a correção de pontuação para melhorar a clareza e a coerência, enquanto preserva a voz e o estilo originais.","ru":"Наделяет агентов возможностью уточнять черновики текста с точностью, предлагая режимы грамматики и полировки, которые используют согласование субъекта и глагола, последовательность времени и исправление пунктуации для повышения ясности и связности, сохраняя при этом оригинальный голос и стиль.","ar":"تمكن الوكلاء من تعديل مسودات النص بدقة، مع تقديم أوضاع القواعد والتصفية التي تستخدم اتفاق الفاعل والفعل والاتساق الزمني وتصحيح علامات الترقيم لتحسين الوضوح والترابط، مع الحفاظ على الصوت والأسلوب الأصليين."},"useCases":{"en":["Refining blog posts for clarity and grammar","Polishing academic papers for publication","Editing website content for consistency and style"],"zh":["为清晰度和语法而改进博客文章","为出版而润色学术论文","为一致性和风格而编辑网站内容"],"ja":["明確性と文法のためにブログ記事を改良する","出版のために学術論文を磨き上げる","一貫性とスタイルのためにウェブサイトのコンテンツを編集する"],"ko":["명확성과 문법을 위해 블로그 게시물 정련하기","출판을 위해 학술 논문 연마하기","일관성과 스타일을 위해 웹사이트 콘텐츠 편집하기"],"es":["Perfeccionar publicaciones de blog para claridad y gramática","Pulir artículos académicos para publicación","Editar contenido web para coherencia y estilo"],"fr":["Raffiner les billets de blog pour la clarté et la grammaire","Polir les articles universitaires pour publication","Éditer le contenu du site Web pour la cohérence et le style"],"de":["Verfeinern von Blog-Beiträgen für Klarheit und Grammatik","Polieren von akademischen Artikeln für die Veröffentlichung","Bearbeiten von Website-Inhalten für Konsistenz und Stil"],"pt":["Refinamento de posts de blog para clareza e gramática","Polimento de artigos acadêmicos para publicação","Edição de conteúdo de sites para consistência e estilo"],"ru":["Уточнение блог-постов для ясности и грамматики","Полировка академических работ для публикации","Редактирование веб-контента для согласованности и стиля"],"ar":["تطوير منشورات المدونة لخلق وضوح وقواعد","تجمل الأبحاث الأكاديمية للنشر","تعديل محتوى الموقع للاتساق والأسلوب"]},"limitations":{"en":["Requires specific mode selection (grammar or polish) for tailored editing","Preserves original voice and style, limiting drastic content changes"],"zh":["需要选择特定的模式（语法或润色）以进行定制编辑","保留原始的声音和风格，限制剧烈的内容更改"],"ja":["カスタマイズされた編集のために特定のモード（文法または磨き上げ）の選択が必要","元の声とスタイルを保ったまま、劇的なコンテンツの変更を制限する"],"ko":["맞춤 편집을 위해 특정 모드(문법 또는 연마)의 선택이 필요","원래的声音과 스타일을 보존하는 동시에 극적인 콘텐츠 변경을 제한한다"],"es":["Requiere una selección de modo específica (gramática o pulido) para una edición personalizada","Preserva la voz y el estilo originales, lo que limita los cambios de contenido drásticos"],"fr":["Nécessite une sélection de mode spécifique (grammaire ou polissage) pour une édition personnalisée","Préserve la voix et le style d''origine, limitant ainsi les changements de contenu drastiques"],"de":["Benötigt eine spezifische Modusaufwahl (Grammatik oder Polieren) für eine maßgeschneiderte Bearbeitung","Bewahrt die ursprüngliche Stimme und den Stil, wodurch drastische Inhaltsänderungen begrenzt werden"],"pt":["Requer seleção de modo específico (gramática ou polimento) para edição personalizada","Preserva a voz e o estilo originais, limitando alterações drásticas de conteúdo"],"ru":["Требует выбора конкретного режима (грамматика или полировка) для индивидуальной редакции","Сохраняет оригинальный голос и стиль, ограничивая радикальные изменения содержания"],"ar":["يتطلب اختيار وضع محدد (قواعد أو تصفية) لتعديل مخصص","الحفاظ على الصوت والأسلوب الأصليين، مما يحد من التغييرات الكبيرة في المحتوى"]},"version":4},"contentHash":"116a4e46c699c7424195a8106c4500e9c509fdc37d51a0721d9663606f7dc975","qualityScore":44}');
