INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agude/agude.github.io/copyedit', 'copyedit', 'agude', 'agude.github.io', 'community', 'copyedit agude agude.github.io community The copyedit skill edits drafts for alexgude.com, preserving voice and style. It offers grammar and polish modes for tailored editing solutions. copyedit是一种代码编辑工具，提供语法和润色模式，帮助开发者提高代码质量 copyeditは、AIエージェントを利用した文法とポリッシュモードを備えたコード編集ツールです copyedit는 문법 및 다듬기 모드를 제공하는 코드 편집 도구로 개발자에게 코드 품질을 높이는 데 도움을 줍니다 Copyedit es una habilidad que edita borradores para alexgude.com mientras mantiene la voz y el estilo. Ofrece dos modos: grammar y polish Copyedit est une compétence qui édite les brouillons pour alexgude.com tout en préservant la voix et le style. Elle propose deux modes : grammar et polish Copyedit ist eine Fähigkeit, die Entwürfe für alexgude.com bearbeitet und Stil und Stimme beibehält. Sie bietet zwei Modi: grammar und polish O copyedit é uma habilidade que edita rascunhos para alexgude.com, preservando a voz e o estilo do autor. Ele oferece dois modos: grammar e polish Copyedit - это навык, который редактирует черновики для alexgude.com, сохраняя голос и стиль автора. Он предлагает два режима: grammar и polish أداة Copyedit هي مهارة تعمل على تحرير المسودات لموقع alexgude.com مع الحفاظ على صوت وأسلوب الكاتب. وهي توفر وضعين: تحرير النحو وتحسين الأسلوب how to use copyedit copyedit alternative copyedit setup guide what is copyedit copyedit vs grammarly install copyedit skill copyedit polish mode ai-powered editing tools content editing solutions copyedit 代码编辑工具 语法检查 润色模式 代码质量 开发效率 AI代码编辑 代码风格检查 Fixes spelling, grammar, and punctuation errors via `/copyedit grammar` command Improves clarity and coherence with `/copyedit polish` command Preserves original voice and style in edited content Supports two editing modes: grammar and polish Asks for mode specification if none is provided copyedit is a skill that edits content while preserving the original voice and style, offering modes for grammar and polish editing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thirdlf03/ccpeek/my-plan', 'community', 'thirdlf03', 'ccpeek', 'thirdlf03/ccpeek', 'my-plan', 0, 0, 44, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.338Z', '5662b9e04cc13d99d7d397b08815a573390397c987289e6e77816e30e41b1632', '{"id":"thirdlf03/ccpeek/my-plan","name":"my-plan","description":{"en":"my-plan assists developers in creating implementation plans by reading project conventions and exploring codebases. It helps identify necessary file changes and existing patterns.","zh":"my-plan 是一个帮助您创建彻底的实施计划的技能，包括了解项目约定、探索代码库和遵循测试规则","ja":"my-plan は、プロジェクト規約の理解、コードベースの探索、テスト規則の遵守などを含む、徹底的な実装計画を作成するためのスキルです","ko":"my-plan은 프로젝트 규칙 이해, 코드베이스 탐색, 테스트 규칙 준수를 포함한 완벽한 구현 계획을 만드는 데 도움이 되는 스킬입니다","es":"my-plan es una habilidad de AI Agent que permite a los desarrolladores crear un plan de implementación detallado para proyectos de IA. Incluye la comprensión de la solicitud, la exploración del código y la identificación de patrones","fr":"my-plan est une compétence d''outils d''IA qui permet aux développeurs de créer un plan de mise en œuvre détaillé pour les projets d''IA. Elle comprend la compréhension de la demande, l''exploration du code et l''identification de modèles","de":"my-plan ist eine Fähigkeit von AI-Tools, die es Entwicklern ermöglicht, einen detaillierten Implementierungsplan für IA-Projekte zu erstellen. Sie umfasst das Verständnis der Anforderung, die Code-Exploration und die Identifizierung von Mustern","pt":"O my-plan é uma ferramenta para criar planos de implementação de projetos de IA. Ele ajuda a entender as convenções do projeto e a explorar o código.","ru":"My-plan - это инструмент для создания планов реализации проектов ИИ Агентов. Он помогает понять конвенции проекта и изучить код.","ar":"my-plan هو أداة لإنشاء خطط تنفيذ لمشاريع أدوات الذكاء الاصطناعي. يساعد على فهم اتفاقيات المشروع والاستكشاف الرمز."},"seo":{"title":{"en":"my-plan: Implementation Planning Guide for AI Agents","zh":"my-plan 技术实施指南","ja":"my-plan 導入ガイド - AIエージェントのベストプラクティス","ko":"my-plan 구현 계획 가이드 - AI 도구 최적화","es":"Guía de configuración de my-plan: Implementación de proye...","fr":"Guide de configuration de my-plan: Mise en œuvre de proje...","de":"Einrichtungsleitfaden für my-plan: Implementierung von AI...","pt":"Guia de Configuração do my-plan: Implementação de Projeto...","ru":"Руководство по настройке my-plan: Создание плана реализац...","ar":"دليل إعداد my-plan: خطة تنفيذ أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create a thorough implementation plan with my-plan. Learn to read project conventions, explore codebases, and identify necessary file changes.","zh":"了解 my-plan 技术实施流程，包括项目约定、代码库探索和测试遵循","ja":"my-plan 導入のためのステップバイステップガイド - プロジェクト規約、コードベースの探索、テストの準備","ko":"my-plan 구현 계획을 위한 완벽한 가이드 - 프로젝트 규칙, 코드베이스 탐색, 테스트 준비","es":"Aprenda a configurar my-plan para proyectos de AI Agent. Descubra las mejores prácticas para la implementación de proyectos de IA","fr":"Découvrez comment configurer my-plan pour les projets d''outils d''IA. Trouvez les meilleures pratiques pour la mise en œuvre de projets d''IA","de":"Erfahren Sie, wie Sie my-plan für AI-Tool-Projekte konfigurieren. Entdecken Sie die besten Praktiken für die Implementierung von IA-Projekten","pt":"Aprenda a configurar o my-plan para projetos de IA. Leia sobre as melhores práticas para criar um plano de implementação completo.","ru":"Узнайте, как настроить my-plan для проектов ИИ Агентов. Читайте о лучших практиках создания плана реализации.","ar":"تعرف على كيفية إعداد my-plan لمشاريع أدوات الذكاء الاصطناعي. اقرأ عن أفضل الممارسات لإنشاء خطة تنفيذ شاملة."},"definition":{"en":"my-plan is a skill that enables AI agents to generate thorough implementation plans by understanding project requests and exploring codebases.","zh":"my-plan 是一个 AI 技术实施计划工具，帮助开发者创建详细的项目计划","ja":"my-plan は、開発者が詳細なプロジェクト計画を作成するための AI 技術実装計画ツールです","ko":"my-plan은 개발자가 자세한 프로젝트 계획을 만들 수 있는 AI 기술 구현 계획 도구입니다","es":"my-plan es una habilidad de AI Agent que facilita la creación de planes de implementación para proyectos de IA","fr":"my-plan est une compétence d''outils d''IA qui facilite la création de plans de mise en œuvre pour les projets d''IA","de":"my-plan ist eine Fähigkeit von AI-Tools, die die Erstellung von Implementierungsplänen für IA-Projekte erleichtert","pt":"O my-plan é um plano de implementação de projetos de IA que ajuda a entender as convenções do projeto e a explorar o código.","ru":"My-plan - это план реализации проектов ИИ Агентов, который помогает понять конвенции проекта и изучить код.","ar":"my-plan هو خطة تنفيذ لمشاريع أدوات الذكاء الاصطناعي التي تساعد على فهم اتفاقيات المشروع والاستكشاف الرمز."},"features":{"en":["Reads project conventions from CLAUDE.md","Explores codebases to identify existing patterns and necessary file changes","Utilizes AskUserQuestion for clarifying ambiguous requirements","Identifies files that need changes based on the requested feature","Checks existing tests for conventions and patterns"],"zh":["项目约定理解","代码库探索","测试规则遵守","AskUserQuestion 机制","CLAUDE.md 文件支持"],"ja":["プロジェクト規約の理解","コードベースの探索","テスト規則の遵守","AskUserQuestion メカニズム","CLAUDE.md ファイルのサポート"],"ko":["프로젝트 규칙 이해","코드베이스 탐색","테스트 규칙 준수","AskUserQuestion 메커니즘","CLAUDE.md 파일 지원"],"es":["Comprensión de la solicitud de proyecto","Exploración del código para identificar patrones","Identificación de archivos que requieren cambios","Revisión de pruebas existentes para convenciones y patrones"],"fr":["Compréhension de la demande de projet","Exploration du code pour identifier les modèles","Identification des fichiers qui nécessitent des modifications","Révision des tests existants pour les conventions et les modèles"],"de":["Verständnis der Anforderung des Projekts","Code-Exploration zur Identifizierung von Mustern","Identifizierung von Dateien, die Änderungen erfordern","Überprüfung von bestehenden Tests für Konventionen und Muster"],"pt":["Leitura de convenções do projeto em CLAUDE.md","Exploração do código para identificar padrões semelhantes","Identificação de arquivos que precisam ser alterados","Verificação de testes existentes para convenções e padrões"],"ru":["Чтение конвенций проекта в CLAUDE.md","Изучение кода для выявления подобных паттернов","Определение файлов, которые необходимо изменить","Проверка существующих тестов на конвенции и паттерны"],"ar":["قراءة اتفاقيات المشروع في CLAUDE.md","استكشاف الرمز لتحديد الأنماط المماثلة","تحديد الملفات التي تحتاج إلى تعديل","فحص الاختبارات الحالية لاتفاقيات والأنماط"]},"keywords":{"en":["how to use my-plan","my-plan setup guide","what is my-plan","my-plan alternative","my-plan vs project management tools","my-plan implementation planning","my-plan codebase exploration","my-plan AI agent skill"],"zh":["my-plan 技术实施","AI 技术计划","项目约定理解","代码库探索","测试规则遵守","AskUserQuestion 机制","CLAUDE.md 文件"],"ja":["my-plan 導入","AI 技術実装計画","プロジェクト規約の理解","コードベースの探索","テスト規則の遵守","AskUserQuestion メカニズム","CLAUDE.md ファイル"],"ko":["my-plan 구현 계획","AI 기술 구현 계획","프로젝트 규칙 이해","코드베이스 탐색","테스트 규칙 준수","AskUserQuestion 메커니즘","CLAUDE.md 파일"],"es":["my-plan AI Agent","implementación de proyectos de IA","configuración de my-plan","mejores prácticas para IA","desarrollo de proyectos de IA","herramientas de IA para desarrolladores"],"fr":["my-plan outils d''IA","mise en œuvre de projets d''IA","configuration de my-plan","meilleures pratiques pour l''IA","développement de projets d''IA","outils d''IA pour développeurs"],"de":["my-plan AI-Tools","Implementierung von IA-Projekten","Konfiguration von my-plan","beste Praktiken für IA","Entwicklung von IA-Projekten","AI-Tools für Entwickler"],"pt":["my-plan","IA","projetos de IA","planejamento de projetos","configuração de projetos","ferramentas de IA","desenvolvimento de projetos","implementação de projetos"],"ru":["my-plan","ИИ Агенты","проекты ИИ Агентов","планирование проектов","настройка проектов","инструменты ИИ","разработка проектов","реализация проектов"],"ar":["my-plan","أدوات الذكاء الاصطناعي","مشاريع أدوات الذكاء الاصطناعي","تخطيط المشاريع","إعداد المشاريع","أدوات الذكاء الاصطناعي","تنمية المشاريع","تنفيذ المشاريع"]}},"owner":"thirdlf03","repo":"ccpeek","repoPath":"thirdlf03/ccpeek","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.349Z","topics":[],"category":"community","skillMd":{"name":"my-plan","description":"Create a structured implementation plan for a feature or task","bodyPreview":"You are now in planning mode. Your goal is to create a thorough implementation plan.\n\n## Instructions\n\n1. **Understand the Request**\n   - Read CLAUDE.md for project conventions\n   - Read relevant rules/ files for the domain\n   - If the requirement is ambiguous, ask clarifying questions via AskUserQuestion\n\n2. **Explore the Codebase**\n   - Search for existing patterns similar to the requested feature\n   - Identify all files that will need changes\n   - Check existing tests for conventions and patt","body":"You are now in planning mode. Your goal is to create a thorough implementation plan.\n\n## Instructions\n\n1. **Understand the Request**\n   - Read CLAUDE.md for project conventions\n   - Read relevant rules/ files for the domain\n   - If the requirement is ambiguous, ask clarifying questions via AskUserQuestion\n\n2. **Explore the Codebase**\n   - Search for existing patterns similar to the requested feature\n   - Identify all files that will need changes\n   - Check existing tests for conventions and patterns\n   - Look for reusable utilities, types, and components\n\n3. **Design the Solution**\n   - Propose an architecture with trade-off analysis\n   - Identify dependencies between components\n   - Plan the TDD approach: which tests to write first\n   - Consider edge cases and error handling\n\n4. **Create the Plan**\n   - Use TaskCreate to build a sequenced implementation list\n   - Each task should be small enough to complete in <50% context\n   - Include test files in the sequence (RED before GREEN)\n   - Note file paths for every change\n\n5. **Output the Plan**\n   - Analysis of what exists\n   - Recommended approach with rationale\n   - Step-by-step implementation tasks (phased)\n   - Trade-off analysis for key decisions\n   - Risks and mitigation strategies (with severity)\n   - Success criteria checklist\n\n6. **Wait for Confirmation**\n   - End with: `**WAITING FOR CONFIRMATION**: Proceed? (yes / no / modify)`\n   - Do NOT write any code until the user explicitly confirms\n   - If user says \"modify\", revise the plan accordingly\n\n## Arguments\n\nThe user will provide a feature description or requirement as the command argument.\n"},"lastSynced":"2026-03-08T02:03:44.338Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents requiring automated implementation planning and codebase exploration.","zh":"适用于需要自动实现规划和代码库探索的代码分析代理。","ja":"コード分析エージェントが自動実装計画とコードベースの探索を必要とする場合に適しています。","ko":"자동 구현 계획 및 코드베이스 탐색이 필요한 코드 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Código que requieren una planificación de implementación automatizada y exploración de código base.","fr":"Idéal pour les Agents d''Analyse de Code nécessitant une planification d''implémentation automatisée et une exploration de base de code.","de":"Ideal für Code-Analyse-Agents, die eine automatisierte Implementierungsplanung und Codebase-Exploration erfordern.","pt":"Ideal para Agentes de Análise de Código que exigem planejamento de implementação automatizado e exploração do código-fonte.","ru":"Идеально для агентов анализа кода, требующих автоматического планирования реализации и изучения кодовой базы.","ar":"مثالي لعمليات تحليل الشفرة التي تتطلب التخطيط التلقائي للتطبيق واستكشاف قاعدة الشفرة."},"recommendation":{"en":"Empowers agents to read project conventions from files like CLAUDE.md, explore codebases for existing patterns, and identify necessary file changes using protocols like AskUserQuestion for clarifying ambiguities.","zh":"赋予代理从文件（如CLAUDE.md）读取项目约定，探索代码库以查找现有模式，并使用诸如AskUserQuestion的协议来澄清模糊性以确定必要的文件更改。","ja":"エージェントがファイル（CLAUDE.mdなど）からプロジェクトの約定を読み取り、コードベースを探索して既存のパターンを特定し、AskUserQuestionなどのプロトコルを使用して曖昧さを明確化して必要なファイルの変更を特定できるようにします。","ko":"에이전트가 파일(CLAUDE.md 등)에서 프로젝트 규칙을 읽고 코드베이스를 탐색하여 기존 패턴을 찾고 AskUserQuestion와 같은 프로토콜을 사용하여 모호함을 명확히 하여 필요한 파일 변경을 식별할 수 있도록 합니다.","es":"Habilita a los agentes a leer convenciones de proyecto de archivos como CLAUDE.md, explorar código bases en busca de patrones existentes e identificar cambios de archivo necesarios utilizando protocolos como AskUserQuestion para aclarar ambigüedades.","fr":"Permet aux agents de lire les conventions de projet à partir de fichiers comme CLAUDE.md, d''explorer les bases de code pour trouver des modèles existants et d''identifier les modifications de fichiers nécessaires en utilisant des protocoles comme AskUserQuestion pour clarifier les ambigüités.","de":"Ermöglicht es den Agents, Projekt-Konventionen aus Dateien wie CLAUDE.md zu lesen, Codebasen nach bestehenden Mustern zu durchsuchen und erforderliche Dateiänderungen unter Verwendung von Protokollen wie AskUserQuestion zur Klärung von Unklarheiten zu identifizieren.","pt":"Habilita os agentes a ler convenções de projeto de arquivos como CLAUDE.md, explorar código-fonte para padrões existentes e identificar alterações de arquivo necessárias usando protocolos como AskUserQuestion para esclarecer ambiguidades.","ru":"Наделяет агентов возможностью читать проектные соглашения из файлов, таких как CLAUDE.md, исследовать кодовую базу для существующих шаблонов и определять необходимые изменения файлов с помощью протоколов, таких как AskUserQuestion, для разъяснения неоднозначностей.","ar":"تمكّن الوكلاء من قراءة اتفاقيات المشروع من ملفات مثل CLAUDE.md، واستكشاف قاعدة الشفرة للنماطات الحالية، وتحديد التغييرات المطلوبة في الملفات باستخدام بروتوكولات مثل AskUserQuestion لتوضيح الغموض."},"useCases":{"en":["Creating thorough implementation plans","Exploring codebases for similar feature patterns","Identifying necessary file changes for new feature integration"],"zh":["创建彻底的实现计划","探索代码库以查找类似的功能模式","确定新功能集成所需的文件更改"],"ja":["徹底した実装計画の作成","コードベースを探索して類似の機能パターンを特定する","新しい機能の統合に必要なファイルの変更を特定する"],"ko":["철저한 구현 계획 생성","코드베이스 탐색을 통해 유사한 기능 패턴 찾기","새 기능 통합을 위한 필요한 파일 변경 식별"],"es":["Crear planes de implementación exhaustivos","Explorar código bases en busca de patrones de características similares","Identificar cambios de archivo necesarios para la integración de nuevas características"],"fr":["Créer des plans d''implémentation complets","Explorer les bases de code pour trouver des modèles de fonctionnalités similaires","Identifier les modifications de fichiers nécessaires pour l''intégration de nouvelles fonctionnalités"],"de":["Erstellen von umfassenden Implementierungsplänen","Durchsuchen von Codebasen nach ähnlichen Funktionsmustern","Identifizieren von erforderlichen Dateiänderungen für die Integration neuer Funktionen"],"pt":["Criar planos de implementação abrangentes","Explorar código-fonte para padrões de recursos semelhantes","Identificar alterações de arquivo necessárias para integração de recursos novos"],"ru":["Создание всесторонних планов реализации","Изучение кодовой базы для подобных шаблонов функций","Определение необходимых изменений файлов для интеграции новых функций"],"ar":["إنشاء خطط تنفيذ شاملة","استكشاف قاعدة الشفرة لنماطات الميزات المماثلة","تحديد التغييرات المطلوبة في الملفات لتكامل الميزات الجديدة"]},"limitations":{"en":["Requires access to project convention files like CLAUDE.md","Needs ability to search codebases and read file contents"],"zh":["需要访问项目约定文件，如CLAUDE.md","需要搜索代码库并读取文件内容的能力"],"ja":["CLAUDE.mdなどのプロジェクトの約定ファイルへのアクセスが必要","コードベースを検索し、ファイルの内容を読み取る能力が必要"],"ko":["프로젝트 규칙 파일(CLAUDE.md 등)에 대한 액세스가 필요","코드베이스를 검색하고 파일 내용을 읽을 수 있는 능력이 필요"],"es":["Requiere acceso a archivos de convención de proyecto como CLAUDE.md","Necesita la capacidad de buscar código bases y leer contenido de archivos"],"fr":["Nécessite l''accès à des fichiers de convention de projet comme CLAUDE.md","A besoin de la capacité de rechercher des bases de code et de lire le contenu des fichiers"],"de":["Benötigt Zugriff auf Projekt-Konventionsdateien wie CLAUDE.md","Benötigt die Fähigkeit, Codebasen zu durchsuchen und Dateiinhalte zu lesen"],"pt":["Exige acesso a arquivos de convenção do projeto, como CLAUDE.md","Necessita capacidade de pesquisar código-fonte e ler conteúdo de arquivos"],"ru":["Требует доступа к файлам проектных соглашений, таким как CLAUDE.md","Требует возможности искать кодовую базу и читать содержимое файлов"],"ar":["يتطلب الوصول إلى ملفات اتفاقيات المشروع مثل CLAUDE.md","يحتاج إلى القدرة على البحث في قاعدة الشفرة وقراءة محتوى الملفات"]},"version":4},"contentHash":"5662b9e04cc13d99d7d397b08815a573390397c987289e6e77816e30e41b1632","qualityScore":44}');
