INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thirdlf03/ccpeek/my-plan', 'my-plan', 'thirdlf03', 'ccpeek', 'community', 'my-plan thirdlf03 ccpeek community my-plan assists developers in creating implementation plans by reading project conventions and exploring codebases. It helps identify necessary file changes and existing patterns. my-plan 是一个帮助您创建彻底的实施计划的技能，包括了解项目约定、探索代码库和遵循测试规则 my-plan は、プロジェクト規約の理解、コードベースの探索、テスト規則の遵守などを含む、徹底的な実装計画を作成するためのスキルです my-plan은 프로젝트 규칙 이해, 코드베이스 탐색, 테스트 규칙 준수를 포함한 완벽한 구현 계획을 만드는 데 도움이 되는 스킬입니다 my-plan es una habilidad de AI Agent que permite a los desarrolladores crear un plan de implementación detallado para proyectos de IA. Incluye la comprensión de la solicitud, la exploración del código y la identificación de patrones my-plan est une compétence d''outils d''IA qui permet aux développeurs de créer un plan de mise en œuvre détaillé pour les projets d''IA. Elle comprend la compréhension de la demande, l''exploration du code et l''identification de modèles my-plan ist eine Fähigkeit von AI-Tools, die es Entwicklern ermöglicht, einen detaillierten Implementierungsplan für IA-Projekte zu erstellen. Sie umfasst das Verständnis der Anforderung, die Code-Exploration und die Identifizierung von Mustern O my-plan é uma ferramenta para criar planos de implementação de projetos de IA. Ele ajuda a entender as convenções do projeto e a explorar o código. My-plan - это инструмент для создания планов реализации проектов ИИ Агентов. Он помогает понять конвенции проекта и изучить код. my-plan هو أداة لإنشاء خطط تنفيذ لمشاريع أدوات الذكاء الاصطناعي. يساعد على فهم اتفاقيات المشروع والاستكشاف الرمز. how to use my-plan my-plan setup guide what is my-plan my-plan alternative my-plan vs project management tools my-plan implementation planning my-plan codebase exploration my-plan AI agent skill my-plan 技术实施 AI 技术计划 项目约定理解 代码库探索 测试规则遵守 AskUserQuestion 机制 CLAUDE.md 文件 Reads project conventions from CLAUDE.md Explores codebases to identify existing patterns and necessary file changes Utilizes AskUserQuestion for clarifying ambiguous requirements Identifies files that need changes based on the requested feature Checks existing tests for conventions and patterns my-plan is a skill that enables AI agents to generate thorough implementation plans by understanding project requests and exploring codebases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JFEspanolito/Template_FrontEnd_NextJS_JF/find-bugs', 'community', 'JFEspanolito', 'Template_FrontEnd_NextJS_JF', 'JFEspanolito/Template_FrontEnd_NextJS_JF', 'find-bugs', 0, 0, 44, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:50.336Z', 'edad456696ade7d64c855594e55b9064689a6ce354e667dc2a64e83362a56a8e', '{"id":"JFEspanolito/Template_FrontEnd_NextJS_JF/find-bugs","name":"find-bugs","description":{"en":"The find-bugs skill helps developers review changes on their branch for bugs, security vulnerabilities, and code quality issues, using git diff and attack surface mapping.","zh":"Find Bugs AI Agent是一种代码审查工具，使用Git Diff和TypeScript识别安全漏洞和代码质量问题。它可以帮助开发人员提高代码质量和安全性","ja":"Find Bugs AIエージェントは、コードをレビューするツールで、Git DiffとTypeScriptを使用してセキュリティ脆弱性とコード品質の問題を特定します","ko":"Find Bugs AI 에이전트는 코드를 검토하는 도구로 Git Diff와 TypeScript를 사용하여 보안 취약점 및 코드 품질 문제를 식별합니다","es":"Find-bugs es una herramienta para revisar cambios en el código y detectar bugs, vulnerabilidades y problemas de calidad","fr":"Find-bugs est un outil pour examiner les modifications du code et identifier les bugs, les vulnérabilités et les problèmes de qualité","de":"Find-bugs ist ein Werkzeug zur Überprüfung von Code-Änderungen und zur Erkennung von Fehlern, Sicherheitslücken und Qualitätsproblemen","pt":"O Find-Bugs é uma ferramenta que ajuda a identificar bugs e problemas de código em projetos Next com TypeScript. Ele analisa as alterações no código e lista todos os arquivos modificados.","ru":"ИИ Агенты Find-Bugs - это инструмент, который помогает выявить ошибки и проблемы кода в проектах Next с TypeScript. Он анализирует изменения в коде и перечисляет все измененные файлы.","ar":"أداة العثور على الأخطاء هي أداة تساعد في تحديد الأخطاء ومشاكل الكود في المشاريع التالية مع TypeScript. أنها تحليل التغييرات في الكود وتقدم قائمة بجميع الملفات المعدلة."},"seo":{"title":{